/**
 * Tool Registry (ADR-003)
 *
 * Central registry for MCP tools with capability-based authorization.
 *
 * Key features:
 * - Tools register themselves with capabilities
 * - Registry enforces tier and capability requirements
 * - No circular dependencies (tools don't import registry)
 * - Lifecycle hooks (beforeExecute, afterExecute, onError)
 *
 * @module registry/ToolRegistry
 */

import { trackActualToolCallAsync } from "../adapters/session-adapter.js";
import { CapabilityManager } from "./CapabilityManager.js";
import {
	CapabilityNotGrantedError,
	InputValidationError,
	type IToolRegistry,
	isZodSchema,
	TIER_HIERARCHY,
	TierNotAuthorizedError,
	type ToolCapability,
	type ToolContext,
	type ToolDefinition,
	type ToolExecutionResult,
	ToolNotFoundError,
	type ToolTier,
	type ValidationResult,
} from "./types.js";

/**
 * Dual-mode input validator.
 *
 * - Zod schema (preferred): uses `safeParse` for rich, structural validation.
 * - Legacy JSON Schema object: falls back to a minimal required-fields check
 *   for backward compatibility with tools that haven't migrated yet.
 */
function validateInputSchema(
	schema:
		| { type: string; properties?: Record<string, unknown>; required?: string[] }
		| {
				safeParse: (v: unknown) => {
					success: boolean;
					error?: { issues: Array<{ path: (string | number)[]; message: string }> };
				};
		  },
	input: unknown,
): ValidationResult {
	// Prefer Zod safeParse when available
	if (isZodSchema(schema as Parameters<typeof isZodSchema>[0])) {
		const result = (
			schema as {
				safeParse: (v: unknown) => {
					success: boolean;
					error?: { issues: Array<{ path: (string | number)[]; message: string }> };
				};
			}
		).safeParse(input);
		if (result.success) {
			return { valid: true };
		}
		const errors = result.error?.issues.map((i) => `${i.path.join(".") || "input"}: ${i.message}`) ?? [
			"Validation failed",
		];
		return { valid: false, errors };
	}

	// Legacy JSON Schema: check required fields only
	const jsonSchema = schema as { type: string; properties?: Record<string, unknown>; required?: string[] };
	const errors: string[] = [];
	if (jsonSchema.type === "object") {
		if (typeof input !== "object" || input === null) {
			return { valid: false, errors: ["Input must be an object"] };
		}
		const inputObj = input as Record<string, unknown>;
		if (jsonSchema.required) {
			for (const field of jsonSchema.required) {
				if (!(field in inputObj)) {
					errors.push(`Missing required field: ${field}`);
				}
			}
		}
	}
	return { valid: errors.length === 0, errors: errors.length > 0 ? errors : undefined };
}

/**
 * Tool Registry Implementation
 *
 * Manages tool registration, capability checking, and execution.
 */
export class ToolRegistry implements IToolRegistry {
	private tools = new Map<string, ToolDefinition>();
	private capabilityManager: CapabilityManager;

	constructor(capabilityManager?: CapabilityManager) {
		this.capabilityManager = capabilityManager ?? new CapabilityManager();
	}

	/**
	 * Register a tool
	 */
	register<TInput, TOutput>(tool: ToolDefinition<TInput, TOutput>): void {
		// Validate tool definition
		this.validateToolDefinition(tool as ToolDefinition);

		// Check for duplicate registration
		if (this.tools.has(tool.name)) {
			throw new Error(`Tool '${tool.name}' is already registered`);
		}

		// Cast to base type for storage (type safety enforced at call site)
		this.tools.set(tool.name, tool as unknown as ToolDefinition);
	}

	/**
	 * Get a tool by name
	 */
	get(name: string): ToolDefinition | undefined {
		return this.tools.get(name);
	}

	/**
	 * List all tools (optionally filtered by tier)
	 */
	list(options?: { tier?: ToolTier }): ToolDefinition[] {
		const allTools = Array.from(this.tools.values());

		if (!options?.tier) {
			return allTools;
		}

		// Filter by tier (include lower tiers)
		const maxTierIndex = TIER_HIERARCHY.indexOf(options.tier);

		return allTools.filter((tool) => {
			const toolTierIndex = TIER_HIERARCHY.indexOf(tool.tier ?? "free");
			return toolTierIndex <= maxTierIndex;
		});
	}

	/**
	 * Execute a tool with capability checking
	 */
	async execute<TInput, TOutput>(
		name: string,
		input: TInput,
		context: ToolContext,
	): Promise<ToolExecutionResult<TOutput>> {
		const startTime = Date.now();
		const tool = this.tools.get(name);

		if (!tool) {
			throw new ToolNotFoundError(name);
		}

		// Check tier authorization
		if (!this.isTierAuthorized(tool, context)) {
			throw new TierNotAuthorizedError(name, tool.tier ?? "free");
		}

		// Check capabilities
		const missingCapabilities = this.getMissingCapabilities(tool, context);
		if (missingCapabilities.length > 0) {
			throw new CapabilityNotGrantedError(name, missingCapabilities);
		}

		// Validate input
		const validationResult = this.validateInput(name, input);
		if (!validationResult.valid) {
			throw new InputValidationError(name, validationResult.errors ?? []);
		}

		// Execute with hooks
		try {
			// Before hook
			if (tool.hooks?.beforeExecute) {
				await tool.hooks.beforeExecute(input, context);
			}

			// Main execution
			const output = await tool.handler(input, context);

			// After hook
			if (tool.hooks?.afterExecute) {
				await tool.hooks.afterExecute(output, context);
			}

			// Track tool call for follow-through rate computation (nextActions feedback loop)
			if (context.workspace?.path) {
				// Extract mode from input if present (for tools like vreko, check that use mode parameter)
				const mode =
					typeof input === "object" && input !== null && "mode" in input
						? String((input as Record<string, unknown>).mode)
						: undefined;
				await trackActualToolCallAsync(context.workspace.path, name, mode);
			}

			return {
				success: true,
				result: output as TOutput,
				durationMs: Date.now() - startTime,
			};
		} catch (error) {
			// Error hook
			if (tool.hooks?.onError) {
				await tool.hooks.onError(error as Error, context);
			}

			// P0-005: Preserve stack trace for debugging "Cannot read properties of undefined" errors
			// Previously only captured error.message, making it impossible to locate the crash site
			const errorMessage = error instanceof Error ? error.message : String(error);
			const errorStack = error instanceof Error ? error.stack : undefined;

			return {
				success: false,
				error: errorMessage,
				stack: errorStack,
				durationMs: Date.now() - startTime,
			};
		}
	}

	/**
	 * Check if a tool is available for given context
	 */
	isAvailable(name: string, context: ToolContext): boolean {
		const tool = this.tools.get(name);
		if (!tool) {
			return false;
		}

		return this.isTierAuthorized(tool, context) && this.getMissingCapabilities(tool, context).length === 0;
	}

	/**
	 * Validate input against tool schema
	 */
	validateInput(name: string, input: unknown): ValidationResult {
		const tool = this.tools.get(name);
		if (!tool) {
			return { valid: false, errors: [`Tool '${name}' not found`] };
		}

		return validateInputSchema(tool.inputSchema, input);
	}

	/**
	 * Get the capability manager
	 */
	getCapabilityManager(): CapabilityManager {
		return this.capabilityManager;
	}

	/**
	 * Get all registered tool names
	 */
	getToolNames(): string[] {
		return Array.from(this.tools.keys());
	}

	/**
	 * Check if tool is registered
	 */
	has(name: string): boolean {
		return this.tools.has(name);
	}

	/**
	 * Unregister a tool (mainly for testing)
	 */
	unregister(name: string): boolean {
		return this.tools.delete(name);
	}

	/**
	 * Clear all registered tools (mainly for testing)
	 */
	clear(): void {
		this.tools.clear();
	}

	// ==========================================================================
	// Private Methods
	// ==========================================================================

	private isTierAuthorized(tool: ToolDefinition, context: ToolContext): boolean {
		const requiredTierIndex = TIER_HIERARCHY.indexOf(tool.tier ?? "free");
		const userTierIndex = TIER_HIERARCHY.indexOf(context.workspace.tier);
		return userTierIndex >= requiredTierIndex;
	}

	private getMissingCapabilities(tool: ToolDefinition, context: ToolContext): ToolCapability[] {
		return tool.capabilities.filter((cap) => !context.activeCapabilities.has(cap));
	}

	private validateToolDefinition(tool: ToolDefinition): void {
		if (!tool.name || typeof tool.name !== "string") {
			throw new Error("Tool must have a valid name");
		}
		if (!tool.handler || typeof tool.handler !== "function") {
			throw new Error(`Tool '${tool.name}' must have a handler function`);
		}
		if (!Array.isArray(tool.capabilities)) {
			throw new Error(`Tool '${tool.name}' must declare capabilities array`);
		}
		if (!tool.inputSchema || typeof tool.inputSchema !== "object") {
			throw new Error(`Tool '${tool.name}' must have an inputSchema`);
		}
	}
}

/**
 * Create a tool registry with default configuration
 */
export function createToolRegistry(capabilityManager?: CapabilityManager): ToolRegistry {
	return new ToolRegistry(capabilityManager);
}
