/**
 * Input Sanitization Module
 *
 * Defense-in-depth protection against prompt injection attacks.
 * Used by MCP tools to validate user inputs before storage or processing.
 *
 * Layers:
 * 1. Zod schema validation (type + length limits)
 * 2. Structural validation (balanced brackets, valid structure)
 * 3. Injection pattern detection (obfuscation-resistant)
 * 4. Content normalization (trim, collapse whitespace)
 *
 * @module security/input-sanitization
 */

import { resolve } from "node:path";
import { z } from "zod";

// =============================================================================
// Constants
// =============================================================================

/** Maximum lengths for user-controlled fields */
export const MAX_LENGTHS = {
	trigger: 500,
	action: 2000,
	task: 500,
	description: 2000,
	reason: 1000,
	prevention: 1000,
	source: 100,
	type: 50,
	file: 500,
	keyword: 100,
} as const;

/**
 * Injection patterns - designed to catch obfuscation attempts
 *
 * Strategy: Look for structural markers, not just literal strings.
 * Attackers can encode "SYSTEM:" as "S​Y​S​T​E​M​:" (zero-width chars)
 * or use homoglyphs, but the structural intent remains detectable.
 */
const INJECTION_PATTERNS = [
	// System/role injection attempts
	/\b(system|assistant|user|human|ai)\s*:/i,
	/\[\s*(system|inst|instructions?)\s*\]/i,
	/<\s*(system|inst|instructions?)\s*>/i,

	// XML/tag injection (common in prompt injection)
	// Match tags with content/attributes: <tag>content</tag>
	// Exclude TypeScript generics: Promise<void>, Array<T>
	/<(?!(?:void|string|number|boolean|any|unknown|never|object|null|undefined|T|K|V)\s*>)[a-z_-]+(?:\s[^>]*)?>[^<]*<\//i,

	// Event handler injection (XSS via attributes)
	/\bon(?:error|load|click|mouse|key|focus|blur|change|submit|reset|select|input)\s*=/i,

	// Instruction override attempts
	/\b(ignore|disregard|forget)\s+(previous|above|all|prior)\s+(instructions?|context|rules?)/i,
	/\bnew\s+(instructions?|rules?|context)\s*:/i,
	/\boverride\s*:/i,

	// Role hijacking
	/\b(you\s+are|act\s+as|pretend\s+to\s+be|roleplay\s+as)\b/i,
	/\b(from\s+now\s+on|starting\s+now)\b.*\b(you|your)\b/i,

	// Code execution attempts
	/\$\{.*\}/s, // Template literals
	/\{\{.*\}\}/s, // Mustache/Handlebars
	/<%.*%>/s, // ERB/EJS
	/`[^`]*`/s, // Backticks (potential code)

	// Control character injection
	/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/,

	// Zero-width character obfuscation
	/[\u200B-\u200D\u2060\uFEFF]/,

	// Unicode homoglyph detection (Cyrillic lookalikes for common injection words)
	/[\u0400-\u04FF]/,

	// Multi-line delimiter injection
	/^---+\s*$/m,
	/^===+\s*$/m,
	/^###\s*(system|context|instructions?)/im,
] as const;

/**
 * Structural validation patterns
 */
const STRUCTURAL_CHECKS = {
	/** Max consecutive repeated characters (catches spam/padding) */
	maxRepeatedChars: 10,
	/** Max nesting depth for brackets/parens */
	maxNestingDepth: 5,
	/** Minimum unique character ratio (catches encoding tricks) */
	minUniqueCharRatio: 0.1,
} as const;

// =============================================================================
// Sanitization Functions
// =============================================================================

/**
 * Check if a string contains injection patterns
 */
function containsInjectionPattern(input: string): { detected: boolean; pattern?: string } {
	for (const pattern of INJECTION_PATTERNS) {
		if (pattern.test(input)) {
			return { detected: true, pattern: pattern.source };
		}
	}
	return { detected: false };
}

/**
 * Structural validation - catches obfuscation attempts
 */
function validateStructure(input: string): { valid: boolean; reason?: string } {
	// Check for excessive repeated characters
	const repeatedMatch = input.match(/(.)\1{10,}/);
	if (repeatedMatch) {
		return { valid: false, reason: `Excessive repeated character: "${repeatedMatch[1]}"` };
	}

	// Check bracket balance and nesting
	let depth = 0;
	let maxDepth = 0;
	for (const char of input) {
		if ("([{<".includes(char)) {
			depth++;
			maxDepth = Math.max(maxDepth, depth);
		} else if (")]}>".includes(char)) {
			depth--;
		}
		if (depth < 0) {
			return { valid: false, reason: "Unbalanced brackets" };
		}
	}
	if (depth !== 0) {
		return { valid: false, reason: "Unbalanced brackets" };
	}
	if (maxDepth > STRUCTURAL_CHECKS.maxNestingDepth) {
		return { valid: false, reason: `Nesting depth ${maxDepth} exceeds max ${STRUCTURAL_CHECKS.maxNestingDepth}` };
	}

	// Check unique character ratio (catches binary/encoded data)
	const uniqueChars = new Set(input).size;
	const ratio = uniqueChars / Math.max(input.length, 1);
	if (input.length > 50 && ratio < STRUCTURAL_CHECKS.minUniqueCharRatio) {
		return { valid: false, reason: "Suspiciously low character diversity" };
	}

	return { valid: true };
}

/**
 * Normalize content - removes problematic characters while preserving meaning
 */
function normalizeContent(input: string): string {
	return (
		input
			// Remove zero-width characters
			.replace(/[\u200B-\u200D\u2060\uFEFF]/g, "")
			// Remove control characters (except newline, tab)
			.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, "")
			// Collapse multiple whitespace
			.replace(/[ \t]+/g, " ")
			// Collapse multiple newlines
			.replace(/\n{3,}/g, "\n\n")
			// Trim
			.trim()
	);
}

// =============================================================================
// Zod Schemas
// =============================================================================

/**
 * Base sanitized string schema
 */
const sanitizedString = (maxLength: number, fieldName: string) =>
	z
		.string()
		.max(maxLength, { message: `${fieldName} exceeds max length of ${maxLength}` })
		.transform(normalizeContent)
		.refine(
			(val) => {
				const injection = containsInjectionPattern(val);
				return !injection.detected;
			},
			{ message: `${fieldName} contains potentially malicious content` },
		)
		.refine(
			(val) => {
				const structure = validateStructure(val);
				return structure.valid;
			},
			{ message: `${fieldName} has invalid structure` },
		);

