/**
 * Validate a file path for path traversal
 */
export function validateFilePath(path: string, basePath: string): ValidationResult<string> {
	const pathResult = FilePathSchema.safeParse(path);
	if (!pathResult.success) {
		return {
			success: false,
			errors: pathResult.error.errors.map((e) => e.message),
		};
	}

	// Additional runtime check: resolve and verify containment
	// This is done at runtime because we need the actual basePath
	const resolvedBase = resolve(basePath);
	const resolvedPath = resolve(basePath, path);

	if (!resolvedPath.startsWith(`${resolvedBase}/`) && resolvedPath !== resolvedBase) {
		return {
			success: false,
			errors: ["Path traversal detected: resolved path escapes base directory"],
		};
	}

	return { success: true, data: resolvedPath };
}

