/**
 * Risk assessment for begin-task
 *
 * Evaluates risk level of planned files and determines if snapshot is needed.
 * Routes through daemon for actual risk assessment when available.
 *
 * @module facades/begin-task/risk-assessment
 */

import type { RiskArea } from "../../session/types.js";
import type { RiskAssessment, StaticAnalysisOutput } from "./types.js";

// =============================================================================
// DAEMON RISK ASSESSMENT
// =============================================================================

/**
 * Assess risk via daemon IPC
 *
 * Routes risk assessment through the daemon for intelligent multi-factor analysis.
 * Falls back to local assessment if daemon is unavailable.
 */
export async function assessRiskViaDaemon(workspaceRoot: string, files: string[]): Promise<RiskAssessment> {
	try {
		// Dynamic import to avoid circular dependencies
		const { assessRiskViaDaemon: callDaemonRisk } = await import("../../daemon/intelligence-adapter.js");

		// For begin-task, we assess based on planned files
		// Build a synthetic context for daemon risk assessment
		const result = await callDaemonRisk(workspaceRoot, files[0] || "", "", undefined, {
			sources: { planned_files: files },
			riskFactors: files.map((f) => ({
				name: f.split("/").pop() || f,
				score: 0.5,
				source: "planned_file",
				description: `Planned modification: ${f}`,
			})),
		});

		if (result.success && result.assessment) {
			// Map daemon result to RiskAssessment shape
			const riskAreas: RiskArea[] = [];
			const level = result.assessment.level;
			if (level === "high") {
				if (files.some((f) => f.includes("auth"))) {
					riskAreas.push("auth");
				}
				if (files.some((f) => f.includes("payment"))) {
					riskAreas.push("payment");
				}
				if (files.some((f) => f.includes("database") || f.includes("migration"))) {
					riskAreas.push("database");
				}
				if (files.some((f) => f.includes("config") || f.includes(".env"))) {
					riskAreas.push("config");
				}
				if (files.some((f) => f.includes("security"))) {
					riskAreas.push("security");
				}
			}

			return {
				overallRisk: level,
				riskAreas,
				recommendations:
					result.assessment.recommendation === "block"
						? ["High risk detected - consider creating a snapshot before proceeding"]
						: [],
			};
		}
	} catch {
		// Daemon unavailable, fall back to local assessment
	}

	// Fallback to local assessment
	return assessRisk(files, workspaceRoot);
}

// =============================================================================
// LOCAL RISK ASSESSMENT (FALLBACK)
// =============================================================================

/**
 * Assess risk of planned files
 */
export function assessRisk(files: string[], _workspaceRoot: string): RiskAssessment {
	const riskAreas: RiskArea[] = [];
	const recommendations: string[] = [];

	for (const file of files) {
		const lowerPath = file.toLowerCase();

		if (lowerPath.includes("auth") || lowerPath.includes("login")) {
			if (!riskAreas.includes("auth")) {
				riskAreas.push("auth");
			}
		}
		if (lowerPath.includes("payment") || lowerPath.includes("stripe")) {
			if (!riskAreas.includes("payment")) {
				riskAreas.push("payment");
			}
		}
		if (lowerPath.includes("database") || lowerPath.includes("migration")) {
			if (!riskAreas.includes("database")) {
				riskAreas.push("database");
			}
		}
		if (lowerPath.includes("config") || lowerPath.includes(".env")) {
			if (!riskAreas.includes("config")) {
				riskAreas.push("config");
			}
		}
		if (lowerPath.includes("api") || lowerPath.includes("route")) {
			if (!riskAreas.includes("api")) {
				riskAreas.push("api");
			}
		}
		if (lowerPath.includes("security") || lowerPath.includes("crypto")) {
			if (!riskAreas.includes("security")) {
				riskAreas.push("security");
			}
		}
	}

	// Determine overall risk
	const criticalAreas: RiskArea[] = ["auth", "payment", "security"];
	const hasCritical = riskAreas.some((a) => criticalAreas.includes(a));
	const overallRisk: "low" | "medium" | "high" = hasCritical
		? "high"
		: riskAreas.length >= 2
			? "medium"
			: riskAreas.length > 0
				? "medium"
				: "low";

	// Build recommendations
	if (riskAreas.includes("auth")) {
		recommendations.push("Test with both valid and invalid credentials");
	}
	if (riskAreas.includes("payment")) {
		recommendations.push("Use test mode/sandbox for payment testing");
	}
	if (riskAreas.includes("database")) {
		recommendations.push("Verify migrations can be rolled back");
	}
	if (riskAreas.includes("config")) {
		recommendations.push("Ensure secrets are not committed");
	}
	if (files.length >= 5) {
		recommendations.push("Consider breaking into smaller focused changes");
	}

	return { overallRisk, riskAreas, recommendations };
}

/**
 * Decide if snapshot should be auto-created
 */
export function shouldAutoSnapshot(risk: RiskAssessment, files?: string[]): boolean {
	// Always snapshot for high risk
	if (risk.overallRisk === "high") {
		return true;
	}

	// Snapshot if touching critical areas
	const criticalAreas: RiskArea[] = ["auth", "payment", "database", "security"];
	if (risk.riskAreas.some((a) => criticalAreas.includes(a))) {
		return true;
	}

	// Snapshot if modifying 3+ files
	if (files && files.length >= 3) {
		return true;
	}

	// Medium risk + config files
	if (risk.overallRisk === "medium" && files?.some((f) => f.includes("config") || f.endsWith(".env"))) {
		return true;
	}

	return false;
}

/**
 * Generate next actions based on context
 */
export function generateNextActions(
	risk: RiskAssessment,
	_learnings: Array<{ type: string }>,
	staticAnalysis?: StaticAnalysisOutput,
): Array<{ tool: string; priority: number; reason: string }> {
	const actions: Array<{ tool: string; priority: number; reason: string }> = [];

	// If skipped tests found, suggest enabling them first
	if (staticAnalysis?.skippedTests && staticAnalysis.skippedTests.length > 0) {
		actions.push({
			tool: "enable_skipped_tests",
			priority: 1,
			reason: `${staticAnalysis.skippedTests.length} skipped test(s) may be ready to enable`,
		});
	}

	// Always suggest quick_check after implementation
	actions.push({
		tool: "quick_check",
		priority: 2,
		reason: "Validate changes after implementation",
	});

	// If high risk, suggest frequent validation
	if (risk.overallRisk === "high") {
		actions.push({
			tool: "what_changed",
			priority: 3,
			reason: "Track changes in high-risk area",
		});
	}

	// Before commit
	actions.push({
		tool: "review_work",
		priority: 4,
		reason: "Review before committing",
	});

	return actions;
}
