/**
 * Union type for any snapshot manifest version
 */
export type AnySnapshotManifest = SnapshotManifestV1 | SnapshotManifestV2;

/**
 * Type guard for V2 manifests
 */
export function isSnapshotManifestV2(manifest: unknown): manifest is SnapshotManifestV2 {
	return (
		typeof manifest === "object" &&
		manifest !== null &&
		"schemaVersion" in manifest &&
		(manifest as Record<string, unknown>).schemaVersion === 2
	);
}

/**
 * Type guard for POST checkpoints (have content)
 */
export function isPostCheckpoint(manifest: AnySnapshotManifest): boolean {
	if (!isSnapshotManifestV2(manifest)) {
		return true; // V1 manifests always have content
	}
	return manifest.type === "POST";
}

/**
 * Type guard for pointer checkpoints (PRE, PRE_ROLLBACK)
 */
export function isPointerCheckpoint(manifest: AnySnapshotManifest): boolean {
	if (!isSnapshotManifestV2(manifest)) {
		return false;
	}
	return manifest.type === "PRE" || manifest.type === "PRE_ROLLBACK";
}

