/**
 * Shared IPC Client Pool
 *
 * Single source of truth for VrekoLocalClient instances shared across all
 * daemon adapters (local-service, intelligence, etc.).
 *
 * Before this module, each adapter maintained its own `Map<string, VrekoLocalClient>`.
 * For N open workspaces that creates 2N daemon connections, halving the effective
 * `maxClients` capacity. With this pool, every workspace gets exactly ONE connection
 * regardless of how many adapters are in use.
 *
 * Design constraints:
 * - No imports from local-service-adapter or intelligence-adapter (prevents cycles)
 * - Connection logic (auto-start, backoff) stays in local-service-adapter
 * - This module owns ONLY the maps and the shared connect+initialize path
 *
 * Race Condition Fixes (SB-190):
 * - Added pendingConnections Map to prevent TOCTOU races in acquireClient()
 * - Fixed removePooledClient() to delete from map BEFORE closing (prevents reconnect race)
 * - Fixed clearPool() to snapshot before clearing (atomic operation)
 *
 * @module daemon/client-pool
 */

import { VrekoLocalClient } from "@vreko/local-service-client";

// =============================================================================
// SHARED STATE
// =============================================================================

/** One client per workspace  -  keyed by absolute workspace root path. */
const clients = new Map<string, VrekoLocalClient>();

/**
 * Pending connection promises  -  prevents TOCTOU race where multiple callers
 * can create duplicate clients before the first connect() completes.
 * Acts as a mutex: if a connection is in progress, subsequent calls wait for it.
 */
const pendingConnections = new Map<string, Promise<VrekoLocalClient>>();

/** Per-workspace connection health  -  used for backoff in local-service-adapter. */
export interface PoolConnectionStatus {
	connected: boolean;
	lastAttempt: number;
	consecutiveFailures: number;
}

const connectionStatus = new Map<string, PoolConnectionStatus>();

// =============================================================================
// CLIENT ACCESSORS
// =============================================================================

/** Return the pooled client for a workspace (may be disconnected). */
export function getPooledClient(workspaceRoot: string): VrekoLocalClient | undefined {
	return clients.get(workspaceRoot);
}

/** Store a client in the pool. Caller is responsible for connecting it. */
export function setPooledClient(workspaceRoot: string, client: VrekoLocalClient): void {
	clients.set(workspaceRoot, client);
}

/**
 * Close and remove the pooled client for a workspace.
 * Safe to call even if no client exists.
 *
 * IMPORTANT: Deletes from map FIRST to prevent reconnection race condition.
 * If we closed first, the auto-reconnect logic could re-add the client
 * before we delete it, leaving a zombie.
 */
export function removePooledClient(workspaceRoot: string): void {
	const client = clients.get(workspaceRoot);
	if (client) {
		// Delete from map FIRST to prevent reconnection race
		clients.delete(workspaceRoot);
		// Clear status to reset backoff state
		clearPoolConnectionStatus(workspaceRoot);
		// Cancel any pending connection
		pendingConnections.delete(workspaceRoot);
		// Then close (may trigger reconnect logic, but client no longer in pool)
		try {
			client.close();
		} catch {
			// Ignore close errors - client is already removed from pool
		}
	}
}

/**
 * Return the first connected client across all workspaces.
 * Used for workspace-agnostic operations (e.g. embedding generation).
 */
export function getAnyConnectedClient(): VrekoLocalClient | undefined {
	for (const c of clients.values()) {
		if (c.isConnected()) {
			return c;
		}
	}
	return undefined;
}

/**
 * Returns all currently connected clients from the pool.
 * Used for workspace-agnostic operations (e.g. embeddings) that can use
 * any live connection.
 */
export function getAllConnectedClients(): VrekoLocalClient[] {
	const result: VrekoLocalClient[] = [];
	for (const client of clients.values()) {
		if (client.isConnected()) {
			result.push(client);
		}
	}
	return result;
}

/**
 * Close every client and reset all pool state.
 * Called during process shutdown or full reset.
 *
 * IMPORTANT: Snapshots maps before clearing to avoid modification during iteration.
 * This makes the operation atomic - no new clients can be added mid-clear.
 */
export function clearPool(): void {
	// Snapshot to avoid modification during iteration
	const clientsToClose = Array.from(clients.values());

	// Clear maps FIRST to prevent new operations during close
	clients.clear();
	connectionStatus.clear();
	pendingConnections.clear();

	// Then close all clients
	for (const client of clientsToClose) {
		try {
			client.close();
		} catch {
			// Expected: client close may fail if connection already terminated
		}
	}
}

// =============================================================================
// CONNECTION STATUS ACCESSORS
// =============================================================================

export function getPoolConnectionStatus(workspaceRoot: string): PoolConnectionStatus | undefined {
	return connectionStatus.get(workspaceRoot);
}

export function setPoolConnectionStatus(workspaceRoot: string, status: PoolConnectionStatus): void {
	connectionStatus.set(workspaceRoot, status);
}

export function clearPoolConnectionStatus(workspaceRoot: string): void {
	connectionStatus.delete(workspaceRoot);
}

/** Clear backoff state for all workspaces  -  called after a successful daemon (re)start. */
export function clearAllPoolConnectionStatuses(): void {
	connectionStatus.clear();
}

// =============================================================================
// CONNECT + INITIALIZE (shared, no auto-start)
// =============================================================================

/**
 * Get or create a connected, initialized client from the pool.
 *
 * - If a connected client already exists for the workspace, returns it immediately.
 * - If a connection is already in progress (pending), waits for and returns that.
 * - Otherwise creates a new client, connects, and sends the `initialize` handshake.
 * - Does NOT perform auto-start  -  callers that need daemon spawning handle it themselves.
 *
 * Race Condition Fix:
 * Uses pendingConnections Map as a mutex to prevent TOCTOU bugs where multiple
 * concurrent callers could:
 * 1. Create duplicate clients (second overwrites first in Map)
 * 2. Call connect() concurrently on the same client
 * 3. Leave orphaned clients with active sockets
 *
 * @throws on connection or initialization failure
 */
export async function acquireClient(workspaceRoot: string): Promise<VrekoLocalClient> {
	// Check 1: Return existing pending connection (mutex pattern)
	// This prevents multiple concurrent callers from creating duplicate clients
	const pending = pendingConnections.get(workspaceRoot);
	if (pending) {
		return pending;
	}

	// Check 2: Return existing connected client
	const existing = clients.get(workspaceRoot);
	if (existing?.isConnected()) {
		return existing;
	}

	// Create connection promise and cache it (this is the mutex lock)
	const connectionPromise = (async (): Promise<VrekoLocalClient> => {
		// Re-check for existing client inside the lock
		// (another caller may have created one while we were waiting)
		let client = clients.get(workspaceRoot);

		try {
			if (!client) {
				client = new VrekoLocalClient({
					timeout: 60000,
					autoReconnect: true,
					maxReconnectAttempts: 5,
					reconnectDelay: 1000,
					maxReconnectDelay: 30000,
				});
				clients.set(workspaceRoot, client);
			}

			if (!client.isConnected()) {
				await client.connect();
				await client.initialize({
					protocolVersion: "1.0.0",
					clientInfo: { name: "vreko-mcp", version: "1.0.0" },
					capabilities: { notifications: true },
				});
			}

			return client;
		} catch (error) {
			// Remove failed client from pool to allow retry
			clients.delete(workspaceRoot);
			throw error;
		}
	})();

	// Store the promise so concurrent callers wait for the same connection
	pendingConnections.set(workspaceRoot, connectionPromise);

	try {
		return await connectionPromise;
	} finally {
		// Always clean up pending promise, whether success or failure
		pendingConnections.delete(workspaceRoot);
	}
}

/**
 * Check if there's a pending connection for a workspace.
 * Useful for status reporting.
 */
export function hasPendingConnection(workspaceRoot: string): boolean {
	return pendingConnections.has(workspaceRoot);
}

/**
 * Get count of active clients in the pool.
 * Useful for monitoring and debugging.
 */
export function getPoolSize(): number {
	return clients.size;
}

/**
 * Get count of connected (not just pooled) clients.
 */
export function getConnectedCount(): number {
	let count = 0;
	for (const client of clients.values()) {
		if (client.isConnected()) {
			count++;
		}
	}
	return count;
}
