/**
 * Error Handling Utilities for V2 Tools
 *
 * Provides consistent error handling across the 3-tool MCP surface.
 * Includes health checking, graceful degradation, and actionable guidance.
 *
 * @module tools/v2/utils/errors
 */

import { resetCircuitBreaker } from "../../../daemon/intelligence-adapter.js";
import type { ToolResult } from "../../../types/tool-types.js";

// =============================================================================
// Health Status Types
// =============================================================================

/**
 * Daemon health status for tools to understand operational state
 */
export interface DaemonHealthStatus {
	/** Whether daemon connection is healthy */
	healthy: boolean;
	/** Whether we're in degraded mode (some features unavailable) */
	degraded: boolean;
	/** Reason for current state */
	reason: "connected" | "not_running" | "starting" | "connection_failed" | "timeout" | "null_response";
	/** Human-readable message for the agent */
	message: string;
	/** Actionable suggestions */
	suggestions: string[];
	/** Whether auto-start is in progress */
	autoStartInProgress?: boolean;
}

// =============================================================================
// Error Classification
// =============================================================================

/**
 * Error categories for better handling
 */
export type DaemonErrorCategory =
	| "not_running" // Daemon process not started
	| "connection_refused" // Daemon running but rejecting connections
	| "timeout" // Daemon not responding in time
	| "null_response" // Daemon responded but returned null (internal error)
	| "protocol_error" // Daemon returned invalid response (malformed JSON etc.)
	| "schema_error" // JSON-RPC -32602: method called with wrong parameters (client/server version skew)
	| "unknown"; // Unclassified error

/**
 * Classify an error into a category for appropriate handling
 */
export function classifyDaemonError(error: unknown): DaemonErrorCategory {
	if (error === null || error === undefined) {
		return "null_response";
	}

	if (error instanceof Error) {
		const message = error.message.toLowerCase();
		const code = (error as Error & { code?: number }).code;

		// Code-first: JSON-RPC -32602 (InvalidParams) means client called with wrong schema.
		// Must run before message-string matching because message may contain "invalid".
		if (code === -32602) {
			return "schema_error";
		}

		if (message.includes("enoent") || message.includes("no such file")) {
			return "not_running";
		}
		if (message.includes("econnrefused") || message.includes("connection refused")) {
			return "connection_refused";
		}
		if (message.includes("timeout") || message.includes("etimedout") || message.includes("timed out")) {
			return "timeout";
		}
		if (message.includes("invalid") || message.includes("parse") || message.includes("json")) {
			return "protocol_error";
		}
		if (message.includes("socket") || message.includes("daemon") || message.includes("unavailable")) {
			return "not_running";
		}
	}

	return "unknown";
}

/**
 * Check if an error indicates the daemon is not running
 */
export function isDaemonConnectionError(error: unknown): boolean {
	const category = classifyDaemonError(error);
	return category === "not_running" || category === "connection_refused";
}

/**
 * Check if a null response from daemon indicates a recoverable state
 */
export function isDaemonNullResponse(result: unknown): boolean {
	return result === null || result === undefined;
}

// =============================================================================
// Graceful Degradation Support
// =============================================================================

/**
 * Build a degraded mode response that clearly indicates partial functionality
 *
 * Use this when the daemon is unavailable but the tool can still provide
 * some value (e.g., local-only operations, cached data).
 */
export function formatDegradedModeResponse(
	mainContent: string,
	options: {
		reason: DaemonErrorCategory;
		featuresAvailable: string[];
		featuresUnavailable: string[];
	},
): ToolResult {
	const sections: string[] = [];

	// Main content
	sections.push(mainContent);

	// Degraded mode warning
	sections.push("\n---");
	sections.push("⚠️ **DEGRADED MODE**: Running with limited functionality.");

	// What's working
	if (options.featuresAvailable.length > 0) {
		sections.push("\n**Working:**");
		for (const feature of options.featuresAvailable) {
			sections.push(`  ✓ ${feature}`);
		}
	}

	// What's not working
	if (options.featuresUnavailable.length > 0) {
		sections.push("\n**Unavailable:**");
		for (const feature of options.featuresUnavailable) {
			sections.push(`  ✗ ${feature}`);
		}
	}

	// Actionable fix
	const fix = getFixSuggestion(options.reason);
	sections.push(`\n**To restore full functionality:** ${fix}`);

	return {
		content: [{ type: "text", text: sections.join("\n") }],
		isError: false, // Not an error - just degraded
	};
}

/**
 * Get actionable fix suggestion based on error category
 */
export function getFixSuggestion(category: DaemonErrorCategory): string {
	switch (category) {
		case "not_running":
			return "Run `vreko daemon start` in your terminal.";
		case "connection_refused":
			return "The daemon may be starting up. Wait a moment and try again, or run `vreko daemon restart`.";
		case "timeout":
			return "The daemon is slow to respond. Try `vreko daemon restart` if this persists.";
		case "null_response":
			return "The daemon encountered an internal error. Try `vreko daemon restart`.";
		case "protocol_error":
			return "Daemon returned an unexpected response. Run `vreko daemon restart` to restore functionality.";
		case "schema_error":
			return "Parameter mismatch between CLI and daemon. Run `vreko daemon restart`. If it persists, update with `npm update -g @vreko/cli`.";
		default:
			return "Run `vreko daemon restart` to restore functionality.";
	}
}

// =============================================================================
// Standard Error Formatters
// =============================================================================

/**
 * Format a daemon connection error for user display
 * Enhanced with specific guidance based on error type
 */
export function formatDaemonError(category?: DaemonErrorCategory): ToolResult {
	const cat = category ?? "not_running";
	const fix = getFixSuggestion(cat);

	const messages: Record<DaemonErrorCategory, string> = {
		not_running: "Vreko daemon is not running. Your files are NOT protected until the daemon is running.",
		connection_refused: "Vreko daemon is starting up or busy. Your files may not be fully protected.",
		timeout: "Vreko daemon is not responding. Your files may not be fully protected during this time.",
		null_response: "Vreko daemon encountered an internal error. Some features may be unavailable.",
		protocol_error: "Vreko daemon returned an unexpected response. A restart usually resolves this.",
		schema_error:
			"Vreko daemon schema mismatch: the CLI and daemon disagree on method parameters. Restart to resync.",
		unknown: "Vreko daemon connection failed. Your files are NOT protected until this is resolved.",
	};

	return {
		content: [
			{
				type: "text",
				text: `${messages[cat]}\n\n**Fix:** ${fix}`,
			},
		],
		isError: true,
	};
}

/**
 * Format an unexpected error for user display
 */
export function formatUnexpectedError(context: string, error: unknown): ToolResult {
	const category = classifyDaemonError(error);
	const fix = getFixSuggestion(category);

	return {
		content: [
			{
				type: "text",
				text: `Vreko encountered an unexpected error during ${context}.\n\n**Fix:** ${fix}`,
			},
		],
		isError: true,
	};
}

// =============================================================================
// Pre-flight Health Check
// =============================================================================

/**
 * Perform a pre-flight health check on the daemon connection.
 *
 * Call this at the start of tools to provide better UX than failing mid-operation.
 * Returns health status so tools can decide how to proceed.
 *
 * @param daemon - The daemon client instance
 * @param workspace - Workspace path for context
 * @returns Health status with actionable information
 */
export async function checkDaemonHealth(
	daemon: {
		isAvailable: () => boolean;
		request: <T>(method: string, params: Record<string, unknown>) => Promise<T | null>;
	},
	workspace: string,
): Promise<DaemonHealthStatus> {
	// Quick check: is client even connected?
	if (!daemon.isAvailable()) {
		return {
			healthy: false,
			degraded: true,
			reason: "not_running",
			message: "Daemon is not running",
			suggestions: [
				"Run `vreko daemon start` to enable file protection",
				"All tools will work in degraded mode without the daemon",
			],
		};
	}

	// Deeper check: can we make a request?
	try {
		const result = await daemon.request<{ ok: boolean }>("health/ping", { workspace });

		if (result === null) {
			return {
				healthy: false,
				degraded: true,
				reason: "null_response",
				message: "Daemon returned no response",
				suggestions: [
					"The daemon may be initializing",
					"Wait a moment and retry, or run `vreko daemon restart`",
				],
			};
		}

		// Reset circuit breaker on successful health check
		resetCircuitBreaker(workspace);

		return {
			healthy: true,
			degraded: false,
			reason: "connected",
			message: "Daemon is healthy",
			suggestions: [],
		};
	} catch (error) {
		const category = classifyDaemonError(error);
		// Map error category to health status reason
		const reasonMap: Record<DaemonErrorCategory, DaemonHealthStatus["reason"]> = {
			not_running: "not_running",
			connection_refused: "connection_failed",
			timeout: "timeout",
			null_response: "null_response",
			protocol_error: "connection_failed",
			schema_error: "connection_failed",
			unknown: "connection_failed",
		};
		return {
			healthy: false,
			degraded: true,
			reason: reasonMap[category],
			message: `Daemon health check failed: ${category}`,
			suggestions: [getFixSuggestion(category)],
		};
	}
}

/**
 * Append health status to a tool response for transparency
 */
export function appendHealthStatus(result: ToolResult, health: DaemonHealthStatus): ToolResult {
	if (health.healthy) {
		return result;
	}

	// Append degraded mode indicator
	const existingText = result.content[0]?.text ?? "";
	const healthNote = `\n\n_[Daemon status: ${health.reason}]_`;

	return {
		...result,
		content: [
			{
				type: "text" as const,
				text: existingText + healthNote,
			},
		],
	};
}
