/**
 * Snap Fix Tool
 *
 * Snapshot list/restore/diff operations. Replaces:
 * - snapshot_list
 * - snapshot_restore
 * - compare_snapshots
 *
 * @see stress_test_remediation.md Section "Tool 3: vreko.fix"
 * @module tools/consolidated/vreko-fix
 *
 * DEPRECATED (Day 4): Direct @vreko/intelligence imports replaced with daemon IPC.
 * Snapshot operations now route through the daemon.
 */

import { basename } from "node:path";
import { generateWorkspaceId } from "@vreko/workspace-identity";
import {
	getRelativeTime as brandGetRelativeTime,
	formatWireLabeled,
	getRelativeTimeHuman,
	INTERNAL_SEPARATOR,
	messages,
	type WireFormatOptions,
} from "../../branding/index.js";
import {
	createDaemonClient,
	listSnapshotsViaDaemon,
	restoreSnapshotViaDaemon,
} from "../../daemon/local-service-adapter.js";
import type { ToolHandler, VrekoTool } from "../../types/tool-types.js";

// =============================================================================
// Local Types (Day 4: no longer imported from @vreko/intelligence)
// =============================================================================

export interface ErrorContext {
	message: string;
	code?: string;
	file?: string;
	line?: number;
	stack?: string;
}

export interface RestoreSnapshot {
	id: string;
	createdAt: string | number;
	fileCount: number;
	reason?: string;
	protected?: boolean;
	files?: string[] | Array<{ path: string; content?: string; hash?: string }>;
	metadata?: Record<string, unknown>;
}

export interface Snapshot extends RestoreSnapshot {
	score?: number;
	matchReasons?: string[];
}

export interface ScoredSnapshot {
	snapshot: RestoreSnapshot;
	score: number;
	confidence: number;
	reasoning: string;
	factors: string[];
	matchReasons?: string[];
}

// =============================================================================
// Types
// =============================================================================

/**
 * Snap.fix parameters
 */
export interface SnapFixParams {
	/** Action: list, restore, diff, or suggest */
	action?: "list" | "restore" | "diff" | "suggest";
	/** Snapshot ID (for restore/diff operations) */
	id?: string;
	/** Second snapshot ID (for diff operation) */
	diffWith?: string;
	/** @deprecated Legacy diff param (use 'diffWith' instead) */
	diff?: string;
	/** Preview only (dry run for restore) - DEFAULT: true for safety */
	dryRun?: boolean;
	/** @deprecated Legacy dry param (use 'dryRun' instead) */
	dry?: boolean;
	/** Confirm actual restore execution (required when dryRun is false) */
	confirm?: boolean;
	/** Specific files to restore */
	files?: string[];
	/** Error symptom/message for suggest action */
	symptom?: string;
	/** File path with error for suggest action */
	file?: string;
	/** Max number of suggestions to return (default: 5) */
	limit?: number;
	/** Use compact positional wire format instead of labeled (default: false = labeled) */
	compact?: boolean;
}

// =============================================================================
// Handler
// =============================================================================

/**
 * Handle vreko.fix
 */
export const handleSnapFix: ToolHandler = async (args, context) => {
	const params = args as unknown as SnapFixParams;
	const options: WireFormatOptions = { compact: params.compact ?? false };
	const daemon = createDaemonClient(context.workspaceRoot);

	// Normalize parameters
	const diffWith = params.diffWith ?? params.diff;
	// Safety-first: dryRun defaults to TRUE unless explicitly set to false AND confirm is true
	const explicitDryRun = params.dryRun ?? params.dry;
	const dryRun = !(explicitDryRun === false && params.confirm === true);

	// Determine action: explicit action param, or infer from other params
	let action: "list" | "restore" | "diff" | "suggest" = params.action ?? "list";
	if (!params.action) {
		if (diffWith && params.id) {
			action = "diff";
		} else if (params.id) {
			action = "restore";
		} else if (params.symptom || params.file) {
			action = "suggest";
		}
	}

	// Suggest mode - intelligent snapshot recommendations via daemon IPC
	if (action === "suggest") {
		const snapshots = await listSnapshotsViaDaemon(context.workspaceRoot);
		const limit = params.limit ?? 5;

		if (snapshots.length === 0) {
			const wire = formatWireLabeled("SG", { count: 0, status: "empty" }, options);
			return {
				content: [{ type: "text", text: `${wire}${INTERNAL_SEPARATOR}No snapshots available for suggestions` }],
				structuredContent: { suggestions: [], count: 0 },
			};
		}

		// Score snapshots by recency
		const restoreSnapshots: RestoreSnapshot[] = snapshots.map((vreko) => ({
			id: vreko.id,
			createdAt: vreko.createdAt,
			fileCount: vreko.fileCount,
			reason: vreko.reason,
			protected: vreko.protected,
		}));
		const scoredSnapshots: ScoredSnapshot[] = restoreSnapshots.map((vreko, idx) => ({
			snapshot: vreko,
			score: 100 - idx * 10,
			confidence: 0.7,
			reasoning: "Recent snapshot",
			factors: ["recency"],
		}));
		const topSuggestions = scoredSnapshots.slice(0, limit);

		// Build wire format
		const suggestionSummaries = topSuggestions
			.map((s: ScoredSnapshot) => {
				const createdAt = s.snapshot.createdAt;
				const timestamp = typeof createdAt === "string" ? new Date(createdAt).getTime() : createdAt;
				const age = brandGetRelativeTime(timestamp);
				return `${s.snapshot.id.slice(0, 8)}:${s.score}pts:${age}`;
			})
			.join(",");

		const wire = formatWireLabeled(
			"SG",
			{
				count: topSuggestions.length,
				suggestions: suggestionSummaries,
				top: topSuggestions[0]?.snapshot.id.slice(0, 8) ?? "none",
				confidence: topSuggestions[0]?.confidence ?? 0,
			},
			options,
		);

		const structuredSuggestions = topSuggestions.map((s: ScoredSnapshot) => {
			const createdAt = s.snapshot.createdAt;
			const timestamp = typeof createdAt === "string" ? new Date(createdAt).getTime() : createdAt;
			return {
				id: s.snapshot.id,
				score: s.score,
				confidence: s.confidence,
				reasoning: s.reasoning,
				factors: s.factors,
				files: [],
				age: brandGetRelativeTime(timestamp),
			};
		});

		return {
			content: [{ type: "text", text: wire }],
			structuredContent: {
				action: "suggest",
				suggestions: structuredSuggestions,
				count: structuredSuggestions.length,
				errorContext: {
					symptom: params.symptom,
					file: params.file,
				},
			},
		};
	}

	// List mode
	if (action === "list") {
		const snapshots = await listSnapshotsViaDaemon(context.workspaceRoot, 5);

		if (snapshots.length === 0) {
			const wire = formatWireLabeled("R", { count: 0, status: "empty" }, options);
			return { content: [{ type: "text", text: `${wire}${INTERNAL_SEPARATOR}${messages.restore.notFound()}` }] };
		}

		const snapshotSummaries = snapshots
			.map((vreko) => {
				const age = brandGetRelativeTime(new Date(vreko.createdAt).getTime());
				return `${vreko.id.slice(0, 8)}:${age}:${vreko.fileCount}f`;
			})
			.join(",");

		const wire = formatWireLabeled("R", { count: snapshots.length, snapshots: snapshotSummaries }, options);
		return { content: [{ type: "text", text: wire }] };
	}

	// Diff mode
	if (action === "diff") {
		if (!params.id || !diffWith) {
			const wire = formatWireLabeled(
				"!",
				{ code: "MISSING_PARAMS", reason: "diff requires id and diffWith" },
				options,
			);
			return {
				content: [{ type: "text", text: `${wire}${INTERNAL_SEPARATOR}Diff requires both snapshot IDs` }],
				isError: true,
			};
		}

		// Fetch both snapshot file lists via daemon
		const snap1Data = await daemon.request<{ snapshot?: { files: Array<{ path: string }> } }>("snapshot/get", {
			workspace: context.workspaceRoot,
			snapshotId: params.id,
		});
		const snap2Data = await daemon.request<{ snapshot?: { files: Array<{ path: string }> } }>("snapshot/get", {
			workspace: context.workspaceRoot,
			snapshotId: diffWith,
		});

		if (!snap1Data?.snapshot || !snap2Data?.snapshot) {
			const notFoundId = !snap1Data?.snapshot ? params.id : diffWith;
			const wire = formatWireLabeled("!", { code: "NOT_FOUND", id: notFoundId }, options);
			return {
				content: [
					{
						type: "text",
						text: `${wire}${INTERNAL_SEPARATOR}${messages.error.notFound(`Snapshot ${notFoundId}`)}`,
					},
				],
				isError: true,
			};
		}

		const files1 = new Set(snap1Data.snapshot.files.map((f) => f.path));
		const files2 = new Set(snap2Data.snapshot.files.map((f) => f.path));

		const added = [...files2].filter((f) => !files1.has(f)).length;
		const removed = [...files1].filter((f) => !files2.has(f)).length;
		const changed = [...files1].filter((f) => files2.has(f)).length;

		const wire = formatWireLabeled(
			"D",
			{
				from: params.id.slice(0, 8),
				to: diffWith.slice(0, 8),
				added: `+${added}`,
				removed: `-${removed}`,
				changed: `~${changed}`,
			},
			options,
		);

		return { content: [{ type: "text", text: wire }] };
	}

	// Restore mode
	if (!params.id) {
		const wire = formatWireLabeled("!", { code: "MISSING_ID", reason: "restore requires snapshot id" }, options);
		return {
			content: [{ type: "text", text: `${wire}${INTERNAL_SEPARATOR}Restore requires snapshot ID` }],
			isError: true,
		};
	}

	// Fetch snapshot metadata via daemon
	const snapData = await daemon.request<{
		snapshot?: { files: Array<{ path: string }>; createdAt: number };
	}>("snapshot/get", { workspace: context.workspaceRoot, snapshotId: params.id });

	if (!snapData?.snapshot) {
		const wire = formatWireLabeled("!", { code: "NOT_FOUND", id: params.id }, options);
		return {
			content: [{ type: "text", text: `${wire}${INTERNAL_SEPARATOR}${messages.restore.notFound()}` }],
			isError: true,
		};
	}

	const snapshot = snapData.snapshot;

	if (dryRun) {
		// Preview mode
		const filesToRestore = params.files
			? snapshot.files.filter((f) => params.files?.some((p: string) => f.path.includes(p)))
			: snapshot.files;

		const fileNames = filesToRestore.slice(0, 5).map((f) => basename(f.path));
		const wire = formatWireLabeled(
			"R",
			{
				status: "DRY",
				files: `${filesToRestore.length}f`,
				preview: fileNames.join(","),
			},
			options,
		);

		return {
			content: [
				{
					type: "text",
					text: `${wire}${INTERNAL_SEPARATOR}${messages.restore.preview(filesToRestore.length)}\n\n⚠️  To actually restore: snap_fix({ id: "${params.id}", dryRun: false, confirm: true })`,
				},
			],
		};
	}

	// Actual restore via daemon IPC
	try {
		const result = await restoreSnapshotViaDaemon(context.workspaceRoot, params.id, {
			files: params.files,
			dryRun: false,
		});

		if (!result.success || !result.restoredFiles || result.restoredFiles.length === 0) {
			const wire = formatWireLabeled(
				"!",
				{ code: "RESTORE_FAILED", reason: result.errors?.[0] ?? "no files restored" },
				options,
			);
			return {
				content: [
					{
						type: "text",
						text: `${wire}${INTERNAL_SEPARATOR}${messages.error.generic(result.errors?.[0] ?? "no files restored")}`,
					},
				],
				isError: true,
			};
		}

		const restoredFilePaths = result.restoredFiles;
		const fileNames = restoredFilePaths.slice(0, 5).map((p) => basename(p));

		// ============================================================
		// Loop 1: Rollback Signal Capture
		// ============================================================

		let learningId: string | undefined;

		const decisionRecord = await context.services?.decisionStore?.getDecisionForSnapshot(
			params.id,
			context.workspaceRoot,
		);

		if (decisionRecord) {
			await context.services?.decisionStore?.recordOutcome(decisionRecord.id, "rolled_back");
		}

		if (context.services?.stateStore) {
			const learning = context.services.stateStore.addLearning({
				type: "pitfall",
				trigger: `When ${fileNames.join(", ")} changed`,
				action: "Rollback required  -  review changes to these files carefully",
				source: "manual",
				tier: "warm",
				domain: "rollback",
			});
			learningId = learning.id;
		}

		if (context.services?.analytics) {
			context.services.analytics.track("rollback_triggered", {
				workspace_hash: generateWorkspaceId(context.workspaceRoot),
				file_count: restoredFilePaths.length,
				ai_tool: decisionRecord?.ai_tool ?? "unknown",
				session_id: context.sessionId,
				had_decision_record: !!decisionRecord,
			});
		}

		const wire = formatWireLabeled(
			"R",
			{
				status: "OK",
				files: `${restoredFilePaths.length}f`,
				restored: fileNames.join(","),
			},
			options,
		);

		const timeAgo = getRelativeTimeHuman(snapshot.createdAt);
		const humanMessage =
			restoredFilePaths.length === 1
				? messages.restore.single(fileNames[0], timeAgo)
				: messages.restore.multiple(restoredFilePaths.length, timeAgo);

		const learningMessage = learningId ? `\n\n📝 Pitfall pattern recorded (${learningId}).` : "";

		return {
			content: [{ type: "text", text: `${wire}${INTERNAL_SEPARATOR}${humanMessage}${learningMessage}` }],
			structuredContent: {
				restored: true,
				snapshotId: params.id,
				learningCaptured: learningId,
				fileCount: restoredFilePaths.length,
				files: restoredFilePaths,
				hadDecisionRecord: !!decisionRecord,
			},
		};
	} catch (error) {
		const errorMsg = error instanceof Error ? error.message : "Restore failed";
		const wire = formatWireLabeled("!", { code: "ERROR", reason: errorMsg }, options);
		return {
			content: [{ type: "text", text: `${wire}${INTERNAL_SEPARATOR}${messages.error.generic(errorMsg)}` }],
			isError: true,
		};
	}
};

// =============================================================================
// Tool Definition
// =============================================================================

export const snapFixTool: VrekoTool = {
	name: "vreko_fix",
	description: `[DEPRECATED] 🦎 Vreko Fix - Your safety net for file restoration.

**When to use:** Made a mistake? Need to compare changes? Restore specific files? Get intelligent suggestions?

**Actions:**
- **list** (default): Show recent snapshots with age and file counts
- **restore**: Restore files from a specific snapshot
- **diff**: Compare two snapshots to see what changed
- **suggest**: Get AI-scored suggestions for which snapshot to restore

**Behavioral Flow (restore):**
1. **Validate** → Check snapshot exists and files are restorable
2. **Preview** → Show what will change (if dryRun: true)
3. **Backup** → Auto-create new snapshot before restore
4. **Apply** → Write original file contents
5. **Confirm** → Report restored files and timing

**Wire Format:**
  List:    🦎|R|count:5|snapshots:snap_a:2m:3f,snap_b:1h:5f
  Restore: 🦎|R|status:OK|files:3f|restored:auth.ts,api.ts
  Diff:    🦎|D|from:snap_a|to:snap_b|added:+2|removed:-1
  Suggest: 🦎|SG|count:3|suggestions:snap_a:85pts:2m,snap_b:72pts:1h

**Examples:**

List recent snapshots:
  snap_fix({ action: "list" })

Get suggestions based on error:
  snap_fix({ action: "suggest", symptom: "JWT validation failed", file: "src/auth.ts" })

Preview restore (ALWAYS do this first - safety-first default):
  snap_fix({ action: "restore", id: "snap_abc123" })
  // OR explicitly: snap_fix({ action: "restore", id: "snap_abc123", dryRun: true })

Actually restore (requires BOTH dryRun: false AND confirm: true):
  snap_fix({ action: "restore", id: "snap_abc123", dryRun: false, confirm: true })

Restore specific files only:
  snap_fix({ action: "restore", id: "snap_abc123", files: ["auth.ts"] })

Compare snapshots:
  snap_fix({ action: "diff", id: "snap_before", diffWith: "snap_after" })

**Boundaries:**

Will:
- List snapshots from .vreko/snapshots/
- Restore file contents to original state
- Create backup snapshot before restore
- Show diff summary between snapshots
- Provide intelligent restoration suggestions

Will Not:
- Restore files outside workspace
- Delete snapshots (manual cleanup only)
- Modify files without explicit restore action
- Restore without valid snapshot ID

**⚠️ Pro Feature:** Requires Vreko Pro tier.

**Safety-First:** Restore defaults to dryRun mode. To actually restore, set dryRun: false AND confirm: true.

**Legacy Support:** Single-letter params (diff, dry) still work but are not shown in schema.`,
	inputSchema: {
		type: "object",
		properties: {
			action: {
				type: "string",
				enum: ["list", "restore", "diff", "suggest"],
				description: "Operation: list (default), restore, diff, or suggest",
			},
			id: {
				type: "string",
				description: "Snapshot ID (for restore/diff operations)",
			},
			diffWith: {
				type: "string",
				description: "Second snapshot ID (for diff operation)",
			},
			dryRun: {
				type: "boolean",
				default: true,
				description: "Preview mode (DEFAULT: true). Set false + confirm: true to execute.",
			},
			confirm: {
				type: "boolean",
				description: "Confirm actual restore execution. Required when dryRun: false.",
			},
			files: {
				type: "array",
				items: { type: "string" },
				description: "Specific files to restore (optional filter)",
			},
			symptom: {
				type: "string",
				description: "Error symptom/message for suggest action (e.g., 'JWT validation failed')",
			},
			file: {
				type: "string",
				description: "File path with error for suggest action (e.g., 'src/auth.ts')",
			},
			limit: {
				type: "number",
				default: 5,
				description: "Maximum suggestions to return (default: 5)",
			},
			compact: {
				type: "boolean",
				default: false,
				description: "Use compact wire format instead of labeled (default: labeled)",
			},
		},
	},
	outputSchema: {
		type: "object",
		properties: {
			action: { type: "string", enum: ["list", "restore", "diff", "suggest"], description: "Action performed" },
			count: { type: "number", description: "Snapshot count (list/suggest) or files restored (restore)" },
			snapshots: { type: "array", items: { type: "string" }, description: "Snapshot summaries (list)" },
			restoredFiles: { type: "array", items: { type: "string" }, description: "Files restored (restore)" },
			restored: { type: "boolean", description: "Whether restore was successful" },
			snapshotId: { type: "string", description: "Snapshot ID that was restored" },
			learningCaptured: { type: "string", description: "ID of captured pitfall learning (if any)" },
			hadDecisionRecord: {
				type: "boolean",
				description: "Whether a decision record was found for this snapshot",
			},
			diff: {
				type: "object",
				properties: {
					added: { type: "number" },
					removed: { type: "number" },
					changed: { type: "number" },
				},
				description: "Diff results (diff)",
			},
			suggestions: {
				type: "array",
				items: {
					type: "object",
					properties: {
						id: { type: "string" },
						score: { type: "number" },
						confidence: { type: "number" },
						reasoning: { type: "string" },
						factors: {
							type: "object",
							properties: {
								recency: { type: "number" },
								fileOverlap: { type: "number" },
								riskScore: { type: "number" },
								errorContext: { type: "number" },
							},
						},
					},
				},
				description: "Scored suggestions (suggest)",
			},
		},
	},
	annotations: {
		title: "🦎 Vreko Fix",
		readOnlyHint: false,
		destructiveHint: true,
		idempotentHint: false,
	},
	tier: "pro",
};
