// ESM imports fixed for Node.js v22+
/**
 * Secure Workspace Session Storage
 *
 * Manages workspace-scoped session tokens using the same secure storage
 * hierarchy as the existing credentials system:
 * 1. OS Keychain (via keytar) - workspace-scoped keys
 * 2. Encrypted file fallback (AES-256-GCM)
 *
 * Registry (~/.vreko/workspaces.json) stores non-sensitive metadata.
 * Sensitive tokens are stored in OS keychain or encrypted file.
 *
 * @module workspace-storage
 */
import { mkdir, readFile, unlink, writeFile } from "node:fs/promises";
import { homedir, hostname, platform, userInfo } from "node:os";
import { dirname, join } from "node:path";
import { createEmptyRegistry, generateWorkspaceId, SessionTokensSchema, validateRegistry, } from "./workspace-session.js";
// =============================================================================
// CONSTANTS
// =============================================================================
/**
 * Get the global Vreko directory path with null safety validation
 * @throws Error if home directory cannot be determined
 */
function getGlobalDir() {
    const home = homedir();
    if (!home || typeof home !== "string") {
        throw new Error("Unable to determine home directory. Please ensure HOME environment variable is set.");
    }
    return join(home, ".vreko");
}
const GLOBAL_DIR = getGlobalDir();
const REGISTRY_FILE = join(GLOBAL_DIR, "workspaces.json");
const SERVICE_NAME = "vreko-cli-workspace";
// =============================================================================
// REGISTRY FILE OPERATIONS
// =============================================================================
/**
 * Read workspace session registry from disk
 */
export async function readRegistry() {
    try {
        const content = await readFile(REGISTRY_FILE, "utf-8");
        const data = JSON.parse(content);
        const validated = validateRegistry(data);
        return validated || createEmptyRegistry();
    }
    catch {
        return createEmptyRegistry();
    }
}
/**
 * Write workspace session registry to disk
 */
export async function writeRegistry(registry) {
    await mkdir(dirname(REGISTRY_FILE), { recursive: true });
    await writeFile(REGISTRY_FILE, JSON.stringify(registry, null, 2), { mode: 0o600 });
}
/**
 * Delete workspace session registry
 */
export async function deleteRegistry() {
    try {
        await unlink(REGISTRY_FILE);
    }
    catch {
        // Ignore if doesn't exist
    }
}
/**
 * Create keytar provider for workspace tokens
 */
async function createKeytarProvider() {
    try {
        const keytar = await import("keytar");
        return {
            name: "keytar",
            async isAvailable() {
                try {
                    await keytar.getPassword("__vreko_test__", "__test__");
                    return true;
                }
                catch {
                    return false;
                }
            },
            async getPassword(service, account) {
                return keytar.getPassword(service, account);
            },
            async setPassword(service, account, password) {
                await keytar.setPassword(service, account, password);
            },
            async deletePassword(service, account) {
                return keytar.deletePassword(service, account);
            },
        };
    }
    catch {
        return null;
    }
}
// =============================================================================
// ENCRYPTED FILE STORAGE (Fallback)
// =============================================================================
import { createCipheriv, createDecipheriv, randomBytes, scryptSync } from "node:crypto";
const ENCRYPTION_ALGORITHM = "aes-256-gcm";
const KEY_LENGTH = 32;
const IV_LENGTH = 12;
const AUTH_TAG_LENGTH = 16;
const SALT_LENGTH = 32;
function deriveMachineKey(salt) {
    const machineData = [hostname(), platform(), userInfo().username, homedir(), process.arch, process.platform].join("|");
    return scryptSync(machineData, salt, KEY_LENGTH);
}
function encryptData(data, salt) {
    const key = deriveMachineKey(salt);
    const iv = randomBytes(IV_LENGTH);
    const cipher = createCipheriv(ENCRYPTION_ALGORITHM, key, iv);
    const encrypted = Buffer.concat([cipher.update(data, "utf8"), cipher.final()]);
    const authTag = cipher.getAuthTag();
    return Buffer.concat([salt, iv, authTag, encrypted]);
}
function decryptData(data) {
    const salt = data.subarray(0, SALT_LENGTH);
    const iv = data.subarray(SALT_LENGTH, SALT_LENGTH + IV_LENGTH);
    const authTag = data.subarray(SALT_LENGTH + IV_LENGTH, SALT_LENGTH + IV_LENGTH + AUTH_TAG_LENGTH);
    const encrypted = data.subarray(SALT_LENGTH + IV_LENGTH + AUTH_TAG_LENGTH);
    const key = deriveMachineKey(salt);
    const decipher = createDecipheriv(ENCRYPTION_ALGORITHM, key, iv);
    decipher.setAuthTag(authTag);
    const decrypted = Buffer.concat([decipher.update(encrypted), decipher.final()]);
    return decrypted.toString("utf8");
}
const ENCRYPTED_TOKENS_FILE = join(GLOBAL_DIR, "workspace-tokens.enc");
async function readEncryptedTokens() {
    try {
        const data = await readFile(ENCRYPTED_TOKENS_FILE);
        const decrypted = decryptData(data);
        return JSON.parse(decrypted);
    }
    catch {
        return {};
    }
}
async function writeEncryptedTokens(tokens) {
    const salt = randomBytes(SALT_LENGTH);
    const encrypted = encryptData(JSON.stringify(tokens), salt);
    await mkdir(dirname(ENCRYPTED_TOKENS_FILE), { recursive: true });
    await writeFile(ENCRYPTED_TOKENS_FILE, encrypted, { mode: 0o600 });
}
// =============================================================================
// SECURE TOKEN STORAGE
// =============================================================================
class SecureTokenStorage {
    provider = null;
    initialized = false;
    async initialize() {
        if (this.initialized) {
            return;
        }
        const keytarProvider = await createKeytarProvider();
        if (keytarProvider && (await keytarProvider.isAvailable())) {
            this.provider = keytarProvider;
        }
        this.initialized = true;
    }
    getAccountName(workspaceId) {
        return `tokens_${workspaceId}`;
    }
    async getTokens(workspaceId) {
        await this.initialize();
        if (this.provider) {
            const stored = await this.provider.getPassword(SERVICE_NAME, this.getAccountName(workspaceId));
            if (stored) {
                try {
                    const parsed = JSON.parse(stored);
                    const validated = SessionTokensSchema.safeParse(parsed);
                    if (validated.success) {
                        return validated.data;
                    }
                }
                catch {
                    // Invalid format, fall through
                }
            }
        }
        // Fallback to encrypted file
        const tokens = await readEncryptedTokens();
        return tokens[workspaceId] || null;
    }
    async setTokens(workspaceId, tokens) {
        await this.initialize();
        if (this.provider) {
            await this.provider.setPassword(SERVICE_NAME, this.getAccountName(workspaceId), JSON.stringify(tokens));
            return;
        }
        // Fallback to encrypted file
        const allTokens = await readEncryptedTokens();
        allTokens[workspaceId] = tokens;
        await writeEncryptedTokens(allTokens);
    }
    async deleteTokens(workspaceId) {
        await this.initialize();
        if (this.provider) {
            await this.provider.deletePassword(SERVICE_NAME, this.getAccountName(workspaceId));
        }
        // Also clean up from encrypted file
        const allTokens = await readEncryptedTokens();
        delete allTokens[workspaceId];
        await writeEncryptedTokens(allTokens);
    }
    async clearAllTokens() {
        await this.initialize();
        // Get all workspace IDs from registry
        const registry = await readRegistry();
        const workspaceIds = Object.keys(registry.workspaces);
        // Delete from keychain
        if (this.provider) {
            for (const workspaceId of workspaceIds) {
                await this.provider.deletePassword(SERVICE_NAME, this.getAccountName(workspaceId));
            }
        }
        // Delete encrypted file
        try {
            await unlink(ENCRYPTED_TOKENS_FILE);
        }
        catch {
            // Ignore
        }
    }
}
// Singleton instance
let secureTokenStorage = null;
function getSecureTokenStorage() {
    if (!secureTokenStorage) {
        secureTokenStorage = new SecureTokenStorage();
    }
    return secureTokenStorage;
}
// =============================================================================
// HIGH-LEVEL WORKSPACE STORAGE API
// =============================================================================
/**
 * Store workspace session (metadata in registry, tokens in secure storage)
 */
export async function storeWorkspaceSession(workspacePath, entry) {
    const workspaceId = generateWorkspaceId(workspacePath);
    const registry = await readRegistry();
    // Store metadata in registry (non-sensitive)
    registry.workspaces[workspaceId] = {
        ...entry,
        workspaceId,
        workspacePath,
    };
    // Store tokens in secure storage
    await getSecureTokenStorage().setTokens(workspaceId, entry.session);
    // Save registry
    await writeRegistry(registry);
}
/**
 * Get workspace session (combines registry metadata with secure tokens)
 */
export async function getWorkspaceSession(workspacePath) {
    const workspaceId = generateWorkspaceId(workspacePath);
    const registry = await readRegistry();
    const metadata = registry.workspaces[workspaceId];
    if (!metadata) {
        return null;
    }
    // Get tokens from secure storage
    const tokens = await getSecureTokenStorage().getTokens(workspaceId);
    if (!tokens) {
        return null;
    }
    return {
        ...metadata,
        session: tokens,
    };
}
/**
 * Update workspace session tokens (e.g., after refresh)
 */
export async function updateWorkspaceSessionTokens(workspacePath, tokens) {
    const workspaceId = generateWorkspaceId(workspacePath);
    const registry = await readRegistry();
    const metadata = registry.workspaces[workspaceId];
    if (!metadata) {
        throw new Error(`Workspace session not found: ${workspacePath}`);
    }
    // Update tokens in secure storage
    await getSecureTokenStorage().setTokens(workspaceId, tokens);
    // Update metadata
    metadata.updatedAt = new Date().toISOString();
    metadata.session = tokens; // Also update in registry for expiry tracking
    await writeRegistry(registry);
}
/**
 * Update last used timestamp
 */
export async function touchWorkspaceSession(workspacePath) {
    const workspaceId = generateWorkspaceId(workspacePath);
    const registry = await readRegistry();
    const metadata = registry.workspaces[workspaceId];
    if (metadata) {
        metadata.lastUsedAt = new Date().toISOString();
        await writeRegistry(registry);
    }
}
/**
 * Delete workspace session
 */
export async function deleteWorkspaceSession(workspacePath) {
    const workspaceId = generateWorkspaceId(workspacePath);
    const registry = await readRegistry();
    delete registry.workspaces[workspaceId];
    await writeRegistry(registry);
    await getSecureTokenStorage().deleteTokens(workspaceId);
}
/**
 * List all workspace sessions (without tokens, but with expiresAt)
 */
export async function listWorkspaceSessions() {
    const registry = await readRegistry();
    return Object.values(registry.workspaces).map(({ session, ...metadata }) => ({
        ...metadata,
        expiresAt: session.expiresAt,
    }));
}
/**
 * Store global fallback credentials
 */
export async function storeGlobalFallback(entry) {
    const registry = await readRegistry();
    registry.global = entry;
    await writeRegistry(registry);
}
/**
 * Get global fallback credentials
 */
export async function getGlobalFallback() {
    const registry = await readRegistry();
    return registry.global || null;
}
/**
 * Clear global fallback
 */
export async function clearGlobalFallback() {
    const registry = await readRegistry();
    delete registry.global;
    await writeRegistry(registry);
}
/**
 * Clear all workspace sessions
 */
export async function clearAllWorkspaceSessions() {
    await getSecureTokenStorage().clearAllTokens();
    await deleteRegistry();
}
/**
 * Cleanup expired sessions
 */
export async function cleanupExpiredSessions() {
    const registry = await readRegistry();
    const now = new Date();
    let cleaned = 0;
    for (const [workspaceId, entry] of Object.entries(registry.workspaces)) {
        const expiresAt = new Date(entry.session.expiresAt);
        if (expiresAt < now) {
            delete registry.workspaces[workspaceId];
            await getSecureTokenStorage().deleteTokens(workspaceId);
            cleaned++;
        }
    }
    registry.lastCleanupAt = now.toISOString();
    await writeRegistry(registry);
    return cleaned;
}
