/**
 * Check Modes Registry - Single Source of Truth
 *
 * This registry is the authoritative source for all check tool modes.
 * All consumers (inputSchema, param-normalizer, snap_help) derive from this.
 *
 * @module check-modes-registry
 * @see SB-179 - Consolidated tool refactoring
 */

// =============================================================================
// Types
// =============================================================================

/**
 * Category grouping for check modes
 */
export type CheckModeCategory = "validation" | "analysis" | "security" | "maintenance";

/**
 * Definition of a single check mode
 */
export interface CheckModeDefinition {
	/** Mode name (used in API calls) */
	name: string;
	/** Short description for help text */
	description: string;
	/** Category for grouping in documentation */
	category: CheckModeCategory;
	/** Estimated execution time */
	estimatedTime: string;
	/** Whether the mode is currently implemented */
	implemented: boolean;
}

