// =============================================================================
// Derived Exports
// =============================================================================

/**
 * Get all implemented mode names
 * Used by inputSchema.enum and CHECK_MODE_MAP
 */
export const IMPLEMENTED_CHECK_MODES: string[] = CHECK_MODE_REGISTRY.filter((m) => m.implemented).map((m) => m.name);

/**
 * Get count of implemented modes
 */
export const IMPLEMENTED_MODE_COUNT = IMPLEMENTED_CHECK_MODES.length;

/**
 * Get all mode names (including unimplemented)
 */
export const ALL_CHECK_MODE_NAMES: string[] = CHECK_MODE_REGISTRY.map((m) => m.name);

/**
 * Get mode definition by name
 */
export function getCheckModeDefinition(name: string): CheckModeDefinition | undefined {
	return CHECK_MODE_REGISTRY.find((m) => m.name === name);
}

/**
 * Check if a mode is implemented
 */
export function isCheckModeImplemented(name: string): boolean {
	const mode = getCheckModeDefinition(name);
	return mode?.implemented ?? false;
}

/**
 * Get modes by category
 */
export function getCheckModesByCategory(category: CheckModeCategory): CheckModeDefinition[] {
	return CHECK_MODE_REGISTRY.filter((m) => m.category === category && m.implemented);
}

/**
 * Generate formatted mode list for documentation
 */
export function formatCheckModesList(includeUnimplemented = false): string {
	const modes = includeUnimplemented ? CHECK_MODE_REGISTRY : CHECK_MODE_REGISTRY.filter((m) => m.implemented);

	const lines = modes.map((m) => {
		const prefix = m.implemented ? "  " : "  [ROADMAP] ";
		const suffix = m.implemented ? "" : " (not yet implemented)";
		return `${prefix}${m.name.padEnd(12)} - ${m.description} ${m.estimatedTime}${suffix}`;
	});

	return lines.join("\n");
}
