/**
 * Session reporter for vreko-end module
 *
 * Generates celebration messages, narratives, and next steps.
 *
 * @module tools/consolidated/vreko-end/session-reporter
 */

import type { CeremonyResult, EfficiencyMetrics, LearningTrajectorySummary, SnapEndParams } from "./types.js";

// =============================================================================
// CELEBRATION & NARRATIVE
// =============================================================================

/**
 * Generate intelligent celebration message based on session metrics.
 * This is where Vreko brags about what it did this session.
 */
export function generateCelebrationMessage(
	metrics: EfficiencyMetrics,
	ceremonyResult: CeremonyResult | undefined,
	params: SnapEndParams,
	trajectory?: LearningTrajectorySummary,
): string {
	const celebrations: string[] = [];

	if (metrics.saved !== "not reported") {
		celebrations.push(
			`🦎 Vreko saved you ${metrics.saved} tokens  -  context that would've been lost without protection.`,
		);
	}

	if (metrics.prevented !== "none reported") {
		celebrations.push(
			`🛡️ Prevented ${metrics.prevented} - your repository's patterns caught this before you wasted time.`,
		);
	}

	if (metrics.newLearnings > 0) {
		celebrations.push(
			`✨ ${metrics.newLearnings} new learning(s) added  -  these patterns will inform every future session.`,
		);
	}

	if (metrics.helped && metrics.helped !== "general context") {
		celebrations.push(
			`📚 Vreko surfaced "${metrics.helped}" at exactly the right time - that's clairvoyant context injection.`,
		);
	}

	if (ceremonyResult?.passed) {
		const checksRun = ceremonyResult.steps.length;
		celebrations.push(
			`✅ ${ceremonyResult.level} ceremony passed (${checksRun} checks) - you're shipping this change with confidence.`,
		);
	}

	if (params.survey?.patterns_used && params.survey.patterns_used > 0) {
		celebrations.push(
			"🎯 Applied " +
				`${params.survey.patterns_used} learned pattern(s) - your codebase memory is actively protecting this session.`,
		);
	}

	if (params.survey?.pitfalls_avoided && params.survey.pitfalls_avoided > 0) {
		celebrations.push(
			"⚡ Avoided " +
				`${params.survey.pitfalls_avoided} pitfall(s) you've hit before - learning compound interest in action.`,
		);
	}

	if (trajectory && trajectory.totalTracked > 0) {
		const hotText = typeof trajectory.hotTier === "number" ? ` (${trajectory.hotTier} hot patterns)` : "";
		celebrations.push(`📊 Repository intelligence: ${trajectory.totalTracked} tracked learnings${hotText}`);
	}

	return celebrations.length > 0
		? `\n🦎 Vreko Session Complete:\n${celebrations.map((c) => `   ${c}`).join("\n")}\n`
		: "";
}

/**
 * Generate a short narrative about what happened during the session.
 */
export function generateSessionNarrative(
	data: Record<string, unknown>,
	metrics: EfficiencyMetrics,
	params: SnapEndParams,
): string {
	const story: string[] = [];
	const filesModified = (data.filesModified as number) || 0;

	if (filesModified > 0) {
		story.push(`📝 Modified ${filesModified} file(s)`);
	}

	if (metrics.helped !== "general context") {
		story.push(`🧠 Injected relevant context: "${metrics.helped}"`);
	}

	if (params.survey?.patterns_used && params.survey.patterns_used > 0) {
		story.push(`🎯 Applied ${params.survey.patterns_used} learned pattern(s) from your repo history`);
	}

	if (metrics.prevented !== "none reported") {
		story.push(`🛡️ Prevented mistakes: ${metrics.prevented}`);
	}

	if (metrics.newLearnings > 0) {
		story.push(`✨ Captured ${metrics.newLearnings} new learning(s) for future sessions`);
	}

	const outcome = params.outcome || (params.ok === 1 ? "completed" : "incomplete");
	const outcomeEmoji =
		outcome === "completed" ? "✅" : outcome === "abandoned" ? "⏸️" : outcome === "blocked" ? "🚫" : "✅";

	return story.length > 0
		? `\n${outcomeEmoji} Session ${outcome}:\n${story.map((s) => `   • ${s}`).join("\n")}\n`
		: "";
}

/**
 * Suggest next steps based on session outcome and validation state.
 */
export function suggestNextSteps(
	params: SnapEndParams,
	ceremonyResult?: CeremonyResult,
	data?: Record<string, unknown>,
): string[] {
	const suggestions: string[] = [];
	const filesModified = (data?.filesModified as number) || 0;
	const linesAdded = (data?.linesAdded as number) || 0;
	const linesRemoved = (data?.linesRemoved as number) || 0;
	const totalLinesChanged = linesAdded + linesRemoved;

	// No ceremony was run
	if (!params.ceremony) {
		if (filesModified > 10 || totalLinesChanged > 500) {
			suggestions.push(
				"Large change detected - strongly recommend: snap_end({ ceremony: 'standard' }) before committing.",
			);
		} else if (filesModified > 5) {
			suggestions.push(
				"Consider running snap_end({ ceremony: 'quick' }) before committing to add a validation gate.",
			);
		}
	}

	// Ceremony ran but failed
	if (ceremonyResult && !ceremonyResult.passed) {
		suggestions.push(`Fix ${ceremonyResult.blockers.length} ceremony blocker(s), then re-run ceremony.`);
	}

	// Ceremony passed - green light
	if (ceremonyResult?.passed) {
		suggestions.push("All checks passed - ready to commit with confidence.");
	}

	// High pattern usage - suggest architecture check
	if (params.survey?.patterns_used && params.survey.patterns_used > 3) {
		suggestions.push("High pattern usage! Consider check({ mode: 'architecture' }) to validate consistency.");
	}

	// Successful outcome without ceremony
	if ((params.outcome === "completed" || params.ok === 1) && !ceremonyResult && filesModified > 0) {
		suggestions.push("Capture any new patterns with snap_learn() before context resets.");
	}

	return suggestions;
}
