/**
 * Backend Router
 *
 * Routes tool calls to either daemon (local/IPC) or remote API (HTTPS).
 * Determines backend target based on tool name and configuration.
 *
 * @module bridge/router
 */

import { REMOTE_ONLY_TOOLS } from "./remote-client.js";
import type { BackendRouter, BackendTarget, ResolvedRemoteConfig } from "./types.js";

// =============================================================================
// Tool Classification
// =============================================================================

/**
 * Tools that MUST be served by remote API.
 * These are Pro-tier features that require server-side intelligence.
 */
const REMOTE_ONLY_TOOL_NAMES = new Set(REMOTE_ONLY_TOOLS.map((t) => t.name));

/**
 * Tools that can use remote as enhancement but fall back to daemon.
 * Daemon provides local result; remote enriches it with ML insights.
 *
 * Future: Tools where daemon gives local answer, remote adds ML insights
 */
const REMOTE_ENHANCED_TOOLS = new Set<string>([
	// Future enhanced tools:
	// "vreko",  // Daemon gives context, remote adds ML predictions
	// "check",     // Daemon runs local checks, remote adds cloud analysis
]);

/**
 * V2 tools that should always route to daemon.
 * These are the core tools that work entirely locally.
 */
const DAEMON_PREFERRED_TOOLS = new Set([
	"vreko",
	"vreko_learn",
	"vreko_end",
	"vreko_pulse",
	"vreko",
	"check",
	"advise",
	"guide",
	"pulse",
]);

// =============================================================================
// Router Factory
// =============================================================================

/**
 * Create a backend router that determines where tool calls should be dispatched.
 *
 * @param remoteConfig - Resolved remote configuration, or null if remote is disabled
 * @returns Router instance with routing methods
 */
export function createBackendRouter(remoteConfig: ResolvedRemoteConfig | null): BackendRouter {
	return {
		/**
		 * Determine backend for a tool call.
		 *
		 * Routing rules:
		 * 1. If no remote config → always daemon
		 * 2. If tool is in REMOTE_ONLY_TOOL_NAMES → remote
		 * 3. If tool is in REMOTE_ENHANCED_TOOLS → remote (with fallback)
		 * 4. If tool is in DAEMON_PREFERRED_TOOLS → daemon
		 * 5. Default → daemon
		 *
		 * @param toolName - Name of the tool being called
		 * @returns Backend target
		 */
		route(toolName: string): BackendTarget {
			// No remote configured → everything goes to daemon
			if (!remoteConfig) {
				return "daemon";
			}

			// Remote-only tools (Pro-tier features)
			if (REMOTE_ONLY_TOOL_NAMES.has(toolName)) {
				return "remote";
			}

			// Remote-enhanced tools (can use remote for enrichment)
			if (REMOTE_ENHANCED_TOOLS.has(toolName)) {
				return "remote";
			}

			// Daemon-preferred tools (core functionality)
			if (DAEMON_PREFERRED_TOOLS.has(toolName)) {
				return "daemon";
			}

			// Default: daemon for safety
			return "daemon";
		},

		/**
		 * Check if remote backend is configured.
		 */
		hasRemote(): boolean {
			return remoteConfig !== null;
		},

		/**
		 * Get list of remote-only tool names.
		 */
		getRemoteTools(): string[] {
			return Array.from(REMOTE_ONLY_TOOL_NAMES);
		},
	};
}

// =============================================================================
// Utility Functions
// =============================================================================

/**
 * Check if a tool name is a remote-only tool.
 *
 * @param toolName - Tool name to check
 * @returns true if tool requires remote backend
 */
export function isRemoteOnlyTool(toolName: string): boolean {
	return REMOTE_ONLY_TOOL_NAMES.has(toolName);
}

/**
 * Check if a tool name is a daemon-preferred tool.
 *
 * @param toolName - Tool name to check
 * @returns true if tool should prefer daemon backend
 */
export function isDaemonPreferredTool(toolName: string): boolean {
	return DAEMON_PREFERRED_TOOLS.has(toolName);
}

/**
 * Get all tool names that require remote backend.
 */
export function getRemoteToolNames(): string[] {
	return Array.from(REMOTE_ONLY_TOOL_NAMES);
}
