/**
 * Shared V2 surface registration (ARCH-09)
 *
 * Both transports  -  stdio (`createMcpServer` auto-populate path in `server.ts`)
 * and HTTP/remote (`HttpTransportManager.ensureRegistryInitialized` in
 * `transport/http.ts`)  -  must advertise EXACTLY the four V2 tools in
 * `tools/list`: `vreko`, `vreko_pulse`, `vreko_learn`, `vreko_end`.
 *
 * Previously the V2 registration block lived inline in `server.ts` only, so the
 * HTTP transport (which seeded only the adapted consolidated tools = minimal 3)
 * silently diverged and omitted `vreko_pulse`. This helper is the single source
 * of that registration so the two surfaces cannot drift again.
 *
 * @module registry/apply-v2-surface
 */

import { createRequestContext, logError } from "../errors/index.js";
import type { ToolHandler, VrekoTool } from "../types/tool-types.js";
import { adaptLegacyTools } from "./adapter.js";
import type { ToolRegistry } from "./ToolRegistry.js";

/**
 * Register the V2 tool surface onto a registry, taking precedence over any
 * same-named consolidated tools that were already seeded.
 *
 * Idempotent with respect to tool identity: a same-named entry is unregistered
 * before the V2 tool is registered, so calling this after the adapted
 * consolidated tools are seeded yields exactly the V2 surface for those names.
 *
 * @returns the number of V2 tools successfully registered.
 * @throws if zero V2 tools register  -  the MCP server cannot serve its primary
 *   tool surface, so callers should treat this as a fatal startup error.
 */
export async function applyV2Surface(registry: ToolRegistry): Promise<number> {
	const startupCtx = createRequestContext("vreko-mcp-startup");
	let v2RegisteredCount = 0;

	try {
		const { V2_TOOLS, V2_HANDLERS } = await import("../tools/v2/index.js");

		// Adapt V2 tools using their handlers
		const v2ToolPairs = V2_TOOLS.map((tool) => [tool, V2_HANDLERS[tool.name]]) as Array<[VrekoTool, ToolHandler]>;

		const adaptedV2Tools = adaptLegacyTools(v2ToolPairs);
		for (const tool of adaptedV2Tools) {
			try {
				// V2 tools take precedence over consolidated tools with same name
				if (registry.has(tool.name)) {
					registry.unregister?.(tool.name);
				}
				registry.register(tool);
				v2RegisteredCount++;
			} catch (perToolError) {
				const msg = perToolError instanceof Error ? perToolError.message : String(perToolError);
				logError(
					startupCtx,
					"E503_INTERNAL_ERROR" as Parameters<typeof logError>[1],
					`V2 tool registration failed for '${tool.name}': ${msg}`,
					{ toolName: tool.name },
				);
			}
		}
	} catch (err) {
		const msg = err instanceof Error ? err.message : String(err);
		logError(
			startupCtx,
			"E503_INTERNAL_ERROR" as Parameters<typeof logError>[1],
			`V2 tool import/adapt failed: ${msg}`,
		);
	}

	if (v2RegisteredCount === 0) {
		throw new Error(
			"V2 tool registration failed: zero of 4 tools registered. " +
				"The MCP server cannot start without its primary tool surface. " +
				"Check server logs for per-tool errors.",
		);
	}

	return v2RegisteredCount;
}
