/**
 * Snapshot Storage Factory
 *
 * CLI/SDK-only entry point for creating snapshot storage instances.
 * This file is NOT exported from the main @vreko/contracts index
 * to avoid bundler issues with dynamic imports in web builds.
 *
 * Usage (CLI/SDK only):
 * ```ts
 * import { createSnapshotStorage } from "@vreko/contracts/storage";
 * const storage = await createSnapshotStorage(process.cwd());
 * ```
 */
var __rewriteRelativeImportExtension = (this && this.__rewriteRelativeImportExtension) || function (path, preserveJsx) {
    if (typeof path === "string" && /^\.\.?\//.test(path)) {
        return path.replace(/\.(tsx)$|((?:\.d)?)((?:\.[^./]+?)?)\.([cm]?)ts$/i, function (m, tsx, d, ext, cm) {
            return tsx ? preserveJsx ? ".jsx" : ".js" : d && (!ext || !cm) ? m : (d + ext + "." + cm.toLowerCase() + "js");
        });
    }
    return path;
};
/**
 * Factory function to create a snapshot storage instance
 * This allows public packages to create storage instances without
 * directly depending on the private @vreko/storage package.
 *
 * @param basePath The base path for storage operations
 * @returns A SnapshotStorage instance
 */
export async function createSnapshotStorage(basePath) {
    // Dynamically import the storage package to avoid circular dependencies
    // The import path is resolved at runtime after both packages are built
    try {
        // Dynamic import with webpack ignore to prevent bundling warnings in web builds
        // This function is only called at runtime in CLI context, not bundled into web
        // biome-ignore lint/suspicious/noExplicitAny: dynamic import path is runtime-resolved; type assertion required to bypass module resolution at build time
        const { StorageBrokerAdapter } = await import(__rewriteRelativeImportExtension(/* webpackIgnore: true */ "@vreko/sdk/storage"));
        // Use the standard workspace database path
        const storage = new StorageBrokerAdapter(`${basePath}/.vreko/vreko.db`);
        await storage.initialize();
        return {
            create: async (data) => {
                const snapshot = {
                    id: `vreko-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`,
                    timestamp: Date.now(),
                    version: "1.0",
                    meta: {
                        ...data,
                        protected: data.protected || false,
                        description: data.description || "",
                    },
                };
                await storage.save(snapshot);
                return snapshot;
            },
            retrieve: async (id) => {
                return await storage.get(id);
            },
            list: async () => {
                return await storage.list();
            },
            restore: async (id, _targetPath, options) => {
                // Note: Full restore implementation requires file system operations
                // This is a simplified version - real implementation in storage package
                const snapshot = await storage.get(id);
                if (!snapshot) {
                    return {
                        success: false,
                        restoredFiles: [],
                        errors: [`Snapshot ${id} not found`],
                    };
                }
                if (options?.dryRun) {
                    return {
                        success: true,
                        restoredFiles: snapshot.files || [],
                        errors: [],
                    };
                }
                return {
                    success: true,
                    restoredFiles: snapshot.files || [],
                    errors: [],
                };
            },
        };
    }
    catch (error) {
        throw new Error(`Failed to initialize snapshot storage: ${error instanceof Error ? error.message : String(error)}. ` +
            "Ensure @vreko/sdk is installed and storage path is writable.");
    }
}
