/**
 * Vreko Learn Tool (V2) - Learning Capture
 *
 * Record a discovery about this codebase that should be remembered across sessions.
 * Call this when you notice something surprising, fragile, or important.
 *
 * This is a black-box formatting layer on top of the daemon intelligence engine.
 * The tool does NOT compute, store, or decide  -  it formats daemon responses
 * into LLM-consumable natural language payloads.
 *
 * @module tools/v2/vreko-learn
 */

import { LearningType } from "@vreko/contracts/local-service/schemas";
import type { z } from "zod";
import { MAX_LENGTHS, normalizeContent } from "../../security/input-sanitization.js";
import type { ToolHandler, ToolResult, VrekoTool } from "../../types/tool-types.js";
import { getToolCreditEstimate } from "./utils/credit-registry.js";
import {
	buildLearningSearchParams,
	buildSessionCurrentParams,
	buildSessionStartParams,
	formatDaemonError,
	formatDegradedModeResponse,
	formatUnexpectedError,
	getDaemonClient,
	isActiveSession,
	isDaemonConnectionError,
	isDaemonNullResponse,
	resolveWorkspace,
} from "./utils/index.js";
import { appendToPendingQueue } from "./utils/pending-queue.js";
import { logNonFatalError } from "./utils/telemetry.js";

// =============================================================================
// Types
// =============================================================================

export interface VrekoLearnParams {
	/** The condition under which this rule applies. Starts with "when". */
	trigger: string;
	/** What to do when the trigger fires. Starts with a verb. */
	action: string;
	/** Files this rule is scoped to. Narrows future retrieval relevance. */
	files?: string[];
	/** Controls how this learning surfaces in future briefings. */
	type?: z.infer<typeof LearningType>;
	/** critical surfaces in vreko even on cold start. */
	severity?: "info" | "warning" | "critical";
	/** @deprecated Use trigger + action instead. Kept for backward compatibility. */
	insight?: string;
}

interface SessionCurrentResult {
	/** Legacy field  -  may not be present in all daemon versions */
	active?: boolean;
	/** Actual field from daemon: "active" | "ended" | "idle" */
	state?: string;
	id?: string;
	taskId?: string;
}

interface LearningAddResult {
	success: boolean;
	id?: string;
	tier?: string;
}

interface LearningSearchResult {
	results?: Array<{
		id?: string;
		solution?: string;
		insight?: string;
		content?: string;
	}>;
	learnings?: Array<{
		type?: string;
		trigger?: string;
		action?: string;
		relevanceScore?: number;
	}>;
}

// =============================================================================
// Handler
// =============================================================================

/**
 * Handle vreko_learn tool call
 *
 * Flow:
 * 1. Check for active session (create implicitly if needed)
 * 2. Map parameters to daemon learning format
 * 3. Add the learning via daemon
 * 4. Search for related learnings (reinforcement loop)
 * 5. Format as natural language response
 */
export const handleVrekoLearn: ToolHandler = async (args, context): Promise<ToolResult> => {
	// HIGH-2: Sanitize free-text fields to prevent prompt injection
	const rawArgs = args as Record<string, unknown>;
	const sanitizedArgs: VrekoLearnParams = {
		...(rawArgs as unknown as VrekoLearnParams),
		...(typeof rawArgs.trigger === "string" && {
			trigger: normalizeContent(rawArgs.trigger).slice(0, MAX_LENGTHS.trigger),
		}),
		...(typeof rawArgs.action === "string" && {
			action: normalizeContent(rawArgs.action).slice(0, MAX_LENGTHS.action),
		}),
		...(typeof rawArgs.insight === "string" && {
			insight: normalizeContent(rawArgs.insight).slice(0, MAX_LENGTHS.trigger),
		}),
	};

	const params = sanitizedArgs;
	const workspace = resolveWorkspace(context);
	const daemon = getDaemonClient(workspace);
	const severity = params.severity ?? "info";

	// Resolve trigger/action from params with backward compat for deprecated 'insight'
	const trigger = params.trigger ?? params.insight ?? "";
	const action = params.action ?? deriveAction(params.insight ?? "", severity);
	// Prefer explicit type; fall back to severity-derived type
	const type = params.type ?? mapSeverityToType(severity);

	// Step 1: Ensure session exists (implicit creation if needed)
	let implicitSession = false;
	let currentSessionId: string | undefined;
	let daemonAvailable = true;
	try {
		const currentSession = await daemon.request<SessionCurrentResult>(
			"session/current",
			buildSessionCurrentParams(workspace),
		);

		// NOTE: daemon.request() swallows errors and returns null rather than throwing.
		// isDaemonConnectionError() in the catch below is dead code in practice  -  handle
		// null responses here instead.
		if (isDaemonNullResponse(currentSession)) {
			// Daemon unreachable  -  skip session gate but still attempt learning/add below.
			// This keeps vreko_learn consistent with vreko() which degrades gracefully
			// rather than failing immediately. The learning may still be stored by the daemon
			// if only the session lookup failed.
			daemonAvailable = false;
		} else if (!isActiveSession(currentSession)) {
			// Use shared utility for consistent session state check
			// No active session  -  create one implicitly
			const beginResult = await daemon.request<{ sessionId?: string; taskId?: string }>(
				"session/start",
				buildSessionStartParams(workspace, {
					task: "Implicit session (learning captured before explicit session start)",
					files: params.files ?? [],
				}),
			);
			// Bug fix: only claim implicit session was created when session/start actually succeeded.
			// Previously this was always set to true, falsely reporting "session created" even when
			// the daemon returned null (offline or error).
			if (!isDaemonNullResponse(beginResult)) {
				currentSessionId = beginResult?.sessionId ?? beginResult?.taskId;
				implicitSession = true;
			} else {
				// session/start returned null  -  daemon went offline between session/current
				// and session/start. Mark unavailable so learning/add null triggers queue-write.
				daemonAvailable = false;
			}
		} else {
			// GAP 1 FIX: Extract sessionId for ceremony attribution
			currentSessionId = currentSession.id ?? currentSession.taskId;
		}
	} catch (error) {
		if (isDaemonConnectionError(error)) {
			daemonAvailable = false;
		}
		// Continue anyway  -  try to add the learning
	}

	// Step 2: Map parameters to daemon learning format
	const learningPayload = {
		type,
		trigger,
		action,
		source: "llm-observation" as const,
	};

	// Step 3: Add the learning
	// GAP 1 FIX: Thread sessionId for ceremony attribution
	let addResult: LearningAddResult | null = null;
	try {
		addResult = await daemon.request<LearningAddResult>("learning/add", {
			workspace,
			...learningPayload,
			...(currentSessionId ? { sessionId: currentSessionId } : {}),
		});
	} catch (error) {
		if (isDaemonConnectionError(error)) {
			return formatDaemonError();
		}
		return formatUnexpectedError("learning add", error);
	}

	// If the daemon returned null for learning/add, the learning was NOT persisted.
	// Use degraded mode response (not an error) to keep parity with vreko()'s graceful degradation.
	if (isDaemonNullResponse(addResult)) {
		if (!daemonAvailable) {
			// Write to pending.jsonl so the learning survives until the daemon comes back.
			// The next vreko call will drain this file and replay the entries via IPC.
			try {
				appendToPendingQueue(workspace, {
					type,
					trigger,
					action,
					source:
						typeof (args as Record<string, unknown>).source === "string"
							? ((args as Record<string, unknown>).source as string)
							: undefined,
					queuedAt: new Date().toISOString(),
				});
			} catch {
				// Non-fatal: if queue write fails, still return the degraded response.
				// The learning will be lost, but we don't interrupt the AI coding flow.
			}
			return formatDegradedModeResponse(`Learning queued (offline): when ${trigger} → ${action}`, {
				reason: "null_response",
				featuresAvailable: [],
				featuresUnavailable: [
					"Learning storage (daemon offline  -  start with `vreko daemon start`)",
					"Related learning lookup",
					"Session attribution",
				],
			});
		}
		// Daemon is running but learning/add returned null  -  internal daemon error
		return formatDaemonError("null_response");
	}

	// Step 4: Search for related learnings (reinforcement loop)
	let relatedLearnings: string[] = [];
	try {
		const searchResult = await daemon.request<LearningSearchResult>(
			"learning/search",
			buildLearningSearchParams(workspace, trigger, 5),
		);

		const related = searchResult?.results
			? searchResult.results
					.filter((r) => r.id !== addResult?.id)
					.map((r) => r.solution ?? r.insight ?? r.content)
					.filter((v): v is string => Boolean(v))
			: (searchResult?.learnings ?? [])
					.map((r) => (r.trigger && r.action ? `${r.trigger} -> ${r.action}` : undefined))
					.filter((v): v is string => Boolean(v));
		relatedLearnings = related.slice(0, 3);
	} catch (error) {
		// Search failure is non-fatal  -  learning was still captured
		logNonFatalError({
			tool: "vreko_learn",
			operation: "learning/search",
			workspace,
			error,
			metadata: { trigger, learningId: addResult?.id },
		});
	}

	// Step 5: Format response
	// Note: addResult is guaranteed non-null here due to the isDaemonNullResponse guard above.
	return formatLearnResponse({
		captured: addResult?.success === true,
		implicitSession,
		relatedLearnings,
		severity,
		type,
		trigger,
		action,
	});
};

// =============================================================================
// Response Formatter
// =============================================================================

interface FormatLearnParams {
	captured: boolean;
	implicitSession: boolean;
	relatedLearnings: string[];
	severity: string;
	type: string;
	trigger: string;
	action: string;
}

function formatLearnResponse(data: FormatLearnParams): ToolResult {
	const sections: string[] = [];

	// Echo the encoded rule so the LLM can verify it captured the right thing
	const typeLabel = data.type !== "pattern" ? ` [${data.type}]` : "";
	sections.push(`Rule encoded${typeLabel} (${data.severity}): when ${data.trigger} → ${data.action}`);

	if (data.implicitSession) {
		sections.push(
			"\nNote: No active session was found, so one was created automatically. For full codebase intelligence, call `vreko` before starting work.",
		);
	}

	if (data.relatedLearnings.length > 0) {
		sections.push(`\n## Related Knowledge (${data.relatedLearnings.length} existing)\n`);
		sections.push("Previous rules about this area:");
		for (const learning of data.relatedLearnings) {
			sections.push(`- ${learning}`);
		}
	}

	const creditEstimate = getToolCreditEstimate("vreko_learn");
	return {
		content: [{ type: "text", text: sections.join("\n") }],
		structuredContent: creditEstimate ? { creditsEstimate: creditEstimate } : {},
	};
}

// =============================================================================
// Mapping Helpers
// =============================================================================

function mapSeverityToType(severity: "info" | "warning" | "critical"): string {
	switch (severity) {
		case "critical":
			return "pitfall";
		case "warning":
			return "pitfall";
		case "info":
			return "pattern";
	}
}

function deriveAction(_insight: string, severity: string): string {
	if (severity === "critical") {
		return "CRITICAL: Review this before modifying related files";
	}
	if (severity === "warning") {
		return "Warning: Be cautious when working in this area";
	}
	return "Consider this pattern when working with related files";
}

// =============================================================================
// Tool Definition
// =============================================================================

export const vrekoLearnTool: VrekoTool = {
	name: "vreko_learn",
	description: `Encode a reusable IF/THEN rule into the workspace knowledge base. trigger: the condition under which this rule applies ('when editing auth.ts without running tests'). action: what to do when that condition is true ('always snapshot before touching token refresh logic'). Not for observations or file annotations  -  call vreko_pulse with a query param for retrieval.

CALL IMMEDIATELY WHEN:
- User corrects an assumption you made ("Actually, we use X not Y")
- You discover a codebase pattern that contradicts your expectations
- An error reveals an unknown constraint or fragile dependency
- You find undocumented behavior that future sessions must know about
- You identify a team preference or hard rule

WHEN NOT TO CALL:
- To retrieve learnings → vreko_pulse with query param (read-only)
- For trivial observations that won't matter in future sessions
- To confirm expected/standard behavior

WORKFLOW POSITION: Anytime during a session.
  vreko → [work] → vreko_learn → [work] → vreko_learn → vreko_end

  Works without an active session, but for full intelligence context,
  call vreko first. Without a session, learnings are stored but
  not attributed to any task in the closing ceremony.

WHAT YOU GET BACK (natural language text):
- Confirmation the rule was stored
- Related learnings already in the knowledge base (deduplication loop)

EXAMPLE:
vreko_learn({
  trigger: "when modifying token refresh logic in auth.ts",
  action: "snapshot first  -  this code has 3 rollbacks across 2 sessions",
  type: "pitfall",
  severity: "warning",
  files: ["src/auth/auth.ts"]
})`,
	inputSchema: {
		type: "object",
		properties: {
			trigger: {
				type: "string",
				title: "Condition",
				description: `The condition. Starts with 'when'  -  when X is true, when Y happens, when you're in Z state.

GOOD: "when editing auth.ts without running tests first"
GOOD: "when the daemon restarts during an active session"
BAD:  "auth.ts is fragile"
BAD:  "I noticed something"`,
			},
			action: {
				type: "string",
				title: "Action",
				description: `What to do when the trigger fires. Starts with a verb.

GOOD: "always snapshot before touching token refresh logic"
GOOD: "check that session.json was cleaned up before starting a new session"
BAD:  "be careful"
BAD:  "token refresh is tricky"`,
			},
			files: {
				type: "array",
				items: { type: "string" },
				title: "Related Files",
				description: `Files this rule is scoped to. Narrows retrieval relevance.

Example: ["src/services/session-registry.ts"]`,
			},
			type: {
				type: "string",
				enum: LearningType.options,
				title: "Rule Type",
				description: `Controls how this learning surfaces in future briefings.

"pattern"     -  A repeating structure worth following
"pitfall"     -  A known failure mode to avoid
"constraint"  -  A hard rule that must not be violated
"preference"  -  A soft team preference`,
			},
			severity: {
				type: "string",
				enum: ["info", "warning", "critical"],
				title: "Severity Level",
				description: `How urgently this rule surfaces.

"info"      -  Shown when relevant files are in scope (default)
"warning"   -  Shown whenever related files are modified
"critical"  -  Shown in vreko even on cold start, regardless of file scope`,
			},
			insight: {
				type: "string",
				title: "Insight (deprecated)",
				description: "Deprecated. Use trigger + action instead.",
			},
		},
		required: ["trigger", "action"],
	},
	annotations: {
		title: "📚 Vreko Learn",
		readOnlyHint: false,
		destructiveHint: false,
		idempotentHint: false,
		openWorldHint: true,
	},
	tier: "free",
};
