// =============================================================================
// Types
// =============================================================================

/**
 * Snap.learn parameters
 */
export interface SnapLearnParams {
	/** Full-word learning type */
	type?: "pattern" | "pitfall" | "efficiency" | "discovery" | "workflow";
	/** What situation triggers this learning */
	trigger: string;
	/** @deprecated Legacy trigger param (use 'trigger' instead) */
	t?: string;
	/** What action to take when triggered */
	action: string;
	/** @deprecated Legacy action param (use 'action' instead) */
	a?: string;
	/** Source of the learning (optional) */
	source?: string;
	/** @deprecated Legacy source param (use 'source' instead) */
	s?: string;
	/** Use compact positional wire format instead of labeled (default: false = labeled) */
	compact?: boolean;
}

