// =============================================================================
// Reward Signal Builder
// =============================================================================

/**
 * Build a rich, rewarding human-readable response for a captured learning.
 * This is the "flywheel accelerator"  -  making capture feel worthwhile
 * encourages more captures, which makes the entire system smarter.
 */
function buildRewardSignal(
	learningType: string,
	trigger: string,
	action: string,
	trajectory: LearningTrajectory | null,
): string {
	const meta = LEARNING_TYPE_META[learningType] || LEARNING_TYPE_META.pattern;
	const lines: string[] = [];

	// -- User-facing section (human reward copy) --

	// 1. Confirmation echo  -  show what was captured
	lines.push(`${meta.emoji} ${meta.verb}!`);
	lines.push(`  When: "${truncate(trigger, 60)}"`);
	lines.push(`  Do: "${truncate(action, 60)}"`);

	// 2. Future value  -  what this learning will do
	lines.push(`  → This ${meta.future}`);

	// 3. Trajectory  -  running totals and milestone-based progress
	if (trajectory) {
		const { totalTracked, hotCount, maxHotSize } = trajectory;
		lines.push("");

		// Running total
		const trackedLabel =
			totalTracked === 1
				? "🧠 First tracked learning  -  your repo is getting smarter."
				: `🧠 Repository intelligence: ${totalTracked} tracked learnings`;
		lines.push(trackedLabel);

		// Hot tier status
		if (hotCount > 0) {
			const bar = buildMiniBar(hotCount, maxHotSize);
			lines.push(`🔥 Hot tier: ${bar} ${hotCount}/${maxHotSize} slots`);
		}

		// Next milestone nudge  -  discrete, journey-style
		if (hotCount === 0) {
			lines.push("💡 Tip: Learnings used 3+ times auto-promote to hot tier (always loaded)");
		} else if (hotCount < maxHotSize) {
			const remaining = maxHotSize - hotCount;
			lines.push(
				`📈 ${remaining} more hot slot${remaining !== 1 ? "s" : ""} until your top insights are always loaded`,
			);
		}
	}

	// -- LLM-facing section (structured hints for model behavior) --
	lines.push("");
	lines.push("LLM_HINT:");
	lines.push(`- When context matches "${truncate(trigger, 50)}", suggest "${truncate(action, 50)}" early.`);
	lines.push("- Highlight this learning when planning steps for similar tasks.");

	return lines.join("\n");
}

/** Truncate and buildMiniBar use shared truncate from learning-meta */
/** Build a mini progress bar for hot tier */
function buildMiniBar(filled: number, total: number): string {
	if (total <= 0) {
		return "[-]";
	}
	const barLen = Math.min(total, 10); // Cap visual at 10 chars
	const filledLen = Math.round((filled / total) * barLen);
	return `[${"█".repeat(filledLen)}${"░".repeat(Math.max(0, barLen - filledLen))}]`;
}

// =============================================================================
// Handler
// =============================================================================

/**
 * Handle vreko.learn  -  with rich reward signal
 */
export const handleSnapLearn: ToolHandler = async (args, context) => {
	// Security: Validate and sanitize all user inputs
	const validation = validateSnapLearnParams(args);
	if (!validation.success) {
		return {
			content: [
				{
					type: "text",
					text: `❌ Input validation failed:\n${validation.errors?.join("\n") ?? "Unknown validation error"}`,
				},
			],
			isError: true,
		};
	}

	const params = validation.data as SnapLearnParams;
	const options: WireFormatOptions = { compact: (args as Record<string, unknown>).compact === true };

	// Parameters are now sanitized by Zod (normalized, length-limited, injection-checked)
	const trigger = params.trigger ?? params.t ?? "";
	const action = params.action ?? params.a ?? "";
	const source = params.source ?? params.s ?? "snap_learn";

	// Normalize type through whitelist (unknown types fall back to "pattern")
	const learningType = normalizeLearningType(params.type);

	const learnArgs: Record<string, unknown> = {
		type: learningType,
		trigger,
		action,
		source,
	};

	const result = await handleLearn(learnArgs, context);

	// Build reward signal even if facade response is unexpected.
	// The reward UX is too valuable to drop silently on parse failure.
	let learningId = "unknown";
	try {
		const content = result.content[0]?.text || "";
		const data = JSON.parse(content);
		learningId = data.id || "unknown";
	} catch {
		// Facade returned non-JSON  -  proceed with "unknown" id
	}

	// Wire format: machine-readable portion before INTERNAL_SEPARATOR.
	// Fields are stable contract: status, id, type, trigger, action, total, hot.
	const trajectory = getLearningTrajectory(context.workspaceRoot);
	const wireFields: Record<string, string | number | undefined> = {
		status: "OK",
		id: learningId,
		type: learningType,
		trigger: truncate(trigger, 40),
		action: truncate(action, 40),
	};
	if (trajectory) {
		wireFields.total = trajectory.totalTracked;
		wireFields.hot = trajectory.hotCount;
	}
	const wire = formatWireLabeled("L", wireFields, options);

	// Human-readable reward signal (after separator, user-facing).
	// LLM: use id + type + trigger + action from wire above; the text below is for the user.
	const rewardSignal = buildRewardSignal(learningType, trigger, action, trajectory);

	// Add nextAction hints (2026 session hygiene)
	let nextActionHint = "";
	if (context.workspaceRoot) {
		const suggestions = await suggestNextActionAsync(context.workspaceRoot, "snap_learn");
		if (suggestions.length > 0) {
			const primary = suggestions[0];
			nextActionHint = `\n\n👉 **Next:** ${primary.reason}\n   → ${primary.tool}${primary.mode ? `({ mode: "${primary.mode}" })` : "()"}`;
		}
	}

	return {
		content: [
			{
				type: "text",
				text: `${wire}${INTERNAL_SEPARATOR}${rewardSignal}${nextActionHint}`,
			},
		],
	};
};

