export class PrivacyValidator {
	/**
	 * Check that payload contains only metadata
	 */
	isMetadataOnly(data: Record<string, unknown>): boolean {
		// Forbidden properties
		const forbidden = [
			"content",
			"sourceCode",
			"fileContent",
			"code",
			"text",
			"body",
			"filePath", // Only hashed paths allowed
			"fullPath",
			"absolutePath",
		];

		// Check for forbidden properties (including nested ones)
		const props = this.getAllProps(data);
		for (const prop of props) {
			// Extract the last segment of the property path (e.g., "nested.deep.content" → "content")
			const propName = prop.split(".").pop() || prop;
			if (forbidden.includes(propName)) {
				return false;
			}
		}

		// Check for suspiciously large strings
		const strings = this.getAllStrings(data);
		for (const str of strings) {
			if (str.length > 1000) {
				return false;
			}

			// Check for code-like patterns
			if (this.looksLikeCode(str)) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Get all property names recursively
	 */
	private getAllProps(obj: Record<string, unknown>, prefix = ""): string[] {
		let props: string[] = [];

		for (const [key, value] of Object.entries(obj)) {
			const fullKey = prefix ? `${prefix}.${key}` : key;
			props.push(fullKey);

			if (typeof value === "object" && value !== null && !Array.isArray(value)) {
				props = props.concat(this.getAllProps(value as Record<string, unknown>, fullKey));
			}
		}

		return props;
	}

	/**
	 * Get all string values recursively
	 */
	private getAllStrings(obj: Record<string, unknown>): string[] {
		let strings: string[] = [];

		for (const value of Object.values(obj)) {
			if (typeof value === "string") {
				strings.push(value);
			} else if (typeof value === "object" && value !== null) {
				strings = strings.concat(this.getAllStrings(value as Record<string, unknown>));
			}
		}

		return strings;
	}

	/**
	 * Heuristic to detect code-like strings
	 */
	private looksLikeCode(str: string): boolean {
		const codePatterns = [
			/function\s+\w+/,
			/const\s+\w+\s*=/,
			/let\s+\w+\s*=/,
			/var\s+\w+\s*=/,
			/class\s+\w+/,
			/import\s+.*from/,
			/export\s+(default\s+)?/,
			/if\s*\(/,
			/for\s*\(/,
			/while\s*\(/,
		];

		return codePatterns.some((pattern) => pattern.test(str));
	}
}
