/**
 * Daemon Client Access Utility
 *
 * Provides access to the daemon client for v2 tools.
 * Delegates to the existing local-service-adapter infrastructure.
 *
 * @module tools/v2/utils/daemon
 */

import { createDaemonClient } from "../../../daemon/local-service-adapter.js";

/**
 * Daemon client interface for v2 tools
 */
export interface DaemonClient {
	/** Check if the daemon is available */
	isAvailable: () => boolean;
	/** Make a request to the daemon */
	request: <T>(method: string, params: Record<string, unknown>) => Promise<T | null>;
}

/**
 * Get a daemon client for the given workspace.
 *
 * Uses the existing createDaemonClient from local-service-adapter.
 * The client provides:
 * - isAvailable(): Check if daemon is connected
 * - request<T>(method, params): Make typed IPC calls
 *
 * @param workspaceRoot - The workspace root path
 * @returns Daemon client instance
 */
export function getDaemonClient(workspaceRoot: string): DaemonClient {
	return createDaemonClient(workspaceRoot);
}
