/**
 * Workspace Health MCP Tool
 *
 * Exposes workspace health status to MCP clients via the workspace_health tool.
 *
 * @module health/tool
 */

import type { ToolContext, ToolResult } from "../types/tool-types.js";
import { checkWorkspaceHealth } from "./integration.js";

/**
 * Input schema for workspace_health tool
 */
export interface WorkspaceHealthInput {
	/** Optional specific checks to run */
	check?: string[];
}

/**
 * Output format for workspace_health tool
 */
export interface WorkspaceHealthOutput {
	/** Overall health status */
	healthy: boolean;
	/** Workspace root path */
	workspaceRoot: string;
	/** Workspace ID */
	workspaceId: string;
	/** Failed checks */
	issues: Array<{
		name: string;
		message: string;
		severity: "info" | "warning" | "error";
	}>;
	/** Whether auto-fix is available */
	canAutoFix: boolean;
	/** Number of auto-fixable issues */
	autoFixableCount: number;
	/** Total checks performed */
	totalChecks: number;
	/** Passed checks count */
	passedChecks: number;
}

/**
 * Handle workspace_health tool call
 *
 * Provides clients with current workspace health status including:
 * - Overall health boolean
 * - List of failed checks with severity
 * - Auto-fix availability
 *
 * @param args - Tool arguments (optional check filters)
 * @param context - Tool execution context
 * @returns Tool result with health status
 */
export async function handleWorkspaceHealth(args: WorkspaceHealthInput, context: ToolContext): Promise<ToolResult> {
	try {
		const health = await checkWorkspaceHealth(context.workspaceRoot);

		// Filter to requested checks if specified
		let checks = health.checks;
		if (args.check && args.check.length > 0) {
			checks = checks.filter((c) => args.check?.includes(c.name));
		}

		// Build output
		const failedChecks = checks.filter((c) => !c.passed);
		const output: WorkspaceHealthOutput = {
			healthy: health.healthy,
			workspaceRoot: health.workspaceRoot,
			workspaceId: health.workspaceId,
			issues: failedChecks.map((c) => ({
				name: c.name,
				message: c.message || "Check failed",
				severity: c.severity,
			})),
			canAutoFix: health.autoFixable.length > 0,
			autoFixableCount: health.autoFixable.length,
			totalChecks: checks.length,
			passedChecks: checks.filter((c) => c.passed).length,
		};

		return {
			content: [
				{
					type: "text",
					text: JSON.stringify(output, null, 2),
				},
			],
			isError: false,
		};
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		return {
			content: [
				{
					type: "text",
					text: JSON.stringify(
						{
							error: "HEALTH_CHECK_FAILED",
							message: `Failed to check workspace health: ${message}`,
						},
						null,
						2,
					),
				},
			],
			isError: true,
		};
	}
}

/**
 * Tool definition for workspace_health
 */
export const workspaceHealthTool = {
	name: "workspace_health",
	description: "Check workspace health status. Returns overall health, failed checks, and auto-fix availability.",
	inputSchema: {
		type: "object" as const,
		properties: {
			check: {
				type: "array",
				items: { type: "string" },
				description: "Optional specific checks to run (e.g., ['vreko_dir', 'workspace_id'])",
			},
		},
	},
};

/**
 * Tool definition for health/check (alias for workspace_health)
 */
export const healthCheckTool = {
	name: "health/check",
	description: "Check workspace health status. Returns overall health, failed checks, and auto-fix availability.",
	inputSchema: {
		type: "object" as const,
		properties: {
			check: {
				type: "array",
				items: { type: "string" },
				description: "Optional specific checks to run (e.g., ['vreko_dir', 'workspace_id'])",
			},
		},
	},
};
