/**
 * Session Adapter for Daemon IPC
 *
 * Provides async equivalents to the synchronous session state functions
 * from session/state.ts, routing all operations through the daemon.
 *
 * This is the migration path from local Map-based state to daemon IPC.
 * All MCP tools should use these async functions instead of the sync ones.
 *
 * @see docs/session_state_migration_complete.md
 * @module adapters/session-adapter
 */

import {
	addLearningViaDaemon,
	endTaskViaService,
	getSessionChangesViaService,
	getSessionStatusViaService,
	quickCheckViaService,
	recordFileModificationViaService,
} from "../daemon/local-service-adapter.js";

// =============================================================================
// Types (re-exported from canonical source)
// =============================================================================

// Re-export all types from the canonical source
export type {
	CurrentTask,
	FileChange,
	GitFileStatus,
	MCPSessionState,
	Observation,
	RiskArea,
	ShownLearnings,
	TaskIntent,
	ToolCallEvent,
	ValidationCategory,
	ValidationEvent,
	ValidationSource,
} from "../session/types.js";

// Import types for internal use
import type { CurrentTask, FileChange, MCPSessionState, Observation, ValidationEvent } from "../session/types.js";

// =============================================================================
// Session Adapter Functions
// =============================================================================

/**
 * Get session state from daemon (async version of getSessionState)
 *
 * @param workspaceRoot - Workspace root path
 * @returns Session state or null if unavailable
 */
export async function getSessionStateAsync(workspaceRoot: string): Promise<MCPSessionState | null> {
	const result = await getSessionStatusViaService(workspaceRoot);
	if (!result) {
		return null;
	}
	return daemonStateToMCP(result);
}

/**
 * Get current task from daemon (async version of getCurrentTask)
 *
 * @param workspaceRoot - Workspace root path
 * @returns Current task or null
 */
export async function getCurrentTaskAsync(workspaceRoot: string): Promise<CurrentTask | null> {
	const result = await getSessionStatusViaService(workspaceRoot);
	if (!result || !result.active) {
		return null;
	}
	return {
		id: result.taskId ?? "",
		description: result.task ?? "",
		startedAt: result.startedAt ? new Date(result.startedAt).getTime() : Date.now(),
		plannedFiles: [],
		keywords: [],
	};
}

/**
 * Start a new task via daemon (async version of startTask)
 *
 * @param workspaceRoot - Workspace root path
 * @param task - Task details
 * @returns Created task
 */
export async function startTaskAsync(
	workspaceRoot: string,
	task: Omit<CurrentTask, "id" | "startedAt" | "gitBaseline">,
): Promise<CurrentTask | null> {
	// Use beginTaskViaService from local-service-adapter
	const { beginTaskViaService } = await import("../daemon/local-service-adapter.js");
	const result = await beginTaskViaService(workspaceRoot, task.description, task.plannedFiles, task.keywords);
	if (!result) {
		return null;
	}
	return {
		id: result.taskId,
		description: task.description,
		startedAt: Date.now(),
		plannedFiles: task.plannedFiles,
		keywords: task.keywords,
	};
}

/**
 * End current task via daemon (async version of endTask)
 *
 * @param workspaceRoot - Workspace root path
 * @param outcome - Task outcome
 * @returns Ended task or null
 */
export async function endTaskAsync(workspaceRoot: string, outcome: string): Promise<CurrentTask | null> {
	const result = await endTaskViaService(workspaceRoot, outcome);
	if (!result) {
		return null;
	}
	// Return a minimal task object with the outcome
	return {
		id: "",
		description: "",
		startedAt: Date.now(),
		plannedFiles: [],
		keywords: [],
	};
}

/**
 * Record a file change via daemon (async version of recordFileChange)
 *
 * @param workspaceRoot - Workspace root path
 * @param change - File change details
 */
export async function recordFileChangeAsync(workspaceRoot: string, change: FileChange): Promise<void> {
	await recordFileModificationViaService(workspaceRoot, change.file, change.linesChanged, change.aiAttributed);
}

/**
 * Record a validation event via daemon (async version of recordValidationEvent)
 *
 * @param workspaceRoot - Workspace root path
 * @param event - Validation event details
 */
export async function recordValidationEventAsync(
	workspaceRoot: string,
	_event: Omit<ValidationEvent, "id" | "timestamp">,
): Promise<void> {
	await quickCheckViaService(workspaceRoot);
}

