/**
 * Risk Handlers
 *
 * Handlers for risk acknowledgment and violation reporting.
 *
 * @module facades/handlers/risk-handlers
 */

import { CommonErrors } from "../../errors/index.js";
import type { Learning } from "../../sync/learning-sync.js";
import { createLearningSync } from "../../sync/learning-sync.js";
import type { ToolHandler } from "../../types/tool-types.js";
import { getIntelligence } from "../intelligence.js";
import { errorJsonResult, jsonResult, result } from "./utils.js";

/**
 * acknowledge_risk - Acknowledge risk state before proceeding
 */
export const handleAcknowledgeRisk: ToolHandler = async (args, context) => {
	const { files, reason } = args as { files?: string[]; reason?: string };

	if (!files || !reason) {
		return errorJsonResult(CommonErrors.missingParam("files, reason"));
	}

	const acknowledgment = {
		files,
		reason,
		acknowledgedAt: new Date().toISOString(),
		tier: context.tier,
	};

	return jsonResult({
		status: "acknowledged",
		acknowledged: true,
		files,
		reason,
		timestamp: acknowledgment.acknowledgedAt,
		message: "Risk acknowledged - proceed with changes",
		next_actions: [
			{
				tool: "snapshot_create",
				priority: 1,
				reason: "Create safety snapshot",
				args: { files, reason: `Pre-risk: ${reason}` },
			},
		],
	});
};

/**
 * report_violation - Report violations with auto-promotion
 */
export const handleReportViolation: ToolHandler = async (args, context) => {
	const { type, file, whatHappened, whyItHappened, prevention } = args as {
		type?: string;
		file?: string;
		whatHappened?: string;
		whyItHappened?: string;
		prevention?: string;
	};

	if (!type || !file || !whatHappened || !whyItHappened || !prevention) {
		return errorJsonResult(CommonErrors.missingParam("type, file, whatHappened, whyItHappened, prevention"));
	}

	try {
		const intel = getIntelligence(context.workspaceRoot);

		// Report violation to Intelligence
		const status = await intel.reportViolation({
			type,
			file,
			message: whatHappened,
			reason: whyItHappened,
			prevention,
		});

		// Queue promoted violations for cross-workspace sync (non-blocking)
		// Only sync violations that have reached promotion threshold
		if (status.shouldPromote && context.workspaceId) {
			const syncService = createLearningSync({
				workspaceRoot: context.workspaceRoot,
				workspaceId: context.workspaceId,
			});

			// Convert violation to learning format for sync
			// Tag with workspaceId for cross-workspace scoping
			const violationLearning: Learning = {
				id: status.id,
				type: "pitfall", // Violations become pitfalls (avoid patterns)
				trigger: `${type} in ${file}`,
				action: `${prevention} (Cause: ${whyItHappened})`,
				source: "violation",
				timestamp: new Date().toISOString(),
			};

			syncService.queueLearning(violationLearning).catch((_syncError) => {
				// Intentionally ignored: violation sync is non-blocking best-effort
			});
		}

		return jsonResult({
			recorded: true,
			violationId: status.id,
			type,
			file,
			occurrences: status.count,
			promoted: status.shouldPromote,
			promotedTo: status.shouldPromote ? "pattern" : null,
			automation: status.shouldAutomate ? "pending" : null,
			syncQueued: status.shouldPromote && !!context.workspaceId,
			message: status.shouldPromote
				? `Violation promoted to pattern after ${status.count} occurrences`
				: `Violation recorded (${status.count}/3 for promotion)`,
			next_actions: status.shouldPromote
				? [{ tool: "get_context", priority: 2, reason: "New pattern available in context" }]
				: [],
		});
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		return result(`Failed to report violation: ${message}`, true);
	}
};
