/**
 * Safe-To-Write Tool - Pillar 06: Pre-Write MCP Interception
 *
 * Composite risk evaluation that orchestrates all 5 intelligence pillars
 * to determine if a file write operation should proceed.
 *
 * This tool should be called by MCP write operations (edit, write, etc.)
 * before making changes to ensure the operation is safe.
 *
 * Pillars evaluated:
 * 1. Git Risk - Working on main? Detached HEAD? Mid-rebase?
 * 2. Rollback Patterns - Does this match a known failure cluster?
 * 3. Fatigue Detection - Is the developer rubber-stamping?
 * 4. Annotations - Historical calibration from user feedback
 * 5. Context Poisoning - Is AI repeating rejected patterns?
 *
 * @module tools/consolidated/safe-to-write
 */

import { formatWireLabeled, INTERNAL_SEPARATOR, type WireFormatOptions } from "../../branding/index.js";
import { validateSafeToWriteParams } from "../../security/input-sanitization.js";
import type { ToolHandler, ToolResult, VrekoTool } from "../../types/tool-types.js";

// =============================================================================
// Types
// =============================================================================

export interface SafeToWriteParams {
	/** File path being written */
	filePath: string;
	/** Alias for filePath */
	f?: string;
	/** Proposed diff/content change */
	proposedDiff: string;
	/** Alias for proposedDiff */
	diff?: string;
	/** AI tool making the change */
	tool?: string;
	/** Intent of the change */
	intent?: string;
	/** Use compact wire format */
	compact?: boolean;
}

interface SafeToWriteFactor {
	source: string;
	score: number;
	description: string;
}

interface SafeToWriteResult {
	allowed: boolean;
	action: "PROCEED" | "PROCEED_WITH_SNAPSHOT" | "WARN" | "BLOCK";
	riskScore: number;
	factors: SafeToWriteFactor[];
	recommendation: string;
	snapshotHash?: string;
	retryable: boolean;
	alternativeActions: Array<{ tool: string; description: string; params?: Record<string, unknown> }>;
}

// =============================================================================
// Parameter Normalization
// =============================================================================

function normalizeParams(params: SafeToWriteParams): {
	filePath: string;
	proposedDiff: string;
	tool: string;
	intent?: string;
	compact: boolean;
} {
	return {
		filePath: params.filePath || params.f || "",
		proposedDiff: params.proposedDiff || params.diff || "",
		tool: params.tool || "mcp",
		intent: params.intent,
		compact: params.compact || false,
	};
}

// =============================================================================
// Result Formatting
// =============================================================================

function formatResult(result: SafeToWriteResult, options: WireFormatOptions): ToolResult {
	// Action emoji mapping
	const actionEmoji: Record<SafeToWriteResult["action"], string> = {
		PROCEED: "✅",
		PROCEED_WITH_SNAPSHOT: "📸",
		WARN: "⚠️",
		BLOCK: "🛑",
	};

	// Build wire format
	const wireFields: Record<string, string> = {
		action: result.action,
		risk: result.riskScore.toFixed(2),
		factors: `${result.factors.length}`,
	};

	const wire = formatWireLabeled("STW", wireFields, options);

	// Human-readable message
	const emoji = actionEmoji[result.action];
	let humanMessage = `${emoji} **${result.action}** (risk: ${result.riskScore.toFixed(2)})\n\n`;
	humanMessage += `${result.recommendation}`;

	// Add factors if any
	if (result.factors.length > 0) {
		humanMessage += "\n\n**Risk Factors:**";
		for (const factor of result.factors) {
			const sign = factor.score > 0 ? "+" : "";
			humanMessage += `\n- [${factor.source}] ${sign}${factor.score.toFixed(2)}: ${factor.description}`;
		}
	}

	// Add alternative actions if blocked or warned
	if (result.alternativeActions.length > 0 && (result.action === "BLOCK" || result.action === "WARN")) {
		humanMessage += "\n\n**Suggested Actions:**";
		for (const alt of result.alternativeActions) {
			humanMessage += `\n- ${alt.tool}: ${alt.description}`;
		}
	}

	const structuredContent = {
		allowed: result.allowed,
		action: result.action,
		riskScore: result.riskScore,
		factors: result.factors,
		recommendation: result.recommendation,
		retryable: result.retryable,
		alternativeActions: result.alternativeActions,
	};

	return {
		content: [{ type: "text", text: `${wire}${INTERNAL_SEPARATOR}${humanMessage}` }],
		structuredContent,
		isError: !result.allowed,
	};
}

// =============================================================================
// Handler
// =============================================================================

export const handleSafeToWrite: ToolHandler = async (args, context) => {
	// Security: Validate and sanitize all user inputs
	const validation = validateSafeToWriteParams(args);
	if (!validation.success) {
		return {
			content: [
				{
					type: "text",
					text: `❌ Input validation failed:\n${validation.errors?.join("\n") ?? "Unknown validation error"}`,
				},
			],
			isError: true,
		};
	}

	const params = validation.data as SafeToWriteParams;
	const { filePath, proposedDiff, tool, intent, compact } = normalizeParams(params);

	// Validate required params (Zod already validates but keep for clear error messages)
	if (!filePath) {
		return {
			content: [{ type: "text", text: "❌ Missing required parameter: filePath" }],
			isError: true,
		};
	}

	if (!proposedDiff) {
		return {
			content: [{ type: "text", text: "❌ Missing required parameter: proposedDiff" }],
			isError: true,
		};
	}

	// Call daemon IPC for composite evaluation
	const daemonClient = context.services?.daemon;
	if (!daemonClient) {
		// Fallback: allow if no daemon (local-only mode)
		return {
			content: [
				{
					type: "text",
					text: "⚠️ Daemon not available - proceeding without risk evaluation",
				},
			],
			structuredContent: {
				allowed: true,
				action: "PROCEED",
				riskScore: 1.0,
				factors: [],
				recommendation: "Daemon unavailable - skipping risk evaluation",
				retryable: true,
				alternativeActions: [],
			},
		};
	}

	try {
		const result = (await daemonClient.request("protection/safe-to-write", {
			workspace: context.workspaceRoot,
			filePath,
			proposedDiff,
			tool,
			intent,
		})) as SafeToWriteResult;

		return formatResult(result, { compact });
	} catch (error) {
		const message = error instanceof Error ? error.message : "Unknown error";
		return {
			content: [{ type: "text", text: `❌ Safe-to-write evaluation failed: ${message}` }],
			isError: true,
		};
	}
};

