/**
 * Transport Health Monitoring
 *
 * Provides connection health status for MCP transport diagnostics.
 * Extracted to break circular dependency: check.ts → stdio.ts → server.ts
 *
 * @module transport/health
 */

/** Connection state for health monitoring */
export interface ConnectionState {
	startTime: Date;
	lastActivity: Date;
	toolsLoaded: boolean;
	toolCount: number;
	errorCount: number;
	isShuttingDown: boolean;
}

/** Global connection state for diagnostics */
let connectionState: ConnectionState | null = null;

/**
 * Get current connection health status (for debugging)
 */
export function getConnectionHealth(): ConnectionState | null {
	return connectionState ? { ...connectionState } : null;
}

/**
 * Set connection state (internal use by stdio transport)
 */
export function setConnectionState(state: ConnectionState | null): void {
	connectionState = state;
}

/**
 * Update connection state properties (internal use)
 */
export function updateConnectionState(updates: Partial<ConnectionState>): void {
	if (connectionState) {
		Object.assign(connectionState, updates);
	}
}
