/**
 * Get the top N most relevant blind spots for a given tool
 */
export function getTopBlindSpots(tool: string, limit = 2): ToolBlindSpot[] {
	const spots = TOOL_BLIND_SPOTS[tool] || [];
	return spots.sort((a, b) => b.relevanceScore - a.relevanceScore).slice(0, limit);
}

/**
 * Format blind spots for MCP briefing inclusion
 */
export function formatBlindSpotsForBriefing(tool: string, confidence: number): string | null {
	// Only include if confidence >= 0.7
	if (confidence < 0.7) {
		return null;
	}

	const spots = getTopBlindSpots(tool, 2);
	if (spots.length === 0) {
		return null;
	}

	let output = `\n## ${tool} Structural Blind Spots\n\n`;
	output += `Vreko detected you're using ${tool} (${(confidence * 100).toFixed(0)}% confidence).\n`;
	output += "Here are areas where Vreko provides complementary intelligence:\n\n";

	for (const spot of spots) {
		output += `**${spot.title}**\n`;
		output += `- ${spot.description}\n`;
		output += `- Vreko mitigation: ${spot.vrekoMitigation}\n\n`;
	}

	return output;
}
