/**
 * Snap Violation Tool
 *
 * Violation reporting with auto-promotion. Replaces:
 * - report_violation
 *
 * @see stress_test_remediation.md
 * @module tools/consolidated/vreko-violation
 */

import { formatWireLabeled, INTERNAL_SEPARATOR, messages, type WireFormatOptions } from "../../branding/index.js";
import { handleReportViolation } from "../../facades/handlers/index.js";
import { validateSnapViolationParams } from "../../security/input-sanitization.js";
import type { ToolHandler, VrekoTool } from "../../types/tool-types.js";

// =============================================================================
// Types
// =============================================================================

/**
 * Snap.violation parameters
 */
export interface SnapViolationParams {
	/** Violation type (e.g., 'silent_catch', 'layer_violation') */
	type: string;
	/** File where violation occurred */
	file: string;
	/** What went wrong - description of the violation */
	description: string;
	/** @deprecated Legacy param (use 'description' instead) */
	what?: string;
	/** Why it happened - root cause */
	reason?: string;
	/** @deprecated Legacy param (use 'reason' instead) */
	why?: string;
	/** How to prevent this in future */
	prevention: string;
	/** @deprecated Legacy param (use 'prevention' instead) */
	prevent?: string;
	/** Use compact positional wire format instead of labeled (default: false = labeled) */
	compact?: boolean;
}

// =============================================================================
// Handler
// =============================================================================

/**
 * Handle vreko.violation
 */
export const handleSnapViolation: ToolHandler = async (args, context) => {
	// Security: Validate and sanitize all user inputs
	const validation = validateSnapViolationParams(args);
	if (!validation.success) {
		return {
			content: [
				{
					type: "text",
					text: `❌ Input validation failed:\n${validation.errors?.join("\n") ?? "Unknown validation error"}`,
				},
			],
			isError: true,
		};
	}

	const params = validation.data as SnapViolationParams;
	const options: WireFormatOptions = { compact: (args as Record<string, unknown>).compact === true };

	// Parameters are now sanitized by Zod (normalized, length-limited, injection-checked)
	const description = params.description ?? params.what ?? "";
	const reason = params.reason ?? params.why ?? "";
	const prevention = params.prevention ?? params.prevent ?? "";

	const violationArgs: Record<string, unknown> = {
		type: params.type,
		file: params.file,
		whatHappened: description,
		whyItHappened: reason,
		prevention,
	};

	const result = await handleReportViolation(violationArgs, context);

	// Format as labeled wire response (default) or compact
	try {
		const content = result.content[0]?.text || "";
		const data = JSON.parse(content);
		const count = data.count || 1;

		const wireFields: Record<string, string | number | undefined> = {
			status: "OK",
			type: params.type,
			count,
		};

		if (data.shouldPromote) {
			wireFields.promote = "PROMOTED";
		}
		if (data.shouldAutomate) {
			wireFields.auto = "YES";
		}

		const wire = formatWireLabeled("V", wireFields, options);

		// Add human-readable branded message
		const humanMessage = data.shouldAutomate
			? messages.violation.automate(params.type)
			: data.shouldPromote
				? messages.violation.promoted(params.type)
				: messages.violation.recorded(params.type, count);

		return { content: [{ type: "text", text: `${wire}${INTERNAL_SEPARATOR}${humanMessage}` }] };
	} catch {
		return result;
	}
};

// =============================================================================
// Tool Definition
// =============================================================================

export const snapViolationTool: VrekoTool = {
	name: "vreko_violation",
	description: `[DEPRECATED] 🦎 Vreko Violation - Your mistake tracker that learns.

**When to use:** Something broke or went wrong? Report it so you never repeat it.

**vs snap_learn pitfall:**
- snap_violation: For BUGS/ERRORS that actually happened (track occurrences)
- snap_learn({ type: "pitfall" }): For POTENTIAL mistakes to avoid (no tracking)

**Auto-Escalation:**
- **1st time**: Recorded, tracked
- **3rd time**: 📥 Promoted to pattern (prevents future occurrences)
- **5th time**: 🤖 Flagged for automation (seriously, automate this check)

**What to report:**
- Bugs that slipped through
- Security issues caught late
- Performance problems discovered
- Architecture violations
- Test failures from bad patterns

**Wire Format:** 🦎|V|status:OK|type:silent_catch|count:3|promote:PROMOTED

**Examples:**

Report a caught error pattern:
  snap_violation({
    type: "silent_catch",
    file: "auth.ts",
    description: "Catch block swallowed error without logging",
    reason: "Rushed implementation, forgot logging",
    prevention: "Always log in catch blocks with context"
  })

Architecture violation:
  snap_violation({
    type: "wrong_layer_import",
    file: "packages/core/utils.ts",
    description: "Core imported from platform layer",
    reason: "Didn't check dependency direction",
    prevention: "Core should never import platform - use dependency injection"
  })

Security issue:
  snap_violation({
    type: "exposed_secret",
    file: "config.ts",
    description: "API key hardcoded in source",
    reason: "Testing shortcut left in code",
    prevention: "Use environment variables, never commit secrets"
  })

**Boundaries:**

Will:
- Track occurrence count locally
- Auto-promote at thresholds
- Store in .vreko/patterns/violations.jsonl
- Surface in future vreko starts

Will Not:
- Share violations externally
- Auto-fix code
- Require manual category management
- Expire violations (cleanup is manual)

**Pro Tip:** Be specific with type names ("silent_catch" not "error"). Specific types promote faster and help more.

**Legacy Support:** Single-letter params (what, why, prevent) still work but are not shown in schema.`,
	inputSchema: {
		type: "object",
		properties: {
			type: {
				type: "string",
				description: "Violation type key (e.g., 'silent_catch', 'missing_auth_check')",
			},
			file: {
				type: "string",
				description: "File where violation occurred",
			},
			description: {
				type: "string",
				description: "What went wrong - description of the violation",
			},
			reason: {
				type: "string",
				description: "Why it happened - root cause analysis (optional)",
			},
			prevention: {
				type: "string",
				description: "How to prevent this in future",
			},
			compact: {
				type: "boolean",
				default: false,
				description: "Use compact wire format instead of labeled (default: labeled)",
			},
		},
		required: ["type", "file", "description", "prevention"],
	},
	outputSchema: {
		type: "object",
		properties: {
			type: { type: "string", description: "Violation type recorded" },
			count: { type: "number", description: "Occurrence count for this type" },
			promoted: { type: "boolean", description: "Whether promoted to pattern" },
			flaggedForAutomation: { type: "boolean", description: "Whether flagged for automation" },
		},
	},
	annotations: {
		title: "🦎 Vreko Violation",
		readOnlyHint: false,
		destructiveHint: false,
		idempotentHint: false,
	},
	tier: "free",
};
