/**
 * Vreko Pulse Tool (V2) - Mid-Session Intelligence Surface
 *
 * A read-only composite query that returns the daemon's current intelligence
 * state for the active session. No side effects. Just: "here's what the daemon
 * thinks about what you're doing right now."
 *
 * @module tools/v2/vreko-pulse
 */

import { basename } from "node:path";
import { MAX_LENGTHS, normalizeContent } from "../../security/input-sanitization.js";
import type { ToolHandler, ToolResult, VrekoTool } from "../../types/tool-types.js";
import { getToolCreditEstimate } from "./utils/credit-registry.js";
import {
	buildLearningSearchParams,
	buildSessionCurrentParams,
	type CoChangePair,
	type DaemonCoChangesResponse,
	formatDaemonError,
	getDaemonClient,
	isActiveSession,
	isDaemonConnectionError,
	mapCoChangePairs,
	resolveWorkspace,
} from "./utils/index.js";

// =============================================================================
// Types
// =============================================================================

export interface SnapPulseParams {
	/** Optional: focus area for targeted query */
	focus?: "risk" | "cochanges" | "vitals";
	/** Optional: task context for topology-enhanced briefing and learning search */
	task?: string;
	/** Alias for task  -  query the intelligence layer with this text (report card v2 fix) */
	query?: string;
}

/** Learning search result from pulse query */
interface LearningSearchPulseResult {
	results?: Array<{
		id?: string;
		insight?: string;
		solution?: string;
		content?: string;
		action?: string;
		trigger?: string | string[];
		severity?: string;
		files?: string[];
		relevanceScore?: number;
	}>;
	learnings?: Array<{
		type: string;
		trigger: string;
		action: string;
		relevanceScore: number;
	}>;
	total?: number;
}

interface SessionStatusResult {
	active: boolean;
	durationMin?: number;
	filesTouched?: number;
	snapshotsCreated?: number;
	touchedFiles?: string[];
}

/** Actual shape returned by the session/current daemon endpoint */
interface SessionCurrentResponse {
	/** Actual field from daemon: "active" | "ended" | "idle" */
	state?: string;
	/** Legacy field  -  may not be present in all daemon versions */
	active?: boolean;
	id?: string;
	startedAt?: string;
	touchedFiles?: string[];
	snapshotIds?: string[];
}

interface Warning {
	severity: "info" | "warn" | "critical";
	message: string;
	action?: string;
}

interface IntelligenceWarningsResult {
	warnings: Warning[];
}

interface FragileFile {
	path: string;
	fragility: number;
	reason?: string;
	rollbackCount?: number;
}

interface FragileFilesResult {
	files: FragileFile[];
}

interface IntelligenceCaptureResult {
	captured?: boolean;
}

/** Shape returned by session/vitals endpoint  -  canonical source for pressure */
interface SessionVitalsResult {
	pulse: string;
	pressure: number;
	trajectory: string;
	snapshotRecommended: boolean;
	filesModified: number;
	snapshotsCreated: number;
	learningsCaptured: number;
	changesPerMinute?: number;
}

