/** File role from topology classification */
type FileRole =
	| "route"
	| "middleware"
	| "controller"
	| "service"
	| "model"
	| "repository"
	| "utility"
	| "config"
	| "test"
	| "fixture"
	| "type"
	| "hook"
	| "component"
	| "layout"
	| "store"
	| "migration"
	| "script"
	| "asset"
	| "barrel"
	| "entry"
	| "unknown";

/** Scoped file from task resolution */
interface ScopedFile {
	path: string;
	role: FileRole;
	module: string;
	reason: string;
	convention?: string;
	deviation?: string;
	fragility?: number;
}

/** Deviation category */
type DeviationCategory =
	| "structure"
	| "naming"
	| "routing"
	| "state"
	| "data_access"
	| "middleware"
	| "dependency"
	| "config"
	| "testing"
	| "entry_point"
	| "barrel_pattern"
	| "layer_violation"
	| "custom_abstraction";

/** Topology deviation */
interface TopologyDeviation {
	file_path: string;
	category: DeviationCategory;
	severity: "critical" | "warning" | "info";
	description: string;
	impact: string;
}

/** Task-scoped briefing from topology query (Phase D CTI) */
interface TaskScopedBriefing {
	primary_files: ScopedFile[];
	context_files: ScopedFile[];
	test_files: ScopedFile[];
	framework: string;
	boundaries: {
		layer: string;
		modules: string[];
		must_not_cross: string[];
	};
	deviations: {
		category: string;
		severity: string;
		description: string;
		impact: string;
		files?: string[];
	}[];
	behavioral: {
		fragile_files: string[];
		co_change_patterns: {
			file: string;
			usually_changes_with: string[];
		}[];
		recent_failures: {
			file: string;
			failure_count: number;
			last_failure_session: string;
		}[];
	};
	confidence: number;
	topology_stale: boolean;
	scan_version: number;
}

/** Response from topology/status daemon endpoint */
interface TopologyStatusResult {
	exists: boolean;
	framework?: string;
	stale?: boolean;
	scan_version?: number;
	file_count?: number;
	node_count?: number;
	deviation_count?: number;
	critical_deviations?: TopologyDeviation[];
	scanned_at?: number;
}

/** Response from topology/query daemon endpoint */
interface TopologyQueryResult {
	briefing: TaskScopedBriefing | null;
	topology_stale: boolean;
	framework: string;
}

// Progressive disclosure thresholds
const RISK_THRESHOLD = 0.3;
const CO_CHANGE_CONFIDENCE_THRESHOLD = 0.5;

// Duration thresholds for guidance (in minutes)
const DURATION_SHORT = 5; // < 5 min = just started
const DURATION_MEDIUM = 30; // 5-30 min = in flow
const DURATION_LONG = 60; // > 60 min = extended session

/**
 * Phase 4 Intelligence Wiring: Duration-aware guidance
 * Provides contextual recommendations based on session duration and activity patterns.
 */
function getDurationGuidance(
	durationMin: number | undefined,
	filesTouched: number | undefined,
	snapshotsCreated: number | undefined,
	pressure: number | undefined,
): string | null {
	if (durationMin === undefined) {
		return null;
	}

	const files = filesTouched ?? 0;
	const snapshots = snapshotsCreated ?? 0;
	const riskPressure = pressure ?? 0;

	// Short session: Just getting started
	if (durationMin < DURATION_SHORT) {
		if (files === 0) {
			return "💡 Just getting started. Vreko will surface relevant patterns once you begin editing files.";
		}
		return null; // No guidance needed for active short sessions
	}

	// Medium session: In the flow
	if (durationMin < DURATION_MEDIUM) {
		// Check for high activity without snapshots
		if (files >= 3 && snapshots === 0 && riskPressure > 0.5) {
			return "💡 You've modified several files without snapshots. Consider pausing to review changes before continuing.";
		}
		// Check for scattered changes
		if (files >= 5 && riskPressure < 0.3) {
			return "💡 Multiple files touched with low risk. Your changes seem well-scoped.";
		}
		return null;
	}

	// Long session: Extended work
	if (durationMin < DURATION_LONG) {
		// Check for sustained high pressure
		if (riskPressure > 0.7) {
			return "💡 Extended session with high risk pressure. Consider committing your changes or taking a short break.";
		}
		// Check for many files without recent snapshots
		if (files >= 10 && snapshots < 2) {
			return "💡 You've touched many files. Vreko recommends creating a checkpoint snapshot before continuing.";
		}
		return "💡 Session running for 30+ minutes. Consider a brief pause to review progress.";
	}

	// Very long session: Extended work
	if (riskPressure > 0.5) {
		return "💡 Extended session detected. Consider wrapping up or creating a summary of changes made.";
	}
	return "💡 Long session in progress. Remember to take breaks and review your work periodically.";
}

/**
 * Normalize the daemon's session/current response to the SessionStatusResult shape.
 * session/current returns { state: "active", startedAt, touchedFiles, snapshotIds, ... }
 * while the formatters expect { active: boolean, durationMin, filesTouched, snapshotsCreated, touchedFiles }.
 *
 * Bug 2 Fix: Uses shared isActiveSession utility for consistent session state check.
 */
function normalizeSessionStatus(raw: SessionCurrentResponse | null): SessionStatusResult | null {
	if (!raw) {
		return null;
	}
	// Use shared utility for consistent session state check
	if (!isActiveSession(raw)) {
		return null;
	}

	const durationMin = raw.startedAt
		? Math.round((Date.now() - new Date(raw.startedAt).getTime()) / 60000)
		: undefined;

	return {
		active: true,
		durationMin,
		filesTouched: raw.touchedFiles?.length,
		snapshotsCreated: raw.snapshotIds?.length,
		touchedFiles: raw.touchedFiles,
	};
}

// =============================================================================
// Handler
// =============================================================================

/**
 * Handle vreko_pulse tool call
 *
 * Flow:
 * 1. Parallel daemon queries (all read-only)
 * 2. Extract results (graceful degradation)
 * 3. Compose intelligence briefing
 * 4. Fire feedback log (non-blocking)
 */
export const handleVrekoPulse: ToolHandler = async (args, context): Promise<ToolResult> => {
	const params = (args as unknown as SnapPulseParams) ?? {};
	const workspace = resolveWorkspace(context);
	const daemon = getDaemonClient(workspace);

	// HIGH-3: Sanitize free-text params before forwarding to daemon endpoints
	const rawTask = params.task ? normalizeContent(params.task).slice(0, MAX_LENGTHS.task) : undefined;
	const rawQuery = params.query ? normalizeContent(params.query).slice(0, MAX_LENGTHS.task) : undefined;

	// Report card v2 fix: resolve effective query from either 'task' or 'query' param
	// Previously the query param was a no-op  -  now it drives learning/search
	const effectiveQuery = rawTask ?? rawQuery;

	// Parallel daemon queries  -  all read-only, all fast
	// NOTE: session/current is used instead of session/status because session/status
	// requires a sessionId parameter and always returns "Session not found" without one.
	// FIX 1: Added session/vitals as canonical source for pressure (single source of truth)
	// SB-HEALTH-001 R6: Added health/workspace for guard health data
	// Phase D CTI: Added topology/status (always) and topology/query (when task provided)
	const [
		sessionResult,
		vitalsResult,
		warningsResult,
		fragileResult,
		coChangeResult,
		guardHealthResult,
		topologyStatusResult,
		topologyQueryResult,
		learningSearchResult,
	] = await Promise.allSettled([
		daemon.request<SessionCurrentResponse>("session/current", buildSessionCurrentParams(workspace)),
		daemon.request<SessionVitalsResult>("session/vitals", { workspacePath: workspace }),
		daemon.request<IntelligenceWarningsResult>("intelligence/warnings", { workspace }),
		daemon.request<FragileFilesResult>("intelligence/fragile-files", { workspace }),
		daemon.request<DaemonCoChangesResponse>("intelligence/co-changes", { workspace }),
		daemon.request<HealthWorkspaceResult>("health/workspace", { workspace, profile: "fast" }),
		// Phase D CTI: Always get topology status for critical deviations
		daemon.request<TopologyStatusResult>("topology/status", { workspace }),
		// Phase D CTI: Query topology with task context when provided
		effectiveQuery
			? daemon.request<TopologyQueryResult>("topology/query", { workspace, task: effectiveQuery })
			: Promise.resolve(null as unknown as TopologyQueryResult),
		// Report card v2 fix: BM25 learning search when query/task is provided
		effectiveQuery
			? daemon.request<LearningSearchPulseResult>(
					"learning/search",
					buildLearningSearchParams(workspace, effectiveQuery, 5),
				)
			: Promise.resolve(null as unknown as LearningSearchPulseResult),
	]);

	// Extract results (graceful  -  any failed query returns null, doesn't fail the tool)
	const rawSession = sessionResult.status === "fulfilled" ? sessionResult.value : null;
	// Normalize session/current response → SessionStatusResult shape used by formatters
	const session = normalizeSessionStatus(rawSession);
	// FIX 1: Get vitals from canonical source (same as _sessionHealth uses)
	const vitals = vitalsResult.status === "fulfilled" ? vitalsResult.value : null;
	const warnings = warningsResult.status === "fulfilled" ? warningsResult.value : null;
	const fragile = fragileResult.status === "fulfilled" ? fragileResult.value : null;
	const coChanges = mapCoChangePairs(coChangeResult.status === "fulfilled" ? coChangeResult.value : null);
	// SB-HEALTH-001 R6: Get guard health data (cached, non-blocking)
	const guardHealth = guardHealthResult.status === "fulfilled" ? guardHealthResult.value : null;
	// Phase D CTI: Extract topology results (I-25: missing topology ≠ error)
	const topologyStatus = topologyStatusResult.status === "fulfilled" ? topologyStatusResult.value : null;
	const topologyQuery = topologyQueryResult.status === "fulfilled" ? topologyQueryResult.value : null;
	// Report card v2 fix: Extract learning search results (query-scoped intelligence)
	const learningSearch = learningSearchResult.status === "fulfilled" ? learningSearchResult.value : null;

	// Check for daemon connection errors
	if (!session && sessionResult.status === "rejected") {
		if (isDaemonConnectionError(sessionResult.reason)) {
			const errorResponse = formatDaemonError();
			const llmHint = composeHint({
				workspaceName: basename(workspace) || workspace,
				sessionId: "unknown",
				durationMinutes: 0,
				fragileFiles: [],
				coChanges: [],
				warnings: [],
				daemonError: true,
			});
			return {
				...errorResponse,
				llmHint,
				structuredContent: { ...(errorResponse.structuredContent ?? {}), llmHint },
			};
		}
	}

	// No active session  -  brief response
	if (!session || !session.active) {
		const llmHint = composeHint({
			workspaceName: basename(workspace) || workspace,
			sessionId: "unknown",
			durationMinutes: 0,
			fragileFiles: [],
			coChanges: [],
			warnings: [],
			noSession: true,
		});
		return {
			content: [
				{
					type: "text",
					text: 'No active session. Call vreko({ task: "..." }) to start one.',
				},
			],
			llmHint,
			structuredContent: { llmHint },
		};
	}

	// Compose intelligence briefing
	const response = formatPulseResponse({
		session,
		vitals,
		warnings,
		fragile,
		coChanges,
		guardHealth,
		topologyStatus,
		topologyQuery,
		learningSearch,
		focus: params.focus,
		task: effectiveQuery,
	});

	// Compute the structured llmHint from raw daemon signals and attach it to
	// the response. Kept as a top-level ToolResult field (not inside
	// content[].text) so the Claude Code PreToolUse hook (AMBIENT-06) can
	// extract it via `jq -r '.llmHint // empty'` and so agents can read it
	// deterministically regardless of how the text content was formatted.
	const filteredWarningsForHint = (warnings?.warnings ?? []).filter((w) => w.severity !== "info");
	const hintParams: ComposeHintParams =
		session.touchedFiles && session.touchedFiles.length === 0
			? {
					workspaceName: basename(workspace) || workspace,
					sessionId: rawSession?.id ?? "unknown",
					durationMinutes: Math.max(0, (session.durationMin ?? 0) | 0),
					fragileFiles: [],
					coChanges: [],
					warnings: [],
					noFilesTracked: true,
				}
			: buildComposeHintParams({
					workspace,
					sessionId: rawSession?.id,
					durationMinutes: session.durationMin ?? 0,
					fragile: fragile?.files ?? [],
					missingCoChanges: findMissingCoChanges(session.touchedFiles, coChanges),
					warnings: filteredWarningsForHint,
				});
	const hasHistory =
		hintParams.noFilesTracked === true ||
		(hintParams.fragileFiles?.length ?? 0) > 0 ||
		(hintParams.coChanges?.length ?? 0) > 0 ||
		(hintParams.warnings?.length ?? 0) > 0;
	if (hasHistory) {
		const llmHint = composeHint(hintParams);
		response.llmHint = llmHint;
		response.structuredContent = { ...(response.structuredContent ?? {}), llmHint };
	}
	// When hasHistory is false, response.llmHint remains undefined (absent from JSON wire format)

	const creditEstimate = getToolCreditEstimate("vreko_pulse");
	if (creditEstimate) {
		response.structuredContent = {
			...(response.structuredContent ?? {}),
			creditsEstimate: creditEstimate,
		};
	}

	// Fire feedback log (non-blocking)
	// NOTE: daemon.request may return undefined when unavailable  -  use optional chaining
	void daemon
		.request<IntelligenceCaptureResult>("intelligence/capture", {
			workspace,
			type: "pulse_check",
			data: {
				alertCount: warnings?.warnings?.length ?? 0,
				fragileFilesInScope: fragile?.files?.length ?? 0,
				missingCoChanges: countMissingCoChanges(session.touchedFiles, coChanges),
				sessionDurationMin: session.durationMin ?? 0,
			},
		})
		?.catch(() => {
			/* Fire and forget  -  pulse logging is best-effort */
		});

	return response;
};

// =============================================================================
// Response Formatter
// =============================================================================

interface FormatParams {
	session: SessionStatusResult;
	vitals: SessionVitalsResult | null;
	warnings: IntelligenceWarningsResult | null;
	fragile: FragileFilesResult | null;
	coChanges: CoChangePair[];
	guardHealth: HealthWorkspaceResult | null;
	topologyStatus: TopologyStatusResult | null;
	topologyQuery: TopologyQueryResult | null;
	/** Report card v2 fix: query-scoped learning search results */
	learningSearch: LearningSearchPulseResult | null;
	focus?: "risk" | "cochanges" | "vitals";
	task?: string;
}

function formatPulseResponse(data: FormatParams): ToolResult {
	const {
		session,
		vitals,
		warnings,
		fragile,
		coChanges,
		guardHealth,
		topologyStatus,
		topologyQuery,
		learningSearch,
		focus,
		task,
	} = data;
	const sections: string[] = [];

	// Apply progressive disclosure filtering
	const filteredWarnings = (warnings?.warnings ?? []).filter((w) => w.severity !== "info");
	const filteredFragile = (fragile?.files ?? []).filter((f) => f.fragility >= RISK_THRESHOLD);
	const missingCoChanges = findMissingCoChanges(session.touchedFiles, coChanges);

	// Build relevant learnings from query search (report card v2 fix)
	const queryLearnings = extractLearningsFromSearch(learningSearch);

	// Check if everything is healthy (including topology)
	// I-10: Critical deviations must always be shown  -  they override "healthy" status
	const hasCriticalDeviations = (topologyStatus?.critical_deviations?.length ?? 0) > 0;
	const topologyHealthy = !topologyStatus?.exists || !topologyStatus.stale;
	const isHealthy =
		filteredWarnings.length === 0 &&
		filteredFragile.length === 0 &&
		missingCoChanges.length === 0 &&
		topologyHealthy &&
		!hasCriticalDeviations;

	if (isHealthy) {
		// Still include guard health and query learnings in healthy response if available
		const healthyText = formatHealthyResponse(session, vitals);
		const _guardHealthFormatted = guardHealth ? formatGuardHealth(guardHealth, session.touchedFiles) : "";
		const guardHealthText = _guardHealthFormatted ? `\n\n${_guardHealthFormatted}` : "";
		// Report card v2 fix: include query-scoped learnings even when healthy
		const learningsText = queryLearnings.length > 0 ? `\n\n${formatQueryLearnings(queryLearnings, task)}` : "";
		return {
			content: [
				{
					type: "text",
					text: healthyText + guardHealthText + learningsText,
				},
			],
		};
	}

	// Format based on focus or full briefing
	if (!focus || focus === "risk") {
		// Alerts first (from warnings)
		if (filteredWarnings.length > 0) {
			sections.push(formatAlerts(filteredWarnings));
		}

		// Risk surface (fragile files)
		if (filteredFragile.length > 0) {
			sections.push(formatRiskSurface(filteredFragile));
		}
	}

	if (!focus || focus === "cochanges") {
		// Missing co-changes
		if (missingCoChanges.length > 0) {
			sections.push(formatMissingCoChanges(missingCoChanges));
		}
	}

	// Phase D CTI: Topology section (always included when available)
	if (topologyStatus?.exists) {
		sections.push(formatTopologySection(topologyStatus, topologyQuery, task));
	}

	// Report card v2 fix: Query-scoped learnings (shows when task/query was provided)
	if (queryLearnings.length > 0) {
		sections.push(formatQueryLearnings(queryLearnings, task));
	}

	if (!focus || focus === "vitals") {
		// Session vitals (FIX 1: uses canonical pressure from session/vitals)
		sections.push(formatVitals(session, vitals));
		// SB-HEALTH-001 R6: Guard health summary
		if (guardHealth) {
			const gh = formatGuardHealth(guardHealth, session.touchedFiles);
			if (gh) {
				sections.push(gh);
			}
		}
	}

	// Note: Structured `llmHint` is attached to the ToolResult by the handler
	// (ext_ambient/AMBIENT-01). The previous inline LLM_HINT text section was
	// removed  -  hint text now lives on `ToolResult.llmHint`, not inside the
	// `content[].text` blob, so agents and hooks parse it deterministically.

	// Phase 4 Intelligence Wiring: Add duration-aware guidance
	const durationGuidance = getDurationGuidance(
		session.durationMin,
		session.filesTouched,
		session.snapshotsCreated,
		vitals?.pressure,
	);
	if (durationGuidance) {
		sections.push(durationGuidance);
	}

	return {
		content: [{ type: "text", text: sections.join("\n\n") }],
	};
}

// =============================================================================
// Report Card v2 Fix: Query-Scoped Learning Helpers
// =============================================================================

/** Extract and normalize learnings from a learning search result */
function extractLearningsFromSearch(
	result: LearningSearchPulseResult | null,
): Array<{ text: string; relevanceScore: number }> {
	if (!result) {
		return [];
	}

	// Handle both result shapes from daemon (results[] or learnings[])
	const items = result.results ?? result.learnings ?? [];
	if (items.length === 0) {
		return [];
	}

	return items
		.map((item) => {
			// Cast to permissive type to handle both result shapes from daemon
			const entry = item as {
				id?: string;
				insight?: string;
				solution?: string;
				content?: string;
				action?: string;
				trigger?: string | string[];
				relevanceScore?: number;
			};
			// Normalize across daemon response variants
			const text =
				entry.insight ??
				entry.solution ??
				entry.content ??
				(entry.action && entry.trigger
					? `${Array.isArray(entry.trigger) ? entry.trigger.join(", ") : entry.trigger} → ${entry.action}`
					: (entry.action ?? ""));
			const score = entry.relevanceScore ?? 0.5;
			return { text, relevanceScore: score };
		})
		.filter((l) => l.text.length > 0)
		.sort((a, b) => b.relevanceScore - a.relevanceScore)
		.slice(0, 5);
}

/** Format query-scoped learnings as a pulse section */
function formatQueryLearnings(learnings: Array<{ text: string; relevanceScore: number }>, query?: string): string {
	const header = query
		? `💡 Relevant Learnings for "${query.length > 60 ? `${query.substring(0, 57)}...` : query}"`
		: "💡 Relevant Learnings";

	const lines = [header];
	for (const learning of learnings) {
		lines.push(`- ${learning.text}`);
	}
	return lines.join("\n");
}

function formatHealthyResponse(session: SessionStatusResult, vitals: SessionVitalsResult | null): string {
	const parts = ["✅ Session healthy."];
	if (session.durationMin) {
		parts.push(`${session.durationMin} min`);
	}
	if (vitals?.filesModified) {
		parts.push(`${vitals.filesModified} files touched`);
	} else if (session.filesTouched) {
		parts.push(`${session.filesTouched} files touched`);
	}
	const healthySnapshots = vitals?.snapshotsCreated ?? session.snapshotsCreated;
	if (healthySnapshots) {
		parts.push(`${healthySnapshots} snapshots`);
	}
	// Always show vitals numbers, even at baseline (FIX: don't hide behind "No concerns")
	if (vitals) {
		parts.push(`Pulse: ${vitals.pulse}`);
		parts.push(`Pressure: ${vitals.pressure}%`);
		parts.push(`Trajectory: ${vitals.trajectory}`);
	}
	parts.push("No concerns.");

	// Phase 4 Intelligence Wiring: Add duration-aware guidance for healthy sessions
	const durationGuidance = getDurationGuidance(
		session.durationMin,
		session.filesTouched,
		session.snapshotsCreated,
		vitals?.pressure,
	);
	if (durationGuidance) {
		parts.push(`\n${durationGuidance}`);
	}

	return parts.join(", ");
}

function formatAlerts(warnings: Warning[]): string {
	const lines: string[] = [];
	for (const w of warnings) {
		const icon = w.severity === "critical" ? "🚨" : w.severity === "warn" ? "⚠️" : "ℹ️";
		let line = `${icon} ALERT: ${w.message}`;
		if (w.action) {
			line += ` → ${w.action}`;
		}
		lines.push(line);
	}
	return lines.join("\n");
}

function formatRiskSurface(files: FragileFile[]): string {
	const lines = ["🔴 RISK SURFACE:"];
	for (const f of files) {
		const level = f.fragility >= 0.7 ? "CRITICAL" : f.fragility >= 0.5 ? "HIGH" : "MEDIUM";
		const reason = f.reason ?? "elevated risk";
		lines.push(`  ${f.path}  -  ${level} (${f.fragility.toFixed(2)})  -  ${reason}`);
	}
	return lines.join("\n");
}

function formatMissingCoChanges(pairs: Array<{ file: string; partner: string; confidence: number }>): string {
	const lines = ["📎 MISSING CO-CHANGE:"];
	for (const p of pairs) {
		lines.push(
			`You modified ${p.file} but not ${p.partner}  -  these files change together ${Math.round(p.confidence * 100)}% of the time.`,
		);
	}
	return lines.join("\n");
}

function formatVitals(session: SessionStatusResult, vitals: SessionVitalsResult | null): string {
	const parts = ["🫀 VITALS:"];
	if (session.durationMin) {
		parts.push(`${session.durationMin} min session`);
	}
	// FIX 1: Use canonical values from session/vitals endpoint
	const filesTouched = vitals?.filesModified ?? session.filesTouched ?? 0;
	const snapshotsCreated = vitals?.snapshotsCreated ?? session.snapshotsCreated ?? 0;

	if (filesTouched > 0) {
		parts.push(`${filesTouched} files touched`);
	}
	if (snapshotsCreated > 0) {
		parts.push(`${snapshotsCreated} snapshots`);
	}
	// Always show vitals numbers, even at baseline
	if (vitals) {
		parts.push(`Pulse: ${vitals.pulse}`);
		parts.push(`Pressure: ${vitals.pressure}%`);
		parts.push(`Trajectory: ${vitals.trajectory}`);
	}
	const unsnapshoted = filesTouched - snapshotsCreated;
	if (unsnapshoted > 3) {
		parts.push(`→ ${unsnapshoted} unsnapshotted changes`);
	}
	return parts.join(" · ");
}

/**
 * SB-HEALTH-001 R6: Format guard health data for pulse response
 * Shows guard summary with pass/warn/fail counts and relevant file-level issues.
 */
function formatGuardHealth(health: HealthWorkspaceResult, touchedFiles?: string[]): string {
	const passCount = health.guards.filter((g) => g.status === "pass").length;
	const warnCount = health.guards.filter((g) => g.status === "warn").length;
	const failCount = health.guards.filter((g) => g.status === "fail").length;
	const total = health.guards.length;

	// Guards not configured for this workspace (sub-package or uninitialised repo).
	// Return empty string so callers can omit the section entirely.
	if (total === 0 && !health.refreshing) {
		return "";
	}

	// First check still in progress  -  no results yet.
	if (total === 0 && health.refreshing) {
		return "🔍 GUARD HEALTH: checking...";
	}

	let statusIcon = "✅";
	if (failCount > 0) {
		statusIcon = "❌";
	} else if (warnCount > 0) {
		statusIcon = "⚠️";
	}

	// Build header with staleness info
	const staleSeconds = Math.floor(health.staleMs / 1000);
	const staleText =
		staleSeconds > 60
			? `${Math.floor(staleSeconds / 60)}m ago`
			: staleSeconds > 0
				? `${staleSeconds}s ago`
				: "just now";
	const refreshingText = health.refreshing ? " (refreshing...)" : "";

	const lines: string[] = [];
	lines.push(`${statusIcon} GUARD HEALTH: ${passCount}/${total} passing${refreshingText}`);

	// Show summary if there are issues
	if (failCount > 0 || warnCount > 0) {
		lines.push(`   Issues: ${failCount} failing, ${warnCount} warning${warnCount !== 1 ? "s" : ""}`);
	}

	// Filter to relevant issues (files touched in this session)
	// Use normalized full-path comparison to avoid false positives from filename-only matching
	const relevantIssues: Array<{ guard: string; status: string; file: GuardFile }> = [];
	const touchedSet = touchedFiles
		? new Set(touchedFiles.map((f) => f.replace(/\\/g, "/").replace(/\/+$/, "")))
		: new Set<string>();

	for (const guard of health.guards) {
		if (guard.status === "pass") {
			continue;
		}
		for (const file of guard.files) {
			const normalizedFilePath = file.path.replace(/\\/g, "/").replace(/\/+$/, "");
			// Include if file is in touched files OR if there are few issues total
			if (touchedSet.size === 0 || touchedSet.has(normalizedFilePath) || relevantIssues.length < 3) {
				relevantIssues.push({ guard: guard.guard, status: guard.status, file });
			}
		}
	}

	// Show top relevant issues (max 5)
	if (relevantIssues.length > 0) {
		lines.push("   Relevant issues:");
		for (const issue of relevantIssues.slice(0, 5)) {
			const icon = issue.status === "fail" ? "❌" : "⚠️";
			const lineText = issue.file.line ? `:${issue.file.line}` : "";
			const guardName = issue.guard
				.split("-")
				.map((w) => w.charAt(0).toUpperCase() + w.slice(1))
				.join(" ");
			lines.push(`   ${icon} ${issue.file.path}${lineText}  -  ${guardName}`);
			if (issue.file.message) {
				lines.push(`      ${issue.file.message.slice(0, 80)}${issue.file.message.length > 80 ? "..." : ""}`);
			}
		}
	}

	// Add staleness indicator
	lines.push(`   Last checked: ${staleText}`);

	return lines.join("\n");
}

/**
 * Phase D CTI: Format topology section for pulse response.
 *
 * Invariants enforced:
 * - I-10: Critical deviations always shown
 * - I-22: Briefing never exceeds 4KB (handled by resolver)
 * - I-25: Missing topology handled gracefully (doesn't reach here)
 * - I-26: Degradation produces usable response
 */
function formatTopologySection(status: TopologyStatusResult, query: TopologyQueryResult | null, task?: string): string {
	const lines: string[] = [];

	// Header with framework and staleness
	const staleIcon = status.stale ? "⚠️" : "🗺️";
	const staleText = status.stale ? " (STALE  -  rescan recommended)" : "";
	lines.push(`${staleIcon} TOPOLOGY: ${status.framework ?? "unknown"}${staleText}`);

	// Critical deviations (I-10: always shown)
	if (status.critical_deviations && status.critical_deviations.length > 0) {
		lines.push(`   🚨 Critical deviations (${status.critical_deviations.length}):`);
		for (const d of status.critical_deviations.slice(0, 3)) {
			lines.push(`   - ${d.file_path}: ${d.description}`);
		}
	}

	// Task-scoped briefing (only when task provided)
	if (task && query?.briefing) {
		const briefing = query.briefing;
		lines.push("");
		lines.push(`📋 TASK SCOPE: "${task.slice(0, 50)}${task.length > 50 ? "..." : ""}"`);
		lines.push(`   Confidence: ${Math.round(briefing.confidence * 100)}%`);

		// Primary files
		if (briefing.primary_files.length > 0) {
			lines.push(`   Primary files (${briefing.primary_files.length}):`);
			for (const f of briefing.primary_files.slice(0, 5)) {
				lines.push(`   - ${f.path} (${f.role})  -  ${f.reason}`);
			}
		}

		// Context files (condensed)
		if (briefing.context_files.length > 0) {
			lines.push(`   Context files: ${briefing.context_files.map((f) => f.path).join(", ")}`);
		}

		// Test files (condensed)
		if (briefing.test_files.length > 0) {
			lines.push(`   Test files: ${briefing.test_files.map((f) => f.path).join(", ")}`);
		}

		// Architectural boundaries
		if (briefing.boundaries.modules.length > 0) {
			lines.push(`   Modules: ${briefing.boundaries.modules.join(", ")}`);
		}
		if (briefing.boundaries.must_not_cross.length > 0) {
			lines.push(`   ⚠️ Do not touch: ${briefing.boundaries.must_not_cross.join(", ")}`);
		}

		// Behavioral warnings
		if (briefing.behavioral.fragile_files.length > 0) {
			lines.push(`   🔴 Fragile files in scope: ${briefing.behavioral.fragile_files.join(", ")}`);
		}

		// Task-relevant deviations
		if (briefing.deviations.length > 0) {
			lines.push(`   Deviations affecting scope (${briefing.deviations.length}):`);
			for (const d of briefing.deviations.slice(0, 2)) {
				lines.push(`   - [${d.severity}] ${d.description}`);
			}
		}
	} else if (task) {
		// Task provided but no briefing (topology missing or error)
		lines.push("   ℹ️ Task scope not available  -  topology may be missing or stale");
	}

	// Metadata
	lines.push(`   Files indexed: ${status.file_count ?? 0} | Deviations: ${status.deviation_count ?? 0}`);

	return lines.join("\n");
}

/**
 * Parameters for {@link composeHint}.
 *
 * See `.vreko-swarm/specs/ext_ambient/03-vreko-pulse-llm-hint-spec.md`
 * for the full composition contract. Keep this narrow  -  spec-08 (SessionRegistry)
 * will add `activePeers`, `overlaps`, `leases`, `goal`, `currentStep`, `driftSignal`
 * as optional additive fields.
 */
export interface ComposeHintParams {
	workspaceName: string;
	sessionId: string;
	durationMinutes: number;
	fragileFiles: Array<{ path: string; rollbackCount: number; evidence?: string }>;
	coChanges: Array<{ primary: string; partner: string; partnerTouched: boolean }>;
	warnings: Array<{ message: string; severity: string }>;
	daemonError?: boolean;
	noSession?: boolean;
	noFilesTracked?: boolean;
}

/**
 * Compose a deterministic LLM hint for the vreko_pulse response.
 *
 * Composition follows spec 03 Phase 2  -  session header + fragility line
 * + co-change line + warning line + behavior recommendation. Three edge
 * cases short-circuit with exact sentinel strings documented in the spec.
 *
 * Exported so the CLI pulse command (AMBIENT-02) can reuse the same composer
 * and keep agent-facing output consistent across MCP and CLI surfaces.
 *
 * Invariants (asserted by tests):
 * - Output always starts with "You are in <workspace>" OR a known edge-case sentinel
 * - Output never exceeds 400 space-separated tokens
 * - Same inputs → same output (deterministic)
 */
export function composeHint(params: ComposeHintParams): string {
	// Edge cases  -  return exact sentinel strings from spec 03
	if (params.daemonError) {
		return "Pulse unavailable (daemon error). Proceed with caution; Vreko intelligence degraded.";
	}
	if (params.noSession) {
		return "No active session. Call vreko to open one before working.";
	}
	if (params.noFilesTracked) {
		return "Session open, no files tracked yet. First save will register files with Vreko.";
	}

	const lines: string[] = [];

	// 1. Session header (always)
	lines.push(`You are in ${params.workspaceName}, session ${params.sessionId} (${params.durationMinutes}m).`);

	// 2. Fragility line
	const fragile = params.fragileFiles;
	if (fragile.length === 1) {
		const f = fragile[0];
		const evidence = f.evidence ? `; ${f.evidence}` : "";
		lines.push(`${f.path} is flagged fragile (${f.rollbackCount} rollbacks in 90 days${evidence}).`);
	} else if (fragile.length >= 2) {
		const list = fragile.map((f) => f.path).join(", ");
		const topByRollback = [...fragile].sort((a, b) => b.rollbackCount - a.rollbackCount)[0];
		lines.push(
			`${fragile.length} files in scope are flagged fragile: ${list}. Highest risk: ${topByRollback.path} (${topByRollback.rollbackCount} rollbacks).`,
		);
	}

	// 3. Co-change line (only if an untouched partner exists)
	const untouched = params.coChanges.filter((c) => !c.partnerTouched);
	if (untouched.length > 0) {
		const c = untouched[0];
		lines.push(
			`Co-change partner ${c.partner} hasn't been touched this session; if you're changing ${c.primary}, verify ${c.partner} expectations match.`,
		);
	}

	// 4. Warning line (if any)
	if (params.warnings.length > 0) {
		const severityRank: Record<string, number> = { critical: 3, warn: 2, info: 1 };
		const top = [...params.warnings].sort(
			(a, b) => (severityRank[b.severity] ?? 0) - (severityRank[a.severity] ?? 0),
		)[0];
		lines.push(`Active warnings: ${params.warnings.length}. Highest severity: ${top.message}.`);
	}

	// 5. Behavior recommendation (always terminal)
	const hasFragility = fragile.length > 0;
	const hasWarnings = params.warnings.length > 0;
	if (!hasFragility && !hasWarnings) {
		lines.push("No concerning signals. Proceed.");
	} else if (hasFragility && !hasWarnings) {
		lines.push(`Recommend: before editing ${fragile[0].path}, restate change plan and call vreko_learn.`);
	} else if (!hasFragility && hasWarnings) {
		lines.push("Recommend: address warning before continuing.");
	} else {
		lines.push(
			`Recommend: before editing ${fragile[0].path}, restate change plan and call vreko_learn. Also address warning before continuing.`,
		);
	}

	return lines.join("\n");
}

/**
 * Build composeHint() parameters from the raw daemon signals available in the
 * pulse handler. Centralizes the structural mapping so every return path stays
 * consistent and so peer-coordination fields (spec-08) have a single insertion
 * point later.
 *
 * @internal
 */
function buildComposeHintParams(input: {
	workspace: string;
	sessionId?: string;
	durationMinutes: number;
	fragile: FragileFile[];
	missingCoChanges: Array<{ file: string; partner: string; confidence: number }>;
	warnings: Warning[];
}): ComposeHintParams {
	const fragileFiles = input.fragile
		.filter((f) => f.fragility >= RISK_THRESHOLD)
		.map((f) => ({
			path: f.path,
			rollbackCount: f.rollbackCount ?? 0,
			evidence: f.reason,
		}));

	// All entries in `missingCoChanges` are, by construction, untouched-partner
	// pairs  -  `findMissingCoChanges` already filters to that case. We preserve
	// the `partnerTouched` flag on the ComposeHintParams contract so the composer
	// stays authoritative about the edge case rather than inferring it.
	const coChanges = input.missingCoChanges.map((c) => ({
		primary: c.file,
		partner: c.partner,
		partnerTouched: false,
	}));

	const warnings = input.warnings
		.filter((w) => w.severity !== "info")
		.map((w) => ({ message: w.message, severity: w.severity }));

	return {
		workspaceName: basename(input.workspace) || input.workspace,
		sessionId: input.sessionId ?? "unknown",
		durationMinutes: Math.max(0, input.durationMinutes | 0),
		fragileFiles,
		coChanges,
		warnings,
	};
}

// =============================================================================
// Helpers
// =============================================================================

function findMissingCoChanges(
	touchedFiles: string[] | undefined,
	pairs: CoChangePair[] | undefined,
): Array<{ file: string; partner: string; confidence: number }> {
	if (!touchedFiles || !pairs) {
		return [];
	}

	const touchedSet = new Set(touchedFiles);
	const missing: Array<{ file: string; partner: string; confidence: number }> = [];

	for (const pair of pairs) {
		// Filter by confidence threshold
		if (pair.confidence < CO_CHANGE_CONFIDENCE_THRESHOLD) {
			continue;
		}

		// Check if source was touched but target wasn't
		if (touchedSet.has(pair.source) && !touchedSet.has(pair.target)) {
			missing.push({ file: pair.source, partner: pair.target, confidence: pair.confidence });
		}
		// Also check reverse
		if (touchedSet.has(pair.target) && !touchedSet.has(pair.source)) {
			missing.push({ file: pair.target, partner: pair.source, confidence: pair.confidence });
		}
	}

	return missing.slice(0, 3); // Limit to top 3
}

function countMissingCoChanges(touchedFiles: string[] | undefined, pairs: CoChangePair[] | undefined): number {
	return findMissingCoChanges(touchedFiles, pairs).length;
}

