/**
 * VitalsEnricherService - Session Health Enrichment
 *
 * Single responsibility: Enrich MCP tool responses with session health and proactive alerts.
 * Extracted from server.ts to follow Single Responsibility Principle.
 *
 * @packageDocumentation
 */

import type { ToolResult } from "../registry.js";
import type { McpEventTracker } from "../telemetry/mcp-event-tracker.js";
import type { ProactiveAlert } from "../types/alerts.js";

/**
 * SessionHealth summary added to all tool responses
 * Provides workspace vitals visibility to AI agents
 */
export interface SessionHealth {
	pulse: string; // "resting" | "elevated" | "racing" | "critical"
	pressure: number; // 0-100
	trajectory: string; // "stable" | "escalating" | "critical" | "recovering"
	snapshotRecommended: boolean;
	hint?: string;
	// Proactive fields
	proactive_alerts?: ProactiveAlert[];
	next_action?: string;
}

/**
 * Vitals snapshot from intelligence service
 */
export interface VitalsSnapshot {
	pulse: { level: string; changesPerMinute: number };
	pressure: { value: number };
	trajectory: string;
}

/**
 * Interface for reading alerts from the alert queue
 */
export interface IAlertQueueReader {
	readPendingAlerts(workspaceRoot: string, maxAlerts?: number): ProactiveAlert[];
}

/**
 * Interface for accessing vitals data
 * Updated to async to support daemon queries (Pass 2 - Single Source of Truth)
 */
export interface IVitalsProvider {
	getVitalsSnapshot(workspaceRoot: string): Promise<VitalsSnapshot | null> | VitalsSnapshot | null;
}

/**
 * Default alert queue reader using filesystem
 */
export class FileSystemAlertQueueReader implements IAlertQueueReader {
	readPendingAlerts(workspaceRoot: string, maxAlerts = 3): ProactiveAlert[] {
		try {
			const path = require("node:path");
			const fs = require("node:fs");
			const alertsPath = path.join(workspaceRoot, ".vreko", "alerts.jsonl");

			if (!fs.existsSync(alertsPath)) {
				return [];
			}

			const content = fs.readFileSync(alertsPath, "utf-8");
			const lines = content.trim().split("\n").filter(Boolean);
			const pendingAlerts: ProactiveAlert[] = [];

			for (const line of lines.slice(-maxAlerts)) {
				try {
					const entry = JSON.parse(line);
					if (!entry.delivered && entry.confidence >= 80) {
						pendingAlerts.push({
							id: entry.id,
							timestamp: entry.timestamp,
							severity: entry.severity,
							category: entry.category,
							summary: entry.summary,
							details: entry.details,
							suggested_action: entry.suggested_action,
							confidence: entry.confidence,
							dismissible: entry.dismissible,
						});
					}
				} catch {
					// Skip malformed entries
				}
			}

			return pendingAlerts;
		} catch {
			return [];
		}
	}
}

/**
 * Service for enriching tool responses with session health data
 */
export class VitalsEnricherService {
	constructor(
		private readonly vitalsProvider: IVitalsProvider,
		private readonly alertReader: IAlertQueueReader = new FileSystemAlertQueueReader(),
	) {}

	/**
	 * Enhance a tool result with SessionHealth data and proactive alerts
	 *
	 * @param result - The tool result to enhance
	 * @param workspaceRoot - Workspace root path
	 * @param eventTracker - Optional event tracker for telemetry
	 * @returns Enhanced tool result
	 */
	async enhance(result: ToolResult, workspaceRoot: string, eventTracker?: McpEventTracker): Promise<ToolResult> {
		// Validate input
		if (!result || !Array.isArray(result.content)) {
			return {
				content: [{ type: "text", text: JSON.stringify({ error: "Invalid result structure" }) }],
				isError: true,
			};
		}

		// Skip enhancement for error results
		if (result.isError) {
			return result;
		}

		try {
			const vitals = await Promise.resolve(this.vitalsProvider.getVitalsSnapshot(workspaceRoot));

			if (!vitals) {
				return result;
			}

			// Build session health summary
			const sessionHealth = this.buildSessionHealth(vitals, workspaceRoot, eventTracker);

			// Parse existing result and add _sessionHealth
			const originalText = result.content[0]?.text;
			if (originalText) {
				try {
					const parsed = JSON.parse(originalText);
					const enhanced = {
						...parsed,
						_sessionHealth: sessionHealth,
					};
					return {
						content: [{ type: "text", text: JSON.stringify(enhanced, null, 2) }],
						isError: false,
					};
				} catch {
					// If not JSON, return original result without appending raw session health
					// The session health is only added to structured JSON responses
					return result;
				}
			}

			return result;
		} catch {
			// If vitals retrieval fails, return original result
			return result;
		}
	}

	/**
	 * Build session health summary from vitals
	 */
	private buildSessionHealth(
		vitals: VitalsSnapshot,
		workspaceRoot: string,
		eventTracker?: McpEventTracker,
	): SessionHealth {
		const sessionHealth: SessionHealth = {
			pulse: vitals.pulse.level,
			pressure: vitals.pressure.value,
			trajectory: vitals.trajectory,
			snapshotRecommended: vitals.pressure.value > 60 || vitals.trajectory === "escalating",
		};

		// Read proactive alerts
		const pendingAlerts = this.alertReader.readPendingAlerts(workspaceRoot);

		if (pendingAlerts.length > 0) {
			sessionHealth.proactive_alerts = pendingAlerts;

			// Track telemetry for shown alerts
			if (eventTracker) {
				for (const alert of pendingAlerts) {
					eventTracker.trackAlertShown({
						alert_id: alert.id,
						category: alert.category,
						severity: alert.severity,
						confidence: alert.confidence,
						delivery_method: "enriched_response",
					});
				}
			}

			// Suggest next action based on critical alerts
			const critical = pendingAlerts.find((a) => a.severity === "critical");
			if (critical) {
				sessionHealth.next_action = critical.suggested_action || "Review critical alert";
			}
		}

		// Add hint for elevated states
		// Note: Snapshots are automatic based on risk, so hints focus on caution not manual action
		if (vitals.trajectory === "critical" || vitals.pressure.value > 80) {
			sessionHealth.hint = "High risk state detected - proceed with caution, major changes should be incremental";
		} else if (vitals.pulse.level === "racing") {
			sessionHealth.hint = "High change velocity detected - take care with modifications";
		}

		return sessionHealth;
	}
}
