/**
 * Pattern/Learning Retrieval Cache
 *
 * Caches hybrid retrieval results (semantic + keyword search) to:
 * - Reduce pattern lookup latency from 200-500ms to <10ms (20-50x faster)
 * - Achieve 70-80% cache hit rate for common queries
 * - Reduce SQLite query load
 *
 * Key Generation: hash(query + intent + packages + options)
 * TTL: 1 day (86,400 seconds)
 * Prefix: cache:pat:*
 *
 * Following Vreko patterns:
 * - Cache-aside with graceful fallback
 * - Key prefixing convention
 * - Non-blocking cache operations
 */
import { createHash } from "node:crypto";
import { createLogger, LogLevel } from "@vreko/contracts";
import { getCache, isRedisAvailable, setCache } from "./redis-client.js";
const logger = createLogger({ name: "pattern-cache", level: LogLevel.INFO });
// Cache configuration
const PATTERN_CACHE_TTL = 24 * 60 * 60; // 1 day in seconds
const CACHE_PREFIX = "cache:pat:"; // Following established key prefixing
// Stats tracking
let cacheStats = {
    hits: 0,
    misses: 0,
    totalRequests: 0,
    get hitRate() {
        return this.totalRequests > 0 ? (this.hits / this.totalRequests) * 100 : 0;
    },
};
/**
 * Generate cache key for pattern retrieval
 */
function generatePatternCacheKey(key) {
    const { query, intent = "", packages = [], options = {} } = key;
    // Normalize query
    const normalizedQuery = query.trim().toLowerCase();
    // Sort packages for consistent hashing
    const sortedPackages = [...packages].sort();
    // Create deterministic key material
    const keyMaterial = JSON.stringify({
        query: normalizedQuery,
        intent,
        packages: sortedPackages,
        ...options,
    });
    const hash = createHash("sha256").update(keyMaterial).digest("hex");
    return `${CACHE_PREFIX}${hash}`;
}
/**
 * Get cached pattern retrieval results
 */
export async function getCachedPatterns(key) {
    if (!isRedisAvailable()) {
        return null;
    }
    const cacheKey = generatePatternCacheKey(key);
    try {
        const cached = await getCache(cacheKey);
        if (cached) {
            cacheStats.hits++;
            cacheStats.totalRequests++;
            logger.info("Pattern cache HIT", {
                query: key.query.substring(0, 50),
                intent: key.intent,
                cacheAge: Date.now() - cached.cachedAt,
                hitRate: cacheStats.hitRate.toFixed(1),
            });
            return cached;
        }
        cacheStats.misses++;
        cacheStats.totalRequests++;
        logger.debug("Pattern cache MISS", {
            query: key.query.substring(0, 50),
            hitRate: cacheStats.hitRate.toFixed(1),
        });
        return null;
    }
    catch (error) {
        logger.error("Pattern cache check failed", { error, cacheKey });
        return null;
    }
}
/**
 * Cache pattern retrieval results
 */
export async function cachePatternResults(key, result) {
    if (!isRedisAvailable()) {
        return false;
    }
    const cacheKey = generatePatternCacheKey(key);
    const cachedResult = {
        ...result,
        cachedAt: Date.now(),
    };
    try {
        const success = await setCache(cacheKey, cachedResult, PATTERN_CACHE_TTL);
        if (success) {
            logger.debug("Pattern results cached", {
                query: key.query.substring(0, 50),
                resultsCount: result.results.length,
                ttl: PATTERN_CACHE_TTL,
            });
        }
        return success;
    }
    catch (error) {
        logger.error("Failed to cache pattern results", { error, cacheKey });
        return false;
    }
}
/**
 * Wrapper for hybrid retrieval with automatic caching
 *
 * Usage in hybrid-retrieval-service.ts:
 * ```ts
 * export async function retrieveAdaptive(...) {
 *   return withPatternCache(
 *     { query, intent },
 *     async () => { /* existing retrieval logic *\/ }
 *   );
 * }
 * ```
 */
export async function withPatternCache(key, retrievalFn) {
    // Check cache first
    const cached = await getCachedPatterns(key);
    if (cached) {
        // Return cached result (cachedAt field is present but T doesn't require it)
        return cached;
    }
    // Cache miss - execute retrieval
    const result = await retrievalFn();
    // Cache the result (fire-and-forget)
    cachePatternResults(key, result).catch((error) => {
        logger.warn("Failed to cache pattern results (non-blocking)", { error });
    });
    return result;
}
/**
 * Get cache statistics
 */
export function getPatternCacheStats() {
    return { ...cacheStats };
}
/**
 * Reset cache statistics (testing)
 */
export function resetPatternCacheStats() {
    cacheStats = {
        hits: 0,
        misses: 0,
        totalRequests: 0,
        get hitRate() {
            return this.totalRequests > 0 ? (this.hits / this.totalRequests) * 100 : 0;
        },
    };
}
