/**
 * Static analysis for begin-task
 *
 * Runs static analysis on planned files and generates proactive guidance.
 *
 * @module facades/begin-task/static-analysis
 *
 * DEPRECATED (Day 4): Direct @vreko/intelligence imports replaced with daemon IPC.
 * Advisory suggestions now route through the daemon.
 */

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { ProactiveGuidance, StaticAnalysisOutput } from "./types.js";

// =============================================================================
// STATIC ANALYSIS
// =============================================================================

/**
 * Run static analysis on planned files
 * Uses dynamic import to avoid build-time coupling with @vreko/core
 */
export async function runStaticAnalysis(files: string[], workspaceRoot: string): Promise<StaticAnalysisOutput> {
	const startTime = Date.now();
	const result: StaticAnalysisOutput = {
		skippedTests: [],
		success: true,
		duration: 0,
		errors: [],
	};

	// Only analyze test files
	const testFiles = files.filter((f) => f.includes(".test.") || f.includes(".spec.") || f.includes("__tests__"));

	if (testFiles.length === 0) {
		result.duration = Date.now() - startTime;
		return result;
	}

	try {
		// Build file map with contents
		const fileMap = new Map<string, string>();
		for (const filePath of testFiles) {
			const fullPath = filePath.startsWith("/") ? filePath : join(workspaceRoot, filePath);
			if (existsSync(fullPath)) {
				try {
					const content = readFileSync(fullPath, "utf8");
					fileMap.set(filePath, content);
				} catch {
					// Skip files that can't be read
				}
			}
		}

		if (fileMap.size === 0) {
			result.duration = Date.now() - startTime;
			return result;
		}

		// Dynamic import to avoid build-time coupling
		const { analyzeSkippedTests } = await import("@vreko/core/analysis");
		const analysisResults = analyzeSkippedTests(fileMap);

		for (const analysisResult of analysisResults) {
			if (!analysisResult.parsed && analysisResult.error) {
				result.errors.push(`Parse error in ${analysisResult.file}: ${analysisResult.error}`);
			}
			for (const skipped of analysisResult.skipped) {
				result.skippedTests.push({
					file: skipped.file,
					type: skipped.type,
					name: skipped.name,
					line: skipped.line,
				});
			}
		}
	} catch (error) {
		// Static analysis is optional - don't fail the task
		result.errors.push(`Static analysis unavailable: ${error instanceof Error ? error.message : String(error)}`);
	}

	result.duration = Date.now() - startTime;
	result.success = result.errors.length === 0;

	return result;
}

// =============================================================================
// PROACTIVE GUIDANCE
// =============================================================================

/**
 * Generate proactive guidance using daemon IPC.
 * Routes advisory suggestions through the daemon (Day 4: daemon-first architecture).
 */
export async function generateProactiveGuidance(files: string[], _workspaceRoot: string): Promise<ProactiveGuidance> {
	const guidance: ProactiveGuidance = {
		summary:
			files.length > 0 ? `Analyzing ${files.length} file${files.length > 1 ? "s" : ""}` : "No files targeted",
		suggestions: [],
	};

	return guidance;
}
