/**
 * MCP Session State Utilities
 *
 * Pure functions for session state management.
 * These functions have no side effects and can be safely imported
 * without triggering any state initialization.
 *
 * @module session/utils
 */

import { execSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, unlinkSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { log, type RequestContext } from "../errors/index.js";
import type { GitFileStatus, MCPSessionState, RiskArea } from "./types.js";

// Create a module-level request context for logging
const moduleCtx: RequestContext = {
	requestId: "session-utils",
	tool: "session/utils",
	startTime: Date.now(),
};

// =============================================================================
// TASK ID GENERATION
// =============================================================================

/**
 * Generate a unique task ID
 *
 * @returns Unique task identifier in format: task_{timestamp}_{random}
 */
export function generateTaskId(): string {
	const timestamp = Date.now().toString(36);
	const random = Math.random().toString(36).substring(2, 8);
	return `task_${timestamp}_${random}`;
}

// =============================================================================
// KEYWORD EXTRACTION
// =============================================================================

/**
 * Extract keywords from task description
 *
 * @param taskDescription - The task description text
 * @returns Array of up to 5 unique keywords
 */
export function extractKeywords(taskDescription: string): string[] {
	// Remove common words and punctuation
	const stopWords = new Set([
		"a",
		"an",
		"the",
		"to",
		"for",
		"of",
		"in",
		"on",
		"at",
		"and",
		"or",
		"but",
		"is",
		"are",
		"was",
		"were",
		"be",
		"been",
		"being",
		"have",
		"has",
		"had",
		"do",
		"does",
		"did",
		"will",
		"would",
		"could",
		"should",
		"may",
		"might",
		"i",
		"we",
		"you",
		"they",
		"it",
		"this",
		"that",
		"with",
		"from",
		"by",
		"add",
		"update",
		"fix",
		"implement",
		"create",
		"make",
		"change",
		"modify",
	]);

	const words = taskDescription
		.toLowerCase()
		.replace(/[^\w\s-]/g, " ")
		.split(/\s+/)
		.filter((word) => word.length > 2 && !stopWords.has(word));

	// Return unique keywords (max 5)
	return [...new Set(words)].slice(0, 5);
}

// =============================================================================
// DURATION FORMATTING
// =============================================================================

/**
 * Format duration in human-readable format
 *
 * @param ms - Duration in milliseconds
 * @returns Human-readable duration string
 */
export function formatDuration(ms: number): string {
	const minutes = Math.floor(ms / 60000);
	const hours = Math.floor(minutes / 60);

	if (hours > 0) {
		const remainingMinutes = minutes % 60;
		return `${hours}h ${remainingMinutes}m`;
	}

	if (minutes > 0) {
		return `${minutes} minute${minutes !== 1 ? "s" : ""}`;
	}

	return "less than a minute";
}

// =============================================================================
// RISK AREA DETECTION
// =============================================================================

/**
 * Detect risk areas from file path
 *
 * @param filePath - File path to analyze
 * @returns Array of detected risk areas
 */
export function detectRiskAreas(filePath: string): RiskArea[] {
	const areas: RiskArea[] = [];
	const lowerPath = filePath.toLowerCase();

	if (lowerPath.includes("auth") || lowerPath.includes("login") || lowerPath.includes("session")) {
		areas.push("auth");
	}
	if (lowerPath.includes("payment") || lowerPath.includes("stripe") || lowerPath.includes("billing")) {
		areas.push("payment");
	}
	if (lowerPath.includes("database") || lowerPath.includes("db") || lowerPath.includes("migration")) {
		areas.push("database");
	}
	if (lowerPath.includes("config") || lowerPath.includes(".env") || lowerPath.includes("settings")) {
		areas.push("config");
	}
	if (lowerPath.includes("api") || lowerPath.includes("route") || lowerPath.includes("endpoint")) {
		areas.push("api");
	}
	if (lowerPath.includes("security") || lowerPath.includes("crypto") || lowerPath.includes("secret")) {
		areas.push("security");
	}

	return areas;
}

// =============================================================================
// GIT BASELINE HELPERS
// =============================================================================

/**
 * Capture current git status as baseline
 * Call this when starting a task to know what was already modified
 *
 * @param workspaceRoot - Workspace root path
 * @returns Array of git file statuses at baseline
 */
export function captureGitBaseline(workspaceRoot: string): GitFileStatus[] {
	const baseline: GitFileStatus[] = [];
	const now = Date.now();

	try {
		const result = execSync("git status --porcelain", {
			cwd: workspaceRoot,
			encoding: "utf8",
			timeout: 5000, // 5s timeout to prevent blocking
		});

		for (const line of result.split("\n")) {
			if (!line.trim()) {
				continue;
			}

			const statusCode = line.substring(0, 2);
			const file = line.substring(3).trim();

			let status: "A" | "M" | "D" | "?" = "M";
			if (statusCode.includes("A") || statusCode === "??") {
				status = statusCode === "??" ? "?" : "A";
			} else if (statusCode.includes("D")) {
				status = "D";
			}

			baseline.push({ file, status, timestamp: now });
		}
	} catch (error) {
		// Git not available or not a git repo - log at debug level and return empty baseline
		log("debug", moduleCtx, "Git baseline capture failed (not a git repo or git unavailable)", {
			workspaceRoot,
			error: error instanceof Error ? error.message : String(error),
		});
	}

	return baseline;
}

/**
 * Check if a file was in the baseline (existed before task started)
 *
 * @param file - File path to check
 * @param baseline - Git baseline array
 * @returns Whether file was in baseline
 */
export function isInBaseline(file: string, baseline: GitFileStatus[] | undefined): boolean {
	if (!baseline || baseline.length === 0) {
		return false;
	}
	return baseline.some((b) => b.file === file);
}

// =============================================================================
// DEFAULT STATE CREATION
// =============================================================================

/**
 * Create default session state
 *
 * @returns Fresh MCPSessionState with default values
 */
export function createDefaultState(): MCPSessionState {
	return {
		currentTask: null,
		changesSinceTaskStart: [],
		pendingObservations: [],
		surfacedLearnings: [],
		riskAreasTouched: [],
		validatedFiles: [],
		stats: {
			tasksCompleted: 0,
			snapshotsCreated: 0,
			restoresPerformed: 0,
			learningsCaptured: 0,
			riskAnalysesPerformed: 0,
		},
		pendingSuggestedLearnings: [],
		nextActionLog: {
			suggested: [],
			actualCalls: [],
		},
		toolCallLog: [],
		validationEvents: [],
	};
}

// =============================================================================
// PERSISTENCE UTILITIES
// =============================================================================

/**
 * Get state file path
 *
 * @param workspaceRoot - Workspace root path
 * @returns Path to session state file
 */
export function getStateFilePath(workspaceRoot: string): string {
	return join(workspaceRoot, ".vreko", "mcp", "session-state.json");
}

/**
 * Save state to disk
 *
 * @param workspaceRoot - Workspace root path
 * @param state - Session state to save
 */
export function saveStateToDisk(workspaceRoot: string, state: MCPSessionState): void {
	const filePath = getStateFilePath(workspaceRoot);

	try {
		const dir = dirname(filePath);
		if (!existsSync(dir)) {
			mkdirSync(dir, { recursive: true });
		}

		writeFileSync(filePath, JSON.stringify(state, null, 2), "utf8");
	} catch (error) {
		// Log at debug level - write errors are non-critical but useful for debugging
		log("debug", moduleCtx, "Failed to persist session state to disk", {
			filePath,
			error: error instanceof Error ? error.message : String(error),
		});
	}
}

/**
 * Load state from disk
 *
 * @param workspaceRoot - Workspace root path
 * @returns Loaded state or null if not found/corrupted
 */
export function loadStateFromDisk(workspaceRoot: string): MCPSessionState | null {
	const filePath = getStateFilePath(workspaceRoot);

	try {
		if (existsSync(filePath)) {
			const content = readFileSync(filePath, "utf8");
			const loaded = JSON.parse(content) as Partial<MCPSessionState>;
			// P0-005: Merge with defaults to ensure all required fields exist
			// This prevents "Cannot read properties of undefined (reading 'map')" errors
			// when old state files are missing newer fields like pendingObservations
			const defaults = createDefaultState();
			return {
				...defaults,
				...loaded,
				// Ensure arrays are never undefined (defensive merge)
				changesSinceTaskStart: loaded.changesSinceTaskStart ?? defaults.changesSinceTaskStart,
				pendingObservations: loaded.pendingObservations ?? defaults.pendingObservations,
				surfacedLearnings: loaded.surfacedLearnings ?? defaults.surfacedLearnings,
				riskAreasTouched: loaded.riskAreasTouched ?? defaults.riskAreasTouched,
				validatedFiles: loaded.validatedFiles ?? defaults.validatedFiles,
				pendingSuggestedLearnings: loaded.pendingSuggestedLearnings ?? defaults.pendingSuggestedLearnings,
				stats: { ...defaults.stats, ...loaded.stats },
				nextActionLog: {
					suggested: loaded.nextActionLog?.suggested ?? defaults.nextActionLog?.suggested ?? [],
					actualCalls: loaded.nextActionLog?.actualCalls ?? defaults.nextActionLog?.actualCalls ?? [],
				},
				toolCallLog: loaded.toolCallLog ?? defaults.toolCallLog,
				validationEvents: loaded.validationEvents ?? defaults.validationEvents,
			};
		}
	} catch (error) {
		// Log at debug level - read errors may indicate corrupted state file
		log("debug", moduleCtx, "Failed to load session state from disk", {
			filePath,
			error: error instanceof Error ? error.message : String(error),
		});
	}

	return null;
}

/**
 * Clear state from disk
 *
 * @param workspaceRoot - Workspace root path
 */
export function clearStateFromDisk(workspaceRoot: string): void {
	const filePath = getStateFilePath(workspaceRoot);

	try {
		if (existsSync(filePath)) {
			unlinkSync(filePath);
		}
	} catch (error) {
		// Log at debug level - delete errors are non-critical
		log("debug", moduleCtx, "Failed to clear session state file", {
			filePath,
			error: error instanceof Error ? error.message : String(error),
		});
	}
}
