/**
 * Handle vreko_refactor_assess tool.
 */
export async function handleRefactorAssess(args: Record<string, unknown>, context: ToolContext): Promise<ToolResult> {
	const {
		workspace,
		limit = 10,
		minPriority = "medium",
	} = args as {
		workspace: string;
		limit?: number;
		minPriority?: "critical" | "high" | "medium" | "low";
	};

	try {
		// Try daemon service first
		if (context.services?.daemon?.isAvailable()) {
			const result = await context.services.daemon.request<{
				recommendations: Array<{
					id: string;
					name: string;
					action: string;
					priority: string;
					priorityScore: number;
					confidence: number;
					rationale: string;
					nextSteps: string[];
				}>;
			}>("refactoring.getTopRecommendations", {
				workspace,
				limit,
				minPriority,
			});

			if (result) {
				return formatAssessResult(result.recommendations);
			}
		}

		return formatAssessResult([]);
	} catch (error) {
		return {
			content: [
				{
					type: "text",
					text: `Refactoring assessment failed: ${error instanceof Error ? error.message : String(error)}`,
				},
			],
			isError: true,
		};
	}
}

/**
 * Format assessment result for display.
 */
function formatAssessResult(
	recommendations: Array<{
		id: string;
		name: string;
		action: string;
		priority: string;
		priorityScore: number;
		confidence: number;
		rationale: string;
		nextSteps: string[];
	}>,
): ToolResult {
	if (recommendations.length === 0) {
		return {
			content: [
				{
					type: "text",
					text: "No refactoring recommendations found. The codebase appears healthy.",
				},
			],
		};
	}

	const lines: string[] = [
		"# Refactoring Assessment Results",
		"",
		`Found ${recommendations.length} recommendation(s):`,
		"",
	];

	for (const rec of recommendations) {
		const priorityEmoji =
			rec.priority === "critical"
				? "🔴"
				: rec.priority === "high"
					? "🟠"
					: rec.priority === "medium"
						? "🟡"
						: "🟢";
		const actionEmoji =
			rec.action === "refactor-now"
				? "⚡"
				: rec.action === "schedule"
					? "📅"
					: rec.action === "defer"
						? "⏳"
						: "👀";

		lines.push(`## ${priorityEmoji} ${rec.name}`);
		lines.push(`- **Action**: ${actionEmoji} ${rec.action}`);
		lines.push(`- **Priority**: ${rec.priority} (score: ${rec.priorityScore})`);
		lines.push(`- **Confidence**: ${Math.round(rec.confidence * 100)}%`);
		lines.push(`- **Rationale**: ${rec.rationale}`);
		lines.push(`- **Next Steps**: ${rec.nextSteps.join("; ")}`);
		lines.push("");
	}

	return {
		content: [
			{
				type: "text",
				text: lines.join("\n"),
			},
		],
	};
}

/**
 * Handle vreko_refactor_report tool.
 */
export async function handleRefactorReport(args: Record<string, unknown>, context: ToolContext): Promise<ToolResult> {
	const { workspace, includeAllCandidates = false } = args as {
		workspace: string;
		includeAllCandidates?: boolean;
	};

	try {
		// Try daemon service first
		if (context.services?.daemon?.isAvailable()) {
			const result = await context.services.daemon.request<{
				summary: {
					totalComponents: number;
					recommendationsCount: number;
					criticalCount: number;
					highCount: number;
					mediumCount: number;
					lowCount: number;
					avgConfidence: number;
				};
				topRecommendations: Array<{
					id: string;
					name: string;
					action: string;
					priority: string;
					priorityScore: number;
					confidence: number;
					rationale: string;
					nextSteps: string[];
				}>;
				dataQuality: {
					overall: string;
					missingCollectors: string[];
					confidenceExplanation: string;
				};
			}>("refactoring.report", { workspace });

			if (result) {
				return formatReportResult(result, includeAllCandidates);
			}
		}

		return formatReportResult(
			{
				summary: {
					totalComponents: 0,
					recommendationsCount: 0,
					criticalCount: 0,
					highCount: 0,
					mediumCount: 0,
					lowCount: 0,
					avgConfidence: 0,
				},
				topRecommendations: [],
				dataQuality: {
					overall: "low",
					missingCollectors: ["daemon-unavailable"],
					confidenceExplanation: "Daemon IPC unavailable for assessment",
				},
			},
			includeAllCandidates,
		);
	} catch (error) {
		return {
			content: [
				{
					type: "text",
					text: `Refactoring report failed: ${error instanceof Error ? error.message : String(error)}`,
				},
			],
			isError: true,
		};
	}
}

/**
 * Format report result for display.
 */
function formatReportResult(
	report: {
		summary: {
			totalComponents: number;
			recommendationsCount: number;
			criticalCount: number;
			highCount: number;
			mediumCount: number;
			lowCount: number;
			avgConfidence: number;
		};
		topRecommendations: Array<{
			id: string;
			name: string;
			action: string;
			priority: string;
			priorityScore: number;
			confidence: number;
			rationale: string;
			nextSteps: string[];
		}>;
		dataQuality: {
			overall: string;
			missingCollectors: string[];
			confidenceExplanation: string;
		};
	},
	_includeAllCandidates: boolean,
): ToolResult {
	const lines: string[] = [
		"# Refactoring Intelligence Report",
		"",
		"## Summary",
		`- **Total Components**: ${report.summary.totalComponents}`,
		`- **Recommendations**: ${report.summary.recommendationsCount}`,
		`  - 🔴 Critical: ${report.summary.criticalCount}`,
		`  - 🟠 High: ${report.summary.highCount}`,
		`  - 🟡 Medium: ${report.summary.mediumCount}`,
		`  - 🟢 Low: ${report.summary.lowCount}`,
		`- **Average Confidence**: ${Math.round(report.summary.avgConfidence * 100)}%`,
		"",
		"## Data Quality",
		`- **Overall**: ${report.dataQuality.overall}`,
		`- **Missing Collectors**: ${report.dataQuality.missingCollectors.join(", ") || "none"}`,
		`- **Explanation**: ${report.dataQuality.confidenceExplanation}`,
		"",
	];

	if (report.topRecommendations.length > 0) {
		lines.push("## Top Recommendations");
		lines.push("");

		for (const rec of report.topRecommendations) {
			const priorityEmoji =
				rec.priority === "critical"
					? "🔴"
					: rec.priority === "high"
						? "🟠"
						: rec.priority === "medium"
							? "🟡"
							: "🟢";
			const actionEmoji =
				rec.action === "refactor-now"
					? "⚡"
					: rec.action === "schedule"
						? "📅"
						: rec.action === "defer"
							? "⏳"
							: "👀";

			lines.push(`### ${priorityEmoji} ${rec.name}`);
			lines.push(`- **Action**: ${actionEmoji} ${rec.action}`);
			lines.push(`- **Priority**: ${rec.priority} (score: ${rec.priorityScore})`);
			lines.push(`- **Confidence**: ${Math.round(rec.confidence * 100)}%`);
			lines.push(`- **Rationale**: ${rec.rationale}`);
			lines.push(`- **Next Steps**: ${rec.nextSteps.join("; ")}`);
			lines.push("");
		}
	}

	return {
		content: [
			{
				type: "text",
				text: lines.join("\n"),
			},
		],
	};
}

/**
 * Handle vreko_refactor_set_gate tool.
 */
export async function handleRefactorSetGate(args: Record<string, unknown>, context: ToolContext): Promise<ToolResult> {
	const { workspace, componentId, gate, status } = args as {
		workspace: string;
		componentId: string;
		gate: "migrationPlan" | "rollbackStrategy" | "ownerAssigned" | "stakeholderSignoff";
		status: "pass" | "fail" | "warn" | "pending";
	};

	try {
		// Try daemon service first
		if (context.services?.daemon?.isAvailable()) {
			const result = await context.services.daemon.request<{
				success: boolean;
				gates: Record<string, string>;
				message: string;
			}>("refactoring.setGate", {
				workspace,
				componentId,
				gate,
				status,
			});

			if (result) {
				return {
					content: [
						{
							type: "text",
							text: `✅ Gate updated for ${componentId}\n\n${result.message}\n\nCurrent gates:\n${Object.entries(
								result.gates,
							)
								.map(([k, v]) => `  - ${k}: ${v}`)
								.join("\n")}`,
						},
					],
				};
			}
		}

		// Fallback: Return informational message
		return {
			content: [
				{
					type: "text",
					text: `Gate '${gate}' for component '${componentId}' would be set to '${status}'.\n\nNote: Daemon not available. Gates will be persisted when daemon is connected.`,
				},
			],
		};
	} catch (error) {
		return {
			content: [
				{
					type: "text",
					text: `Set gate failed: ${error instanceof Error ? error.message : String(error)}`,
				},
			],
			isError: true,
		};
	}
}

/**
 * Handle vreko_refactor_stats tool.
 */
export async function handleRefactorStats(args: Record<string, unknown>, context: ToolContext): Promise<ToolResult> {
	const { workspace } = args as { workspace: string };

	try {
		// Try daemon service first
		if (context.services?.daemon?.isAvailable()) {
			const result = await context.services.daemon.request<{
				totalComponents: number;
				recommendationsCount: number;
				readyToRefactor: number;
				scheduled: number;
				deferred: number;
				byPriority: {
					critical: number;
					high: number;
					medium: number;
					low: number;
				};
				avgConfidence: number;
				dataQuality: string;
			}>("refactoring.getStats", { workspace });

			if (result) {
				return formatStatsResult(result);
			}
		}

		return formatStatsResult({
			totalComponents: 0,
			recommendationsCount: 0,
			readyToRefactor: 0,
			scheduled: 0,
			deferred: 0,
			byPriority: { critical: 0, high: 0, medium: 0, low: 0 },
			avgConfidence: 0,
			dataQuality: "unavailable",
		});
	} catch (error) {
		return {
			content: [
				{
					type: "text",
					text: `Get stats failed: ${error instanceof Error ? error.message : String(error)}`,
				},
			],
			isError: true,
		};
	}
}

/**
 * Format stats result for display.
 */
function formatStatsResult(stats: {
	totalComponents: number;
	recommendationsCount: number;
	readyToRefactor: number;
	scheduled: number;
	deferred: number;
	byPriority: {
		critical: number;
		high: number;
		medium: number;
		low: number;
	};
	avgConfidence: number;
	dataQuality: string;
}): ToolResult {
	const lines: string[] = [
		"# Refactoring Statistics",
		"",
		"## Overview",
		`- **Total Components**: ${stats.totalComponents}`,
		`- **Recommendations**: ${stats.recommendationsCount}`,
		`- **Ready to Refactor**: ${stats.readyToRefactor}`,
		`- **Scheduled**: ${stats.scheduled}`,
		`- **Deferred**: ${stats.deferred}`,
		"",
		"## By Priority",
		`- 🔴 Critical: ${stats.byPriority.critical}`,
		`- 🟠 High: ${stats.byPriority.high}`,
		`- 🟡 Medium: ${stats.byPriority.medium}`,
		`- 🟢 Low: ${stats.byPriority.low}`,
		"",
		"## Data Quality",
		`- **Average Confidence**: ${Math.round(stats.avgConfidence * 100)}%`,
		`- **Data Quality**: ${stats.dataQuality}`,
	];

	return {
		content: [
			{
				type: "text",
				text: lines.join("\n"),
			},
		],
	};
}

