/**
 * Validation Handlers
 *
 * Handlers for code validation and pattern checking.
 *
 * @module facades/handlers/validation-handlers
 */

import { CommonErrors } from "../../errors/index.js";
import type { ToolHandler } from "../../types/tool-types.js";
import { getFacades, getIntelligence } from "../intelligence.js";
import { errorJsonResult, jsonResult, result } from "./utils.js";

/**
 * validate - Quick or comprehensive code validation
 */
export const handleValidate: ToolHandler = async (args, context) => {
	const {
		mode = "quick",
		code,
		filePath,
	} = args as {
		mode?: "quick" | "comprehensive";
		code?: string;
		filePath?: string;
	};

	if (!code || !filePath) {
		return errorJsonResult(CommonErrors.missingParam("code, filePath"));
	}

	// Comprehensive mode: use full 7-layer ValidationPipeline from Intelligence
	if (mode === "comprehensive") {
		try {
			const intel = getIntelligence(context.workspaceRoot);
			const validation = await intel.checkPatterns([filePath], { workspaceRoot: context.workspaceRoot });

			return jsonResult({
				status: "success",
				mode: "comprehensive",
				filePath,
				passed: validation.overall.passed,
				confidence: validation.overall.confidence,
				totalIssues: validation.overall.totalIssues,
				recommendation: validation.recommendation,
				layers: (validation.layers || []).map((l) => {
					const issues = (l.issues || []) as Array<{
						severity?: string;
						type?: string;
						message?: string;
						line?: number;
						fix?: string;
					}>;
					return {
						name: l.layer || l.name,
						passed: l.passed,
						issueCount: issues.length,
						issues: issues.map((i) => ({
							severity: i.severity,
							type: i.type,
							message: i.message,
							line: i.line,
							fix: i.fix,
						})),
						duration: l.duration,
					};
				}),
				focusPoints: validation.focusPoints,
				message: validation.overall.passed
					? "All validation layers passed"
					: `Found ${validation.overall.totalIssues} issue(s) across ${(validation.layers || []).filter((l) => !l.passed).length} layer(s)`,
				next_actions: validation.overall.passed
					? []
					: [
							{
								tool: "validate",
								priority: 1,
								reason: "Re-validate after fixes",
								args: { mode: "comprehensive" },
							},
						],
			});
		} catch (error) {
			const message = error instanceof Error ? error.message : String(error);
			return result(`Comprehensive validation failed: ${message}`, true);
		}
	}

	// Quick mode: delegate to intelligence facade checkPatterns()
	const validation = await getFacades().validation.checkPatterns(context.workspaceRoot, [filePath]);

	// Map facade result to MCP violation format
	const violations = validation.issues.map((issue) => ({
		rule: `${issue.rule || "unknown"}-check`,
		severity: issue.rule?.includes("error") ? ("critical" as const) : ("warning" as const),
		line: issue.line,
		message: issue.message,
	}));

	const criticalCount = violations.filter((v) => v.severity === "critical").length;
	const warningCount = violations.filter((v) => v.severity === "warning").length;
	const confidence =
		criticalCount > 0
			? 30
			: warningCount > 2
				? 60
				: violations.length === 0
					? 100
					: Math.max(70, 100 - warningCount * 10);

	const recommendation = confidence >= 95 ? "auto_merge" : confidence >= 70 ? "quick_review" : "full_review";

	return jsonResult({
		status: "success",
		mode: "quick",
		filePath,
		passed: criticalCount === 0,
		confidence,
		totalIssues: violations.length,
		violations,
		recommendation,
		message:
			violations.length === 0
				? "No violations found"
				: `${violations.length} violation(s) found (${criticalCount} critical, ${warningCount} warning)`,
		next_actions:
			violations.length > 0 ? [{ tool: "validate", priority: 1, reason: "Fix violations and re-validate" }] : [],
	});
};

/**
 * check_patterns - Validate code against 7-layer pipeline
 */
export const handleCheckPatterns: ToolHandler = async (args, context) => {
	const { code, filePath } = args as {
		code?: string;
		filePath?: string;
	};

	if (!code || !filePath) {
		return errorJsonResult(CommonErrors.missingParam("code, filePath"));
	}

	try {
		const intel = getIntelligence(context.workspaceRoot);

		// Run full 7-layer validation
		const validation = await intel.checkPatterns([filePath], { workspaceRoot: context.workspaceRoot });

		return jsonResult({
			passed: validation.overall.passed,
			confidence: validation.overall.confidence,
			totalIssues: validation.overall.totalIssues,
			recommendation: validation.recommendation,
			layers: (validation.layers || []).map((l) => {
				const issues = (l.issues || []) as Array<{
					severity?: string;
					type?: string;
					message?: string;
					line?: number;
					fix?: string;
				}>;
				return {
					name: l.layer || l.name,
					passed: l.passed,
					issueCount: issues.length,
					issues: issues.map((i) => ({
						severity: i.severity,
						type: i.type,
						message: i.message,
						line: i.line,
						fix: i.fix,
					})),
					duration: l.duration,
				};
			}),
			focusPoints: validation.focusPoints,
			next_actions: validation.overall.passed
				? []
				: [{ tool: "check_patterns", priority: 1, reason: "Re-validate after fixes" }],
		});
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		return result(`Failed to check patterns: ${message}`, true);
	}
};
