/**
 * Result Pattern and Structured Error Types
 *
 * Provides McpError, Result<T, E>, factory functions, and type guards
 * for consistent error handling across the MCP package.
 *
 * @module errors/result
 */

import type { ErrorCode } from "./codes.js";
import { getErrorCategory, getErrorMessage, isRecoverableError } from "./codes.js";

// =============================================================================
// McpErrorCode  -  value object for dot-access (e.g. McpErrorCode.DAEMON_UNAVAILABLE)
// =============================================================================

