// =============================================================================
// McpError  -  structured error type
// =============================================================================

/** Structured MCP error with code, message, and optional details */
export interface McpError {
	readonly code: string;
	readonly message: string;
	readonly details?: Record<string, unknown>;
	readonly cause?: Error;
	readonly retryable: boolean;
	readonly timestamp: string;
}

// =============================================================================
// Result<T, E>  -  discriminated union for success/failure
// =============================================================================

interface OkResult<T> {
	readonly ok: true;
	readonly value: T;
}

interface ErrResult<E> {
	readonly ok: false;
	readonly error: E;
}

/** Result type: either Ok with value or Err with error */
export type Result<T, E = McpError> = OkResult<T> | ErrResult<E>;

// =============================================================================
// Factory Functions
// =============================================================================

/** Create an Ok result */
export function ok<T>(value: T): Result<T, never> {
	return { ok: true, value };
}

/** Create an Err result */
export function err<E = McpError>(error: E): Result<never, E> {
	return { ok: false, error };
}

/** Create a structured McpError */
export function createMcpError(code: string, message: string, details?: Record<string, unknown>): McpError {
	return {
		code,
		message,
		details,
		retryable: isRetryable({ code } as McpError),
		timestamp: new Date().toISOString(),
	};
}

/** Create a structured McpError from an existing Error cause */
export function createMcpErrorFromCause(
	code: string,
	message: string,
	cause: Error,
	details?: Record<string, unknown>,
): McpError {
	return {
		code,
		message: `${message}: ${cause.message}`,
		details: { ...details, originalError: cause.name, stack: cause.stack?.split("\n").slice(0, 3).join("\n") },
		cause,
		retryable: isRetryable({ code } as McpError),
		timestamp: new Date().toISOString(),
	};
}

// =============================================================================
// Type Guards
// =============================================================================

/** Check if a value is a McpError */
export function isMcpError(value: unknown): value is McpError {
	return (
		value !== null &&
		typeof value === "object" &&
		"code" in value &&
		"message" in value &&
		typeof (value as McpError).code === "string" &&
		typeof (value as McpError).message === "string"
	);
}

/** Check if a string is a valid ErrorCode */
export function isErrorCode(code: string): code is ErrorCode {
	return /^E\d{3}_/.test(code);
}

/** Check if an error is retryable based on its code category */
export function isRetryable(error: McpError): boolean {
	if (!isErrorCode(error.code)) {
		return false;
	}
	return isRecoverableError(error.code);
}

// =============================================================================
// Formatters
// =============================================================================

/** Format McpError for structured logging */
export function formatForLog(error: McpError): string {
	const parts = [`[${error.code}] ${error.message}`];
	if (error.details) {
		parts.push(`details=${JSON.stringify(error.details)}`);
	}
	return parts.join(" | ");
}

/** Format McpError for user-facing display */
export function formatForUser(error: McpError): string {
	const category = isErrorCode(error.code) ? getErrorCategory(error.code) : "internal";
	const fallback = isErrorCode(error.code) ? getErrorMessage(error.code) : "An error occurred";
	return `${error.message || fallback} (${category}: ${error.code})`;
}

/** Format McpError for MCP tool response */
export function formatMcpError(error: McpError): { error: string; code: string; message: string } {
	return {
		error: error.code,
		code: error.code,
		message: error.message,
	};
}

// =============================================================================
// McpErrors  -  convenience error builders
// =============================================================================

/** Pre-built error factories for common scenarios */
export const McpErrors = {
	invalidParam: (param: string, reason?: string) =>
		createMcpError(McpErrorCode.INVALID_PARAM, `Invalid parameter: ${param}${reason ? `  -  ${reason}` : ""}`),

	missingParam: (param: string) => createMcpError(McpErrorCode.MISSING_PARAM, `Required parameter missing: ${param}`),

	fileNotFound: (path: string) => createMcpError(McpErrorCode.FILE_NOT_FOUND, `File not found: ${path}`, { path }),

	snapshotNotFound: (id: string) =>
		createMcpError(McpErrorCode.SNAPSHOT_NOT_FOUND, `Snapshot not found: ${id}`, { snapshotId: id }),

	serviceUnavailable: (service: string) =>
		createMcpError(McpErrorCode.SERVICE_UNAVAILABLE, `Service unavailable: ${service}`, { service }),

	internal: (message: string, details?: Record<string, unknown>) =>
		createMcpError(McpErrorCode.INTERNAL_ERROR, message, details),

	daemonUnavailable: (workspace: string) =>
		createMcpError(McpErrorCode.DAEMON_UNAVAILABLE, "Local service is not available", { workspace }),

	daemonRequestFailed: (message: string, details?: Record<string, unknown>) =>
		createMcpError(McpErrorCode.DAEMON_REQUEST_FAILED, message, details),
} as const;
