/**
 * Evolution Detector Service
 *
 * Scans codebase for deprecated patterns indicating evolution needs.
 * Part of P1: Evolution Detection (1/5 → 3/5 improvement goal)
 *
 * Detection methods:
 * 1. @deprecated JSDoc annotations (highest confidence)
 * 2. Naming patterns: legacy, old, v1, deprecated
 * 3. TODO/FIXME deprecate comments // Issue: LIN-0000
 *
 * @module services/evolution-detector-service
 */

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { glob } from "glob";
import ts from "typescript";

// =============================================================================
// Types
// =============================================================================

/**
 * Type of deprecation detection
 */
export type DeprecationType = "jsdoc" | "naming" | "comment" | "unused-export";

/**
 * Information about a detected deprecation
 */
export interface DeprecationInfo {
	/** Type of detection method */
	type: DeprecationType;
	/** Symbol name (function, class, type, etc.) */
	symbol: string;
	/** File path relative to workspace */
	filePath: string;
	/** Line number in file */
	line: number;
	/** Deprecation message if present */
	message?: string;
	/** Suggested replacement from message */
	suggestedReplacement?: string;
	/** Confidence score (0-1) */
	confidence: number;
}

/**
 * Result of evolution detection scan
 */
export interface EvolutionResult {
	/** All detected deprecations */
	deprecations: DeprecationInfo[];
	/** Total files scanned */
	totalScanned: number;
	/** Breakdown by pattern type */
	patterns: Array<{ type: string; count: number }>;
}

/**
 * Options for evolution detector
 */
export interface EvolutionDetectorOptions {
	/** Custom source directories to scan */
	sourceDirectories?: string[];
	/** Include test files in scan */
	includeTests?: boolean;
}

// =============================================================================
// Constants
// =============================================================================

/** Default source directories to scan */
const DEFAULT_SOURCE_DIRS = ["src", "lib", "packages"];

/** Naming patterns that indicate deprecation */
const DEPRECATION_NAMING_PATTERNS = [
	{ pattern: /Legacy$/i, confidence: 0.75 },
	{ pattern: /^legacy/i, confidence: 0.75 },
	{ pattern: /^old[A-Z]/i, confidence: 0.7 },
	{ pattern: /Old$/i, confidence: 0.65 },
	{ pattern: /V1$/i, confidence: 0.7 },
	{ pattern: /^v1[A-Z]/i, confidence: 0.7 },
	{ pattern: /deprecated/i, confidence: 0.85 },
];

/** Comment patterns indicating planned deprecation */
const DEPRECATION_COMMENT_PATTERNS = [
	{ pattern: /TODO:?\s*deprecate/i, confidence: 0.6 }, // Issue: LIN-0000
	{ pattern: /FIXME:?\s*remove.*legacy/i, confidence: 0.65 }, // Issue: LIN-0000
	{ pattern: /TODO\s+deprecate:/i, confidence: 0.6 }, // Issue: LIN-0000
	{ pattern: /@deprecated.*scheduled/i, confidence: 0.8 },
];

/** Words that should NOT trigger "old" pattern when embedded */
const OLD_FALSE_POSITIVES = ["gold", "bold", "cold", "fold", "hold", "mold", "sold", "told", "older", "oldest"];

// =============================================================================
// EvolutionDetectorService
// =============================================================================

export class EvolutionDetectorService {
	private workspaceRoot: string;
	private sourceDirectories: string[];
	private includeTests: boolean;

	constructor(workspaceRoot: string, options?: EvolutionDetectorOptions) {
		this.workspaceRoot = workspaceRoot;
		this.sourceDirectories = options?.sourceDirectories ?? DEFAULT_SOURCE_DIRS;
		this.includeTests = options?.includeTests ?? false;
	}

	// =========================================================================
	// Main Scan Method
	// =========================================================================

	/**
	 * Scan for deprecations in the workspace
	 * @param files - Optional specific files to scan (relative paths)
	 */
	async scanForDeprecations(files?: string[]): Promise<EvolutionResult> {
		const deprecations: DeprecationInfo[] = [];
		const seenSymbols = new Set<string>();
		let totalScanned = 0;

		// Get files to scan
		const filesToScan = files ? files.map((f) => join(this.workspaceRoot, f)) : await this.discoverSourceFiles();

		for (const filePath of filesToScan) {
			if (!existsSync(filePath)) {
				continue;
			}

			// Only scan TypeScript/JavaScript files
			if (!/\.(ts|tsx|js|jsx)$/.test(filePath)) {
				continue;
			}

			totalScanned++;

			try {
				const content = readFileSync(filePath, "utf-8");
				const relativePath = filePath.replace(`${this.workspaceRoot}/`, "");

				// 1. Scan for JSDoc @deprecated
				const jsdocDeprecations = this.scanJSDocDeprecated(content, relativePath);
				for (const dep of jsdocDeprecations) {
					const key = `${dep.symbol}:${dep.filePath}`;
					if (!seenSymbols.has(key)) {
						seenSymbols.add(key);
						deprecations.push(dep);
					}
				}

				// 2. Scan for naming patterns
				const namingDeprecations = this.scanNamingPatterns(content, relativePath);
				for (const dep of namingDeprecations) {
					const key = `${dep.symbol}:${dep.filePath}`;
					if (!seenSymbols.has(key)) {
						seenSymbols.add(key);
						deprecations.push(dep);
					}
				}

				// 3. Scan for TODO/FIXME comments // Issue: LIN-0000
				const commentDeprecations = this.scanComments(content, relativePath);
				for (const dep of commentDeprecations) {
					const key = `${dep.symbol}:${dep.filePath}`;
					if (!seenSymbols.has(key)) {
						seenSymbols.add(key);
						deprecations.push(dep);
					}
				}
			} catch {
				// Skip files that can't be read
			}
		}

		// Build pattern breakdown
		const patternCounts = new Map<string, number>();
		for (const dep of deprecations) {
			patternCounts.set(dep.type, (patternCounts.get(dep.type) ?? 0) + 1);
		}

		const patterns = Array.from(patternCounts.entries()).map(([type, count]) => ({
			type,
			count,
		}));

		return {
			deprecations,
			totalScanned,
			patterns,
		};
	}

	// =========================================================================
	// Discovery
	// =========================================================================

	/**
	 * Discover TypeScript/JavaScript source files
	 */
	private async discoverSourceFiles(): Promise<string[]> {
		const patterns: string[] = [];

		for (const dir of this.sourceDirectories) {
			const dirPath = join(this.workspaceRoot, dir);
			if (existsSync(dirPath)) {
				patterns.push(`${dir}/**/*.{ts,tsx}`);
			}
		}

		if (patterns.length === 0) {
			// Fallback: scan root for TS files
			patterns.push("**/*.{ts,tsx}");
		}

		const ignore = ["**/node_modules/**", "**/dist/**", "**/.next/**"];

		if (!this.includeTests) {
			ignore.push("**/*.test.*", "**/*.spec.*", "**/__tests__/**");
		}

		const files = await glob(patterns, {
			cwd: this.workspaceRoot,
			absolute: true,
			ignore,
		});

		return files;
	}

	// =========================================================================
	// JSDoc Scanning (TypeScript AST)
	// =========================================================================

	/**
	 * Scan file for @deprecated JSDoc tags using TypeScript AST
	 */
	private scanJSDocDeprecated(content: string, filePath: string): DeprecationInfo[] {
		const deprecations: DeprecationInfo[] = [];

		try {
			// Create source file
			const sourceFile = ts.createSourceFile(filePath, content, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);

			// Visit all nodes
			const visit = (node: ts.Node): void => {
				// Check for JSDoc comments
				const jsDocs = ts.getJSDocTags(node);

				for (const tag of jsDocs) {
					if (tag.tagName.text === "deprecated") {
						const symbol = this.getNodeName(node);
						if (symbol) {
							const message = this.extractJSDocMessage(tag);
							const line = sourceFile.getLineAndCharacterOfPosition(node.getStart()).line + 1;

							deprecations.push({
								type: "jsdoc",
								symbol,
								filePath,
								line,
								message,
								suggestedReplacement: this.extractReplacement(message),
								confidence: 0.95,
							});
						}
					}
				}

				ts.forEachChild(node, visit);
			};

			visit(sourceFile);
		} catch {
			// TypeScript parsing failed, skip
		}

		return deprecations;
	}

	/**
	 * Get the name of a node (function, class, interface, etc.)
	 */
	private getNodeName(node: ts.Node): string | null {
		if (ts.isFunctionDeclaration(node) && node.name) {
			return node.name.text;
		}
		if (ts.isClassDeclaration(node) && node.name) {
			return node.name.text;
		}
		if (ts.isInterfaceDeclaration(node) && node.name) {
			return node.name.text;
		}
		if (ts.isTypeAliasDeclaration(node) && node.name) {
			return node.name.text;
		}
		if (ts.isVariableStatement(node)) {
			const decl = node.declarationList.declarations[0];
			if (decl && ts.isIdentifier(decl.name)) {
				return decl.name.text;
			}
		}
		if (ts.isMethodDeclaration(node) && node.name && ts.isIdentifier(node.name)) {
			return node.name.text;
		}
		return null;
	}

	/**
	 * Extract message text from JSDoc tag
	 */
	private extractJSDocMessage(tag: ts.JSDocTag): string | undefined {
		if (tag.comment) {
			if (typeof tag.comment === "string") {
				return tag.comment.trim();
			}
			// Handle JSDocComment array
			const parts = tag.comment as ts.NodeArray<ts.JSDocComment>;
			return parts
				.map((p) => p.getText())
				.join(" ")
				.trim();
		}
		return undefined;
	}

	/**
	 * Extract replacement suggestion from deprecation message
	 */
	private extractReplacement(message?: string): string | undefined {
		if (!message) {
			return undefined;
		}

		// Common patterns: "Use X instead", "Migrate to X", "Replace with X"
		const patterns = [
			/[Uu]se\s+(\w+)\s+instead/,
			/[Mm]igrate\s+to\s+(\w+)/,
			/[Rr]eplace\s+with\s+(\w+)/,
			/→\s*(\w+)/,
			/prefer\s+(\w+)/i,
		];

		for (const pattern of patterns) {
			const match = message.match(pattern);
			if (match) {
				return match[1];
			}
		}

		return undefined;
	}

	// =========================================================================
	// Naming Pattern Scanning
	// =========================================================================

	/**
	 * Scan for deprecation-indicating naming patterns
	 */
	private scanNamingPatterns(content: string, filePath: string): DeprecationInfo[] {
		const deprecations: DeprecationInfo[] = [];
		const _lines = content.split("\n");

		// Match exported symbols
		const exportPattern = /export\s+(?:function|class|interface|type|const|let|var)\s+(\w+)/g;

		let match: RegExpExecArray | null;
		while ((match = exportPattern.exec(content)) !== null) {
			const symbol = match[1];

			// Skip false positives for "old"
			const lowerSymbol = symbol.toLowerCase();
			if (OLD_FALSE_POSITIVES.some((fp) => lowerSymbol.includes(fp))) {
				continue;
			}

			// Check against naming patterns
			for (const { pattern, confidence } of DEPRECATION_NAMING_PATTERNS) {
				if (pattern.test(symbol)) {
					// Find line number
					const lineIndex = this.findLineIndex(content, match.index);

					deprecations.push({
						type: "naming",
						symbol,
						filePath,
						line: lineIndex + 1,
						message: `Symbol name suggests deprecation: matches pattern ${pattern.source}`,
						confidence,
					});
					break; // Only add once per symbol
				}
			}
		}

		return deprecations;
	}

	// =========================================================================
	// Comment Scanning
	// =========================================================================

	/**
	 * Scan for TODO/FIXME deprecation comments // Issue: LIN-0000
	 */
	private scanComments(content: string, filePath: string): DeprecationInfo[] {
		const deprecations: DeprecationInfo[] = [];
		const lines = content.split("\n");

		for (let i = 0; i < lines.length; i++) {
			const line = lines[i];

			for (const { pattern, confidence } of DEPRECATION_COMMENT_PATTERNS) {
				if (pattern.test(line)) {
					// Try to find the next exported symbol
					const nextSymbol = this.findNextExportedSymbol(lines, i);

					if (nextSymbol) {
						deprecations.push({
							type: "comment",
							symbol: nextSymbol.name,
							filePath,
							line: i + 1,
							message: line.trim(),
							confidence,
						});
					}
					break;
				}
			}
		}

		return deprecations;
	}

	/**
	 * Find the next exported symbol after a comment
	 */
	private findNextExportedSymbol(lines: string[], startLine: number): { name: string; line: number } | null {
		// Look ahead up to 5 lines for an export
		for (let i = startLine + 1; i < Math.min(startLine + 6, lines.length); i++) {
			const line = lines[i];
			const exportMatch = line.match(/export\s+(?:function|class|interface|type|const|let|var)\s+(\w+)/);

			if (exportMatch) {
				return { name: exportMatch[1], line: i };
			}
		}
		return null;
	}

	/**
	 * Find line index for a character position
	 */
	private findLineIndex(content: string, charIndex: number): number {
		let lineIndex = 0;
		let charCount = 0;

		for (const line of content.split("\n")) {
			charCount += line.length + 1; // +1 for newline
			if (charCount > charIndex) {
				return lineIndex;
			}
			lineIndex++;
		}

		return lineIndex;
	}
}

// =============================================================================
// Factory Functions
// =============================================================================

/**
 * Create a new EvolutionDetectorService instance
 */
export function createEvolutionDetectorService(
	workspaceRoot: string,
	options?: EvolutionDetectorOptions,
): EvolutionDetectorService {
	return new EvolutionDetectorService(workspaceRoot, options);
}

// =============================================================================
// Singleton per workspace
// =============================================================================

const services = new Map<string, EvolutionDetectorService>();

/**
 * Get or create service for workspace (singleton pattern)
 */
export function getEvolutionDetectorService(
	workspaceRoot: string,
	options?: EvolutionDetectorOptions,
): EvolutionDetectorService {
	const key = workspaceRoot;
	if (!services.has(key)) {
		services.set(key, new EvolutionDetectorService(workspaceRoot, options));
	}
	const service = services.get(key);
	if (!service) {
		throw new Error(`Failed to get or create EvolutionDetectorService for ${workspaceRoot}`);
	}
	return service;
}
