/**
 * Schema for vreko tool (unified entry point)
 * Replaces: begin_task, get_context, prepare_workspace, get_learnings
 *
 * Supports both full-word modes (mode) and legacy single-letter modes (m)
 * At least one mode parameter must be provided
 */
export const snapSchema = z
	.object({
		// Mode parameters - at least one required
		mode: z
			.enum(["start", "check", "context"])
			.optional()
			.describe("Mode (full-word, recommended): start=begin task, check=validate code, context=get status"),
		m: z.enum(["s", "c", "x"]).optional().describe("Legacy mode: s=start, c=check, x=context (use 'mode' instead)"),
		// Task parameters
		task: z.string().optional().describe("Task description (mode: start)"),
		t: z.string().optional().describe("Legacy: use 'task' instead"),
		// File parameters
		files: z.array(z.string()).optional().describe("Files to work on (mode: start, check)"),
		f: z.array(z.string()).optional().describe("Legacy: use 'files' instead"),
		// Keyword parameters
		keywords: z.array(z.string()).optional().describe("Keywords for learning retrieval (mode: start, context)"),
		k: z.array(z.string()).optional().describe("Legacy: use 'keywords' instead"),
		// Intent parameters
		intent: z
			.enum(["implement", "debug", "refactor", "review", "explore"])
			.optional()
			.describe("Task intent for context loading optimization"),
		i: z
			.enum(["implement", "debug", "refactor", "review", "explore"])
			.optional()
			.describe("Legacy: use 'intent' instead"),
		// Other parameters
		thorough: z.boolean().optional().describe("Enable thorough 7-layer validation (mode: check)"),
		compact: z
			.boolean()
			.optional()
			.describe("Use compact positional wire format instead of labeled (default: false)"),
		goal: z
			.object({
				metric: z
					.enum(["bundle", "performance", "coverage"])
					.describe("ONLY: 'bundle'|'performance'|'coverage'. NOTE: 'momentum' is NOT valid here."),
				target: z.number().describe("Target value (e.g., 100 for KB, 200 for ms, 80 for %)"),
				unit: z.string().describe("Unit: 'KB' for bundle, 'ms' for performance, '%' for coverage"),
			})
			.optional()
			.describe(
				"Optional task goal. Only for tracking bundle size, performance, or coverage. " +
					"Example: { metric: 'coverage', target: 80, unit: '%' }",
			),
	})
	.refine((data) => data.mode !== undefined || data.m !== undefined, {
		message: "Either 'mode' (start|check|context) or 'm' (s|c|x) must be provided",
		path: ["mode"],
	});

/**
 * Schema for snap_end tool (task completion)
 * Replaces: complete_task, review_work, what_changed
 *
 * Supports both full-word params (learnings) and legacy (l)
 */
export const snapEndSchema = z.object({
	ok: z
		.union([z.literal(0), z.literal(1)])
		.optional()
		.describe("Success: 1=ok, 0=failed"),
	// Learnings parameters
	learnings: z.array(z.string()).optional().describe("Quick learnings as strings"),
	l: z.array(z.string()).optional().describe("Legacy: use 'learnings' instead"),
	// Other parameters
	notes: z.string().optional().describe("Completion notes"),
	/** Free-text outcome: what was accomplished, what remains, decisions made. ok:0|1 is the primary signal. */
	outcome: z
		.string()
		.min(1)
		.max(2000)
		.optional()
		.describe("Free-text task outcome (what was accomplished, what remains, decisions made)"),
	// Efficiency tracking (agent-reported metrics)
	efficiency: z
		.object({
			saved: z.string().optional().describe("Tokens saved (e.g., '~12K')"),
			prevented: z.string().optional().describe("Mistakes prevented"),
			helped: z.string().optional().describe("What context helped most"),
		})
		.optional()
		.describe("Agent-reported efficiency metrics"),
	// Internal survey (LLM self-assessment)
	survey: z
		.object({
			patterns_used: z.number().optional().describe("Patterns applied from context"),
			pitfalls_avoided: z.number().optional().describe("Pitfalls avoided due to warnings"),
			helpfulness: z.number().min(1).max(5).optional().describe("Helpfulness rating 1-5"),
			unhelpful_count: z.number().optional().describe("Count of unhelpful suggestions"),
		})
		.optional()
		.describe("LLM self-assessment (internal)"),
	compact: z.boolean().optional().describe("Use compact wire format"),
});

/**
 * Schema for snap_learn tool (mid-session learning capture)
 * Replaces: learn
 *
 * Supports both full-word params (trigger, action, source) and legacy (t, a, s)
 * At least one of each pair must be provided
 */
export const snapLearnSchema = z
	.object({
		// Full-word parameters (recommended)
		trigger: z.string().optional().describe("What situation triggers this learning"),
		action: z.string().optional().describe("What to do when triggered"),
		source: z.string().optional().describe("Where this learning originated (optional)"),
		// Legacy parameters
		t: z.string().optional().describe("Legacy: use 'trigger' instead"),
		a: z.string().optional().describe("Legacy: use 'action' instead"),
		s: z.string().optional().describe("Legacy: use 'source' instead"),
		// Type (supports both full-word and abbreviated)
		type: z
			.union([LearningType, z.enum(["pat", "pit", "eff", "disc", "wf", "con", "prf"])])
			.optional()
			.describe("Learning type (default: pattern)"),
	})
	.refine(
		(data) =>
			(data.trigger !== undefined || data.t !== undefined) && (data.action !== undefined || data.a !== undefined),
		{
			message: "Either 'trigger' or 't' AND 'action' or 'a' must be provided",
			path: ["trigger"],
		},
	);

