// ============================================================================
// Validation Helper
// ============================================================================

/**
 * Validate input against a schema and return structured result
 */
export function validateInput<T extends z.ZodType>(
	schema: T,
	input: unknown,
): { valid: true; data: z.infer<T> } | { valid: false; error: string; issues: z.ZodIssue[] } {
	const result = schema.safeParse(input);

	if (result.success) {
		return { valid: true, data: result.data };
	}

	const errorMessages = (result.error.issues || [])
		.map((issue) => `${issue.path.join(".")}: ${issue.message}`)
		.join("; ");

	return {
		valid: false,
		error: errorMessages,
		issues: result.error.issues,
	};
}

/**
 * Schema for pulse tool (workspace vitals)
 * PERCEIVE stage - check workspace health
 */
export const pulseSchema = z
	.object({
		record_change: z.string().optional().describe("File path to record as changed"),
	})
	.passthrough();

/**
 * Schema for advise tool (proactive recommendations)
 * REASON stage - get recommendations before action
 */
export const adviseSchema = z
	.object({
		files: z.array(z.string()).optional().describe("Files to analyze for recommendations"),
	})
	.passthrough();

// DEPRECATED: Legacy tool schemas. Remove when consolidated/ tools are removed.
// See: daemon-mcp-cli-integration-v1 spec, WS-1.2
/**
 * Schema registry for consolidated tools
 * NOTE: V2 tools (vreko, vreko_learn, vreko_end, vreko_pulse) handle
 * their own validation internally and should NOT be in this registry
 * @see stress_test_remediation.md
 */
export const TOOL_SCHEMAS: Record<string, z.ZodType> = {
	// V2 tools removed - they handle validation internally:
	// - vreko (uses validateSnapStartParams)
	// - vreko_learn (uses SnapLearnParamsSchema)
	// - vreko_end (uses SnapEndParamsSchema)
	// - vreko_pulse (uses SnapPulseParamsSchema)

	// Consolidated tools (non-V2)
	vreko_fix: snapFixSchema,
	vreko_help: snapHelpSchema,
	vreko_violation: snapViolationSchema,
	// Backward-compat aliases (deprecated names)
	snap_fix: snapFixSchema,
	snap_help: snapHelpSchema,
	snap_violation: snapViolationSchema,
	check: checkSchema,
	pulse: pulseSchema,
	advise: adviseSchema,
};

/**
 * Get schema for a tool by name
 */
export function getToolSchema(toolName: string): z.ZodType | undefined {
	return TOOL_SCHEMAS[toolName];
}
