/**
 * Get patterns from daemon IPC
 */
async function getPatternsFromDaemon(
	_context: ToolContext,
	_options: { domains?: string[]; types?: string[]; minConfidence?: number; limit?: number },
): Promise<Pattern[]> {
	throw new Error("tiered learning not yet implemented  -  see Deferred Backlog D5");
}

// =============================================================================
// IPC COMMUNICATION
// =============================================================================

/**
 * Call daemon IPC method.
 * Used for WRITE operations to maintain single-writer pattern.
 */
async function callDaemonIPC(context: ToolContext, method: string, params: Record<string, unknown>): Promise<unknown> {
	// Get daemon client from context
	const daemonClient = context.services?.daemon;
	if (!daemonClient) {
		throw new Error("Daemon client not available in context");
	}

	// Call daemon method
	const result = await daemonClient.request(method, params);
	return result;
}

