export const capturePatternTool: VrekoTool = {
	name: "intelligence.capture",
	description: `[DEPRECATED  -  use vreko_begin/vreko_learn/vreko_end/vreko_pulse] 📝 Capture a learning as a structured pattern.

**When to use:**
- Discovered something that worked or failed
- Found a better approach
- Learned a constraint or gotcha
- Want to remember a workflow

**Quality requirements:**
- Must include action verb (always, never, avoid, prefer, must)
- Must have clear subject (what the pattern is about)
- 10-500 characters
- If quality < 0.4, you'll get helpful warnings to rephrase

**Architecture:**
- WRITE operation → calls daemon IPC
- Daemon validates quality gate (0.4 threshold)
- Daemon handles deduplication (same rule ID strengthens existing)
- Returns success + pattern ID or warnings if quality too low

**Example:**
\`\`\`
Always validate JWT expiry before attempting refresh
\`\`\`
→ Extracted as: prefer-jwt-validation with quality 0.85`,

	inputSchema: {
		type: "object",
		properties: {
			content: {
				type: "string",
				description: "The learning content (10-500 chars). Must include action verb and clear subject.",
				minLength: 10,
				maxLength: 500,
			},
			domain: {
				type: "string",
				enum: ["architecture", "testing", "documentation", "performance", "security", "workflow", "tooling"],
				description: "Domain classification (optional, auto-detected if omitted)",
			},
			type: {
				type: "string",
				enum: ["pattern", "anti-pattern", "best-practice", "constraint", "heuristic"],
				description: "Pattern type (optional, auto-detected if omitted)",
			},
			severity: {
				type: "string",
				enum: ["info", "warning", "error"],
				description: "Severity level (optional, defaults to 'info')",
			},
			relatedTo: {
				type: "array",
				items: { type: "string" },
				description: "Related pattern IDs (optional)",
			},
		},
		required: ["content"],
	},
};

export async function handleCapturePattern(args: Record<string, unknown>, context: ToolContext): Promise<ToolResult> {
	const { content, domain, type, severity, relatedTo } = args as {
		content: string;
		domain?: string;
		type?: string;
		severity?: string;
		relatedTo?: string[];
	};

	// Validate content length
	if (!content || content.length < 10) {
		return {
			content: [
				{
					type: "text",
					text: "❌ Content too short (minimum 10 characters)",
				},
			],
			isError: true,
		};
	}

	if (content.length > 500) {
		return {
			content: [
				{
					type: "text",
					text: "❌ Content too long (maximum 500 characters)",
				},
			],
			isError: true,
		};
	}

	try {
		// Call daemon IPC for write operation
		const result = (await callDaemonIPC(context, "intelligence.capture", {
			workspace: context.workspaceRoot,
			content,
			domain,
			type,
			severity,
			relatedTo,
		})) as {
			success: boolean;
			patternId?: string;
			quality: number;
			warnings?: string[];
			message: string;
		};

		if (!result.success) {
			// Quality below threshold - return helpful warnings
			let summary = `⚠️ Pattern quality too low: ${result.quality.toFixed(2)} / 0.40\n\n`;
			summary += "**To improve quality, try:**\n";
			if (result.warnings && result.warnings.length > 0) {
				for (const warning of result.warnings) {
					summary += `- ${warning}\n`;
				}
			}
			summary += "\n**Example of good pattern:**\n";
			summary += "✅ Always validate JWT expiry before attempting refresh\n";
			summary += "✅ Never use process.env in client code - use import.meta.env instead\n";

			return {
				content: [{ type: "text", text: summary }],
				isError: false, // Not an error, just needs refinement
			};
		}

		// Success - pattern captured
		let summary = "✅ Pattern captured successfully!\n\n";
		summary += `**Pattern ID:** ${result.patternId}\n`;
		summary += `**Quality Score:** ${result.quality.toFixed(2)}\n`;
		if (result.warnings && result.warnings.length > 0) {
			summary += "\n**Notes:**\n";
			for (const warning of result.warnings) {
				summary += `- ${warning}\n`;
			}
		}

		return {
			content: [{ type: "text", text: summary }],
		};
	} catch (error) {
		return {
			content: [
				{
					type: "text",
					text: `❌ Failed to capture pattern: ${error instanceof Error ? error.message : String(error)}`,
				},
			],
			isError: true,
		};
	}
}

