export const queryPatternsTool: VrekoTool = {
	name: "intelligence.patterns",
	description: `[DEPRECATED] 🔍 Query captured patterns by domain, type, or confidence.

**When to use:**
- Find patterns relevant to current task
- Check what learnings exist for a domain
- See high-confidence patterns only
- Review anti-patterns before making changes

**Query options:**
- domains: Filter by domain (architecture, testing, etc.)
- types: Filter by type (pattern, anti-pattern, best-practice)
- actions: Filter by action (avoid, prefer, require, sequence)
- minConfidence: Minimum confidence threshold (0.0-1.0)
- limit: Maximum results (default: 10)
- sortBy: Sort order (confidence, recency, occurrences, relevance)

**Architecture:**
- READ operation → accesses PatternStore locally
- No daemon IPC needed for reads
- Fast O(k) queries using in-memory indices

**Returns:** List of matching patterns with:
- Pattern ID, content, rule
- Confidence score, occurrences
- Domain, type, action
- Timestamps (created, updated, last seen)`,

	inputSchema: {
		type: "object",
		properties: {
			domains: {
				type: "array",
				items: {
					type: "string",
					enum: [
						"architecture",
						"testing",
						"documentation",
						"performance",
						"security",
						"workflow",
						"tooling",
					],
				},
				description: "Filter by domains",
			},
			types: {
				type: "array",
				items: {
					type: "string",
					enum: ["pattern", "anti-pattern", "best-practice", "constraint", "heuristic"],
				},
				description: "Filter by pattern types",
			},
			actions: {
				type: "array",
				items: {
					type: "string",
					enum: ["avoid", "prefer", "require", "sequence", "investigate"],
				},
				description: "Filter by actions",
			},
			minConfidence: {
				type: "number",
				minimum: 0,
				maximum: 1,
				description: "Minimum confidence threshold (0.0-1.0)",
			},
			limit: {
				type: "number",
				minimum: 1,
				maximum: 50,
				description: "Maximum results (default: 10)",
			},
			sortBy: {
				type: "string",
				enum: ["confidence", "recency", "occurrences", "relevance"],
				description: "Sort order (default: relevance)",
			},
		},
		required: [],
	},
};

export async function handleQueryPatterns(args: Record<string, unknown>, context: ToolContext): Promise<ToolResult> {
	const {
		domains,
		types,
		minConfidence,
		limit = 10,
	} = args as {
		domains?: string[];
		types?: string[];
		minConfidence?: number;
		limit?: number;
	};

	try {
		// Day 4: Get patterns via daemon IPC
		const patterns = await getPatternsFromDaemon(context, {
			domains,
			types,
			minConfidence,
			limit,
		});

		if (patterns.length === 0) {
			return {
				content: [
					{
						type: "text",
						text: "📭 No patterns found matching your query.\n\nTry:\n- Broadening filters\n- Lowering minConfidence\n- Checking different domains",
					},
				],
			};
		}

		// Format results
		let summary = `🔍 Found ${patterns.length} pattern${patterns.length === 1 ? "" : "s"}\n\n`;

		for (const pattern of patterns) {
			summary += `**${pattern.core.action.toUpperCase()}: ${pattern.core.subject}**\n`;
			summary += `- Content: ${pattern.original}\n`;
			summary += `- Confidence: ${pattern.insight.confidence.toFixed(2)} (${pattern.evidence.occurrences} occurrences)\n`;
			summary += `- Domain: ${pattern.signal.domain} | Action: ${pattern.core.action}\n`;
			summary += `- Rule: ${pattern.insight.rule}\n`;
			summary += `- ID: ${pattern.id}\n\n`;
		}

		return {
			content: [{ type: "text", text: summary }],
		};
	} catch (error) {
		return {
			content: [
				{
					type: "text",
					text: `❌ Failed to query patterns: ${error instanceof Error ? error.message : String(error)}`,
				},
			],
			isError: true,
		};
	}
}

