export const generateInsightsTool: VrekoTool = {
	name: "intelligence.insights",
	description: `[DEPRECATED] 💡 Generate contextual insights from patterns.

**When to use:**
- Before making changes (get warnings from anti-patterns)
- Planning refactor (get suggestions from best-practices)
- Understanding hotspots (get synthesis of related patterns)
- Assessing regression risk (get predictions based on violations)

**Insight types:**
- warning: From anti-patterns in relevant domains
- suggestion: From best-practices in relevant domains
- synthesis: Hotspot detection (2+ high-confidence patterns in same area)
- prediction: Regression risks based on recent violations

**Architecture:**
- READ operation → uses RuleBasedInsightEngine locally
- Loads relevant patterns from PatternStore
- Generates insights based on session context
- Returns prioritized insights with reasoning

**Session context:**
- domains: Current work domains
- filePatterns: Files being modified
- recentViolations: Recent violation types
- mode: Task mode (implement, debug, refactor, review)`,

	inputSchema: {
		type: "object",
		properties: {
			type: {
				type: "string",
				enum: ["warning", "suggestion", "synthesis", "prediction"],
				description: "Insight type to generate",
			},
			domains: {
				type: "array",
				items: {
					type: "string",
					enum: [
						"architecture",
						"testing",
						"documentation",
						"performance",
						"security",
						"workflow",
						"tooling",
					],
				},
				description: "Current work domains",
			},
			filePatterns: {
				type: "array",
				items: { type: "string" },
				description: "Files being modified (glob patterns)",
			},
			recentViolations: {
				type: "array",
				items: { type: "string" },
				description: "Recent violation types",
			},
			mode: {
				type: "string",
				enum: ["implement", "debug", "refactor", "review"],
				description: "Current task mode",
			},
			focus: {
				type: "string",
				description: "Specific focus area (optional)",
			},
		},
		required: ["type"],
	},
};

export async function handleGenerateInsights(args: Record<string, unknown>, context: ToolContext): Promise<ToolResult> {
	const {
		type,
		domains = [],
		limit = 5,
	} = args as {
		type: "warning" | "suggestion" | "synthesis" | "prediction";
		domains?: string[];
		limit?: number;
	};

	try {
		// Day 4: Get patterns via daemon IPC for insight generation
		const patterns = await getPatternsFromDaemon(context, {
			domains,
			limit: 20,
		});

		// Generate simple insights from patterns (daemon-first architecture)
		const insights = patterns
			.map((p, i) => ({
				id: `insight-${i}`,
				title: p.core.subject,
				detail: p.original,
				priority: p.insight.confidence > 0.8 ? 1 : p.insight.confidence > 0.5 ? 2 : 3,
				basedOn: { patterns: [p.id] },
				action: { type: "consider", target: p.core.action },
			}))
			.filter((_, i) => i < (limit || 5));

		if (insights.length === 0) {
			return {
				content: [
					{
						type: "text",
						text: `📭 No ${type} insights found for current context.

This could mean:
- No relevant patterns exist yet
- Current domains don't match captured patterns
- Try capturing more patterns as you learn`,
					},
				],
			};
		}

		// Format results
		let summary = `💡 Generated ${insights.length} ${type} insight${insights.length === 1 ? "" : "s"}\n\n`;

		for (const insight of insights) {
			const priorityLabel =
				typeof insight.priority === "number"
					? `Priority ${insight.priority}`
					: String(insight.priority).toUpperCase();
			summary += `**${priorityLabel}: ${insight.title}**\n`;
			summary += `${insight.detail}\n\n`;

			if (insight.basedOn.patterns && insight.basedOn.patterns.length > 0) {
				summary += "**Based on Patterns:**\n";
				for (const patternId of insight.basedOn.patterns) {
					summary += `- ${patternId}\n`;
				}
				summary += "\n";
			}

			if (insight.action) {
				summary += "**Recommended Action:**\n";
				summary += `${insight.action.type}: ${insight.action.target}\n\n`;
			}
		}

		return {
			content: [{ type: "text", text: summary }],
		};
	} catch (error) {
		return {
			content: [
				{
					type: "text",
					text: `❌ Failed to generate insights: ${error instanceof Error ? error.message : String(error)}`,
				},
			],
			isError: true,
		};
	}
}

