export const explainInsightTool: VrekoTool = {
	name: "intelligence.explain",
	description: `[DEPRECATED] 🔬 Explain how an insight was generated.

**When to use:**
- Understanding why a warning was raised
- Seeing the reasoning behind a suggestion
- Learning what patterns contributed to synthesis
- Debugging prediction logic

**Returns:**
- Which patterns contributed
- Confidence levels of each pattern
- Why they're relevant to current context
- Pattern evidence (occurrences, outcomes)

**Architecture:**
- READ operation → uses cached insight explanations
- Shows pattern provenance
- Helps build trust in recommendations`,

	inputSchema: {
		type: "object",
		properties: {
			insightId: {
				type: "string",
				description: "Insight ID to explain",
			},
		},
		required: ["insightId"],
	},
};

export async function handleExplainInsight(args: Record<string, unknown>, context: ToolContext): Promise<ToolResult> {
	const { insightId } = args as { insightId: string };

	try {
		// Day 4: Get patterns via daemon IPC
		const patterns = await getPatternsFromDaemon(context, { limit: 20 });

		// Find the matching pattern
		const pattern = patterns.find((p) => p.id === insightId);

		if (!pattern) {
			return {
				content: [
					{
						type: "text",
						text: `❌ Insight not found: ${insightId}\n\nMake sure you're using the ID from a recently generated insight.`,
					},
				],
				isError: true,
			};
		}

		// Format explanation (daemon-first architecture)
		let summary = `🔬 Insight Explanation: ${pattern.id}\n\n`;
		summary += `**Detail:** ${pattern.original}\n\n`;
		summary += "**Supporting Evidence:**\n";
		summary += `- Pattern type: ${pattern.core.action}\n`;
		summary += `  Rule: ${pattern.insight.rule}\n`;
		summary += `  Seen: ${pattern.evidence.occurrences} times\n`;
		summary += "\n";

		summary += "**Reasoning Factors:**\n";
		summary += `- Domain: ${pattern.signal.domain}\n`;
		summary += `- Confidence: ${pattern.insight.confidence.toFixed(2)}\n`;
		summary += `- Subject: ${pattern.core.subject}\n`;

		return {
			content: [{ type: "text", text: summary }],
		};
	} catch (error) {
		return {
			content: [
				{
					type: "text",
					text: `❌ Failed to explain insight: ${error instanceof Error ? error.message : String(error)}`,
				},
			],
			isError: true,
		};
	}
}

