export const recordOutcomeTool: VrekoTool = {
	name: "intelligence.outcome",
	description: `[DEPRECATED] 📊 Record the outcome of applying a pattern.

**When to use:**
- After following a pattern's advice
- When a pattern helped resolve an issue
- If applying a pattern caused a regression
- To ignore patterns that don't apply

**Outcomes:**
- resolved: Pattern helped (+0.1 confidence, max 0.95)
- regressed: Pattern caused issues (-0.15 confidence, min 0.1)
- ignored: Pattern not applicable (no confidence change)

**Architecture:**
- WRITE operation → calls daemon IPC
- Daemon updates pattern confidence
- Updates pattern evidence with outcome
- Tracks outcome history for predictions

**Effect on confidence:**
- 3+ resolved outcomes → pattern promoted to high confidence
- 2+ regressed outcomes → pattern confidence drops significantly
- Feedback loop improves pattern quality over time`,

	inputSchema: {
		type: "object",
		properties: {
			patternId: {
				type: "string",
				description: "Pattern ID to record outcome for",
			},
			outcome: {
				type: "string",
				enum: ["resolved", "regressed", "ignored"],
				description: "Outcome of applying the pattern",
			},
			notes: {
				type: "string",
				description: "Additional notes about the outcome (optional)",
			},
		},
		required: ["patternId", "outcome"],
	},
};

export async function handleRecordOutcome(args: Record<string, unknown>, context: ToolContext): Promise<ToolResult> {
	const { patternId, outcome, notes } = args as {
		patternId: string;
		outcome: "resolved" | "regressed" | "ignored";
		notes?: string;
	};

	try {
		// Call daemon IPC for write operation
		const result = (await callDaemonIPC(context, "intelligence.outcome", {
			workspace: context.workspaceRoot,
			patternId,
			outcome,
			notes,
		})) as {
			success: boolean;
			patternId: string;
			confidence: number;
			previousConfidence: number;
			message: string;
		};

		// Format result
		let summary = `✅ Outcome recorded: ${outcome}\n\n`;
		summary += `**Pattern ID:** ${result.patternId}\n`;
		summary += `**Confidence:** ${result.previousConfidence.toFixed(2)} → ${result.confidence.toFixed(2)}\n`;

		const change = result.confidence - result.previousConfidence;
		if (change > 0) {
			summary += `**Change:** +${change.toFixed(2)} 📈 (pattern strengthened)\n`;
		} else if (change < 0) {
			summary += `**Change:** ${change.toFixed(2)} 📉 (pattern weakened)\n`;
		} else {
			summary += "**Change:** No change (ignored)\n";
		}

		return {
			content: [{ type: "text", text: summary }],
		};
	} catch (error) {
		return {
			content: [
				{
					type: "text",
					text: `❌ Failed to record outcome: ${error instanceof Error ? error.message : String(error)}`,
				},
			],
			isError: true,
		};
	}
}

