/**
 * Learning Handlers
 *
 * Handlers for recording and retrieving learnings.
 *
 * @module facades/handlers/learning-handlers
 *
 * DEPRECATED (Day 4): Direct file writes replaced with daemon IPC.
 * Learning capture now routes through the daemon.
 */

import { join } from "node:path";
import { assertValidWorkspaceId } from "@vreko/workspace-identity";
import { addLearningViaDaemon } from "../../daemon/local-service-adapter.js";
import { CommonErrors } from "../../errors/index.js";
import { invalidateRetrieverCache } from "../../services/hybrid-retrieval-service.js";
import {
	indexLearning,
	invalidateCache as invalidateKnowledgeCache,
} from "../../services/knowledge-ingestion-service.js";
import { validateAndEnhanceLearning } from "../../services/learning-validation.js";
import { createLearningSync, type Learning } from "../../sync/learning-sync.js";
import type { ToolHandler } from "../../types/tool-types.js";
import { errorJsonResult, isLocalWorkspace, jsonResult, result } from "./utils.js";

/**
 * Calculate package relevance score for learning results
 */
function calculatePackageScore(learningPackages: string[] | undefined, queryPackages: string[]): number {
	if (!learningPackages || learningPackages.length === 0 || queryPackages.length === 0) {
		return 0;
	}

	let matches = 0;
	for (const queryPkg of queryPackages) {
		const queryLower = queryPkg.toLowerCase();
		for (const learningPkg of learningPackages) {
			const learningLower = learningPkg.toLowerCase();
			// Exact match or partial match (e.g., "vscode" matches "@vreko/vscode")
			if (
				learningLower === queryLower ||
				learningLower.includes(queryLower) ||
				queryLower.includes(learningLower)
			) {
				matches++;
				break; // Count each query package once
			}
		}
	}

	// Score based on percentage of query packages matched, plus bonus for multiple learning packages matched
	const matchRatio = matches / queryPackages.length;
	return Math.round(matchRatio * 100);
}

/**
 * learn - Record learnings from sessions
 */
export const handleLearn: ToolHandler = async (args, context) => {
	const { type, trigger, action, source } = args as {
		type?: string;
		trigger?: string;
		action?: string;
		source?: string;
	};

	if (!type || !trigger || !action) {
		return errorJsonResult(CommonErrors.missingParam("type, trigger, action"));
	}

	// Validate and enhance learning with security metadata (P0 security hardening)
	const validationResult = validateAndEnhanceLearning({
		type: type as
			| "pattern"
			| "pitfall"
			| "architecture"
			| "performance"
			| "efficiency"
			| "discovery"
			| "workflow"
			| undefined,
		trigger,
		action,
		source: source || "user_explicit",
	});

	if (!validationResult.validation.isValid || !("learning" in validationResult)) {
		return errorJsonResult({
			status: "error",
			message: "Learning validation failed",
			errors: validationResult.validation.errors,
			warnings: validationResult.validation.warnings,
		});
	}

	// Extract validated learning
	const learning = validationResult.learning;
	const { id } = learning;

	// Check if we can write to workspace (local mode) or if this is remote mode
	const _learningsPath = join(context.workspaceRoot, ".vreko", "learnings", "learnings.jsonl");
	const isRemoteMode = !isLocalWorkspace(context.workspaceRoot);

	if (isRemoteMode) {
		// Remote mode: Return learning data for client to store
		// The VS Code extension or CLI will write this locally
		return jsonResult({
			id,
			status: "success",
			learning,
			message: "Learning captured (client-side storage required)",
			remoteMode: true,
			instruction: "Store this learning locally in .vreko/learnings/learnings.jsonl",
			warnings: validationResult.validation.warnings,
		});
	}

	// Local mode: Write via daemon IPC (Day 4: daemon-first architecture)
	try {
		// Tag learning with workspaceId for cross-workspace scoping
		// Learnings without workspaceId are treated as "global" (backward compatible)
		// Validate workspaceId format before tagging
		if (context.workspaceId) {
			assertValidWorkspaceId(context.workspaceId, "handlers.tagLearning");
		}
		const learningEntry = context.workspaceId ? { ...learning, workspaceId: context.workspaceId } : learning;

		// Day 4: Use daemon IPC for learning capture
		const daemonResult = await addLearningViaDaemon(context.workspaceRoot, {
			type: learningEntry.type,
			trigger: Array.isArray(learningEntry.trigger) ? learningEntry.trigger.join(", ") : learningEntry.trigger,
			action: learningEntry.action,
			source: learningEntry.source,
		});

		if (!daemonResult.success) {
			// Intentionally ignored: daemon write failure is non-fatal, learning is still indexed below
		}

		// Index into KnowledgeStore for hybrid retrieval (non-blocking)
		indexLearning(context.workspaceRoot, learning as Learning).catch((_indexError) => {
			// Intentionally ignored: knowledge indexing is non-blocking best-effort
		});

		// Invalidate retriever cache so next query picks up new learning
		invalidateRetrieverCache(context.workspaceRoot);
		invalidateKnowledgeCache(context.workspaceRoot);

		// Queue for cross-workspace cloud sync (non-blocking)
		// Uses workspaceId from context if available
		if (context.workspaceId) {
			const syncService = createLearningSync({
				workspaceRoot: context.workspaceRoot,
				workspaceId: context.workspaceId,
			});
			syncService.queueLearning(learning as Learning).catch((_syncError) => {
				// Intentionally ignored: cloud sync is non-blocking best-effort
			});
		}

		return jsonResult({
			id,
			status: "success",
			learning,
			message: "Learning recorded",
			storagePath: ".vreko/learnings/learnings.jsonl",
			syncQueued: !!context.workspaceId,
			warnings: validationResult.validation.warnings,
			security: {
				provenance: learning.source,
				expiresAt: learning.expires_at,
				validationStatus: learning.validation_status,
			},
		});
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);

		// If daemon fails, fall back to returning data for client-side storage
		if (message.includes("EACCES") || message.includes("EPERM") || message.includes("permission")) {
			return jsonResult({
				id,
				status: "success",
				learning,
				message: "Learning captured (permission denied, client-side storage required)",
				remoteMode: true,
				instruction: "Store this learning locally in .vreko/learnings/learnings.jsonl",
				warning: "Server cannot write to workspace directory",
			});
		}

		return result(`Failed to record learning: ${message}`, true);
	}
};

/**
 * get_learnings - Query past learnings with package awareness
 */
export const handleGetLearnings: ToolHandler = async (args, context) => {
	const {
		keywords,
		limit = 10,
		intent = "implement",
		includeCold = true,
		packages,
		packageMode = "boost",
	} = args as {
		keywords?: string[];
		limit?: number;
		intent?: "implement" | "debug" | "refactor" | "review" | "explore";
		includeCold?: boolean;
		packages?: string[];
		packageMode?: "boost" | "filter";
	};

	if (!keywords || keywords.length === 0) {
		return errorJsonResult(CommonErrors.missingParam("keywords"));
	}

	try {
		// Use daemon IPC for learning retrieval (daemon-first architecture)
		const { searchLearningsViaDaemon } = await import("../../daemon/local-service-adapter.js");

		const allLearnings: Array<{ type: string; trigger: string; action: string; relevanceScore?: number }> = [];

		// Optionally also query cold tier for explicit searches
		if (includeCold) {
			const coldResult = await searchLearningsViaDaemon(context.workspaceRoot, keywords, limit);
			if (coldResult.success && coldResult.learnings) {
				const seen = new Set(allLearnings.map((l) => `${l.type}:${l.trigger}`));
				for (const l of coldResult.learnings) {
					if (!seen.has(`${l.type}:${l.trigger}`)) {
						allLearnings.push(l);
					}
				}
			}
		}

		// Convert to expected format
		const learnings = allLearnings.map((l) => ({
			id: `${l.type}-${l.trigger.slice(0, 20)}`,
			type: l.type,
			trigger: Array.isArray(l.trigger) ? l.trigger.join(", ") : l.trigger,
			action: l.action,
			source: undefined,
			timestamp: undefined,
			loadedFrom: "daemon" as const,
			relevanceScore: l.relevanceScore,
		}));

		// Determine if we should apply package scoring
		const shouldScorePackages = packages && packages.length > 0;
		const effectiveMode = packageMode === "filter" ? "filter" : "boost";

		// Calculate package scores and optionally filter
		type LearningWithScore = (typeof learnings)[number] & { packageScore?: number };
		let scoredLearnings: LearningWithScore[] = learnings.map((l) => {
			// Cast to access packages field that may exist on the stored learning
			const learningWithPkgs = l as typeof l & { packages?: string[] };
			const score = shouldScorePackages ? calculatePackageScore(learningWithPkgs.packages, packages) : undefined;
			return { ...l, packages: learningWithPkgs.packages, packageScore: score };
		});

		// Apply filter mode if specified
		if (shouldScorePackages && effectiveMode === "filter") {
			scoredLearnings = scoredLearnings.filter((l) => (l.packageScore ?? 0) > 0);
		}

		// Sort by package score (highest first) when packages are specified
		if (shouldScorePackages) {
			scoredLearnings.sort((a, b) => (b.packageScore ?? 0) - (a.packageScore ?? 0));
		}

		const limited = scoredLearnings.slice(0, Math.min(limit, 50));

		// Build the response
		return jsonResult({
			status: "success",
			count: limited.length,
			total: allLearnings.length,
			keywords,
			intent,
			learnings: limited.map((l) => ({
				id: l.id,
				type: l.type,
				trigger: l.trigger,
				action: l.action,
				source: l.source,
				timestamp: l.timestamp,
				loadedFrom: l.loadedFrom,
				packageScore: l.packageScore,
			})),
			tierInfo: {
				hotAndWarm: allLearnings.length,
				cold: 0,
			},
			next_actions: limited.length > 0 ? [{ tool: "learn", priority: 2, reason: "Record new learnings" }] : [],
		});
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		return result(`Failed to get learnings: ${message}`, true);
	}
};
