/**
 * Parallel Validator
 *
 * Parallel execution of TypeScript, test, and lint checks.
 *
 * @module services/validation/parallel-validator
 */

import { spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { join } from "node:path";
import { errorMessage } from "@vreko/core";
import type {
	ParallelCheckResult,
	ParallelTestResult,
	ParallelValidationInput,
	ParallelValidationResult,
	ServiceResult,
} from "./types.js";

/**
 * Run command with timeout and capture output.
 */
function runCommand(
	cmd: string,
	args: string[],
	cwd: string,
	timeoutMs = 30000,
): Promise<{ exitCode: number; stdout: string; stderr: string; duration: number }> {
	const start = Date.now();

	return new Promise((resolve) => {
		let stdout = "";
		let stderr = "";
		let killed = false;

		// SECURITY: shell: false prevents command injection via user-controlled args
		const proc = spawn(cmd, args, {
			cwd,
			shell: false,
			stdio: ["pipe", "pipe", "pipe"],
		});

		const timeout = setTimeout(() => {
			killed = true;
			proc.kill("SIGTERM");
		}, timeoutMs);

		proc.stdout?.on("data", (data) => {
			stdout += data.toString();
		});

		proc.stderr?.on("data", (data) => {
			stderr += data.toString();
		});

		proc.on("close", (code) => {
			clearTimeout(timeout);
			resolve({
				exitCode: killed ? -1 : (code ?? 0),
				stdout,
				stderr,
				duration: Date.now() - start,
			});
		});

		proc.on("error", (err) => {
			clearTimeout(timeout);
			resolve({
				exitCode: -1,
				stdout,
				stderr: err.message,
				duration: Date.now() - start,
			});
		});
	});
}

/**
 * Parallel validator for TypeScript, tests, and lint.
 */
export class ParallelValidator {
	/**
	 * Check TypeScript compilation.
	 */
	async checkTypeScript(files: readonly string[], workspacePath: string): Promise<ParallelCheckResult> {
		const start = Date.now();

		try {
			const result = await runCommand(
				"npx",
				["--yes", "tsc", "--noEmit", "--pretty", "false"],
				workspacePath,
				15000,
			);

			const errors: string[] = [];
			const warnings: string[] = [];

			const lines = (result.stdout + result.stderr).split("\n");
			for (const line of lines) {
				if (line.includes("error TS")) {
					const isRelevant =
						files.length === 0 ||
						files.some((f) => line.includes(f) || line.includes(f.replace(/\\/g, "/")));
					if (isRelevant) {
						errors.push(line.trim());
					}
				} else if (line.includes("warning")) {
					warnings.push(line.trim());
				}
			}

			return {
				passed: result.exitCode === 0 || errors.length === 0,
				duration: Date.now() - start,
				errors: errors.slice(0, 10),
				warnings: warnings.slice(0, 5),
			};
		} catch (error) {
			const errMsg = errorMessage(error);
			return {
				passed: false,
				duration: Date.now() - start,
				errors: [
					`TypeScript check failed: ${errMsg}. Ensure TypeScript is installed: npm install -D typescript`,
				],
				warnings: [],
			};
		}
	}

	/**
	 * Check tests.
	 */
	async checkTests(files: readonly string[], workspacePath: string, runTests: boolean): Promise<ParallelTestResult> {
		const start = Date.now();

		// Find test files related to the modified files
		const testFiles: string[] = [];
		for (const file of files) {
			const dir = file.substring(0, file.lastIndexOf("/")) || ".";
			const base =
				file
					.split("/")
					.pop()
					?.replace(/\.(ts|tsx)$/, "") || "";

			const patterns = [
				`${dir}/${base}.test.ts`,
				`${dir}/${base}.test.tsx`,
				`${dir}/${base}.spec.ts`,
				`${dir}/${base}.spec.tsx`,
				`${dir}/__tests__/${base}.test.ts`,
				`${dir}/__tests__/${base}.test.tsx`,
			];

			for (const pattern of patterns) {
				if (existsSync(join(workspacePath, pattern))) {
					testFiles.push(pattern);
				}
			}
		}

		if (testFiles.length === 0) {
			return {
				passed: true,
				duration: Date.now() - start,
				discovered: 0,
				warnings: ["No related test files found"],
				errors: [],
			};
		}

		if (!runTests) {
			return {
				passed: true,
				duration: Date.now() - start,
				discovered: testFiles.length,
				warnings: [`${testFiles.length} test file(s) discovered but not run`],
				errors: [],
			};
		}

		// Run tests with vitest
		try {
			const result = await runCommand(
				"npx",
				["--yes", "vitest", "run", ...testFiles, "--reporter=json"],
				workspacePath,
				60000,
			);

			const errors: string[] = [];
			let passed = 0;
			let failed = 0;

			try {
				const jsonMatch = result.stdout.match(/\{[\s\S]*"testResults"[\s\S]*\}/);
				if (jsonMatch) {
					const testResult = JSON.parse(jsonMatch[0]);
					passed = testResult.numPassedTests || 0;
					failed = testResult.numFailedTests || 0;
					if (testResult.testResults) {
						for (const tr of testResult.testResults) {
							if (tr.status === "failed" && tr.message) {
								errors.push(tr.message.slice(0, 200));
							}
						}
					}
				}
			} catch {
				const passMatch = result.stdout.match(/(\d+) passed/);
				const failMatch = result.stdout.match(/(\d+) failed/);
				if (passMatch) {
					passed = Number.parseInt(passMatch[1], 10);
				}
				if (failMatch) {
					failed = Number.parseInt(failMatch[1], 10);
					errors.push(`${failed} test(s) failed`);
				}
			}

			return {
				passed: result.exitCode === 0,
				duration: Date.now() - start,
				discovered: testFiles.length,
				run: testFiles.length,
				passedCount: passed,
				failedCount: failed,
				errors: errors.slice(0, 5),
				warnings: [],
			};
		} catch (error) {
			const errMsg = errorMessage(error);
			return {
				passed: false,
				duration: Date.now() - start,
				discovered: testFiles.length,
				errors: [`Test execution failed: ${errMsg}. Ensure Vitest is installed: npm install -D vitest`],
				warnings: [],
			};
		}
	}

	/**
	 * Check lint.
	 */
	async checkLint(files: readonly string[], workspacePath: string): Promise<ParallelCheckResult> {
		const start = Date.now();

		try {
			const result = await runCommand(
				"npx",
				["--yes", "biome", "check", "--reporter=json", ...files],
				workspacePath,
				15000,
			);

			const errors: string[] = [];
			const warnings: string[] = [];

			try {
				const diagnostics = JSON.parse(result.stdout);
				if (Array.isArray(diagnostics)) {
					for (const diag of diagnostics) {
						if (diag.severity === "error") {
							errors.push(`${diag.path}: ${diag.message}`);
						} else if (diag.severity === "warning") {
							warnings.push(`${diag.path}: ${diag.message}`);
						}
					}
				}
			} catch {
				if (result.exitCode !== 0) {
					const lines = result.stderr.split("\n").filter((l) => l.trim());
					errors.push(...lines.slice(0, 5));
				}
			}

			return {
				passed: result.exitCode === 0 || errors.length === 0,
				duration: Date.now() - start,
				errors: errors.slice(0, 10),
				warnings: warnings.slice(0, 5),
			};
		} catch (error) {
			const errMsg = errorMessage(error);
			return {
				passed: false,
				duration: Date.now() - start,
				errors: [`Lint check failed: ${errMsg}. Ensure Biome is installed: npm install -D @biomejs/biome`],
				warnings: [],
			};
		}
	}

	/**
	 * Run parallel validation (TypeScript, tests, lint).
	 */
	async run(input: ParallelValidationInput): Promise<ServiceResult<ParallelValidationResult>> {
		const start = Date.now();
		const {
			workspacePath,
			files = [],
			skipTypeScript = false,
			skipTests = false,
			skipLint = false,
			runTests = false,
		} = input;

		// Check for catastrophic failures first
		if (!existsSync(join(workspacePath, "node_modules"))) {
			return {
				ok: false,
				error: "Dependencies missing. Run `pnpm install`.",
				code: "DEPS_MISSING",
			};
		}

		if (!existsSync(join(workspacePath, "tsconfig.json"))) {
			return {
				ok: false,
				error: "TypeScript config missing. Create tsconfig.json.",
				code: "TSCONFIG_MISSING",
			};
		}

		// Run checks in parallel
		const [tsResult, testResult, lintResult] = await Promise.all([
			skipTypeScript
				? Promise.resolve({ passed: true, duration: 0, errors: [] as string[], warnings: ["Skipped"] })
				: this.checkTypeScript(files, workspacePath),
			skipTests
				? Promise.resolve({
						passed: true,
						duration: 0,
						errors: [] as string[],
						warnings: ["Skipped"],
						discovered: 0,
					})
				: this.checkTests(files, workspacePath, runTests),
			skipLint
				? Promise.resolve({ passed: true, duration: 0, errors: [] as string[], warnings: ["Skipped"] })
				: this.checkLint(files, workspacePath),
		]);

		// Determine overall status
		let overall: "pass" | "fail" | "warn" = "pass";
		if (!tsResult.passed || !testResult.passed || !lintResult.passed) {
			overall = "fail";
		} else if (tsResult.warnings.length > 0 || testResult.warnings.length > 0 || lintResult.warnings.length > 0) {
			overall = "warn";
		}

		return {
			ok: true,
			data: {
				overall,
				typescript: tsResult,
				tests: testResult,
				lint: lintResult,
				duration: Date.now() - start,
			},
		};
	}
}
