/**
 * Vreko End Tool (V2) - Session Closure
 *
 * Call this when you've completed your coding task. Returns a session summary
 * showing what was accomplished, what Vreko learned, and what to watch for.
 *
 * This is a black-box formatting layer on top of the daemon intelligence engine.
 * The tool does NOT compute, store, or decide  -  it formats daemon responses
 * into LLM-consumable natural language payloads.
 *
 * Phase 5: AI-powered ceremony synthesis for Pro users.
 *
 * @module tools/v2/vreko-end
 */

import type { AISynthesisOutput } from "@vreko/contracts/api/ai-synthesis";
import type { CeremonyPayloadType, TimelineEventType } from "@vreko/contracts/local-service/schemas";
import type { AIMetadataPayload, PatternDomain, PatternType } from "@vreko/intelligence/learning";
import { MAX_LENGTHS, normalizeContent } from "../../security/input-sanitization.js";
import type { ToolHandler, ToolResult, VrekoTool } from "../../types/tool-types.js";
import { formatDuration } from "../../utils/format-duration.js";
import {
	buildSessionCurrentParams,
	buildSessionReviewParams,
	checkDaemonHealth,
	formatDaemonError,
	formatUnexpectedError,
	getDaemonClient,
	isActiveSession,
	isDaemonConnectionError,
	resolveWorkspace,
} from "./utils/index.js";
import { logNonFatalError } from "./utils/telemetry.js";

// =============================================================================
// Types
// =============================================================================

export interface VrekoEndParams {
	/** What happened. Be honest about completion status. */
	outcome: string;
}

interface SessionCurrentResult {
	/** Legacy field  -  may not be present in all daemon versions */
	active?: boolean;
	/** Actual field from daemon: "active" | "ended" | "idle" | "started" */
	state?: string;
	id?: string;
	taskId?: string;
	task?: string;
	/** Task may be stored in metadata.task depending on daemon version */
	metadata?: {
		task?: string;
		keywords?: string[];
		aiToolsDetected?: string[];
		highestRiskLevel?: string;
		triggerCounts?: Record<string, number>;
	};
	/** Files touched during session */
	touchedFiles?: string[];
	/** Snapshot IDs created during session */
	snapshotIds?: string[];
	/** Learning IDs captured during session */
	learningIds?: string[];
}

interface SessionEndResult {
	success?: boolean;
	coherenceScore?: number;
	duration?: number;
	filesModified?: number;
	snapshotsCreated?: number;
	learningsCaptured?: number;
}

interface SessionReviewResult {
	/** Files modified - derived from session.touchedFiles.length */
	filesModified?: number;
	/** Snapshots created - ceremony returns as checkpointsCreated */
	snapshotsCreated?: number;
	/** Alias for snapshotsCreated from ceremony */
	checkpointsCreated?: number;
	learningsCaptured?: number;
	pitfallsAvoided?: number;
	tokensSaved?: number;
	/** Coherence score - ceremony returns as string ("high", "medium", "low", "scattered") */
	coherenceScore?: number | string;
	insights?: string[];
	carryForward?: string[];
	/** Duration in ms */
	duration?: number;
	/** Top learnings from ceremony */
	topLearnings?: Array<{
		content: string;
		captureMethod: string;
		confidence: number;
	}>;
	/** Full ceremony payload (March 18 spec) */
	ceremony?: CeremonyPayloadType;
	/** Session ID */
	sessionId?: string;
	/** Workspace path */
	workspacePath?: string;
}

interface SessionMetrics {
	filesModified: number;
	snapshotsCreated: number;
	learningsCaptured: number;
	pitfallsAvoided: number;
	tokensSaved: string | null;
	coherenceScore: string | number | null;
	duration: number | null;
}

// =============================================================================
// Handler
// =============================================================================

/**
 * Handle vreko_end tool call
 *
 * Flow:
 * 1. Check for active session
 * 2. End the session via daemon
 * 3. Get ceremony data from session/review
 * 4. Format as natural language closing ceremony
 */
export const handleVrekoEnd: ToolHandler = async (args, context): Promise<ToolResult> => {
	// HIGH-1: Sanitize outcome to prevent prompt injection via user-controlled free-text field
	const rawArgs = args as Record<string, unknown>;
	const rawOutcome = typeof rawArgs.outcome === "string" ? rawArgs.outcome : "";
	const sanitizedOutcome = normalizeContent(rawOutcome).slice(0, MAX_LENGTHS.description);

	const params: VrekoEndParams = { outcome: sanitizedOutcome };
	const workspace = resolveWorkspace(context);
	const daemon = getDaemonClient(workspace);

	// Step 1: Check for active session
	let currentSession: SessionCurrentResult | null = null;
	try {
		currentSession = await daemon.request<SessionCurrentResult>(
			"session/current",
			buildSessionCurrentParams(workspace),
		);
	} catch (error) {
		if (isDaemonConnectionError(error)) {
			return formatDaemonError();
		}
		return formatUnexpectedError("session check", error);
	}

	// Capture raw session before isActiveSession type guard narrows the type.
	// TypeScript's type guard removes SessionCurrentResult from the type after the guard,
	// leaving `never` in the else branch. We need the raw object for late-ceremony lookup.
	const rawSession: SessionCurrentResult | null = currentSession;

	// Use shared utility for consistent session state check
	if (!isActiveSession(currentSession)) {
		// When daemon.request() returns null it means the IPC call failed silently  -
		// distinguish "daemon unreachable" from a genuine "no session" so users get
		// actionable feedback instead of a misleading "no session found" message.
		if (currentSession === null) {
			const health = await checkDaemonHealth(daemon, workspace);
			if (!health.healthy) {
				// Map health reason to DaemonErrorCategory (the two type sets differ slightly)
				const healthReasonToCategory: Record<typeof health.reason, Parameters<typeof formatDaemonError>[0]> = {
					connected: undefined,
					not_running: "not_running",
					starting: "connection_refused",
					connection_failed: "connection_refused",
					timeout: "timeout",
					null_response: "null_response",
				};
				return formatDaemonError(healthReasonToCategory[health.reason]);
			}
		}

		// Seam #4 fix: When session auto-expired (state === "ended"), attempt a late ceremony.
		// The daemon retains session records after they expire  -  session/review can still return
		// metrics and learnings captured before the 15-min idle timeout fired.
		if (rawSession !== null && (rawSession.state === "ended" || rawSession.state === "idle")) {
			const sessionId = rawSession.id ?? rawSession.taskId;
			if (sessionId) {
				try {
					const lateCeremony = await daemon.request<SessionReviewResult>(
						"session/review",
						buildSessionReviewParams(workspace, { sessionId }),
					);
					// Only use late ceremony if it has meaningful data (not just zeros)
					if (
						lateCeremony &&
						(lateCeremony.filesModified || lateCeremony.duration || lateCeremony.learningsCaptured)
					) {
						const expiredNote =
							rawSession.state === "ended"
								? "\n\n⚠️ **Note**: This session auto-expired (15min inactivity) before `vreko_end` was called. The ceremony below reflects work done before expiry."
								: "";
						const lateResult = formatEndResponse({
							endResult: null,
							ceremonyData: lateCeremony,
							outcome: params.outcome + expiredNote,
							session: rawSession,
							aiSynthesis: null,
						});
						// Prepend a header note so the agent understands this is a recovered ceremony
						const existingText = lateResult.content[0]?.text ?? "";
						return {
							...lateResult,
							content: [
								{
									type: "text" as const,
									text: `## Late Ceremony (session recovered)\n\n${existingText}`,
								},
							],
						};
					}
				} catch {
					// Late ceremony fetch failed  -  fall through to WAL recovery
				}

				// WAL-04b: session/review returned empty - fall back to WAL recovery.
				// This is the common case for sessions that expired before the fingerprint
				// was surfaced to the MCP layer (short idle sessions, single-tool call patterns).
				// ledger/recover scans all WAL files when no fingerprint is provided.
				try {
					const walRecovery = await daemon.request<{
						sessionId: string;
						eventCount: number;
						ceremonyAvailable: boolean;
						ceremony: Record<string, unknown> | null;
						expiryReason: string;
					}>("ledger/recover", { sessionId });

					if (walRecovery && walRecovery.ceremonyAvailable && walRecovery.ceremony) {
						const expiredNote =
							"\n\n⚠️ **Note**: Session was recovered from the write-ahead log (WAL). " +
							`Expiry reason: ${walRecovery.expiryReason}. ` +
							`${walRecovery.eventCount} event(s) captured.`;
						return {
							content: [
								{
									type: "text" as const,
									text:
										`## WAL Recovery Ceremony\n\nSession \`${sessionId}\` was recovered from disk.\n` +
										`Events captured: ${walRecovery.eventCount}${expiredNote}`,
								},
							],
						};
					}
				} catch {
					// WAL recovery also failed - fall through to diagnostic info (AP-3: logged by daemon)
				}
			}
		}

		// Daemon is healthy but has no active session  -  build diagnostic info for troubleshooting
		const diagnosticInfo = buildSessionDiagnostics(rawSession, workspace);

		return {
			content: [
				{
					type: "text",
					text:
						"No active session to close. If you were working without calling `vreko` first, " +
						"your files were still protected by Vreko's automatic monitoring, but session " +
						"intelligence (learnings, patterns, risk tracking) was not captured.\n\n" +
						diagnosticInfo,
				},
			],
		};
	}

	// Step 2: End the session
	let endResult: SessionEndResult | null = null;
	try {
		endResult = await daemon.request<SessionEndResult>("session/end-daemon", {
			workspacePath: workspace,
			outcome: params.outcome,
			sessionId: currentSession.id,
		});
	} catch (error) {
		if (isDaemonConnectionError(error)) {
			return formatDaemonError();
		}
		return formatUnexpectedError("session end", error);
	}

	// Step 3: Get ceremony data
	let ceremonyData: SessionReviewResult | null = null;
	try {
		ceremonyData = await daemon.request<SessionReviewResult>(
			"session/review",
			buildSessionReviewParams(workspace, {
				sessionId: currentSession.id,
			}),
		);
	} catch (error) {
		// Intentionally ignored: ceremony data retrieval is optional for session end
		logNonFatalError({
			tool: "vreko_end",
			operation: "session/review",
			workspace,
			error,
			metadata: { sessionId: currentSession.id ?? currentSession.taskId },
		});
	}

	// Step 4: AI Ceremony Synthesis (Phase 5 - Pro-gated)
	let aiSynthesis: AISynthesisOutput | null = null;
	try {
		// Build anonymized metadata payload
		const payload = buildAIMetadataPayload(ceremonyData, currentSession);

		// Check daemon availability for API base URL
		const daemonBaseUrl = process.env.VREKO_API_URL ?? "http://127.0.0.1:4200";
		const apiKey = process.env.VREKO_API_KEY;

		// HIGH-4: Do not send a Bearer token over a non-TLS, non-loopback connection.
		// Tokens sent over plain HTTP to remote hosts are exposed to network interception.
		const urlHost = new URL(daemonBaseUrl.startsWith("http") ? daemonBaseUrl : `http://${daemonBaseUrl}`).hostname;
		const isLoopback = urlHost === "127.0.0.1" || urlHost === "localhost" || urlHost === "::1";
		if (!daemonBaseUrl.startsWith("https://") && !isLoopback) {
			aiSynthesis = null;
		} else {
			// Fetch AI synthesis with timeout and graceful fallback
			aiSynthesis = await fetchAISynthesis(
				payload,
				currentSession.id ?? currentSession.taskId ?? "unknown",
				daemonBaseUrl,
				apiKey,
			);
		}
	} catch (error) {
		// AI synthesis failed - graceful fallback, continue without it
		logNonFatalError({
			tool: "vreko_end",
			operation: "ai-synthesis",
			workspace,
			error,
			metadata: { sessionId: currentSession.id ?? currentSession.taskId },
		});
		aiSynthesis = null;
	}

	// Step 5: Format the closing ceremony response
	return formatEndResponse({
		endResult,
		ceremonyData,
		outcome: params.outcome,
		session: currentSession,
		aiSynthesis,
	});
};

// =============================================================================
// Response Formatter
// =============================================================================

interface FormatEndParams {
	endResult: SessionEndResult | null;
	ceremonyData: SessionReviewResult | null;
	outcome: string;
	session: SessionCurrentResult;
	/** AI-generated synthesis (Phase 5) - null if unavailable or not Pro */
	aiSynthesis: AISynthesisOutput | null;
}

function formatEndResponse(data: FormatEndParams): ToolResult {
	const sections: string[] = [];

	// FIX: Task may be in session.task or session.metadata.task
	const task = data.session.task ?? data.session.metadata?.task ?? "unnamed task";

	// =============================================================================
	// HEADER
	// =============================================================================
	sections.push("# 🏁 Session Complete\n");
	sections.push(`**Task**: ${task}`);
	sections.push(`**Outcome**: ${data.outcome}`);

	// =============================================================================
	// TIER 1: SESSION SUMMARY (Must-show - highest priority)
	// Core metrics that every user needs to see
	// =============================================================================
	const metrics = gatherMetrics(data.endResult, data.ceremonyData, data.session);

	sections.push("\n## 📊 Session Summary\n");
	sections.push(`- **Duration**: ${formatDuration(metrics.duration ?? 0)}`);
	sections.push(`- **Files modified**: ${metrics.filesModified}`);
	sections.push(`- **Safety snapshots**: ${metrics.snapshotsCreated}`);
	sections.push(`- **Learnings captured**: ${metrics.learningsCaptured}`);

	if (metrics.pitfallsAvoided > 0) {
		sections.push(`- **Pitfalls avoided**: ${metrics.pitfallsAvoided}`);
	}

	if (metrics.tokensSaved) {
		sections.push(`- **Context preserved**: ~${metrics.tokensSaved} tokens`);
	}

	// Coherence score (translated to natural language)
	if (metrics.coherenceScore !== null && metrics.coherenceScore !== undefined) {
		const coherenceDesc = describeCoherence(metrics.coherenceScore);
		sections.push(`- **Session coherence**: ${coherenceDesc}`);
	}

	// =============================================================================
	// TIER 2: INTELLIGENCE HIGHLIGHTS (Useful context - medium priority)
	// Learnings, patterns, and insights from the session
	// =============================================================================

	const tier2Sections: string[] = [];
	let hasTier2 = false;

	// Top learnings from ceremony (highest value)
	if (data.ceremonyData?.topLearnings && data.ceremonyData.topLearnings.length > 0) {
		hasTier2 = true;
		tier2Sections.push("### 🧠 Top Learnings\n");
		for (const learning of data.ceremonyData.topLearnings.slice(0, 5)) {
			const confidence = Math.round(learning.confidence * 100);
			tier2Sections.push(`- ${learning.content} (${confidence}% confidence)`);
		}
	}

	// Patterns from ceremony payload (March 18 spec)
	if (data.ceremonyData?.ceremony?.learnings?.patterns) {
		const patterns = data.ceremonyData.ceremony.learnings.patterns;
		if (patterns.length > 0) {
			hasTier2 = true;
			tier2Sections.push("\n### 📈 Patterns Discovered\n");
			for (const pattern of patterns.slice(0, 3)) {
				const typeIcon = pattern.type === "fragile-file" ? "⚠️" : pattern.type === "co-change" ? "🔗" : "💡";
				tier2Sections.push(`- ${typeIcon} **${pattern.type}**: ${pattern.description}`);
				if (pattern.filesInvolved.length > 0) {
					tier2Sections.push(`  - Files: ${pattern.filesInvolved.slice(0, 3).join(", ")}`);
				}
			}
		}
	}

	// Key insights from ceremony
	if (data.ceremonyData?.insights && data.ceremonyData.insights.length > 0) {
		hasTier2 = true;
		tier2Sections.push("\n### 💡 Insights\n");
		for (const insight of data.ceremonyData.insights) {
			tier2Sections.push(`- ${insight}`);
		}
	}

	// Pitfalls avoided details
	if (data.ceremonyData?.ceremony?.pitfalls?.warnings) {
		const warnings = data.ceremonyData.ceremony.pitfalls.warnings;
		if (warnings.length > 0) {
			hasTier2 = true;
			tier2Sections.push("\n### ⚠️ Pitfalls Avoided\n");
			for (const warning of warnings.slice(0, 5)) {
				tier2Sections.push(`- ${warning.trigger}`);
				tier2Sections.push(`  - Risk: ${warning.risk}`);
			}
			const timeSaved = data.ceremonyData.ceremony.pitfalls.estimatedTimeSaved;
			if (timeSaved > 0) {
				tier2Sections.push(`\n_Estimated time saved: ~${timeSaved} minutes_`);
			}
		}
	}

	// AI-powered synthesis (Phase 5 - Pro feature)
	if (data.aiSynthesis) {
		hasTier2 = true;
		tier2Sections.push("\n### 🤖 AI Analysis\n");
		tier2Sections.push(data.aiSynthesis.summary);

		if (data.aiSynthesis.whyItMatters) {
			tier2Sections.push(`\n**Why it matters**: ${data.aiSynthesis.whyItMatters}`);
		}

		if (data.aiSynthesis.topRisks && data.aiSynthesis.topRisks.length > 0) {
			tier2Sections.push("\n**Top risks identified:**");
			for (const risk of data.aiSynthesis.topRisks) {
				tier2Sections.push(`- ${risk}`);
			}
		}

		if (data.aiSynthesis.insights && data.aiSynthesis.insights.length > 0) {
			tier2Sections.push("\n**AI Insights:**");
			for (const insight of data.aiSynthesis.insights) {
				const typeEmoji = insight.type === "warning" ? "⚠️" : insight.type === "suggestion" ? "💡" : "🔮";
				tier2Sections.push(`- ${typeEmoji} **${insight.title}**: ${insight.body}`);
			}
		}

		// Model attribution (transparency)
		if (data.aiSynthesis.model) {
			tier2Sections.push(
				`\n_Analysis powered by ${data.aiSynthesis.model}${data.aiSynthesis.cached ? " (cached)" : ""}_`,
			);
		}
	}

	if (hasTier2) {
		sections.push("\n## 🎯 Intelligence Highlights\n");
		sections.push(...tier2Sections);
	}

	// =============================================================================
	// TIER 3: GUIDANCE (Behavioral recommendations - conditional)
	// Carry-forward items and next session recommendations
	// =============================================================================

	const tier3Sections: string[] = [];
	let hasTier3 = false;

	// Carry-forward for next session
	if (data.ceremonyData?.carryForward && data.ceremonyData.carryForward.length > 0) {
		hasTier3 = true;
		tier3Sections.push("### 📋 Next Session\n");
		tier3Sections.push("When you return to this codebase, these items need attention:");
		for (const item of data.ceremonyData.carryForward) {
			tier3Sections.push(`- ${item}`);
		}
	}

	// Timeline highlights
	if (data.ceremonyData?.ceremony?.timeline) {
		const timeline = data.ceremonyData.ceremony.timeline;
		const significantEvents = timeline.filter(
			(e: TimelineEventType) =>
				e.severity === "warning" || e.severity === "critical" || e.type === "learning-added",
		);
		if (significantEvents.length > 0) {
			hasTier3 = true;
			tier3Sections.push("\n### 📅 Session Timeline\n");
			for (const event of significantEvents.slice(0, 5)) {
				const icon = event.severity === "critical" ? "🚨" : event.severity === "warning" ? "⚠️" : "📌";
				tier3Sections.push(`- ${icon} ${event.summary}`);
			}
		}
	}

	// Recommended next action from AI synthesis
	if (data.aiSynthesis?.nextAction) {
		hasTier3 = true;
		tier3Sections.push("\n### 🎯 Recommended Action\n");
		tier3Sections.push(data.aiSynthesis.nextAction);
	}

	if (hasTier3) {
		sections.push("\n## 📌 Next Steps\n");
		sections.push(...tier3Sections);
	}

	// =============================================================================
	// FOOTER
	// =============================================================================

	// If snapshots were created, mention they're available
	if (metrics.snapshotsCreated > 0) {
		sections.push(
			`\n---\n${metrics.snapshotsCreated} snapshots were created during this session. If any changes need to be reverted, the developer can restore from these snapshots.`,
		);
	}

	// Report card v2 fix: ceremony zeros transparency
	// When all metrics are zero AND the outcome mentions real work, surface the cold-start explanation
	const allZeros = metrics.filesModified === 0 && metrics.snapshotsCreated === 0 && metrics.learningsCaptured === 0;
	if (allZeros && data.outcome && data.outcome.length > 10) {
		sections.push(
			"\n---\n" +
				"🚧 **Ceremony zeros detected**: All metrics show 0. " +
				"This can happen when:\n" +
				"- The session was restarted mid-task (resumed session tracks only the new leg)\n" +
				"- `vreko` was not called before beginning work\n" +
				"- The daemon was restarted during the session\n\n" +
				"Files were still protected by Vreko's automatic monitoring. " +
				"For full metrics, call `vreko` at the start of every task.",
		);
	}

	return {
		content: [{ type: "text", text: sections.join("\n") }],
	};
}

// =============================================================================
// Helper Functions
// =============================================================================

/**
 * Build diagnostic information when no active session is found.
 * Helps troubleshoot why session lookup failed.
 */
function buildSessionDiagnostics(session: SessionCurrentResult | null, workspace: string): string {
	const lines: string[] = ["**Diagnostic Info:**"];

	if (session === null) {
		lines.push("- Daemon returned no session for this workspace");
		lines.push("- Possible causes:");
		lines.push("  1. `vreko` was never called to start a session");
		lines.push("  2. Session was auto-ended after 15 minutes of inactivity");
		lines.push("  3. Daemon restarted and session wasn't restored");
	} else {
		lines.push("- Session found but not active");
		lines.push(`- Session state: ${session.state ?? "unknown"}`);
		lines.push(`- Session ID: ${session.id ?? session.taskId ?? "none"}`);
		if (session.state === "ended") {
			lines.push("- Session was already ended (possibly by idle timeout or previous vreko_end call)");
		} else if (session.state === "idle") {
			lines.push("- Session is idle (possibly waiting to be started)");
		}
	}

	lines.push(`- Workspace: ${workspace}`);
	lines.push('\n**To start a new session:** Call `vreko({ task: "your task" })` before beginning work.');

	return lines.join("\n");
}

function gatherMetrics(
	endResult: SessionEndResult | null,
	ceremonyData: SessionReviewResult | null,
	_session?: SessionCurrentResult,
): SessionMetrics {
	// CRITICAL FIX: ALWAYS use ceremony data as source of truth
	// Never fall back to session.* arrays - they read from persisted registry state
	// which can be stale after session ends. Ceremony data is fresh from daemon review.
	const filesModified = ceremonyData?.filesModified ?? endResult?.filesModified ?? 0;

	const snapshotsCreated =
		ceremonyData?.checkpointsCreated ?? ceremonyData?.snapshotsCreated ?? endResult?.snapshotsCreated ?? 0;

	const learningsCaptured = ceremonyData?.learningsCaptured ?? endResult?.learningsCaptured ?? 0;

	// Duration from ceremony (canonical) or endResult
	const duration = ceremonyData?.duration ?? ceremonyData?.ceremony?.summary?.duration ?? endResult?.duration ?? null;

	return {
		filesModified,
		snapshotsCreated,
		learningsCaptured,
		pitfallsAvoided: ceremonyData?.pitfallsAvoided ?? ceremonyData?.ceremony?.pitfalls?.warnings?.length ?? 0,
		tokensSaved:
			ceremonyData?.tokensSaved?.toString() ??
			ceremonyData?.ceremony?.metrics?.tokenSavingsEstimate?.toString() ??
			estimateTokenSavings(endResult),
		coherenceScore:
			ceremonyData?.coherenceScore ??
			ceremonyData?.ceremony?.metrics?.coherenceScore ??
			endResult?.coherenceScore ??
			null,
		duration,
	};
}

function describeCoherence(score: string | number): string {
	// Handle string enum from ClosingCeremonyRecord (canonical path)
	if (typeof score === "string") {
		const descriptions: Record<string, string> = {
			high: "Highly focused session  -  changes were well-scoped and consistent",
			medium: "Good coherence  -  mostly focused with minor tangents",
			low: "Mixed session  -  several distinct concerns addressed",
			scattered: "Scattered session  -  many unrelated changes",
		};
		return descriptions[score] ?? `Unknown coherence level: ${score}`;
	}

	// Fallback: numeric range  -  normalize 0-100 contract values to 0-1 before comparison
	let normalizedScore = score;
	if (typeof normalizedScore === "number" && normalizedScore > 1) {
		normalizedScore = normalizedScore / 100;
	}
	if (normalizedScore >= 0.8) {
		return "Highly focused session  -  changes were well-scoped and consistent";
	}
	if (normalizedScore >= 0.6) {
		return "Good coherence  -  mostly focused with minor tangents";
	}
	if (normalizedScore >= 0.4) {
		return "Mixed session  -  several distinct concerns addressed";
	}
	if (normalizedScore >= 0.2) {
		return "Scattered session  -  many unrelated changes";
	}
	return "Low coherence  -  this session touched many unrelated areas";
}

function estimateTokenSavings(endResult: SessionEndResult | null): string | null {
	const learnings = endResult?.learningsCaptured ?? 0;
	if (learnings === 0) {
		return null;
	}
	// Each learning saves roughly 200-500 tokens of context re-discovery
	const estimate = learnings * 350;
	return estimate.toLocaleString();
}

