/**
 * Configuration for AI synthesis endpoint.
 */
const AI_SYNTHESIS_CONFIG = {
	/** API endpoint for ceremony synthesis (relative to daemon base URL). */
	endpoint: "/ai/generate-insights",
	/** Timeout for AI synthesis in milliseconds. */
	timeoutMs: 10_000,
	/** Whether AI synthesis is enabled (can be toggled via env). */
	enabled: process.env.VREKO_AI_SYNTHESIS !== "false",
};

/**
 * Build anonymized metadata payload from ceremony data.
 *
 * Privacy-safe: extracts only statistical metadata, never code or file paths.
 * Maps ceremony metrics to the AIMetadataPayload schema expected by the API.
 */
function buildAIMetadataPayload(
	ceremonyData: SessionReviewResult | null,
	session: SessionCurrentResult,
): AIMetadataPayload {
	// Extract domains from touched files (simplified domain detection)
	const domains = inferDomainsFromFiles(session.touchedFiles ?? []);

	// Count patterns by type (from topLearnings captureMethod)
	const byType: Record<PatternType, number> = {
		"anti-pattern": 0,
		"best-practice": 0,
		decision: 0,
		dependency: 0,
		sequence: 0,
	};

	const byDomain: Record<PatternDomain, number> = {
		exports: 0,
		dependencies: 0,
		testing: 0,
		bundling: 0,
		performance: 0,
		security: 0,
		typescript: 0,
		architecture: 0,
		general: 0,
	};

	// Populate from topLearnings if available
	const topLearnings = ceremonyData?.topLearnings ?? [];
	for (const learning of topLearnings) {
		// Map captureMethod to pattern type (approximation)
		const method = learning.captureMethod?.toLowerCase() ?? "";
		if (method.includes("anti") || method.includes("pitfall")) {
			byType["anti-pattern"]++;
		} else if (method.includes("best") || method.includes("pattern")) {
			byType["best-practice"]++;
		} else if (method.includes("decision")) {
			byType.decision++;
		} else {
			byType["best-practice"]++; // Default to best-practice
		}
	}

	// Calculate totals and averages
	const totalPatterns = topLearnings.length;
	const avgConfidence =
		topLearnings.length > 0
			? topLearnings.reduce((sum, l) => sum + (l.confidence ?? 0.5), 0) / topLearnings.length
			: 0.5;

	// Populate domain counts from inferred domains
	for (const domain of domains) {
		if (domain in byDomain) {
			byDomain[domain as PatternDomain]++;
		}
	}

	return {
		session: {
			mode: "review", // Always review at ceremony time
			domains,
			violationCount: 0, // Would need violation tracking
			scopeType: inferScopeType(session.touchedFiles ?? []),
		},
		patterns: {
			total: totalPatterns,
			byType,
			byDomain,
			avgConfidence,
			regressionRate: 0, // Would need regression tracking
		},
		query: {
			type: "synthesis", // Ceremony synthesis query type
		},
	};
}

/**
 * Infer pattern domains from file paths.
 *
 * Uses file extensions and path patterns to estimate domains.
 * This is a heuristic - actual domain detection would use the pattern store.
 */
function inferDomainsFromFiles(files: string[]): PatternDomain[] {
	const domains = new Set<PatternDomain>();

	for (const file of files) {
		const lower = file.toLowerCase();

		// Testing
		if (
			lower.includes("test") ||
			lower.includes("spec") ||
			lower.endsWith(".test.ts") ||
			lower.endsWith(".spec.ts")
		) {
			domains.add("testing");
		}

		// TypeScript/exports
		if (lower.endsWith(".ts") || lower.endsWith(".tsx")) {
			domains.add("typescript");
			domains.add("exports");
		}

		// Dependencies
		if (
			lower.includes("package.json") ||
			lower.includes("pnpm") ||
			lower.includes("yarn") ||
			lower.includes("npm")
		) {
			domains.add("dependencies");
		}

		// Bundling
		if (
			lower.includes("webpack") ||
			lower.includes("vite") ||
			lower.includes("rollup") ||
			lower.includes("esbuild")
		) {
			domains.add("bundling");
		}

		// Performance
		if (lower.includes("perf") || lower.includes("benchmark") || lower.includes("optimize")) {
			domains.add("performance");
		}

		// Security
		if (lower.includes("auth") || lower.includes("security") || lower.includes("crypto")) {
			domains.add("security");
		}

		// Architecture
		if (
			lower.includes("src/") ||
			lower.includes("lib/") ||
			lower.includes("apps/") ||
			lower.includes("packages/")
		) {
			domains.add("architecture");
		}
	}

	// Default to general if no domains detected
	if (domains.size === 0) {
		domains.add("general");
	}

	return Array.from(domains);
}

/**
 * Infer scope type from file paths.
 *
 * Determines if the session touched a single package, multiple packages, or the whole workspace.
 */
function inferScopeType(files: string[]): "monorepo" | "single-package" | "unknown" {
	if (files.length === 0) {
		return "unknown";
	}

	const packageIndicators = files.filter(
		(f) => f.includes("packages/") || f.includes("apps/") || f.includes("libs/"),
	);

	// If files span multiple packages/apps, it's monorepo scope
	const uniquePackages = new Set(
		packageIndicators.map((f) => {
			const match = f.match(/(?:packages|apps|libs)\/([^/]+)/);
			return match?.[1] ?? "";
		}),
	);

	if (uniquePackages.size > 1) {
		return "monorepo";
	}

	if (uniquePackages.size === 1) {
		return "single-package";
	}

	return "unknown";
}

/**
 * Call the AI synthesis endpoint with timeout and graceful fallback.
 *
 * Pro-gated: Only calls the API if the daemon reports Pro mode.
 * Returns null on any error (timeout, network, API error).
 */
async function fetchAISynthesis(
	payload: AIMetadataPayload,
	sessionId: string,
	daemonBaseUrl: string,
	apiKey?: string,
): Promise<AISynthesisOutput | null> {
	if (!AI_SYNTHESIS_CONFIG.enabled) {
		return null;
	}

	try {
		const controller = new AbortController();
		const timeoutId = setTimeout(() => controller.abort(), AI_SYNTHESIS_CONFIG.timeoutMs);

		const headers: Record<string, string> = {
			"Content-Type": "application/json",
		};

		if (apiKey) {
			headers.Authorization = `Bearer ${apiKey}`;
		}

		const response = await fetch(`${daemonBaseUrl}${AI_SYNTHESIS_CONFIG.endpoint}`, {
			method: "POST",
			headers,
			body: JSON.stringify({
				...payload,
				sessionId, // Add sessionId for tracing
			}),
			signal: controller.signal,
		});

		clearTimeout(timeoutId);

		if (!response.ok) {
			// Graceful fallback - don't throw, just return null
			return null;
		}

		return (await response.json()) as AISynthesisOutput;
	} catch (error) {
		// Timeout, network error, or parse error - graceful fallback
		logNonFatalError({
			tool: "vreko_end",
			operation: "fetch-ai-synthesis",
			error,
			metadata: { sessionId, endpoint: AI_SYNTHESIS_CONFIG.endpoint },
		});
		return null;
	}
}

