/**
 * Streamable HTTP Transport for MCP Server
 *
 * Implements the MCP 2025-03-26 Streamable HTTP transport specification.
 * This transport enables remote MCP server deployment with proper session management.
 *
 * @module transport/http
 */

import { randomUUID } from "node:crypto";
import type { IncomingMessage, ServerResponse } from "node:http";
import { StreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/streamableHttp.js";
import { WebStandardStreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/webStandardStreamableHttp.js";
import { isInitializeRequest } from "@modelcontextprotocol/sdk/types.js";
import { getAdaptedConsolidatedTools } from "../registry/adapter.js";
import { applyV2Surface } from "../registry/apply-v2-surface.js";
import { createToolRegistry, type ToolRegistry } from "../registry/ToolRegistry.js";
import { createMcpServerWithRegistry, type McpServerOptions } from "../server.js";

/**
 * Options for HTTP transport
 */
export interface HttpTransportOptions extends McpServerOptions {
	/** Enable JSON-only response mode (no SSE streaming) */
	enableJsonResponse?: boolean;
	/** Session timeout in milliseconds (default: 30 minutes) */
	sessionTimeoutMs?: number;
	/** Maximum concurrent sessions (default: 1000) */
	maxSessions?: number;
}

/**
 * Session store for managing MCP transports (Node.js HTTP)
 */
interface SessionEntry {
	transport: StreamableHTTPServerTransport;
	createdAt: number;
	lastAccessedAt: number;
}

/**
 * Session store for managing MCP transports (Web Standard / Hono)
 */
interface WebSessionEntry {
	transport: WebStandardStreamableHTTPServerTransport;
	createdAt: number;
	lastAccessedAt: number;
}

/**
 * HTTP Transport Manager
 *
 * Manages StreamableHTTPServerTransport instances for multiple concurrent sessions.
 * Handles session lifecycle, cleanup, and request routing.
 *
 * Uses ToolRegistry (ADR-003) for capability-based tool management.
 */
export class HttpTransportManager {
	private sessions: Map<string, SessionEntry> = new Map();
	private webSessions: Map<string, WebSessionEntry> = new Map();
	private options: HttpTransportOptions;
	private cleanupInterval: NodeJS.Timeout | null = null;
	private registry: ToolRegistry | null = null;
	private registryInitialized = false;

	constructor(options: HttpTransportOptions) {
		this.options = {
			sessionTimeoutMs: 30 * 60 * 1000, // 30 minutes default
			maxSessions: 1000,
			enableJsonResponse: true, // Default to JSON for simpler client handling
			...options,
		};

		// Start session cleanup interval
		this.cleanupInterval = setInterval(() => this.cleanupStaleSessions(), 60000);
	}

	/**
	 * Initialize the shared ToolRegistry (ADR-003)
	 * Called lazily on first request to avoid blocking constructor
	 */
	private async ensureRegistryInitialized(): Promise<ToolRegistry> {
		if (this.registryInitialized && this.registry) {
			return this.registry;
		}

		this.registry = createToolRegistry();
		const adaptedTools = await getAdaptedConsolidatedTools();
		for (const tool of adaptedTools) {
			this.registry.register(tool);
		}

		// Apply the V2 surface so the HTTP transport advertises the same four
		// tools (vreko, vreko_pulse, vreko_learn, vreko_end) as the stdio path
		// in server.ts. Without this, the HTTP `tools/list` omits vreko_pulse
		// (ARCH-09 transport parity). Shared helper: registry/apply-v2-surface.ts.
		await applyV2Surface(this.registry);

		this.registryInitialized = true;
		return this.registry;
	}

	/**
	 * Handle incoming HTTP request
	 * Routes to appropriate transport based on session ID
	 */
	async handleRequest(req: IncomingMessage, res: ServerResponse, body: unknown): Promise<void> {
		const sessionId = req.headers["mcp-session-id"] as string | undefined;

		// Handle based on HTTP method
		switch (req.method) {
			case "POST":
				await this.handlePost(req, res, body, sessionId);
				break;
			case "GET":
				await this.handleGet(req, res, sessionId);
				break;
			case "DELETE":
				await this.handleDelete(req, res, sessionId);
				break;
			default:
				res.writeHead(405, { "Content-Type": "application/json" });
				res.end(JSON.stringify({ error: "Method not allowed" }));
		}
	}

	/**
	 * Handle POST requests (client-to-server messages)
	 */
	private async handlePost(
		req: IncomingMessage,
		res: ServerResponse,
		body: unknown,
		sessionId: string | undefined,
	): Promise<void> {
		let transport: StreamableHTTPServerTransport;

		if (sessionId && this.sessions.has(sessionId)) {
			// Reuse existing session
			// biome-ignore lint/style/noNonNullAssertion: guaranteed by preceding has() check
			const entry = this.sessions.get(sessionId)!;
			entry.lastAccessedAt = Date.now();
			transport = entry.transport;
		} else if (!sessionId && isInitializeRequest(body)) {
			// New session initialization
			if (this.sessions.size >= (this.options.maxSessions || 1000)) {
				res.writeHead(503, { "Content-Type": "application/json" });
				res.end(
					JSON.stringify({
						jsonrpc: "2.0",
						error: { code: -32000, message: "Server at capacity" },
						id: null,
					}),
				);
				return;
			}

			transport = new StreamableHTTPServerTransport({
				sessionIdGenerator: () => randomUUID(),
				enableJsonResponse: this.options.enableJsonResponse,
				onsessioninitialized: (id) => {
					this.sessions.set(id, {
						transport,
						createdAt: Date.now(),
						lastAccessedAt: Date.now(),
					});
				},
			});

			transport.onclose = () => {
				if (transport.sessionId) {
					this.sessions.delete(transport.sessionId);
				}
			};

			// ADR-003: Create and connect MCP server with shared ToolRegistry
			const registry = await this.ensureRegistryInitialized();
			const server = await createMcpServerWithRegistry({
				...this.options,
				registry,
				// Auth context is already in this.options via McpServerOptions
			});
			await server.connect(transport);
		} else {
			// Invalid request - no session and not an initialize request
			res.writeHead(400, { "Content-Type": "application/json" });
			res.end(
				JSON.stringify({
					jsonrpc: "2.0",
					error: {
						code: -32000,
						message: sessionId ? "Session not found or expired" : "Bad Request: Not an initialize request",
					},
					id: null,
				}),
			);
			return;
		}

		await transport.handleRequest(req, res, body);
	}

	/**
	 * Handle GET requests (server-to-client SSE stream)
	 */
	private async handleGet(req: IncomingMessage, res: ServerResponse, sessionId: string | undefined): Promise<void> {
		if (!sessionId || !this.sessions.has(sessionId)) {
			const status = sessionId ? 404 : 400;
			res.writeHead(status, { "Content-Type": "application/json" });
			res.end(
				JSON.stringify({ error: sessionId ? "Session not found or expired" : "Invalid or missing session" }),
			);
			return;
		}

		// biome-ignore lint/style/noNonNullAssertion: guaranteed by preceding has() guard
		const entry = this.sessions.get(sessionId)!;
		entry.lastAccessedAt = Date.now();
		await entry.transport.handleRequest(req, res);
	}

	/**
	 * Handle incoming Web Standard Request (Hono / Cloudflare Workers / Deno / Bun).
	 * Returns a Web Standard Response  -  no Node.js adapters required.
	 * Use this method when running inside a Hono/web-standard HTTP framework.
	 */
	async handleWebRequest(request: Request, parsedBody?: unknown): Promise<Response> {
		const sessionId = request.headers.get("mcp-session-id") ?? undefined;

		switch (request.method) {
			case "POST":
				return this.handleWebPost(request, parsedBody, sessionId);
			case "GET":
				return this.handleWebGet(request, sessionId);
			case "DELETE":
				return this.handleWebDelete(request, sessionId);
			default:
				return new Response(JSON.stringify({ error: "Method not allowed" }), {
					status: 405,
					headers: { "Content-Type": "application/json" },
				});
		}
	}

	private async handleWebPost(
		request: Request,
		parsedBody: unknown,
		sessionId: string | undefined,
	): Promise<Response> {
		let transport: WebStandardStreamableHTTPServerTransport;

		if (sessionId && this.webSessions.has(sessionId)) {
			// biome-ignore lint/style/noNonNullAssertion: guaranteed by preceding has() check
			const entry = this.webSessions.get(sessionId)!;
			entry.lastAccessedAt = Date.now();
			transport = entry.transport;
		} else if (!sessionId && isInitializeRequest(parsedBody)) {
			if (this.webSessions.size >= (this.options.maxSessions || 1000)) {
				return new Response(
					JSON.stringify({
						jsonrpc: "2.0",
						error: { code: -32000, message: "Server at capacity" },
						id: null,
					}),
					{ status: 503, headers: { "Content-Type": "application/json" } },
				);
			}

			transport = new WebStandardStreamableHTTPServerTransport({
				sessionIdGenerator: () => randomUUID(),
				enableJsonResponse: this.options.enableJsonResponse,
				onsessioninitialized: (id) => {
					this.webSessions.set(id, { transport, createdAt: Date.now(), lastAccessedAt: Date.now() });
				},
				onsessionclosed: (id) => {
					this.webSessions.delete(id);
				},
			});

			const registry = await this.ensureRegistryInitialized();
			const server = await createMcpServerWithRegistry({ ...this.options, registry });
			await server.connect(transport);
		} else {
			// Per MCP spec 2025-03-26: session ID present but not found → 404 (triggers client re-init);
			// no session ID and not an init request → 400.
			const status = sessionId ? 404 : 400;
			return new Response(
				JSON.stringify({
					jsonrpc: "2.0",
					error: {
						code: -32000,
						message: sessionId ? "Session not found or expired" : "Bad Request: Not an initialize request",
					},
					id: null,
				}),
				{ status, headers: { "Content-Type": "application/json" } },
			);
		}

		return transport.handleRequest(request, { parsedBody });
	}

	private async handleWebGet(request: Request, sessionId: string | undefined): Promise<Response> {
		if (!sessionId || !this.webSessions.has(sessionId)) {
			// Per MCP spec: known but expired session → 404 (client MUST re-init); missing session ID → 400
			const status = sessionId ? 404 : 400;
			return new Response(
				JSON.stringify({ error: sessionId ? "Session not found or expired" : "Invalid or missing session" }),
				{
					status,
					headers: { "Content-Type": "application/json" },
				},
			);
		}
		// biome-ignore lint/style/noNonNullAssertion: guaranteed by preceding has() guard
		const entry = this.webSessions.get(sessionId)!;
		entry.lastAccessedAt = Date.now();
		return entry.transport.handleRequest(request);
	}

	private async handleWebDelete(request: Request, sessionId: string | undefined): Promise<Response> {
		if (!sessionId || !this.webSessions.has(sessionId)) {
			const status = sessionId ? 404 : 400;
			return new Response(
				JSON.stringify({ error: sessionId ? "Session not found or expired" : "Invalid or missing session" }),
				{
					status,
					headers: { "Content-Type": "application/json" },
				},
			);
		}
		// biome-ignore lint/style/noNonNullAssertion: guaranteed by preceding has() guard
		const entry = this.webSessions.get(sessionId)!;
		const response = await entry.transport.handleRequest(request);
		this.webSessions.delete(sessionId);
		return response;
	}

	/**
	 * Handle DELETE requests (session termination)
	 */
	private async handleDelete(
		req: IncomingMessage,
		res: ServerResponse,
		sessionId: string | undefined,
	): Promise<void> {
		if (!sessionId || !this.sessions.has(sessionId)) {
			// Per MCP spec: known but expired session → 404 (client MUST re-init); missing session ID → 400
			const status = sessionId ? 404 : 400;
			res.writeHead(status, { "Content-Type": "application/json" });
			res.end(
				JSON.stringify({ error: sessionId ? "Session not found or expired" : "Invalid or missing session" }),
			);
			return;
		}

		// biome-ignore lint/style/noNonNullAssertion: guaranteed by preceding has() guard
		const entry = this.sessions.get(sessionId)!;
		await entry.transport.handleRequest(req, res);
		this.sessions.delete(sessionId);
	}

	/**
	 * Clean up stale sessions
	 */
	private cleanupStaleSessions(): void {
		const now = Date.now();
		const timeout = this.options.sessionTimeoutMs || 30 * 60 * 1000;

		for (const [sessionId, entry] of this.sessions) {
			if (now - entry.lastAccessedAt > timeout) {
				entry.transport.close();
				this.sessions.delete(sessionId);
			}
		}

		for (const [sessionId, entry] of this.webSessions) {
			if (now - entry.lastAccessedAt > timeout) {
				entry.transport.close();
				this.webSessions.delete(sessionId);
			}
		}
	}

	/**
	 * Get active session count
	 */
	getSessionCount(): number {
		return this.sessions.size + this.webSessions.size;
	}

	/**
	 * Close all sessions and cleanup
	 */
	async close(): Promise<void> {
		if (this.cleanupInterval) {
			clearInterval(this.cleanupInterval);
			this.cleanupInterval = null;
		}

		for (const [_sessionId, entry] of this.sessions) {
			await entry.transport.close();
		}
		this.sessions.clear();

		for (const [_sessionId, entry] of this.webSessions) {
			await entry.transport.close();
		}
		this.webSessions.clear();
	}
}

/**
 * Create HTTP transport manager
 *
 * @param options - Server and transport configuration
 * @returns Configured HttpTransportManager instance
 *
 * @example
 * ```typescript
 * const manager = createHttpTransport({
 *   workspaceRoot: "/path/to/workspace",
 *   tier: "pro",
 * });
 *
 * // In Express route handler:
 * app.all('/mcp', async (req, res) => {
 *   await manager.handleRequest(req, res, req.body);
 * });
 * ```
 */
export function createHttpTransport(options: HttpTransportOptions): HttpTransportManager {
	return new HttpTransportManager(options);
}
