/**
 * Workspace Session Management
 *
 * Provides workspace-scoped authentication sessions with automatic refresh.
 * Integrates with existing secure credentials system.
 *
 * Storage Architecture:
 * - ~/.vreko/workspaces.json - Workspace session registry (non-sensitive metadata)
 * - OS Keychain / Encrypted file - Session tokens (sensitive data)
 *
 * @module workspace-session
 */
import { generateWorkspaceId } from "@vreko/workspace-identity";
import { z } from "zod";
// =============================================================================
// ZOD SCHEMAS (Runtime validation)
// =============================================================================
export const SessionTokensSchema = z.object({
    accessToken: z.string(),
    refreshToken: z.string(),
    expiresAt: z.string(), // ISO 8601
    sessionId: z.string(),
});
export const SessionUserInfoSchema = z.object({
    id: z.string(),
    email: z.string(),
    name: z.string().optional(),
    tier: z.enum(["free", "pro", "team", "enterprise"]),
    organizationId: z.string().optional(),
});
export const WorkspaceSessionEntrySchema = z.object({
    workspacePath: z.string(),
    workspaceId: z.string(),
    session: SessionTokensSchema,
    user: SessionUserInfoSchema,
    authMethod: z.enum(["oauth", "device-code", "api-key", "global-fallback"]),
    createdAt: z.string(),
    updatedAt: z.string(),
    lastUsedAt: z.string(),
    apiKey: z.string().optional(),
});
export const WorkspaceSessionRegistrySchema = z.object({
    version: z.literal(1),
    lastCleanupAt: z.string(),
    workspaces: z.record(z.string(), WorkspaceSessionEntrySchema),
    global: z
        .object({
        session: SessionTokensSchema,
        user: SessionUserInfoSchema,
        authMethod: z.enum(["oauth", "device-code", "api-key", "global-fallback"]),
        apiKey: z.string().optional(),
    })
        .optional(),
});
// =============================================================================
// ERROR TYPES
// =============================================================================
export class WorkspaceAuthError extends Error {
    code;
    workspaceId;
    constructor(message, code, workspaceId) {
        super(message);
        this.code = code;
        this.workspaceId = workspaceId;
        this.name = "WorkspaceAuthError";
    }
}
export var WorkspaceAuthErrorCode;
(function (WorkspaceAuthErrorCode) {
    WorkspaceAuthErrorCode["SESSION_EXPIRED"] = "SESSION_EXPIRED";
    WorkspaceAuthErrorCode["SESSION_REVOKED"] = "SESSION_REVOKED";
    WorkspaceAuthErrorCode["REFRESH_FAILED"] = "REFRESH_FAILED";
    WorkspaceAuthErrorCode["WORKSPACE_NOT_FOUND"] = "WORKSPACE_NOT_FOUND";
    WorkspaceAuthErrorCode["INVALID_WORKSPACE"] = "INVALID_WORKSPACE";
    WorkspaceAuthErrorCode["INVALID_CREDENTIALS"] = "INVALID_CREDENTIALS";
    WorkspaceAuthErrorCode["NETWORK_ERROR"] = "NETWORK_ERROR";
    WorkspaceAuthErrorCode["STORAGE_ERROR"] = "STORAGE_ERROR";
})(WorkspaceAuthErrorCode || (WorkspaceAuthErrorCode = {}));
// =============================================================================
// UTILITY FUNCTIONS
// =============================================================================
export { generateWorkspaceId } from "@vreko/workspace-identity";
/**
 * Check if session is expired (with optional buffer)
 */
export function isSessionExpired(expiresAt, bufferSeconds = 60) {
    const expiry = new Date(expiresAt);
    const buffer = bufferSeconds * 1000;
    return Date.now() > expiry.getTime() - buffer;
}
/**
 * Calculate seconds until expiry
 */
export function getExpiresIn(expiresAt) {
    const expiry = new Date(expiresAt);
    const remaining = expiry.getTime() - Date.now();
    return Math.max(0, Math.floor(remaining / 1000));
}
/**
 * Validate workspace session registry
 */
export function validateRegistry(data) {
    const result = WorkspaceSessionRegistrySchema.safeParse(data);
    return result.success ? result.data : null;
}
/**
 * Create empty workspace session registry
 */
export function createEmptyRegistry() {
    return {
        version: 1,
        lastCleanupAt: new Date().toISOString(),
        workspaces: {},
    };
}
// =============================================================================
// SESSION CONVERSION HELPERS
// =============================================================================
/**
 * Convert workspace session to legacy GlobalCredentials format
 * For backwards compatibility with existing code
 */
export function workspaceSessionToCredentials(session) {
    return {
        accessToken: session.session.accessToken,
        refreshToken: session.session.refreshToken,
        email: session.user.email,
        tier: session.user.tier === "free" ? "free" : "pro",
        expiresAt: session.session.expiresAt,
    };
}
/**
 * Create workspace session from legacy credentials
 */
export function credentialsToWorkspaceSession(workspacePath, credentials, authMethod = "device-code") {
    const workspaceId = generateWorkspaceId(workspacePath);
    const now = new Date().toISOString();
    return {
        workspacePath,
        workspaceId,
        session: {
            accessToken: credentials.accessToken,
            refreshToken: credentials.refreshToken || credentials.accessToken,
            expiresAt: credentials.expiresAt || new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
            sessionId: `sess_${workspaceId}`,
        },
        user: {
            id: credentials.email,
            email: credentials.email,
            tier: credentials.tier === "free" ? "free" : "pro",
        },
        authMethod,
        createdAt: now,
        updatedAt: now,
        lastUsedAt: now,
    };
}
