/**
 * Begin Task Facade
 *
 * Orchestrates task initialization with intelligence context loading.
 * Uses daemon IPC for all state operations.
 *
 * @module facades/begin-task
 */

import { LearningType as ContractsLearningType } from "@vreko/contracts/local-service/schemas";
import type { z } from "zod";
import { drainPendingObservationsAsync, getSessionStateAsync, startTaskAsync } from "../../adapters/session-adapter.js";
import { formatVectorLearnings, searchFileContext } from "../../context/index.js";
import { beginTaskViaService, createSnapshotViaDaemon } from "../../daemon/local-service-adapter.js";
import { type DependencyContext, getDependencyGraphService } from "../../services/dependency-graph-service.js";
import { createErrorCacheService } from "../../services/error-cache-service.js";
import { createGitContextService } from "../../services/git-context-service.js";
import { classifyQueryType, retrieveAdaptive } from "../../services/hybrid-retrieval-service.js";
import { getTestCoverageService, type TestCoverageContext } from "../../services/test-coverage-service.js";
import type { TaskIntent } from "../../services/tiered-learning-service.js";
import { extractKeywords } from "../../session/utils.js";
import { createLearningSync } from "../../sync/learning-sync.js";
import type { ErrorContext, GitContext } from "../../types/context.js";
import type { ToolHandler, ToolResult } from "../../types/tool-types.js";
import { getIntelligence } from "../intelligence.js";
import { getConstraints, handleStaleContext } from "./context-manager.js";
import { formatCompactResult, formatCompactText } from "./output-formatters.js";
import { assessRisk, generateNextActions, shouldAutoSnapshot } from "./risk-assessment.js";
import { generateProactiveGuidance, runStaticAnalysis } from "./static-analysis.js";
import type { BeginTaskOutput, RiskArea } from "./types.js";
import { getIntentContextHints, inferIntent } from "./types.js";

// =============================================================================
// TYPES RE-EXPORT
// =============================================================================

export type { TaskIntent } from "../../services/tiered-learning-service.js";
export type {
	BeginTaskCompactOutput,
	BeginTaskOutput,
	ContextWarning,
	ProactiveGuidance,
	RiskAssessment,
	SkippedTestInfo,
	StalenessCheckResult,
	StaticAnalysisOutput,
} from "./types.js";
export { getIntentContextHints, INTENT_CONTEXT_CONFIG, inferIntent } from "./types.js";

// =============================================================================
// HELPER
// =============================================================================

function result(text: string, isError = false): ToolResult {
	return {
		content: [{ type: "text", text }],
		isError,
	};
}

// =============================================================================
// HANDLER
// =============================================================================

/**
 * begin_task - Start any development task
 *
 * Combines: get_context + snapshot_create + get_learnings + session.start
 *
 * DAEMON-FIRST ARCHITECTURE:
 * 1. Try to delegate to daemon for cross-surface coordination (Extension, MCP, CLI)
 * 2. If daemon unavailable, fall back to local Intelligence
 */
export const handleBeginTask: ToolHandler = async (args, context): Promise<ToolResult> => {
	const input = args as Record<string, unknown>;
	const task = input.task as string | undefined;
	const files = input.files as string[] | undefined;
	const providedKeywords = input.keywords as string[] | undefined;
	const skipSnapshot = input.skipSnapshot as boolean | undefined;
	const compact = input.compact !== false; // Default to true for token efficiency
	const intent = (input.intent as TaskIntent | undefined) ?? inferIntent(task || "");
	const intentHints = getIntentContextHints(intent);

	if (!task) {
		return result(
			JSON.stringify({
				error: "E102_MISSING_PARAM",
				message: "Required parameter 'task' is missing",
			}),
			true,
		);
	}

	const workspaceRoot = context.workspaceRoot;

	// 0. Check context staleness and auto-rebuild if needed
	const contextWarnings = handleStaleContext(workspaceRoot);

	// 1. Extract keywords from task description if not provided
	const keywords = providedKeywords ?? extractKeywords(task);

	// =========================================================================
	// DAEMON-FIRST: Try delegating to daemon for cross-surface coordination
	// =========================================================================
	const daemonResult = await beginTaskViaService(workspaceRoot, task, files, keywords);

	if (daemonResult) {
		// Daemon is available - use its response directly.
		// Do NOT call startTaskAsync here  -  it would invoke beginTaskViaService a second time,
		// causing the daemon to end the just-created session and create a third one (singleton enforcement).
		// The session is already tracked by the daemon; no local adapter call is needed.

		const observations = (await drainPendingObservationsAsync(workspaceRoot)).map((o) => ({
			type: o.type,
			message: o.message,
		}));

		// Get local-only context enhancements
		let lastKnownErrors: ErrorContext | undefined;
		if (files && files.length > 0) {
			try {
				const errorCacheService = createErrorCacheService(workspaceRoot);
				const cachedErrors = errorCacheService.getErrorsForFiles(files);
				if (cachedErrors.length > 0) {
					lastKnownErrors = {
						typescript: cachedErrors
							.filter((e) => e.source === "typescript")
							.map((e) => ({ ...e, age: e.age })),
						tests: cachedErrors.filter((e) => e.source === "test").map((e) => ({ ...e, age: e.age })),
						lintErrors: cachedErrors.filter((e) => e.source === "lint").map((e) => ({ ...e, age: e.age })),
					};
				}
			} catch {
				/* Error cache is optional */
			}
		}

		let gitContext: GitContext | undefined;
		try {
			const gitContextService = createGitContextService(workspaceRoot);
			gitContext = await gitContextService.getContext(files || []);
			if (
				!gitContext.branch.current &&
				gitContext.uncommittedChanges.length === 0 &&
				gitContext.recentCommits.length === 0
			) {
				gitContext = undefined;
			}
		} catch {
			/* Git context is optional */
		}

		const staticAnalysis = files?.length ? await runStaticAnalysis(files, workspaceRoot) : undefined;

		let dependencyContext: DependencyContext | undefined;
		if (files?.length) {
			try {
				const depGraphService = getDependencyGraphService(workspaceRoot);
				dependencyContext = await depGraphService.getContextForFiles(files);
				if (
					Object.keys(dependencyContext.planned).length === 0 &&
					dependencyContext.circular.length === 0 &&
					dependencyContext.suggestions.length === 0
				) {
					dependencyContext = undefined;
				}
			} catch {
				/* Dependency graph is optional */
			}
		}

		let testCoverage: TestCoverageContext | undefined;
		if (files?.length) {
			try {
				const coverageService = getTestCoverageService(workspaceRoot);
				testCoverage = coverageService.getContextForFiles(files);
				if (testCoverage.summary.filesWithTests === 0 && testCoverage.summary.averageCoverage === 0) {
					testCoverage = undefined;
				}
			} catch {
				/* Coverage context is optional */
			}
		}

		const proactive_guidance = await generateProactiveGuidance(files || [], workspaceRoot);

		const output: BeginTaskOutput = {
			taskId: daemonResult.taskId,
			intent,
			intentHints,
			snapshot: daemonResult.snapshot,
			patterns: (daemonResult.patterns || []) as BeginTaskOutput["patterns"],
			constraints: (daemonResult.constraints || []) as BeginTaskOutput["constraints"],
			learnings: (daemonResult.learnings || []) as BeginTaskOutput["learnings"],
			observations,
			riskAssessment: daemonResult.riskAssessment as BeginTaskOutput["riskAssessment"],
			nextActions: (daemonResult.nextActions || []) as BeginTaskOutput["nextActions"],
			staticAnalysis,
			lastKnownErrors,
			gitContext,
			dependencyContext,
			testCoverage,
			proactive_guidance,
			contextWarnings: contextWarnings.length > 0 ? contextWarnings : undefined,
		};

		if (compact) {
			return result(formatCompactText(formatCompactResult(output, gitContext)));
		}

		const learningsCount = daemonResult.learnings?.length || 0;
		// daemonResult.snapshot may be undefined (daemon returns snapshotIds[], not snapshot{})
		// Use safe access and fall back to snapshotIds for backwards-compatible hint message
		const daemonSnapshotCreated =
			(daemonResult as { snapshot?: { created?: boolean } }).snapshot?.created ??
			((daemonResult as { snapshotIds?: string[] }).snapshotIds?.length ?? 0) > 0;
		const daemonSnapshotId =
			(daemonResult as { snapshot?: { id?: string } }).snapshot?.id ??
			(daemonResult as { snapshotIds?: string[] }).snapshotIds?.[0];
		const hint = daemonSnapshotCreated
			? `Safety snapshot created via daemon: ${daemonSnapshotId}`
			: learningsCount > 0
				? `${learningsCount} relevant learning(s) found`
				: "Ready to start coding! (daemon-coordinated)";

		return result(
			JSON.stringify({ ...output, message: `Task started: ${task}`, _hint: hint, _source: "daemon" }, null, 2),
		);
	}

	// =========================================================================
	// FALLBACK: Daemon unavailable, use daemon IPC with degraded response
	// =========================================================================

	const riskAssessment = files
		? assessRisk(files, workspaceRoot)
		: { overallRisk: "low" as const, riskAreas: [] as RiskArea[], recommendations: [] };

	let snapshot: BeginTaskOutput["snapshot"] = { created: false };

	if (!skipSnapshot && shouldAutoSnapshot(riskAssessment, files) && files?.length) {
		// Use daemon IPC for snapshot creation
		const snapshotResult = await createSnapshotViaDaemon(workspaceRoot, files, {
			reason: `Pre-task: ${task}`,
			trigger: "ai-detection",
		});

		if (snapshotResult.success && snapshotResult.snapshotId) {
			snapshot = {
				created: true,
				id: snapshotResult.snapshotId,
				reason: `Auto-created: ${riskAssessment.overallRisk} risk task`,
			};
			const state = await getSessionStateAsync(workspaceRoot);
			if (state) {
				state.stats.snapshotsCreated++;
			}
		} else if (snapshotResult.reused && snapshotResult.reusedSnapshotId) {
			snapshot = { created: false, id: snapshotResult.reusedSnapshotId, reason: snapshotResult.error };
		} else {
			snapshot = { created: false, reason: `Snapshot creation failed: ${snapshotResult.error}` };
		}
	}

	// Tiered learning load removed  -  see Deferred Backlog D5
	const learnings: Array<{ type: string; trigger: string; action: string; source?: string; relevanceScore: number }> =
		[];

	const shownLearnings = { patterns: [] as string[], pitfalls: [] as string[], other: [] as string[] };

	// Hybrid retrieval enhancement
	try {
		const searchQuery = [task, ...keywords].join(" ");
		const _classification = classifyQueryType(searchQuery);
		const hybridResult = await retrieveAdaptive(workspaceRoot, searchQuery);

		if ((hybridResult.results || []).length > 0) {
			const existingTriggers = new Set(learnings.map((l) => l.trigger));
			for (const result of (hybridResult.results || []).slice(0, 5)) {
				const chunkText = result.text || result.chunk?.chunk_text || "";
				if (!existingTriggers.has(chunkText)) {
					const sourceType = result.source || result.chunk?.source_type || "discovery";
					const learningType =
						sourceType === "pattern"
							? "pattern"
							: sourceType === "violation"
								? "pitfall"
								: sourceType === "adr"
									? "architecture"
									: "discovery";
					learnings.push({
						type: learningType,
						trigger: chunkText,
						action: result.text || chunkText,
						source: "hybrid-retrieval",
						relevanceScore: result.score || result.confidence || 0,
					});
					existingTriggers.add(chunkText);
				}
			}
		}
	} catch {
		/* Hybrid retrieval is optional */
	}

	// Vector search enhancement (if enabled)
	const vectorRetrieval = context.services?.vectorRetrieval;
	if (vectorRetrieval && files && files.length > 0) {
		try {
			const vectorResult = await searchFileContext({
				retrieval: vectorRetrieval,
				workspaceId: context.workspaceId || workspaceRoot,
				filePath: files[0],
				taskDescription: task,
				limit: 5,
				threshold: 0.65,
			});

			if (vectorResult.learnings.length > 0 && vectorResult.source === "vector") {
				const existingTriggers = new Set(learnings.map((l) => l.trigger));
				const vectorLearnings = formatVectorLearnings(vectorResult.learnings);

				for (const vl of vectorLearnings) {
					if (!existingTriggers.has(vl.content)) {
						learnings.push({
							type: vl.type as z.infer<typeof ContractsLearningType>,
							trigger: vl.content,
							action: vl.content,
							source: "vector",
							relevanceScore: vl.score,
						});
						existingTriggers.add(vl.content);
					}
				}
			}
		} catch {
			/* Vector search is optional */
		}
	}

	// Cross-workspace recommendations
	if (context.workspaceId) {
		try {
			const syncService = createLearningSync({ workspaceRoot, workspaceId: context.workspaceId });
			const recommendations = await syncService.fetchRecommendations();
			if (recommendations.length > 0) {
				const existingTriggers = new Set(learnings.map((l) => l.trigger));
				for (const rec of recommendations.slice(0, 3)) {
					if (!existingTriggers.has(rec.title)) {
						type LearningTypeValue = z.infer<typeof ContractsLearningType>;
						const validTypes = [...ContractsLearningType.options] as string[];
						const learningType: LearningTypeValue = validTypes.includes(rec.type as string)
							? (rec.type as LearningTypeValue)
							: "pattern";
						learnings.push({
							type: learningType,
							trigger: rec.title,
							action: rec.description,
							source: "cross-workspace",
							relevanceScore: rec.confidence,
						});
						existingTriggers.add(rec.title);
					}
				}
				syncService.syncPending().catch(() => {
					// Intentionally ignored: cross-workspace sync is non-blocking and optional
				});
			}
		} catch {
			/* Cross-workspace sync is optional */
		}
	}

	let patterns: BeginTaskOutput["patterns"] = [];
	try {
		const intel = getIntelligence(workspaceRoot);
		const contextResult = await intel.getContext({ task, keywords });
		if (contextResult.patterns) {
			const patternLines = contextResult.patterns.split("\n").filter(Boolean);
			patterns = patternLines.slice(0, 5).map((line) => ({ name: line.substring(0, 50), description: line }));
		}
	} catch {
		/* Intelligence not available */
	}

	const constraints = getConstraints(workspaceRoot);
	const staticAnalysis = files?.length ? await runStaticAnalysis(files, workspaceRoot) : undefined;

	let lastKnownErrors: ErrorContext | undefined;
	if (files?.length) {
		try {
			const errorCacheService = createErrorCacheService(workspaceRoot);
			const cachedErrors = errorCacheService.getErrorsForFiles(files);
			if (cachedErrors.length > 0) {
				lastKnownErrors = {
					typescript: cachedErrors
						.filter((e) => e.source === "typescript")
						.map((e) => ({ ...e, age: e.age })),
					tests: cachedErrors.filter((e) => e.source === "test").map((e) => ({ ...e, age: e.age })),
					lintErrors: cachedErrors.filter((e) => e.source === "lint").map((e) => ({ ...e, age: e.age })),
				};
			}
		} catch {
			/* Error cache is optional */
		}
	}

	let gitContext: GitContext | undefined;
	try {
		const gitContextService = createGitContextService(workspaceRoot);
		gitContext = await gitContextService.getContext(files || []);
		if (
			!gitContext.branch.current &&
			gitContext.uncommittedChanges.length === 0 &&
			gitContext.recentCommits.length === 0
		) {
			gitContext = undefined;
		}
	} catch {
		/* Git context is optional */
	}

	let dependencyContext: DependencyContext | undefined;
	if (files?.length) {
		try {
			const depGraphService = getDependencyGraphService(workspaceRoot);
			dependencyContext = await depGraphService.getContextForFiles(files);
			if (
				Object.keys(dependencyContext.planned).length === 0 &&
				dependencyContext.circular.length === 0 &&
				dependencyContext.suggestions.length === 0
			) {
				dependencyContext = undefined;
			}
		} catch {
			/* Dependency graph is optional */
		}
	}

	let testCoverage: TestCoverageContext | undefined;
	if (files?.length) {
		try {
			const coverageService = getTestCoverageService(workspaceRoot);
			testCoverage = coverageService.getContextForFiles(files);
			if (testCoverage.summary.filesWithTests === 0 && testCoverage.summary.averageCoverage === 0) {
				testCoverage = undefined;
			}
		} catch {
			/* Coverage context is optional */
		}
	}

	const observations = (await drainPendingObservationsAsync(workspaceRoot)).map((o) => ({
		type: o.type,
		message: o.message,
	}));

	const currentTask = await startTaskAsync(workspaceRoot, {
		description: task,
		plannedFiles: files || [],
		snapshotId: snapshot.id,
		keywords,
		intent,
		shownLearnings,
	});

	// startTaskAsync calls beginTaskViaService internally  -  it returns null when the daemon
	// is unavailable (same daemon that the fallback path is already working without).
	// Rather than returning a hard error, generate a local task ID so the rest of the
	// fallback path can still produce a useful response with git/static-analysis context.
	const taskId = currentTask?.id ?? `local_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 6)}`;

	const state = await getSessionStateAsync(workspaceRoot);
	if (state) {
		state.riskAreasTouched = riskAssessment.riskAreas;
	}

	try {
		const intel = getIntelligence(workspaceRoot);
		await intel.startSession();
	} catch {
		/* Intelligence session start is best-effort */
	}

	const nextActions = generateNextActions(riskAssessment, learnings, staticAnalysis);
	const proactive_guidance = await generateProactiveGuidance(files || [], workspaceRoot);

	const output: BeginTaskOutput = {
		taskId: taskId,
		intent,
		intentHints,
		snapshot,
		patterns,
		constraints,
		learnings,
		observations,
		riskAssessment,
		nextActions,
		staticAnalysis,
		lastKnownErrors,
		gitContext,
		dependencyContext,
		testCoverage,
		proactive_guidance,
		contextWarnings: contextWarnings.length > 0 ? contextWarnings : undefined,
	};

	if (compact) {
		return result(formatCompactText(formatCompactResult(output, gitContext)));
	}

	const skippedCount = staticAnalysis?.skippedTests?.length ?? 0;
	const knownErrorCount =
		(lastKnownErrors?.typescript?.length ?? 0) +
		(lastKnownErrors?.tests?.length ?? 0) +
		(lastKnownErrors?.lintErrors?.length ?? 0);
	const uncommittedCount = gitContext?.uncommittedChanges?.length ?? 0;

	let hint: string;
	if (contextWarnings.length > 0) {
		const rebuiltWarning = contextWarnings.find((w) => w.type === "context_rebuilt");
		hint = rebuiltWarning
			? `🔄 Context was stale and auto-rebuilt (${rebuiltWarning.daysSinceScanned} days old)`
			: `⚠️ Context is stale - consider running 'context op=scan'`;
	} else if (knownErrorCount > 0) {
		hint = `⚠️ ${knownErrorCount} known error(s) in planned files - check lastKnownErrors`;
	} else if (skippedCount > 0) {
		hint = `⚠️ ${skippedCount} skipped test(s) found - may need enabling`;
	} else if (uncommittedCount > 0) {
		hint = `📝 ${uncommittedCount} uncommitted change(s) in working tree`;
	} else if (snapshot.created) {
		hint = `Safety snapshot created: ${snapshot.id}`;
	} else if (learnings.length > 0) {
		hint = `${learnings.length} relevant learning(s) found`;
	} else {
		hint = "Ready to start coding!";
	}

	return result(JSON.stringify({ ...output, message: `Task started: ${task}`, _hint: hint }, null, 2));
};
