/**
 * Workflow Lifecycle Management (Async - Daemon IPC)
 *
 * Async version of workflow-lifecycle.ts that routes all session state
 * operations through the daemon via the session adapter.
 *
 * Implements 2026 session hygiene patterns for Vreko:
 * - Auto-detection of session completion (validation passed + idle time + files modified)
 * - Workflow stage tracking (idle → starting → developing → validating → ready → closing)
 * - Ceremony requirement detection (high-risk changes enforce validation gates)
 * - NextAction suggestion generation (what tool to call next)
 *
 * @see docs/session_state_migration_complete.md
 * @module session/workflow-lifecycle-async
 */

import { getSessionStateAsync, pushObservationAsync } from "../adapters/session-adapter.js";
import type { CeremonyLevel } from "../tools/consolidated/vreko-end/types.js";

// =============================================================================
// CONSTANTS
// =============================================================================

/**
 * Idle time threshold for suggesting snap_end (3 minutes)
 */
const IDLE_THRESHOLD_MS = 3 * 60 * 1000;

/**
 * High-risk path patterns that trigger ceremony enforcement
 */
const HIGH_RISK_PATHS = [/^packages\//, /^config\//, /\bauth\b/i, /\bsecurity\b/i, /\.env/, /package\.json$/];

/**
 * File count threshold for requiring ceremony (>10 files = comprehensive review)
 */
const HIGH_VOLUME_FILE_THRESHOLD = 10;

// =============================================================================
// TYPES
// =============================================================================

export type WorkflowStage = "idle" | "starting" | "developing" | "validating" | "ready" | "closing";

export interface NextActionSuggestion {
	tool: string;
	mode?: string;
	priority: "required" | "recommended" | "optional";
	reason: string;
}

// =============================================================================
// WORKFLOW STAGE TRACKING (Async)
// =============================================================================

/**
 * Get current workflow stage (async version)
 *
 * @param workspaceRoot - Workspace root path
 * @returns Current workflow stage
 */
export async function getWorkflowStageAsync(workspaceRoot: string): Promise<WorkflowStage> {
	const state = await getSessionStateAsync(workspaceRoot);
	return state?.workflowStage ?? "idle";
}

/**
 * Update workflow stage (async version)
 *
 * Note: This is a thin wrapper that records the stage change via daemon IPC.
 *
 * @param workspaceRoot - Workspace root path
 * @param stage - New workflow stage
 */
export async function updateWorkflowStageAsync(workspaceRoot: string, stage: WorkflowStage): Promise<void> {
	// Record as a progress observation - the daemon will handle stage persistence
	await pushObservationAsync(workspaceRoot, {
		type: "progress",
		message: `Workflow stage: ${stage}`,
		timestamp: Date.now(),
		context: { stage },
	});
}

// =============================================================================
// SESSION COMPLETION DETECTION (Async)
// =============================================================================

/**
 * Check if session should suggest snap_end based on heuristics (async version)
 *
 * @param workspaceRoot - Workspace root path
 * @returns Object with suggestion flag and reason
 */
export async function shouldSuggestSnapEndAsync(workspaceRoot: string): Promise<{
	shouldSuggest: boolean;
	reason?: string;
}> {
	const state = await getSessionStateAsync(workspaceRoot);
	if (!state) {
		return { shouldSuggest: false };
	}

	// No active task → no suggestion
	if (!state.currentTask) {
		return { shouldSuggest: false };
	}

	// No changes → task hasn't really started
	if (state.changesSinceTaskStart.length === 0) {
		return { shouldSuggest: false };
	}

	// Check validation status (most recent validation event)
	const recentValidation =
		state.validationEvents.length > 0 ? state.validationEvents[state.validationEvents.length - 1] : null;

	if (!recentValidation || !recentValidation.success) {
		return { shouldSuggest: false };
	}

	// Check idle time (last tool call timestamp)
	const lastToolCall = state.toolCallLog.length > 0 ? state.toolCallLog[state.toolCallLog.length - 1] : null;

	const now = Date.now();
	const idleTime = lastToolCall ? now - lastToolCall.timestamp : 0;

	if (idleTime < IDLE_THRESHOLD_MS) {
		return { shouldSuggest: false };
	}

	return {
		shouldSuggest: true,
		reason: `Validation passed ${Math.floor(idleTime / 60000)}m ago, ${state.changesSinceTaskStart.length} files modified. Ready to close session?`,
	};
}

// =============================================================================
// CEREMONY REQUIREMENT DETECTION (Async)
// =============================================================================

/**
 * Detect if ceremony should be required based on change patterns (async version)
 *
 * @param workspaceRoot - Workspace root path
 * @returns Ceremony requirement details or null
 */
export async function detectCeremonyRequirementAsync(workspaceRoot: string): Promise<{
	required: boolean;
	level: CeremonyLevel;
	reason: string;
	enforced: boolean;
} | null> {
	const state = await getSessionStateAsync(workspaceRoot);
	if (!state || !state.currentTask) {
		return null;
	}

	const changedFiles = state.changesSinceTaskStart.map((c) => c.file);
	const priorFailures = state.validationEvents.filter((e) => !e.success).length;

	// Check for high-risk paths
	const highRiskFiles = changedFiles.filter((file) => HIGH_RISK_PATHS.some((pattern) => pattern.test(file)));

	if (highRiskFiles.length > 0) {
		return {
			required: true,
			level: "standard",
			reason: `High-risk paths modified: ${highRiskFiles.slice(0, 3).join(", ")}${highRiskFiles.length > 3 ? "..." : ""}`,
			enforced: true,
		};
	}

	// Check for high volume
	if (changedFiles.length > HIGH_VOLUME_FILE_THRESHOLD) {
		return {
			required: true,
			level: "comprehensive",
			reason: `High volume of changes: ${changedFiles.length} files modified`,
			enforced: true,
		};
	}

	// Check for prior failures
	if (priorFailures > 0) {
		return {
			required: true,
			level: "standard",
			reason: `Prior validation failures: ${priorFailures} checks failed earlier in session`,
			enforced: false,
		};
	}

	return null;
}

// =============================================================================
// NEXT ACTION SUGGESTION (Async)
// =============================================================================

/**
 * Suggest next action based on current workflow stage and session state (async version)
 *
 * @param workspaceRoot - Workspace root path
 * @param currentTool - Current tool name
 * @param currentMode - Current tool mode (optional)
 * @returns Array of suggested next actions (prioritized)
 */
export async function suggestNextActionAsync(
	workspaceRoot: string,
	currentTool: string,
	currentMode?: string,
): Promise<NextActionSuggestion[]> {
	const state = await getSessionStateAsync(workspaceRoot);
	if (!state) {
		return [];
	}

	const suggestions: NextActionSuggestion[] = [];

	// After vreko(start) → suggest validation or planning
	if (currentTool === "vreko" && currentMode === "start") {
		suggestions.push({
			tool: "check",
			mode: "quick",
			priority: "recommended",
			reason: "Validate code before making changes",
		});

		suggestions.push({
			tool: "advise",
			priority: "optional",
			reason: "Get recommendations for this task",
		});
	}

	// After check → suggest next steps based on result
	if (currentTool === "check") {
		const recentValidation =
			state.validationEvents.length > 0 ? state.validationEvents[state.validationEvents.length - 1] : null;

		if (recentValidation?.success) {
			const { shouldSuggest, reason } = await shouldSuggestSnapEndAsync(workspaceRoot);

			if (shouldSuggest) {
				suggestions.push({
					tool: "snap_end",
					priority: "required",
					reason: reason || "Task complete, close session",
				});
			}
		}
	}

	// After snap_learn → suggest validation or close
	if (currentTool === "snap_learn") {
		const hasChanges = state.changesSinceTaskStart.length > 0;

		if (hasChanges) {
			suggestions.push({
				tool: "check",
				mode: "quick",
				priority: "recommended",
				reason: "Validate changes before closing session",
			});
		}

		suggestions.push({
			tool: "snap_end",
			priority: "optional",
			reason: "Close session if task is complete",
		});
	}

	// Check ceremony requirement
	const ceremonyReq = await detectCeremonyRequirementAsync(workspaceRoot);
	if (ceremonyReq?.required && ceremonyReq.enforced) {
		const snapEndIndex = suggestions.findIndex((s) => s.tool === "snap_end");
		if (snapEndIndex !== -1) {
			suggestions[snapEndIndex] = {
				...suggestions[snapEndIndex],
				priority: "required",
				reason: `${ceremonyReq.reason} - ceremony required`,
			};
		}
	}

	return suggestions;
}

/**
 * Format nextAction suggestions for wire format
 */
export function formatNextActionsForWire(suggestions: NextActionSuggestion[]): string {
	if (suggestions.length === 0) {
		return "";
	}

	return suggestions
		.map((s) => {
			const mode = s.mode ? `:${s.mode}` : "";
			const priority = s.priority === "required" ? "!" : s.priority === "recommended" ? "*" : "";
			return `${priority}${s.tool}${mode}`;
		})
		.join(",");
}
