/**
 * Tool Registry Types (ADR-003)
 *
 * Defines capabilities, tool definitions, and context types
 * for the capability-based tool registration pattern.
 *
 * Key features:
 * - Capability-based access control
 * - Tier-gated tools
 * - Dependency injection via context
 * - No circular dependencies (tools don't import registry)
 *
 * @module registry/types
 */

import type {
	CreateSnapshotOptions,
	Entitlements,
	Feature,
	PioneerActionMetadata,
	Snapshot,
	SnapshotRestoreResult,
} from "@vreko/contracts";
import type { LearningType } from "@vreko/contracts/local-service/schemas";
import type { ZodTypeAny, z } from "zod";

/**
 * Pioneer action payload used by the MCP registry layer.
 * Kept local to avoid depending on app-level Pioneer types.
 */
export interface PioneerAction {
	id: string;
	pioneerId: string;
	actionType: string;
	points: number;
	verified: boolean;
	verifiedAt?: string;
	metadata?: Record<string, unknown>;
	createdAt: string;
}

/**
 * Pioneer action result used by the MCP registry layer.
 */
export interface ActionResult {
	success: boolean;
	pointsAwarded: number;
	alreadyCompleted?: boolean;
	message?: string;
	errorCode?: string;
}

// =============================================================================
// CAPABILITIES
// =============================================================================

/**
 * Tool capabilities following principle of least privilege.
 * Tools declare required capabilities; registry enforces them.
 */
export const ToolCapability = {
	// Snapshot operations
	SNAPSHOT_READ: "snapshot:read",
	SNAPSHOT_WRITE: "snapshot:write",
	SNAPSHOT_DELETE: "snapshot:delete",

	// Session operations
	SESSION_READ: "session:read",
	SESSION_WRITE: "session:write",

	// Learning operations
	LEARNING_READ: "learning:read",
	LEARNING_WRITE: "learning:write",

	// Validation operations
	VALIDATE_READ: "validate:read",

	// Telemetry operations
	TELEMETRY_WRITE: "telemetry:write",

	// Enterprise capabilities
	TEAM_READ: "team:read",
	TEAM_WRITE: "team:write",
	COMPLIANCE_READ: "compliance:read",
	COMPLIANCE_EXPORT: "compliance:export",
	AUDIT_READ: "audit:read",
} as const;

export type ToolCapability = (typeof ToolCapability)[keyof typeof ToolCapability];

/**
 * All available capabilities
 */
export const ALL_CAPABILITIES = Object.values(ToolCapability);

/**
 * Capability groups for convenience
 */
export const CapabilityGroups = {
	/** All snapshot-related capabilities */
	SNAPSHOT_ALL: [ToolCapability.SNAPSHOT_READ, ToolCapability.SNAPSHOT_WRITE, ToolCapability.SNAPSHOT_DELETE],
	/** All session-related capabilities */
	SESSION_ALL: [ToolCapability.SESSION_READ, ToolCapability.SESSION_WRITE],
	/** All learning-related capabilities */
	LEARNING_ALL: [ToolCapability.LEARNING_READ, ToolCapability.LEARNING_WRITE],
	/** Enterprise-only capabilities */
	ENTERPRISE: [
		ToolCapability.TEAM_READ,
		ToolCapability.TEAM_WRITE,
		ToolCapability.COMPLIANCE_READ,
		ToolCapability.COMPLIANCE_EXPORT,
		ToolCapability.AUDIT_READ,
	],
} as const;

// =============================================================================
// TIERS
// =============================================================================

/**
 * Tool tier restrictions
 */
export type ToolTier = "free" | "pro" | "enterprise";

/**
 * Tier hierarchy (higher index = more access)
 */
export const TIER_HIERARCHY: ToolTier[] = ["free", "pro", "enterprise"];

/**
 * Check if a tier has access to a required tier
 */
export function tierHasAccess(userTier: ToolTier, requiredTier: ToolTier): boolean {
	const userIndex = TIER_HIERARCHY.indexOf(userTier);
	const requiredIndex = TIER_HIERARCHY.indexOf(requiredTier);
	return userIndex >= requiredIndex;
}

// =============================================================================
// WORKSPACE & USER INFO
// =============================================================================

/**
 * Workspace information passed to tools
 */
export interface WorkspaceInfo {
	/** Workspace root path */
	path: string;
	/** Workspace ID (if registered with platform) */
	id?: string;
	/** Team ID (if part of a team) */
	teamId?: string;
	/** User's tier */
	tier: ToolTier;
}

/**
 * User information passed to tools
 */
export interface UserInfo {
	/** User ID */
	id: string;
	/** User email */
	email: string;
	/** Authentication method */
	authMethod?: "oauth" | "device-flow" | "sso";
}

// =============================================================================
// SERVICES (Dependency Injection)
// =============================================================================

/**
 * Runtime router interface (from @vreko/core/runtime)
 * Uses contracts types for type safety
 */
export interface IRuntimeRouter {
	createSnapshot(options: CreateSnapshotOptions): Promise<{ snapshotId: string; snapshot: Snapshot }>;
	getSnapshot(id: string): Promise<Snapshot | null>;
	listSnapshots(options?: { limit?: number; after?: number; before?: number }): Promise<Snapshot[]>;
	restoreSnapshot(id: string, options?: { files?: string[]; dryRun?: boolean }): Promise<SnapshotRestoreResult>;
	deleteSnapshot(id: string): Promise<boolean>;
}

/**
 * Telemetry service interface
 */
export interface ITelemetryService {
	track(event: { event: string; properties?: Record<string, unknown> }): Promise<void>;
	flush(): Promise<void>;
}

/**
 * Learning service interface
 */
export interface ILearningService {
	getRelevant(options: {
		intent?: string;
		keywords?: string[];
		limit?: number;
	}): Promise<Array<{ trigger: string; action: string; type: string }>>;
	create(learning: { trigger: string; action: string; type?: string }): Promise<{ id: string }>;
	list(): Promise<Array<{ id: string; trigger: string; action: string }>>;
}

/**
 * Entitlements service interface for MCP context
 * Uses contracts types - subset of EntitlementsService for tool context
 */
export interface IEntitlementsService {
	getEntitlements(userId: string): Promise<Entitlements>;
	hasFeature(userId: string, feature: Feature): Promise<boolean>;
	checkTier(userId: string, requiredTier: ToolTier): Promise<boolean>;
	invalidateCache(userId: string): Promise<void>;
}

/**
 * Pioneer service interface for MCP context
 * Uses contracts types for action recording
 */
export interface IPioneerService {
	recordAction(
		userId: string,
		action: PioneerAction,
		metadata?: PioneerActionMetadata,
		idempotencyKey?: string,
	): Promise<ActionResult>;
}

/**
 * Services injected into tool context
 */
export interface ToolServices {
	runtime: IRuntimeRouter;
	telemetry: ITelemetryService;
	learning: ILearningService;
	/** Entitlements service for feature gating (Gap 1) */
	entitlements?: IEntitlementsService;
	/** Pioneer service for action recording (Gap 2) */
	pioneer?: IPioneerService;

	// =====================================================================
	// INTELLIGENCE STORES (Loop 1: Rollback Signal Capture)
	// =====================================================================

	/** Decision record store for tracking protection decisions */
	decisionStore?: {
		getDecisionForSnapshot(
			snapshotId: string,
			workspace: string,
		): Promise<{
			id: string;
			file_path: string;
			ai_tool: string | null;
			signal_ids: string[];
		} | null>;
		recordOutcome(id: string, outcome: "rolled_back"): Promise<void>;
	};

	/** State store for capturing learnings */
	stateStore?: {
		addLearning(learning: {
			type: z.infer<typeof LearningType>;
			trigger: string;
			action: string;
			source?: "survey" | "manual" | "violation" | "curated";
			tier: "hot" | "warm" | "cold";
			domain?: string;
		}): { id: string };
	};

	/** Analytics wrapper for event tracking */
	analytics?: {
		track(eventName: string, properties: Record<string, unknown>): void;
	};
}

// =============================================================================
// TOOL CONTEXT
// =============================================================================

/**
 * Context passed to tool handlers via dependency injection.
 * Tools NEVER import the registry directly - they receive context.
 */
export interface ToolContext {
	/** Current workspace info */
	workspace: WorkspaceInfo;

	/** Authenticated user (if any) */
	user?: UserInfo;

	/** Active capabilities for this request */
	activeCapabilities: Set<ToolCapability>;

	/** Injected services */
	services: ToolServices;

	/** Request metadata */
	request: {
		/** Unique request ID */
		id: string;
		/** Request timestamp */
		timestamp: Date;
		/** Source client */
		source: "cursor" | "copilot" | "claude" | "windsurf" | "daemon-mcp-shim" | "unknown";
	};
}

// =============================================================================
// TOOL DEFINITION
// =============================================================================

/**
 * JSON Schema type for input validation (legacy)
 */
export type JsonSchema = {
	type: string;
	properties?: Record<string, unknown>;
	required?: string[];
	[key: string]: unknown;
};

/**
 * Input schema can be a Zod schema (preferred  -  uses safeParse for rich errors)
 * or a plain JSON Schema object (legacy compatibility).
 */
export type InputSchema = ZodTypeAny | JsonSchema;

/** Type guard: is the schema a Zod schema? */
export function isZodSchema(schema: InputSchema): schema is ZodTypeAny {
	return typeof (schema as ZodTypeAny).safeParse === "function";
}

/**
 * Resolve an `InputSchema` to a plain JSON-serializable object safe for the
 * MCP wire protocol (ListTools response).
 *
 * - JSON Schema objects are returned as-is.
 * - Zod schemas attempt a best-effort extraction of their `_def.shape` into a
 *   `{ type: "object", properties, required }` envelope. This covers the common
 *   `z.object({...})` case without requiring the `zod-to-json-schema` package.
 *   For complex schemas (unions, transforms, etc.) it falls back to `{}`.
 */
export function resolveInputSchemaForMcp(schema: InputSchema): Record<string, unknown> {
	if (!isZodSchema(schema)) {
		// Already a plain JSON Schema object
		return schema as Record<string, unknown>;
	}
	// Best-effort Zod → JSON Schema for z.object() schemas
	try {
		const def = (schema as unknown as { _def: { typeName: string; shape: () => Record<string, unknown> } })._def;
		if (def?.typeName === "ZodObject" && typeof def.shape === "function") {
			const shape = def.shape() as Record<string, { isOptional?: () => boolean }>;
			const properties: Record<string, unknown> = {};
			const required: string[] = [];
			for (const [key, field] of Object.entries(shape)) {
				properties[key] = {}; // Minimal  -  callers relying on descriptions should keep JSON Schema
				if (!field.isOptional?.()) {
					required.push(key);
				}
			}
			return { type: "object", properties, ...(required.length ? { required } : {}) };
		}
	} catch {
		// Fall through
	}
	return { type: "object" };
}

/**
 * Tool handler function signature
 */
export type ToolHandler<TInput = unknown, TOutput = unknown> = (
	input: TInput,
	context: ToolContext,
) => Promise<TOutput>;

/**
 * Tool lifecycle hooks
 */
export interface ToolHooks<TInput = unknown, TOutput = unknown> {
	/** Called before tool execution */
	beforeExecute?: (input: TInput, context: ToolContext) => Promise<void>;
	/** Called after successful execution */
	afterExecute?: (output: TOutput, context: ToolContext) => Promise<void>;
	/** Called on error */
	onError?: (error: Error, context: ToolContext) => Promise<void>;
}

/**
 * Complete tool definition
 */
export interface ToolDefinition<TInput = unknown, TOutput = unknown> {
	/** Unique tool name (e.g., 'vreko', 'check') */
	name: string;

	/** Human-readable description for LLM */
	description: string;

	/** Input schema: Zod schema (preferred) or JSON Schema object (legacy) */
	inputSchema: InputSchema;

	/** Capabilities this tool requires */
	capabilities: ToolCapability[];

	/** Minimum tier required (default: 'free') */
	tier?: ToolTier;

	/** Tool handler function */
	handler: ToolHandler<TInput, TOutput>;

	/** Optional lifecycle hooks */
	hooks?: ToolHooks<TInput, TOutput>;

	/** Tool annotations for MCP */
	annotations?: {
		title?: string;
		readOnlyHint?: boolean;
		destructiveHint?: boolean;
		idempotentHint?: boolean;
	};

	/** Is this tool deprecated? */
	deprecated?: boolean;

	/** Deprecation message if deprecated */
	deprecationMessage?: string;
}

// =============================================================================
// REGISTRY INTERFACE
// =============================================================================

/**
 * Validation result
 */
export interface ValidationResult {
	valid: boolean;
	errors?: string[];
}

/**
 * Tool execution result
 */
export interface ToolExecutionResult<T = unknown> {
	success: boolean;
	result?: T;
	error?: string;
	/** Stack trace for debugging - only present on errors */
	stack?: string;
	durationMs: number;
}

/**
 * Tool registry interface
 */
export interface IToolRegistry {
	/** Register a tool */
	register<TInput, TOutput>(tool: ToolDefinition<TInput, TOutput>): void;

	/** Get a tool by name */
	get(name: string): ToolDefinition | undefined;

	/** List all tools (optionally filtered by tier) */
	list(options?: { tier?: ToolTier }): ToolDefinition[];

	/** Execute a tool with capability checking */
	execute<TInput, TOutput>(name: string, input: TInput, context: ToolContext): Promise<ToolExecutionResult<TOutput>>;

	/** Check if a tool is available for given context */
	isAvailable(name: string, context: ToolContext): boolean;

	/** Validate input against tool schema */
	validateInput(name: string, input: unknown): ValidationResult;
}

// =============================================================================
// ERRORS
// =============================================================================

/**
 * Tool not found error
 */
export class ToolNotFoundError extends Error {
	public readonly toolName: string;

	constructor(toolName: string) {
		super(`Tool '${toolName}' not found`);
		this.name = "ToolNotFoundError";
		this.toolName = toolName;
	}
}

/**
 * Tier not authorized error
 */
export class TierNotAuthorizedError extends Error {
	public readonly toolName: string;
	public readonly requiredTier: ToolTier;

	constructor(toolName: string, requiredTier: ToolTier) {
		super(`Tool '${toolName}' requires '${requiredTier}' tier or higher`);
		this.name = "TierNotAuthorizedError";
		this.toolName = toolName;
		this.requiredTier = requiredTier;
	}
}

/**
 * Capability not granted error
 */
export class CapabilityNotGrantedError extends Error {
	public readonly toolName: string;
	public readonly missingCapabilities: ToolCapability[];

	constructor(toolName: string, missingCapabilities: ToolCapability[]) {
		super(`Tool '${toolName}' requires capabilities: ${missingCapabilities.join(", ")}`);
		this.name = "CapabilityNotGrantedError";
		this.toolName = toolName;
		this.missingCapabilities = missingCapabilities;
	}
}

/**
 * Input validation error
 */
export class InputValidationError extends Error {
	public readonly toolName: string;
	public readonly validationErrors: string[];

	constructor(toolName: string, errors: string[]) {
		super(`Tool '${toolName}' input validation failed: ${errors.join("; ")}`);
		this.name = "InputValidationError";
		this.toolName = toolName;
		this.validationErrors = errors;
	}
}
