/**
 * Workspace Identity - Deterministic workspace identification
 *
 * Provides consistent workspace ID generation across all Vreko surfaces:
 * - MCP Server
 * - VSCode Extension
 * - CLI
 * - Web Dashboard
 *
 * Uses SHA-256 hash of workspace path for deterministic, privacy-preserving IDs.
 *
 * @module @vreko/workspace-identity
 */

import { createHash } from "node:crypto";

// =============================================================================
// CONSTANTS
// =============================================================================

/**
 * Workspace ID format: 12 hex characters (48 bits of entropy)
 * Example: "a1b2c3d4e5f6"
 *
 * Why 12 chars?
 * - 48 bits provides sufficient uniqueness for workspace contexts
 * - Short enough for human readability
 * - Compatible with MongoDB ObjectId, Git SHA prefixes
 */
export const WORKSPACE_ID_LENGTH = 12;

/**
 * Regex pattern for validating workspace IDs
 * Format: exactly 12 lowercase hex characters
 */
export const WORKSPACE_ID_PATTERN = /^[a-f0-9]{12}$/;

// =============================================================================
// CORE ALGORITHM
// =============================================================================

/**
 * Generate a deterministic workspace ID from a workspace path
 *
 * Uses SHA-256 hash truncated to first 12 hex characters (48 bits).
 * This ensures:
 * - Same path always produces same ID (deterministic)
 * - Different paths produce different IDs (collision-resistant)
 * - Path cannot be reverse-engineered from ID (privacy-preserving)
 * - Consistent across all surfaces (MCP, Extension, CLI, Web)
 *
 * @param workspacePath - Absolute path to workspace root
 * @returns 12-character hex string (e.g., "a1b2c3d4e5f6")
 *
 * @example
 * ```typescript
 * const workspaceId = generateWorkspaceId("/Users/dev/my-project");
 * // Returns: "a1b2c3d4e5f6" (example)
 * ```
 *
 * @security
 * - Input must be absolute, normalized path
 * - Symlinks should be resolved before calling this function
 * - Same path on different machines will produce same ID (by design)
 */
export function generateWorkspaceId(workspacePath: string): string {
	if (!workspacePath || typeof workspacePath !== "string") {
		throw new Error(`Invalid workspace path: ${workspacePath}`);
	}

	// Normalize path for consistency (handle Windows vs Unix paths)
	const normalizedPath = workspacePath.replace(/\\/g, "/").toLowerCase();

	return createHash("sha256").update(normalizedPath).digest("hex").slice(0, WORKSPACE_ID_LENGTH);
}

// =============================================================================
// VALIDATION
// =============================================================================

/**
 * Validate workspace ID format
 *
 * Checks that ID matches expected format: 12 lowercase hex characters
 *
 * @param workspaceId - The workspace ID to validate
 * @returns true if valid, false otherwise
 *
 * @example
 * ```typescript
 * isValidWorkspaceId("a1b2c3d4e5f6"); // true
 * isValidWorkspaceId("A1B2C3D4E5F6"); // false (uppercase)
 * isValidWorkspaceId("a1b2c3");       // false (too short)
 * isValidWorkspaceId(undefined);      // false
 * ```
 */
export function isValidWorkspaceId(workspaceId: unknown): boolean {
	if (typeof workspaceId !== "string") {
		return false;
	}
	return WORKSPACE_ID_PATTERN.test(workspaceId);
}

/**
 * Assert that workspace ID is valid, throw error if not
 *
 * Useful for runtime validation in security-critical contexts
 *
 * @param workspaceId - The workspace ID to validate
 * @param context - Optional context message for error
 * @throws Error if workspaceId is invalid
 *
 * @example
 * ```typescript
 * assertValidWorkspaceId(context.workspaceId, "ToolContext");
 * ```
 */
export function assertValidWorkspaceId(workspaceId: unknown, context?: string): void {
	if (!isValidWorkspaceId(workspaceId)) {
		const contextMsg = context ? ` in ${context}` : "";
		throw new Error(`Invalid workspace ID format${contextMsg}: expected 12 hex chars, got "${workspaceId}"`);
	}
}

// =============================================================================
// DERIVED UTILITIES
// =============================================================================

/**
 * Generate prefixed workspace ID for UI/display purposes
 *
 * Adds "ws_" prefix for consistency with other workspace identifiers
 *
 * @param workspacePath - Absolute path to workspace root
 * @returns Prefixed ID (e.g., "ws_a1b2c3d4e5f6")
 *
 * @deprecated Use generateWorkspaceId() directly. Prefix is legacy pattern.
 */
export function generatePrefixedWorkspaceId(workspacePath: string): string {
	const id = generateWorkspaceId(workspacePath);
	return `ws_${id}`;
}

/**
 * Extract unprefixed workspace ID from prefixed format
 *
 * @param prefixedId - Workspace ID with optional "ws_" prefix
 * @returns Unprefixed 12-char hex ID
 *
 * @example
 * ```typescript
 * extractWorkspaceId("ws_a1b2c3d4e5f6"); // "a1b2c3d4e5f6"
 * extractWorkspaceId("a1b2c3d4e5f6");    // "a1b2c3d4e5f6"
 * ```
 */
export function extractWorkspaceId(prefixedId: string): string {
	if (prefixedId.startsWith("ws_")) {
		return prefixedId.slice(3);
	}
	return prefixedId;
}

// =============================================================================
// TYPE EXPORTS
// =============================================================================

/**
 * Workspace ID type (12 hex characters)
 */
export type WorkspaceId = string & { readonly __brand: unique symbol };

/**
 * Branded workspace ID with runtime validation
 */
export class SafeWorkspaceId {
	private constructor(public readonly value: WorkspaceId) {
		/* intentionally empty */
	}

	/**
	 * Create from raw string with validation
	 */
	static fromString(value: string): SafeWorkspaceId {
		assertValidWorkspaceId(value, "SafeWorkspaceId.fromString");
		return new SafeWorkspaceId(value as WorkspaceId);
	}

	/**
	 * Generate from workspace path
	 */
	static fromPath(workspacePath: string): SafeWorkspaceId {
		const id = generateWorkspaceId(workspacePath);
		return new SafeWorkspaceId(id as WorkspaceId);
	}

	/**
	 * Get raw string value
	 */
	toString(): string {
		return this.value;
	}

	/**
	 * Check equality with another workspace ID
	 */
	equals(other: SafeWorkspaceId): boolean {
		return this.value === other.value;
	}
}
