/**
 * Credit Cost Estimator
 *
 * Provides credit cost estimates for various operations based on
 * resource consumption drivers. Per pricing_spec_v3.md:
 *
 * Credits apply only to operations with real server-side compute cost.
 * Local intelligence is free and unlimited.
 *
 * @module credit-estimator
 */

/**
 * Job types that consume credits
 */
export type CreditJobType =
	| "deep_risk_sweep"
	| "full_codebase_scan"
	| "memory_sync"
	| "synthesis"
	| "layer3_personalization"
	| "ai_refactor_plan"
	| "fleet_analysis"
	| "vitals_history";

/**
 * Parameters used to estimate credit costs
 */
export interface EstimationParams {
	/** Number of nodes in the codebase graph */
	graphNodes?: number;
	/** Number of files to process */
	fileCount?: number;
	/** Token count for LLM operations */
	tokens?: number;
	/** Duration of operation in seconds */
	durationSeconds?: number;
	/** Number of files changed */
	filesChanged?: number;
}

/**
 * Credit estimate result
 */
export interface CreditEstimate {
	/** Minimum estimated credits */
	min: number;
	/** Maximum estimated credits */
	max: number;
	/** Best estimate (median) */
	estimate: number;
	/** Confidence level (0-1) */
	confidence: number;
	/** Human-readable explanation */
	explanation: string;
	/** Job type */
	jobType: CreditJobType;
}

/**
 * Credit cost configuration per job type
 * Per pricing_spec_v3.md table
 */
export const CREDIT_COST_CONFIG: Record<
	CreditJobType,
	{
		baseMin: number;
		baseMax: number;
		driver: string;
		computeEstimate: (params: EstimationParams) => { min: number; max: number };
	}
> = {
	deep_risk_sweep: {
		baseMin: 8,
		baseMax: 15,
		driver: "Graph size + tokens",
		computeEstimate: (params) => {
			const graphNodes = params.graphNodes || 100;
			const min = Math.min(15, Math.max(8, 8 + Math.floor(graphNodes / 200)));
			const max = Math.min(18, min + 3);
			return { min, max };
		},
	},
	full_codebase_scan: {
		baseMin: 20,
		baseMax: 30,
		driver: "File count + tokens",
		computeEstimate: (params) => {
			const fileCount = params.fileCount || 100;
			const min = Math.min(30, Math.max(20, 20 + Math.floor(fileCount / 100)));
			const max = Math.min(35, min + 5);
			return { min, max };
		},
	},
	memory_sync: {
		baseMin: 1,
		baseMax: 1,
		driver: "Per sync",
		computeEstimate: () => ({ min: 1, max: 1 }),
	},
	synthesis: {
		baseMin: 5,
		baseMax: 12,
		driver: "Token usage",
		computeEstimate: (params) => {
			const tokens = params.tokens || 1000;
			const min = Math.min(12, Math.max(5, 5 + Math.floor(tokens / 2000)));
			const max = Math.min(15, min + 3);
			return { min, max };
		},
	},
	layer3_personalization: {
		baseMin: 2,
		baseMax: 5,
		driver: "Bayesian update",
		computeEstimate: () => {
			// Bayesian updates are relatively consistent
			return { min: 2, max: 5 };
		},
	},
	ai_refactor_plan: {
		baseMin: 15,
		baseMax: 25,
		driver: "Token usage + complexity",
		computeEstimate: (params) => {
			const tokens = params.tokens || 1000;
			const filesChanged = params.filesChanged || 1;
			const min = Math.min(25, Math.max(15, 15 + Math.floor(tokens / 1000)));
			const max = Math.min(30, min + filesChanged * 2);
			return { min, max };
		},
	},
	fleet_analysis: {
		baseMin: 5,
		baseMax: 12,
		driver: "Duration + complexity",
		computeEstimate: (params) => {
			const duration = params.durationSeconds || 10;
			const min = Math.min(12, Math.max(5, 5 + Math.floor(duration / 10)));
			const max = Math.min(15, min + 3);
			return { min, max };
		},
	},
	vitals_history: {
		baseMin: 2,
		baseMax: 2,
		driver: "Per query",
		computeEstimate: () => ({ min: 2, max: 2 }),
	},
};

/**
 * Human-readable job type names
 */
export const JOB_TYPE_LABELS: Record<CreditJobType, string> = {
	deep_risk_sweep: "Deep Risk Sweep",
	full_codebase_scan: "Full Codebase Scan",
	memory_sync: "Memory Sync",
	synthesis: "Synthesis",
	layer3_personalization: "Layer 3 Personalization",
	ai_refactor_plan: "AI Refactor Plan",
	fleet_analysis: "Fleet Analysis",
	vitals_history: "Vitals History",
};

/**
 * Estimate credits for a job
 *
 * @param jobType - The type of job to estimate
 * @param params - Parameters that affect credit cost
 * @returns Credit estimate with min/max/expected values
 */
export function estimateCredits(jobType: CreditJobType, params: EstimationParams = {}): CreditEstimate {
	const config = CREDIT_COST_CONFIG[jobType];
	const { min, max } = config.computeEstimate(params);

	// Calculate median estimate
	const estimate = Math.round((min + max) / 2);

	// Confidence is higher when range is smaller
	const range = max - min;
	const confidence = Math.max(0.5, 1 - range * 0.05);

	// Generate explanation
	const explanation = generateExplanation(jobType, min, max, params);

	return {
		min,
		max,
		estimate,
		confidence,
		explanation,
		jobType,
	};
}

/**
 * Generate a human-readable explanation for the estimate
 */
function generateExplanation(jobType: CreditJobType, min: number, max: number, params: EstimationParams): string {
	const _config = CREDIT_COST_CONFIG[jobType];
	const label = JOB_TYPE_LABELS[jobType];

	let explanation = `${label}: ${min}-${max} credits`;

	// Add driver-specific context
	switch (jobType) {
		case "deep_risk_sweep":
			if (params.graphNodes) {
				explanation += ` (based on ${params.graphNodes} graph nodes)`;
			}
			break;
		case "full_codebase_scan":
			if (params.fileCount) {
				explanation += ` (based on ${params.fileCount} files)`;
			}
			break;
		case "synthesis":
		case "ai_refactor_plan":
			if (params.tokens) {
				explanation += ` (based on ~${Math.round(params.tokens / 1000)}k tokens)`;
			}
			break;
		case "fleet_analysis":
			if (params.durationSeconds) {
				explanation += ` (based on ${params.durationSeconds}s duration)`;
			}
			break;
	}

	return explanation;
}

/**
 * Get a quick estimate for a job type without parameters
 * Uses default/typical values
 */
export function getQuickEstimate(jobType: CreditJobType): number {
	const config = CREDIT_COST_CONFIG[jobType];
	const { min, max } = config.computeEstimate({});
	return Math.round((min + max) / 2);
}

/**
 * Get the credit cost range for display purposes
 */
export function getCreditRange(jobType: CreditJobType): { min: number; max: number; typical: number } {
	const config = CREDIT_COST_CONFIG[jobType];
	const { min, max } = config.computeEstimate({});
	return {
		min,
		max,
		typical: Math.round((min + max) / 2),
	};
}

/**
 * Check if a job type is credit-consuming
 * Some operations may be free (local-only)
 */
export function isCreditConsuming(_jobType: CreditJobType): boolean {
	// All defined job types consume credits
	// Local-only operations are not in CreditJobType
	return true;
}

/**
 * Get all job types with their credit ranges
 * Useful for displaying a cost table to users
 */
export function getAllCreditRanges(): Array<{
	jobType: CreditJobType;
	label: string;
	min: number;
	max: number;
	typical: number;
	driver: string;
}> {
	return (Object.keys(CREDIT_COST_CONFIG) as CreditJobType[]).map((jobType) => {
		const config = CREDIT_COST_CONFIG[jobType];
		const { min, max } = config.computeEstimate({});
		return {
			jobType,
			label: JOB_TYPE_LABELS[jobType],
			min,
			max,
			typical: Math.round((min + max) / 2),
			driver: config.driver,
		};
	});
}
