/**
 * Graph-Enhanced Retrieval - Intelligence Layer v2.0
 *
 * Adds graph proximity boosting to hybrid retrieval results.
 * Per spec: Boost learnings that mention graph-relevant files by 30%.
 *
 * Features:
 * - Graph proximity weight (0.3) alongside semantic (0.4) and keyword (0.3)
 * - File relationship analysis (imports, importedBy, transitiveImporters)
 * - Automatic result re-ranking after boosting
 *
 * @module services/graph-enhanced-retrieval
 */

import type { QueryClassification, RetrievalResult } from "@vreko/intelligence";
import type { TaskIntent } from "./tiered-learning-service.js";

// Re-export for convenience
export type { TaskIntent };

// =============================================================================
// Types
// =============================================================================

/** Configuration for graph-enhanced retrieval */
export interface GraphEnhancedConfigOptions {
	/** Weight for semantic similarity (default: 0.4) */
	semanticWeight?: number;
	/** Weight for keyword matching (default: 0.3) */
	keywordWeight?: number;
	/** Weight for graph proximity (default: 0.3) */
	graphProximityWeight?: number;
	/** RRF constant (default: 60) */
	k?: number;
}

/** Graph context information */
export interface GraphContext {
	/** Files related to the target through imports/importedBy */
	relevantFiles: string[];
	/** Percentage of target files found in graph */
	targetFilesCoverage: number;
}

/** Extended retrieval result with graph relevance */
export interface GraphEnhancedResult extends RetrievalResult {
	/** Whether this result mentions graph-relevant files */
	graphRelevant: boolean;
}

/** Full result from graph-enhanced retrieval */
export interface EnhancedRetrievalResult {
	/** Retrieval results with graph boosting applied */
	results: GraphEnhancedResult[];
	/** Query classification */
	classification: QueryClassification;
	/** Graph context information */
	graphContext: GraphContext;
}

/** Dependency graph node (simplified) */
export interface DependencyNode {
	filePath: string;
	imports: string[];
	importedBy: string[];
	transitiveImporters: {
		depth1: string[];
		depth2: string[];
		depth3Plus: string[];
	};
}

/** Dependency graph (simplified) */
export interface DependencyGraph {
	nodes: Map<string, DependencyNode>;
}

// =============================================================================
// Configuration Class
// =============================================================================

/**
 * GraphEnhancedConfig
 *
 * Configuration for graph-enhanced retrieval with automatic weight normalization.
 */
export class GraphEnhancedConfig {
	semanticWeight: number;
	keywordWeight: number;
	graphProximityWeight: number;
	k: number;

	constructor(options: GraphEnhancedConfigOptions = {}) {
		// Default weights per spec
		let semantic = options.semanticWeight ?? 0.4;
		let keyword = options.keywordWeight ?? 0.3;
		let graph = options.graphProximityWeight ?? 0.3;

		// Normalize weights to sum to 1.0
		const total = semantic + keyword + graph;
		if (Math.abs(total - 1.0) > 0.01) {
			semantic /= total;
			keyword /= total;
			graph /= total;
		}

		this.semanticWeight = semantic;
		this.keywordWeight = keyword;
		this.graphProximityWeight = graph;
		this.k = options.k ?? 60;
	}
}

// =============================================================================
// Constants
// =============================================================================

/** Boost multiplier for graph-relevant results */
const GRAPH_RELEVANCE_BOOST = 1.3; // 30% boost

// =============================================================================
// Main Functions
// =============================================================================

/**
 * Retrieve with graph context
 *
 * Combines standard hybrid retrieval with graph proximity boosting.
 *
 * @param query - Search query
 * @param targetFiles - Files being analyzed/modified
 * @param options - Retrieval options
 * @returns Enhanced retrieval results with graph context
 */
export async function retrieveWithGraphContext(
	_query: string,
	targetFiles: string[],
	options: {
		intent?: TaskIntent;
		workspaceRoot: string;
		hybridResults?: RetrievalResult[];
		graph?: DependencyGraph;
		config?: GraphEnhancedConfig;
	},
): Promise<EnhancedRetrievalResult> {
	const { intent: _intent, hybridResults = [], graph, config = new GraphEnhancedConfig() } = options;

	// 1. Build graph context from target files
	const relevantFiles = buildGraphContext(targetFiles, graph);

	// 2. Apply graph proximity boost to results
	const boostedResults = applyGraphBoost(hybridResults, relevantFiles);

	// 3. Re-sort by boosted score
	boostedResults.sort((a, b) => b.score - a.score);

	// 4. Calculate coverage
	const coverage = calculateCoverage(targetFiles, graph);

	return {
		results: boostedResults,
		classification: {
			type: "factual",
			complexity: "simple",
			confidence: config.semanticWeight,
			weights: {
				semantic: config.semanticWeight,
				keyword: config.keywordWeight,
			},
			reason: "Graph-enhanced retrieval with proximity boosting",
		},
		graphContext: {
			relevantFiles: [...relevantFiles],
			targetFilesCoverage: coverage,
		},
	};
}

/**
 * Build graph context from target files
 *
 * Collects all files related to target files through imports/importedBy.
 */
function buildGraphContext(targetFiles: string[], graph?: DependencyGraph): Set<string> {
	const relevantFiles = new Set<string>();

	if (!graph) {
		return relevantFiles;
	}

	for (const file of targetFiles) {
		const node = graph.nodes.get(file);
		if (node) {
			// Add direct imports
			for (const f of node.imports || []) {
				relevantFiles.add(f);
			}
			// Add direct importers
			for (const f of node.importedBy || []) {
				relevantFiles.add(f);
			}
			// Add transitive depth1 importers
			for (const f of node.transitiveImporters?.depth1 || []) {
				relevantFiles.add(f);
			}
		}
	}

	return relevantFiles;
}

/**
 * Apply graph proximity boost to results
 *
 * Boosts results that mention graph-relevant files by 30%.
 */
function applyGraphBoost(results: RetrievalResult[], relevantFiles: Set<string>): GraphEnhancedResult[] {
	return results.map((result) => {
		const mentionsRelevantFile = [...relevantFiles].some(
			(f) => result.chunk.chunk_text.includes(f) || result.chunk.source_id?.includes(f),
		);

		return {
			...result,
			score: mentionsRelevantFile ? result.score * GRAPH_RELEVANCE_BOOST : result.score,
			graphRelevant: mentionsRelevantFile,
		};
	});
}

/**
 * Calculate target files coverage
 *
 * Returns the percentage of target files that exist in the graph.
 */
function calculateCoverage(targetFiles: string[], graph?: DependencyGraph): number {
	if (!graph || targetFiles.length === 0) {
		return 0;
	}

	const found = targetFiles.filter((f) => graph.nodes.has(f)).length;
	return found / targetFiles.length;
}

// =============================================================================
// Re-export for module index
// =============================================================================

export default {
	retrieveWithGraphContext,
	GraphEnhancedConfig,
	GRAPH_RELEVANCE_BOOST,
};
