/**
 * Session Utilities
 *
 * Shared session state checking logic for V2 tools.
 * Ensures consistent session state handling across vreko, vreko_learn, vreko_end.
 *
 * @module tools/v2/utils/session
 */

/**
 * Minimal session shape for active check
 */
export interface SessionLike {
	/** Legacy boolean field */
	active?: boolean;
	/** State string from daemon: "active" | "ended" | "idle" | "started" */
	state?: string;
	/** Session ID */
	id?: string;
}

/**
 * Check if a session is active.
 *
 * Resilient check that handles multiple daemon response shapes:
 * - Legacy: { active: true }
 * - Current: { state: "active" }
 * - Transitional: { state: "started" }
 *
 * Note: `state === "running"` is NOT included  -  the daemon contract (@vreko/contracts)
 * only emits "active" | "ended". "running" was dead code that never matched real responses.
 *
 * @param session - Session object from daemon
 * @returns true if session is considered active
 */
export function isActiveSession(session: SessionLike | null | undefined): session is SessionLike {
	if (!session) {
		return false;
	}

	// Explicit positive match on known active states only.
	// The previous negative-match fallback (not "ended" and not "idle") returned true
	// for absent or unknown state values, which caused false positives.
	return session.active === true || session.state === "active" || session.state === "started";
}
