/**
 * Learning Sync Service
 *
 * Cross-workspace learning synchronization routed through the daemon IPC.
 * F1: Removed direct intelligence/storage import  -  all state
 *     management is delegated to vrekod via learning/queue IPC methods.
 *
 * Privacy: Pattern keys only, no code content (C-006)
 *
 * @module sync/learning-sync
 */

import type { LearningType as ContractsLearningType } from "@vreko/contracts/local-service/schemas";
import type { z } from "zod";
import { createDaemonClient } from "../daemon/local-service-adapter.js";

// Minimal logger for surfacing daemon errors without importing @vreko/infrastructure
const warn = (msg: string, ctx?: Record<string, unknown>) =>
	process.stderr.write(`[learning-sync] WARN ${msg}${ctx ? ` ${JSON.stringify(ctx)}` : ""}\n`);

// =============================================================================
// Types
// =============================================================================

/**
 * Learning entry from snap_learn or violations
 */
export interface Learning {
	id: string;
	type: z.infer<typeof ContractsLearningType> | string;
	trigger: string;
	action: string;
	source?: string;
	timestamp: string;
}

/**
 * Recommendation from cross-workspace aggregation
 */
export interface Recommendation {
	type: string;
	title: string;
	description: string;
	confidence: number;
}

/**
 * Sync result
 */
export interface SyncResult {
	synced: number;
	failed: number;
	errors: string[];
}

/**
 * Sync options
 */
export interface SyncOptions {
	maxBatchSize?: number;
}

/**
 * Service configuration
 */
export interface LearningSyncConfig {
	workspaceRoot: string;
	apiBaseUrl?: string;
	workspaceId: string;
}

/**
 * Pending sync item returned from daemon
 */
interface PendingSyncItem {
	id: string;
	type: string;
	patternKey: string;
	patternType: string;
	confidence: number;
	queuedAt: string;
	retryCount: number;
}

// =============================================================================
// LearningSync Service
// =============================================================================

/**
 * Learning synchronization service.
 *
 * Routes all state through daemon IPC (learning/queue methods) instead of
 * writing directly to StateStore. This satisfies the architecture fence:
 * packages/mcp MUST NOT import intelligence directly at runtime.
 *
 * Provides local-first learning capture with background cloud sync.
 * Gracefully handles daemon unavailability  -  operations degrade silently.
 */
export class LearningSync {
	private readonly workspaceRoot: string;
	private readonly apiBaseUrl: string;
	private readonly workspaceId: string;

	constructor(config: LearningSyncConfig) {
		this.workspaceRoot = config.workspaceRoot;
		this.apiBaseUrl = config.apiBaseUrl || "https://api.vreko.dev";
		this.workspaceId = config.workspaceId;
	}

	/**
	 * Queue a learning for cloud sync.
	 * Delegates to daemon IPC (learning/queue) instead of writing to state.bin.
	 */
	async queueLearning(learning: Learning): Promise<void> {
		const patternKey = LearningSync.generatePatternKey(learning);
		try {
			const daemonClient = createDaemonClient(this.workspaceRoot);
			await daemonClient.request("learning/queue", {
				workspace: this.workspaceRoot,
				patternKey,
				patternType: learning.type,
				confidence: LearningSync.calculateConfidence(learning.type),
			});
		} catch (error) {
			warn("learning/queue IPC failed  -  learning dropped this cycle", {
				error: error instanceof Error ? error.message : String(error),
				patternKey,
			});
		}
	}

	/**
	 * Sync pending learnings to cloud API.
	 * Returns count of synced/failed items.
	 */
	async syncPending(options: SyncOptions = {}): Promise<SyncResult> {
		const maxBatchSize = options.maxBatchSize ?? 100;
		const result: SyncResult = { synced: 0, failed: 0, errors: [] };

		let pending: PendingSyncItem[];
		let daemonClient: ReturnType<typeof createDaemonClient>;

		try {
			daemonClient = createDaemonClient(this.workspaceRoot);
			const response = await daemonClient.request<{ items: PendingSyncItem[] }>("learning/queue-sync", {
				workspace: this.workspaceRoot,
				maxBatchSize,
			});
			pending = response?.items ?? [];
		} catch {
			return { synced: 0, failed: 0, errors: ["daemon unavailable"] };
		}

		if (pending.length === 0) {
			return result;
		}

		const syncedIds: string[] = [];
		const failedIds: string[] = [];

		for (const item of pending) {
			try {
				await this.syncItem(item);
				syncedIds.push(item.id);
				result.synced++;
			} catch (error) {
				failedIds.push(item.id);
				result.failed++;
				result.errors.push(error instanceof Error ? error.message : String(error));
			}
		}

		// Report results back to daemon
		try {
			await daemonClient.request("learning/queue-sync-complete", {
				workspace: this.workspaceRoot,
				syncedIds,
				failedIds,
			});
		} catch (error) {
			// Best-effort  -  daemon may have restarted between fetch and complete
			warn("learning/queue-sync-complete IPC failed  -  sync state may be inconsistent", {
				error: error instanceof Error ? error.message : String(error),
				syncedCount: syncedIds.length,
				failedCount: failedIds.length,
			});
		}

		return result;
	}

	/**
	 * Fetch cross-workspace recommendations from API.
	 * Returns empty array on error (graceful degradation).
	 */
	async fetchRecommendations(): Promise<Recommendation[]> {
		try {
			const url = `${this.apiBaseUrl}/v1/mcp/recommendations`;
			const response = await fetch(url, {
				method: "POST",
				headers: {
					"Content-Type": "application/json",
				},
				body: JSON.stringify({
					workspaceId: this.workspaceId,
				}),
			});

			if (!response.ok) {
				return [];
			}

			const data = (await response.json()) as { recommendations?: Recommendation[] };
			return data.recommendations || [];
		} catch {
			// Graceful degradation - return empty array
			return [];
		}
	}

	// ===========================================================================
	// Static Helpers
	// ===========================================================================

	/**
	 * Generate pattern key from learning (trigger→action format).
	 * This is what gets stored in the aggregated learnings table.
	 */
	static generatePatternKey(learning: Learning): string {
		return `${learning.trigger}→${learning.action}`;
	}

	/**
	 * Calculate initial confidence based on learning type.
	 * Pitfalls get higher confidence as they represent mistakes to avoid.
	 */
	static calculateConfidence(type: string): number {
		const confidenceMap: Record<string, number> = {
			pattern: 0.6,
			pitfall: 0.7, // Higher - mistakes to avoid are more actionable
			efficiency: 0.5,
			discovery: 0.4, // Lower - discoveries may be workspace-specific
			workflow: 0.5,
		};
		return confidenceMap[type] ?? 0.5;
	}

	// ===========================================================================
	// Private Helpers
	// ===========================================================================

	/**
	 * Sync a single item to the API
	 */
	private async syncItem(item: PendingSyncItem): Promise<void> {
		const url = `${this.apiBaseUrl}/v1/mcp/learning/record`;

		const response = await fetch(url, {
			method: "POST",
			headers: {
				"Content-Type": "application/json",
			},
			body: JSON.stringify({
				workspaceId: this.workspaceId,
				patternKey: item.patternKey,
				patternType: item.patternType,
				confidence: item.confidence,
			}),
		});

		if (!response.ok) {
			throw new Error(`API error: ${response.status} ${response.statusText}`);
		}
	}
}

/**
 * Factory function for creating LearningSync service
 */
export function createLearningSync(config: LearningSyncConfig): LearningSync {
	return new LearningSync(config);
}
