/**
 * SSE Local Transport - Server-Sent Events for Multi-Client MCP
 *
 * Provides a localhost HTTP server (default port 8765) for SSE connections
 * from multiple AI tools (Claude Desktop, Cursor, Windsurf, VS Code).
 *
 * ## Security (Unified Auth)
 * - Supports Better Auth API keys (sk_live_xxx, sk_test_xxx)
 * - Falls back to local token (~/.vreko/mcp-token) for backward compatibility
 * - Token file permissions: 0o600 (user-only read/write)
 * - User context extraction for rate limiting and audit
 *
 * ## Connection Management
 * - Max 10 concurrent clients
 * - 15-minute idle timeout (no pong received)
 * - 30-second ping interval
 * - 3 missed pongs → automatic disconnect
 *
 * @module transport/sse-local
 */

import { randomBytes } from "node:crypto";
import { EventEmitter } from "node:events";
import { access, chmod, mkdir, readFile, writeFile } from "node:fs/promises";
import { createServer, type IncomingMessage, type Server, type ServerResponse } from "node:http";
import { homedir } from "node:os";
import { dirname, join } from "node:path";

// =============================================================================
// Types
// =============================================================================

/** Logger interface for dependency injection */
export interface SSELogger {
	debug(message: string, meta?: Record<string, unknown>): void;
	info(message: string, meta?: Record<string, unknown>): void;
	warn(message: string, meta?: Record<string, unknown>): void;
	error(message: string, meta?: Record<string, unknown>): void;
}

/** Default console-based logger (uses stderr to avoid corrupting MCP stdio) */
const defaultLogger: SSELogger = {
	debug: (msg, meta) => process.stderr.write(`[SSE] DEBUG ${msg} ${meta ? JSON.stringify(meta) : ""}\n`),
	info: (msg, meta) => process.stderr.write(`[SSE] ${msg} ${meta ? JSON.stringify(meta) : ""}\n`),
	warn: (msg, meta) => process.stderr.write(`[SSE] WARN ${msg} ${meta ? JSON.stringify(meta) : ""}\n`),
	error: (msg, meta) => process.stderr.write(`[SSE] ERROR ${msg} ${meta ? JSON.stringify(meta) : ""}\n`),
};

// =============================================================================
// Security Utilities
// =============================================================================

/** Patterns that indicate path traversal attacks */
const PATH_TRAVERSAL_PATTERNS = [
	/\.\./, // Parent directory access
	/\.\.\//, // Unix parent directory
	/\.\.\\/, // Windows parent directory
	/^\/etc/, // System configuration
	/^\/proc/, // Process information
	/^\/sys/, // System information
	/^\/dev/, // Device files
	/^\/root/, // Root home
	/^\//, // Absolute path (require relative or validated absolute)
];

/** Allowed workspace path prefixes (localhost development) */
const ALLOWED_WORKSPACE_PREFIXES = [
	process.env.HOME ?? "", // User home directory
	"/Users/", // macOS
	"/home/", // Linux
	"/Volumes/", // macOS external drives
];

/**
 * Validate workspace path for security
 * Prevents path traversal and system file access
 */
function isValidWorkspacePath(workspace: string): boolean {
	// Check for empty or whitespace-only paths
	if (!workspace || !workspace.trim()) {
		return false;
	}

	// Check for path traversal patterns
	for (const pattern of PATH_TRAVERSAL_PATTERNS) {
		if (pattern.test(workspace)) {
			return false;
		}
	}

	// On localhost, allow any non-traversing absolute path that starts with allowed prefixes
	// This is a development-only endpoint, so we're permissive but safe
	const isAllowedPrefix = ALLOWED_WORKSPACE_PREFIXES.some((prefix) => prefix && workspace.startsWith(prefix));

	// Also allow relative paths (no leading /) for workspace-relative operations
	const isRelativePath = !workspace.startsWith("/");

	return isAllowedPrefix || isRelativePath;
}

/**
 * Validate Origin header for localhost-only endpoints
 * Prevents CSRF from external origins
 */
function isValidLocalhostOrigin(origin: string | undefined): boolean {
	if (!origin) {
		// Allow requests without Origin (non-browser clients like curl)
		return true;
	}

	try {
		const url = new URL(origin);
		return (
			url.hostname === "localhost" || url.hostname === "127.0.0.1" || url.hostname === "[::1]" // IPv6 localhost
		);
	} catch {
		return false;
	}
}

/**
 * Authentication result from unified auth validation
 */
export interface SSEAuthResult {
	/** Whether authentication was successful */
	valid: boolean;
	/** Type of authentication used */
	authType: "apiKey" | "localToken";
	/** User ID from API key (only for apiKey auth type) */
	userId?: string;
	/** User tier from API key metadata */
	tier?: "free" | "pro" | "admin";
	/** Permissions from API key */
	permissions?: string[];
}

/**
 * API key validator interface for dependency injection
 * Allows SSE transport to validate API keys without direct database dependency
 */
export interface ApiKeyValidator {
	/**
	 * Verify an API key and return user context
	 * @param key - The API key to verify
	 * @returns Verification result with userId, tier, permissions, or null if invalid
	 */
	verifyApiKey(key: string): Promise<{
		isValid: boolean;
		userId?: string;
		metadata?: { tier?: string; plan?: string };
		permissions?: Record<string, string[]>;
	} | null>;
}

/**
 * Digest service interface for Pioneer Dashboard
 * Allows SSE transport to serve dashboard data directly
 */
export interface DigestServiceProvider {
	/**
	 * Compute the Pioneer Dashboard digest
	 * @param params - Workspace path and optional user info
	 * @returns Dashboard digest response
	 */
	compute(params: {
		workspace: string;
		force?: boolean;
		user?: { name: string | null; email: string };
		sessionMetrics?: { activeSessionCount: number; lastActivityTime: string };
	}): Promise<{
		status: "success" | "empty" | "error";
		digest?: import("@vreko/contracts/dashboard").PioneerDashboard;
		stalenessMinutes?: number;
		message?: string;
		code?: string;
	}>;
}

interface SSEClient {
	id: string;
	res: ServerResponse;
	lastPong: number;
	missedPongs: number;
	createdAt: number;
	/** User context from unified auth (only set for API key auth) */
	userId?: string;
	tier?: "free" | "pro" | "admin";
	authType: "apiKey" | "localToken";
}

interface SSETransportConfig {
	/** Port to listen on (default: 8765) */
	port: number;
	/** Maximum concurrent clients (default: 10) */
	maxClients: number;
	/** Idle timeout in ms (default: 15 minutes) */
	idleTimeoutMs: number;
	/** Ping interval in ms (default: 30 seconds) */
	pingIntervalMs: number;
	/** Max missed pongs before disconnect (default: 3) */
	maxMissedPongs: number;
	/** Path to token file (default: ~/.vreko/mcp-token) */
	tokenPath: string;
	/** Logger instance (default: console-based) */
	logger?: SSELogger;
	/** API key validator for unified auth (optional - enables API key auth) */
	apiKeyValidator?: ApiKeyValidator;
	/** Digest service for Pioneer Dashboard (optional - enables /digest endpoint) */
	digestService?: DigestServiceProvider;
	/** Session service for web dashboard (optional - enables /session/list endpoint) */
	sessionService?: SessionServiceProvider;
}

// =============================================================================
// Session Service Provider
// =============================================================================

/**
 * Minimal interface consumed by SSELocalTransport for /session/list.
 * Local-service wires the full SessionService here.
 */
export interface SessionServiceProvider {
	list(params: {
		limit?: number;
		includeEnded?: boolean;
		workspacePath?: string;
	}): Promise<{ sessions: unknown[]; hasMore: boolean }>;
}

// =============================================================================
// SSE Local Transport
// =============================================================================

export class SSELocalTransport extends EventEmitter {
	private server: Server | null = null;
	private clients: Map<string, SSEClient> = new Map();
	private token: string | null = null;
	private pingTimer: NodeJS.Timeout | null = null;
	private config: SSETransportConfig;
	private logger: SSELogger;

	constructor(config?: Partial<SSETransportConfig>) {
		super();
		this.logger = config?.logger ?? defaultLogger;
		this.config = {
			port: 8765,
			maxClients: 10,
			idleTimeoutMs: 15 * 60 * 1000,
			pingIntervalMs: 30 * 1000,
			maxMissedPongs: 3,
			tokenPath: join(homedir(), ".vreko", "mcp-token"),
			...config,
		};
	}

	/**
	 * Start the SSE transport server
	 */
	async start(): Promise<void> {
		if (this.server) {
			throw new Error("SSE transport already started");
		}

		// Ensure token exists
		await this.ensureToken();

		// Create HTTP server
		this.server = createServer((req, res) => {
			// Enable CORS for localhost clients
			res.setHeader("Access-Control-Allow-Origin", "*");
			res.setHeader("Access-Control-Allow-Headers", "Authorization, Content-Type");
			res.setHeader("Access-Control-Allow-Methods", "GET, POST, OPTIONS");

			if (req.method === "OPTIONS") {
				res.writeHead(200);
				res.end();
				return;
			}

			if (req.url === "/events" && req.method === "GET") {
				this.handleConnect(req, res);
			} else if (req.url === "/pong" && req.method === "POST") {
				this.handlePongRequest(req, res);
			} else if (req.url === "/health" && req.method === "GET") {
				res.writeHead(200, { "Content-Type": "application/json" });
				res.end(JSON.stringify({ status: "ok", clients: this.clients.size }));
			} else if (req.url === "/digest" && req.method === "POST") {
				this.handleDigestRequest(req, res);
			} else if (req.url === "/session/list" && req.method === "POST") {
				this.handleSessionListRequest(req, res);
			} else {
				res.writeHead(404);
				res.end("Not Found");
			}
		});

		return new Promise((resolve, reject) => {
			this.server?.listen(this.config.port, "127.0.0.1", () => {
				this.logger.info(`Listening on localhost:${this.config.port}`);
				this.startPingLoop();
				resolve();
			});

			this.server?.on("error", reject);
		});
	}

	/**
	 * Stop the SSE transport server
	 */
	async stop(): Promise<void> {
		// Stop ping loop
		if (this.pingTimer) {
			clearInterval(this.pingTimer);
			this.pingTimer = null;
		}

		// Disconnect all clients
		for (const [clientId, client] of this.clients.entries()) {
			this.sendEvent(client, "disconnect", { reason: "server_shutdown" });
			client.res.end();
			this.clients.delete(clientId);
		}

		// Close server
		if (this.server) {
			return new Promise((resolve, reject) => {
				this.server?.close((err) => {
					if (err) {
						reject(err);
					} else {
						this.server = null;
						this.logger.info("Transport stopped");
						resolve();
					}
				});
			});
		}
	}

	/**
	 * Broadcast an event to all connected clients
	 */
	broadcast(event: string, data: unknown): void {
		const deadClients: string[] = [];

		for (const [clientId, client] of this.clients.entries()) {
			try {
				this.sendEvent(client, event, data);
			} catch (err) {
				this.logger.error(`Failed to send to client ${clientId}`, { error: String(err) });
				deadClients.push(clientId);
			}
		}

		// Clean up dead clients
		for (const clientId of deadClients) {
			this.removeClient(clientId);
		}
	}

	/**
	 * Get current client count
	 */
	get clientCount(): number {
		return this.clients.size;
	}

	/**
	 * Check if daemon should suppress idle shutdown
	 * Returns true when clients are connected
	 */
	shouldSuppressIdleShutdown(): boolean {
		return this.clients.size > 0;
	}

	// =========================================================================
	// Private Methods
	// =========================================================================

	/**
	 * Ensure token exists, generate if not
	 */
	private async ensureToken(): Promise<string> {
		try {
			await access(this.config.tokenPath);
			this.token = (await readFile(this.config.tokenPath, "utf8")).trim();
		} catch {
			await mkdir(dirname(this.config.tokenPath), { recursive: true });
			this.token = randomBytes(32).toString("hex");
			await writeFile(this.config.tokenPath, this.token, { mode: 0o600 });
			// Explicitly set permissions (writeFile mode option may not work on all platforms)
			await chmod(this.config.tokenPath, 0o600);
		}
		return this.token;
	}

	/**
	 * Validate authentication using unified auth pattern
	 *
	 * Supports both:
	 * 1. API keys (sk_live_xxx, sk_test_xxx) - validates against Better Auth
	 * 2. Local tokens - validates against ~/.vreko/mcp-token
	 *
	 * @param token - The token to validate
	 * @returns Auth result with user context if valid
	 */
	private async validateAuth(token: string): Promise<SSEAuthResult> {
		// Check if this looks like an API key (sk_live_ or sk_test_ prefix)
		if (token.startsWith("sk_live_") || token.startsWith("sk_test_")) {
			// Use API key validator if available
			if (this.config.apiKeyValidator) {
				try {
					const verified = await this.config.apiKeyValidator.verifyApiKey(token);
					if (verified?.isValid && verified?.userId) {
						// Determine tier from metadata
						let tier: "free" | "pro" | "admin" = "free";
						if (verified.metadata?.tier === "admin") {
							tier = "admin";
						} else if (verified.metadata?.tier === "pro" || verified.metadata?.plan === "pro") {
							tier = "pro";
						}

						return {
							valid: true,
							authType: "apiKey",
							userId: verified.userId,
							tier,
							permissions: Object.keys(verified.permissions || {}),
						};
					}
				} catch (err) {
					this.logger.warn("API key validation failed", { error: String(err) });
				}
			}

			// API key format but no validator or validation failed
			return {
				valid: false,
				authType: "apiKey",
			};
		}

		// Fall back to local token validation
		if (this.token && token === this.token) {
			return {
				valid: true,
				authType: "localToken",
			};
		}

		return {
			valid: false,
			authType: "localToken",
		};
	}

	/**
	 * Handle new SSE connection with unified auth
	 */
	private handleConnect(req: IncomingMessage, res: ServerResponse): void {
		// Check client limit
		if (this.clients.size >= this.config.maxClients) {
			res.writeHead(503, { "Content-Type": "text/plain" });
			res.end("Max clients reached");
			return;
		}

		// Verify bearer token using unified auth
		const authHeader = req.headers.authorization;
		if (!authHeader || !authHeader.startsWith("Bearer ")) {
			res.writeHead(401, { "Content-Type": "text/plain" });
			res.end("Unauthorized: Missing bearer token");
			return;
		}

		const providedToken = authHeader.substring(7); // Remove "Bearer "

		// Use unified auth validation (async, but we handle it)
		this.validateAuth(providedToken)
			.then((authResult) => {
				if (!authResult.valid) {
					res.writeHead(403, { "Content-Type": "text/plain" });
					res.end("Forbidden: Invalid token");
					return;
				}

				// Setup SSE connection
				res.writeHead(200, {
					"Content-Type": "text/event-stream",
					"Cache-Control": "no-cache",
					Connection: "keep-alive",
				});

				// Generate client ID
				const clientId = randomBytes(16).toString("hex");
				const now = Date.now();

				const client: SSEClient = {
					id: clientId,
					res,
					lastPong: now,
					missedPongs: 0,
					createdAt: now,
					authType: authResult.authType,
					userId: authResult.userId,
					tier: authResult.tier,
				};

				this.clients.set(clientId, client);

				// Send welcome event with client ID and auth type
				this.sendEvent(client, "connected", {
					clientId,
					maxIdleMs: this.config.idleTimeoutMs,
					authType: authResult.authType,
					userId: authResult.userId,
				});

				// Handle client disconnect
				req.on("close", () => {
					this.removeClient(clientId);
				});

				this.emit("client:connected", clientId, authResult);
				this.logger.info("Client connected", {
					clientId,
					count: this.clients.size,
					max: this.config.maxClients,
					authType: authResult.authType,
					userId: authResult.userId,
				});
			})
			.catch((err) => {
				this.logger.error("Auth validation failed", { error: String(err) });
				res.writeHead(500, { "Content-Type": "text/plain" });
				res.end("Internal server error during auth validation");
			});
	}

	/**
	 * Handle pong request from client
	 */
	private handlePongRequest(req: IncomingMessage, res: ServerResponse): void {
		let body = "";
		req.on("data", (chunk) => {
			body += chunk.toString();
		});

		req.on("end", () => {
			try {
				const { clientId } = JSON.parse(body);
				this.handlePong(clientId);
				res.writeHead(200);
				res.end("OK");
			} catch {
				res.writeHead(400);
				res.end("Bad Request");
			}
		});
	}

	/**
	 * Handle digest request for Pioneer Dashboard
	 * Direct local-first access from web console on localhost
	 *
	 * Security measures:
	 * - Origin header validation (CSRF protection)
	 * - Path traversal prevention
	 * - Request timeout (5 seconds)
	 */
	private handleDigestRequest(req: IncomingMessage, res: ServerResponse): void {
		// Security: Validate Origin header for localhost-only access
		const origin = req.headers.origin;
		if (!isValidLocalhostOrigin(origin)) {
			this.logger.warn("Digest request rejected - invalid origin", { origin });
			res.writeHead(403, { "Content-Type": "application/json" });
			res.end(
				JSON.stringify({
					status: "error",
					code: "UNAUTHORIZED",
					message: "Access denied - localhost only",
				}),
			);
			return;
		}

		// Check if digest service is available
		const digestService = this.config.digestService;
		if (!digestService) {
			res.writeHead(503, { "Content-Type": "application/json" });
			res.end(
				JSON.stringify({
					status: "error",
					code: "INTERNAL_ERROR",
					message: "Digest service not available",
				}),
			);
			return;
		}

		// Request timeout setup (5 seconds)
		const TIMEOUT_MS = 5000;
		let timeoutId: NodeJS.Timeout | null = null;
		let responded = false;

		const sendResponse = (statusCode: number, data: unknown) => {
			if (responded) {
				return;
			}
			responded = true;
			if (timeoutId) {
				clearTimeout(timeoutId);
			}
			res.writeHead(statusCode, { "Content-Type": "application/json" });
			res.end(JSON.stringify(data));
		};

		timeoutId = setTimeout(() => {
			sendResponse(504, {
				status: "error",
				code: "INTERNAL_ERROR",
				message: "Request timeout",
			});
		}, TIMEOUT_MS);

		let body = "";
		req.on("data", (chunk) => {
			body += chunk.toString();
		});

		req.on("end", async () => {
			try {
				const params = JSON.parse(body);

				// Validate workspace parameter
				if (!params.workspace || typeof params.workspace !== "string") {
					sendResponse(400, {
						status: "error",
						code: "NOT_FOUND",
						message: "Missing or invalid 'workspace' parameter",
					});
					return;
				}

				// Security: Validate workspace path for traversal attacks
				if (!isValidWorkspacePath(params.workspace)) {
					this.logger.warn("Digest request rejected - invalid workspace path", {
						workspace: params.workspace,
					});
					sendResponse(400, {
						status: "error",
						code: "NOT_FOUND",
						message: "Invalid workspace path",
					});
					return;
				}

				// Call digest service
				const result = await digestService.compute({
					workspace: params.workspace,
					force: params.force ?? false,
					user: params.user,
					sessionMetrics: params.sessionMetrics,
				});

				sendResponse(200, result);
			} catch (error) {
				this.logger.error("Digest request failed", { error: String(error) });
				sendResponse(500, {
					status: "error",
					code: "INTERNAL_ERROR",
					message: error instanceof Error ? error.message : "Unknown error",
				});
			}
		});

		req.on("error", (error) => {
			this.logger.error("Digest request stream error", { error: String(error) });
			sendResponse(500, {
				status: "error",
				code: "INTERNAL_ERROR",
				message: "Request stream error",
			});
		});
	}

	/**
	 * Handle POST /session/list  -  exposes session history to web dashboard.
	 * Localhost-only: validates Origin header against allowed origins.
	 */
	private handleSessionListRequest(req: IncomingMessage, res: ServerResponse): void {
		// Security: Validate Origin header for localhost-only access
		const origin = req.headers.origin;
		if (!isValidLocalhostOrigin(origin)) {
			this.logger.warn("Session list request rejected - invalid origin", { origin });
			res.writeHead(403, { "Content-Type": "application/json" });
			res.end(
				JSON.stringify({ status: "error", code: "UNAUTHORIZED", message: "Access denied - localhost only" }),
			);
			return;
		}

		const sessionService = this.config.sessionService;
		if (!sessionService) {
			res.writeHead(503, { "Content-Type": "application/json" });
			res.end(
				JSON.stringify({ status: "error", code: "INTERNAL_ERROR", message: "Session service not available" }),
			);
			return;
		}

		const TIMEOUT_MS = 5000;
		let timeoutId: NodeJS.Timeout | null = null;
		let responded = false;

		const sendResponse = (statusCode: number, data: unknown) => {
			if (responded) {
				return;
			}
			responded = true;
			if (timeoutId) {
				clearTimeout(timeoutId);
			}
			res.writeHead(statusCode, { "Content-Type": "application/json" });
			res.end(JSON.stringify(data));
		};

		timeoutId = setTimeout(() => {
			sendResponse(504, { status: "error", code: "INTERNAL_ERROR", message: "Request timeout" });
		}, TIMEOUT_MS);

		let body = "";
		req.on("data", (chunk) => {
			body += chunk.toString();
		});

		req.on("end", async () => {
			try {
				const params = body
					? JSON.parse(body)
					: {
							/* intentionally empty */
						};
				const result = await sessionService.list({
					limit: params.limit ?? 50,
					includeEnded: params.includeEnded ?? true,
					workspacePath: params.workspacePath,
				});

				sendResponse(200, {
					sessions: result.sessions,
					nextCursor: result.hasMore ? String((params.cursor ?? 0) + 1) : null,
					total: result.sessions.length,
				});
			} catch (error) {
				this.logger.error("Session list request failed", { error: String(error) });
				sendResponse(500, {
					status: "error",
					code: "INTERNAL_ERROR",
					message: error instanceof Error ? error.message : "Unknown error",
				});
			}
		});

		req.on("error", (error) => {
			this.logger.error("Session list request stream error", { error: String(error) });
			sendResponse(500, { status: "error", code: "INTERNAL_ERROR", message: "Request stream error" });
		});
	}

	/**
	 * Process pong from client
	 */
	private handlePong(clientId: string): void {
		const client = this.clients.get(clientId);
		if (!client) {
			return; // Client already disconnected
		}

		client.lastPong = Date.now();
		client.missedPongs = 0;
	}

	/**
	 * Start the ping loop for keepalive
	 */
	private startPingLoop(): void {
		if (this.pingTimer) {
			return; // Already running
		}

		this.pingTimer = setInterval(() => {
			const now = Date.now();
			const deadClients: string[] = [];

			for (const [clientId, client] of this.clients.entries()) {
				// Check for idle timeout
				const idleMs = now - client.lastPong;
				if (idleMs > this.config.idleTimeoutMs) {
					this.logger.info("Client idle, disconnecting", { clientId, idleSec: Math.round(idleMs / 1000) });
					deadClients.push(clientId);
					continue;
				}

				// Check missed pongs
				if (client.missedPongs >= this.config.maxMissedPongs) {
					this.logger.info("Client missed pongs, disconnecting", {
						clientId,
						missedPongs: client.missedPongs,
					});
					deadClients.push(clientId);
					continue;
				}

				// Send ping
				try {
					this.sendEvent(client, "ping", { timestamp: now });
					client.missedPongs++;
				} catch (err) {
					this.logger.error("Failed to ping client", { clientId, error: String(err) });
					deadClients.push(clientId);
				}
			}

			// Clean up dead clients
			for (const clientId of deadClients) {
				this.removeClient(clientId);
			}
		}, this.config.pingIntervalMs);
	}

	/**
	 * Send an SSE event to a client
	 */
	private sendEvent(client: SSEClient, event: string, data: unknown): void {
		const payload = JSON.stringify(data);
		client.res.write(`event: ${event}\n`);
		client.res.write(`data: ${payload}\n\n`);
	}

	/**
	 * Remove and clean up a client
	 */
	private removeClient(clientId: string): void {
		const client = this.clients.get(clientId);
		if (!client) {
			return;
		}

		try {
			this.sendEvent(client, "disconnect", { reason: "cleanup" });
			client.res.end();
		} catch {
			// Client already disconnected
		}

		this.clients.delete(clientId);
		this.emit("client:disconnected", clientId);
		this.logger.info("Client disconnected", { clientId, count: this.clients.size, max: this.config.maxClients });
	}
}

// =============================================================================
// Helper Functions
// =============================================================================

/**
 * Calculate exponential backoff for reconnect attempts
 * @param attemptNumber Zero-based attempt number
 * @returns Backoff duration in milliseconds (1s → 30s max)
 */
export function getReconnectBackoff(attemptNumber: number): number {
	return Math.min(1000 * 2 ** attemptNumber, 30000);
}
