/**
 * Response Calibration - Intelligence Layer v2.0
 *
 * Intent-aware response budgets with scope multipliers.
 * Per spec: Different budgets per task intent (explore, debug, implement, refactor, review).
 *
 * @module services/response-calibration
 */

import type { ScopeSize } from "@vreko/intelligence";
import type { TaskIntent } from "./tiered-learning-service.js";

// =============================================================================
// Re-exports for convenience
// =============================================================================

export type { TaskIntent, ScopeSize };

// =============================================================================
// Types
// =============================================================================

/** Response budget configuration */
export interface ResponseBudget {
	/** Maximum tokens to include in response */
	maxTokens: number;
	/** Maximum number of learnings to include */
	maxLearnings: number;
	/** Whether format compliance is required */
	formatCompliance: boolean;
}

// =============================================================================
// Constants
// =============================================================================

/**
 * Base budgets per task intent
 *
 * Per spec:
 * - explore: More learnings, relaxed format (10 learnings, 500 tokens)
 * - debug: Focused, fewer learnings (5 learnings, 300 tokens)
 * - implement: Moderate budget (7 learnings, 400 tokens)
 * - refactor: More context needed (10 learnings, 600 tokens)
 * - review: Most comprehensive (15 learnings, 800 tokens)
 */
export const INTENT_BUDGETS: Record<TaskIntent, ResponseBudget> = {
	explore: { maxTokens: 500, maxLearnings: 10, formatCompliance: false },
	debug: { maxTokens: 300, maxLearnings: 5, formatCompliance: true },
	implement: { maxTokens: 400, maxLearnings: 7, formatCompliance: true },
	refactor: { maxTokens: 600, maxLearnings: 10, formatCompliance: true },
	review: { maxTokens: 800, maxLearnings: 15, formatCompliance: true },
};

/**
 * Scope size multipliers
 *
 * Per spec:
 * - trivial: Single typo fix (0.3x)
 * - small: Single function change (0.5x)
 * - medium: Multiple files, same module (1.0x)
 * - large: Cross-module changes (1.5x)
 * - massive: Architecture-level changes (2.0x)
 */
export const SCOPE_MULTIPLIERS: Record<ScopeSize, number> = {
	trivial: 0.3,
	small: 0.5,
	medium: 1.0,
	large: 1.5,
	massive: 2.0,
};

// =============================================================================
// Functions
// =============================================================================

/**
 * Calculate response budget for a given intent and scope
 *
 * @param intent - The task intent (explore, debug, implement, refactor, review)
 * @param scope - The scope size (trivial, small, medium, large, massive)
 * @returns Calculated response budget with adjusted tokens and learnings
 */
export function calculateResponseBudget(intent: TaskIntent, scope: ScopeSize): ResponseBudget {
	const base = INTENT_BUDGETS[intent];
	const multiplier = SCOPE_MULTIPLIERS[scope] ?? 1.0; // Default to medium if unknown

	return {
		maxTokens: Math.round(base.maxTokens * multiplier),
		maxLearnings: Math.round(base.maxLearnings * multiplier),
		formatCompliance: base.formatCompliance,
	};
}

/**
 * Get budget for specific intent (without scope adjustment)
 */
export function getIntentBudget(intent: TaskIntent): ResponseBudget {
	return { ...INTENT_BUDGETS[intent] };
}

/**
 * Get multiplier for specific scope
 */
export function getScopeMultiplier(scope: ScopeSize): number {
	return SCOPE_MULTIPLIERS[scope] ?? 1.0;
}

/**
 * Validate if budget is within acceptable bounds
 */
export function validateBudget(budget: ResponseBudget): boolean {
	return budget.maxTokens > 0 && budget.maxTokens <= 2000 && budget.maxLearnings > 0 && budget.maxLearnings <= 50;
}

// =============================================================================
// Default export
// =============================================================================

export default {
	calculateResponseBudget,
	getIntentBudget,
	getScopeMultiplier,
	validateBudget,
	INTENT_BUDGETS,
	SCOPE_MULTIPLIERS,
};
