// LAZY AUTH IMPORT (avoids BetterAuth initialization for read-only operations)
// =============================================================================
// Lazy-load auth only when needed for token refresh
// This allows session reading to work without database/secrets
let _auth = null;
let _authPromise = null;
async function getAuth() {
    if (_auth) {
        return _auth;
    }
    if (_authPromise) {
        return _authPromise;
    }
    _authPromise = import("./auth").then((m) => {
        _auth = m.auth;
        return _auth;
    });
    return _authPromise;
}
const refreshFlights = new Map();
const REFLIGHT_TIMEOUT_MS = 30000; // 30 seconds
